READING.push(...[{"id": "rd5-a1-01", "lvl": "A1", "topic": "daily", "genre": "dialogue", "title": "A Coffee and a Sandwich", "text": "Waiter: Good morning. What would you like?\nAnna: Good morning. I would like a coffee, please.\nWaiter: Small or large?\nAnna: Small, please. How much is it?\nWaiter: A small coffee is two euros.\nAnna: And an egg sandwich, please. How much is it?\nWaiter: It is three euros. Anything else?\nAnna: A glass of orange juice, please.\nWaiter: OK. That is seven euros in total.\nAnna: Here you are.\nWaiter: Thank you. Please sit at the table by the window.", "gist": "Anna gọi cà phê, bánh sandwich trứng và nước cam ở quán cà phê rồi trả tiền.", "qs": [{"kind": "main", "q": "What is the dialogue about?", "opts": ["Ordering breakfast in a cafe", "Cooking an egg at home", "Buying a bus ticket", "Asking the way to a cafe"], "a": 0, "ev": "What would you like?", "why": "Người phục vụ hỏi \"What would you like?\" và Anna gọi đồ ăn sáng, nên đây là hội thoại gọi món ở quán."}, {"kind": "detail", "q": "What size coffee does Anna want?", "opts": ["Large", "Small", "Medium", "Two coffees"], "a": 1, "ev": "Small, please.", "why": "Anna trả lời \"Small, please.\" nghĩa là cô ấy muốn cà phê cỡ nhỏ."}, {"kind": "detail", "q": "How much is the egg sandwich?", "opts": ["Two euros", "Five euros", "Three euros", "Seven euros"], "a": 2, "ev": "It is three euros.", "why": "Người phục vụ nói \"It is three euros.\" về bánh sandwich trứng."}, {"kind": "vocab", "q": "In the text, what does \"in total\" mean?", "opts": ["For each thing", "At the table", "Only today", "All together"], "a": 3, "ev": "That is seven euros in total.", "why": "Tổng cộng bảy euro cho cả ba món, nên \"in total\" nghĩa là tất cả cộng lại."}, {"kind": "tfng", "q": "Anna asks for a large coffee.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Small, please.", "why": "Anna chọn cỡ nhỏ: \"Small, please.\", nên câu này sai."}, {"kind": "tfng", "q": "Anna pays by card.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài chỉ nói \"Here you are.\", không nói cách trả tiền bằng thẻ."}], "notes": {"vocab": [["in total", "tổng cộng", "all together = cộng tất cả"], ["Anything else?", "Còn gì nữa không?", "câu hỏi lịch sự của người bán"], ["Here you are.", "Của bạn đây.", "dùng khi đưa tiền hoặc đồ cho ai"], ["glass", "ly, cốc thủy tinh", "a glass of + đồ uống"]], "grammar": [["Polite request: would like (câu đề nghị lịch sự)", "I would like a coffee, please.", "Dùng \"would like\" để gọi món lịch sự, lịch sự hơn \"I want\"."], ["Wh- question: How much (hỏi giá)", "How much is it?", "\"How much\" dùng để hỏi giá tiền, theo sau là is + chủ ngữ."]], "tips": ["Trong hội thoại, đọc tên người nói trước mỗi dòng để biết ai đang nói gì.", "Với câu hỏi về giá, hãy tìm các con số và từ \"euros\" trong bài."]}}, {"id": "rd5-a1-02", "lvl": "A1", "topic": "travel", "genre": "notice", "title": "Greenford Town Bus Times", "text": "BUS TIMETABLE - GREENFORD TOWN\n\nBus 5 goes from the train station to the market and the hospital.\nFirst bus: 7:00 a.m.\nLast bus: 9:30 p.m.\nA bus comes every 30 minutes.\n\nTICKETS\nAdult: 2 dollars\nChild (5 to 12 years): 1 dollar\nChildren under 5: free\nStudents: 1 dollar 50 with a student card\n\nBuy your ticket from the driver. Pay with coins only. There are no buses on Sunday.", "gist": "Thông báo cho biết giờ chạy và giá vé của xe buýt số 5 ở thị trấn Greenford.", "qs": [{"kind": "main", "q": "What is this notice about?", "opts": ["A train to the hospital", "Bus times and ticket prices", "A new market in town", "Rules for students"], "a": 1, "ev": "BUS TIMETABLE - GREENFORD TOWN", "why": "Tiêu đề \"BUS TIMETABLE - GREENFORD TOWN\" và phần \"TICKETS\" cho thấy thông báo nói về giờ xe buýt và giá vé."}, {"kind": "detail", "q": "How often does a bus come?", "opts": ["Every 5 minutes", "Every 12 minutes", "Every 30 minutes", "Every hour"], "a": 2, "ev": "A bus comes every 30 minutes.", "why": "Bài ghi \"A bus comes every 30 minutes.\" tức là cứ 30 phút có một chuyến."}, {"kind": "detail", "q": "How much is a ticket for an eight-year-old child?", "opts": ["Free", "2 dollars", "1 dollar 50", "1 dollar"], "a": 3, "ev": "Child (5 to 12 years): 1 dollar", "why": "Trẻ 8 tuổi nằm trong nhóm \"Child (5 to 12 years): 1 dollar\"."}, {"kind": "vocab", "q": "In the text, what does \"free\" mean?", "opts": ["You do not pay", "Very cheap", "Very early", "Only for adults"], "a": 0, "ev": "Children under 5: free", "why": "Trẻ dưới 5 tuổi \"free\", nghĩa là không phải trả tiền."}, {"kind": "tfng", "q": "The last bus leaves at 7:00 p.m.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Last bus: 9:30 p.m.", "why": "Chuyến cuối là \"9:30 p.m.\", không phải 7:00 nên câu sai."}, {"kind": "tfng", "q": "The bus stops at the school.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài chỉ nhắc ga tàu, chợ và bệnh viện, không nói đến trường học."}], "notes": {"vocab": [["timetable", "bảng giờ chạy", "bus/train timetable"], ["ticket", "vé", "buy a ticket"], ["coins", "đồng xu", "trái nghĩa: notes = tiền giấy"], ["driver", "tài xế", "drive (v) -> driver (n)"]], "grammar": [["There is/are not (câu phủ định có there are)", "There are no buses on Sunday.", "\"There are no + danh từ số nhiều\" nghĩa là không có cái gì đó."], ["Imperative (câu mệnh lệnh)", "Buy your ticket from the driver.", "Câu mệnh lệnh bắt đầu bằng động từ nguyên mẫu, thường dùng trong thông báo."]], "tips": ["Thông báo thường chia thành các mục có tiêu đề in hoa như TICKETS; hãy đọc tiêu đề trước.", "Khi hỏi số liệu (giờ, giá), tìm con số rồi xem nhãn đứng trước nó."]}}, {"id": "rd5-a1-03", "lvl": "A1", "topic": "daily", "genre": "email", "title": "Park Plans for Sunday", "text": "Subject: Sunday at the park\n\nHi Tom,\n\nHow are you? I am free on Sunday. Let's meet at the park at 10 o'clock. We can play football and have a picnic. I bring sandwiches and water. Can you bring some fruit? My sister Lan comes too. The weather is good on Sunday, but take a hat. The park is near the lake. Meet me at the big gate. Please write back soon.\n\nBest wishes,\nMai", "gist": "Mai viết thư mời Tom gặp ở công viên vào Chủ nhật lúc 10 giờ để chơi bóng và đi dã ngoại.", "qs": [{"kind": "main", "q": "Why does Mai write to Tom?", "opts": ["To say sorry", "To ask about school", "To ask him to meet at the park", "To buy fruit"], "a": 2, "ev": "Let's meet at the park at 10 o'clock.", "why": "Mai đề nghị \"Let's meet at the park at 10 o'clock.\" nên mục đích là mời Tom gặp ở công viên."}, {"kind": "detail", "q": "What time do they meet?", "opts": ["At 8 o'clock", "At 9 o'clock", "At 11 o'clock", "At 10 o'clock"], "a": 3, "ev": "Let's meet at the park at 10 o'clock.", "why": "Giờ hẹn là \"10 o'clock\"."}, {"kind": "detail", "q": "What does Mai ask Tom to bring?", "opts": ["Fruit", "Water", "A hat", "Sandwiches"], "a": 0, "ev": "Can you bring some fruit?", "why": "Mai hỏi \"Can you bring some fruit?\" nên Tom mang trái cây."}, {"kind": "vocab", "q": "In the text, what does \"picnic\" mean?", "opts": ["A game with a ball", "A meal outside", "A trip by bus", "A school lesson"], "a": 1, "ev": "have a picnic", "why": "Cùng với sandwich và nước, \"picnic\" là bữa ăn ngoài trời."}, {"kind": "tfng", "q": "Mai's sister does not come to the park.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "My sister Lan comes too.", "why": "Bài viết \"My sister Lan comes too.\" nên em gái Mai có đi, câu sai."}, {"kind": "tfng", "q": "Tom likes football very much.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài chỉ nói họ có thể chơi bóng, không nói Tom có thích bóng đá không."}], "notes": {"vocab": [["free", "rảnh", "be free on Sunday = rảnh vào Chủ nhật"], ["picnic", "bữa ăn dã ngoại", "have a picnic"], ["gate", "cổng", "the park gate"], ["write back", "trả lời thư", "write back soon"]], "grammar": [["Suggestion: Let's + verb (lời rủ)", "Let's meet at the park at 10 o'clock.", "\"Let's + động từ nguyên mẫu\" dùng để rủ ai cùng làm việc gì."], ["Polite request: Can you...? (nhờ vả)", "Can you bring some fruit?", "\"Can you + động từ?\" dùng để nhờ người khác làm gì."]], "tips": ["Thư điện tử có lời chào (Hi Tom) và lời kết (Best wishes); nội dung chính nằm ở giữa.", "Dòng Subject cho biết chủ đề của thư ngay từ đầu."]}}, {"id": "rd5-a1-04", "lvl": "A1", "topic": "daily", "genre": "blog", "title": "Linh's Quiet Mornings", "text": "My Morning Routine\n\nHello, everyone! My name is Linh. I am a student. Here is my morning.\n\nI get up at 6:00. I wash my face and brush my teeth. Then I have breakfast with my family. I usually eat rice soup and drink tea. At 7:00 I go to school by bike. It takes twenty minutes. My first class starts at 7:30. I like the morning because the streets are quiet. What about you? Write to me!", "gist": "Linh kể về buổi sáng của mình: dậy lúc 6 giờ, ăn sáng cùng gia đình và đạp xe đến trường.", "qs": [{"kind": "main", "q": "What is the blog about?", "opts": ["Linh's favourite food", "Linh's school friends", "Linh's family trip", "Linh's morning"], "a": 3, "ev": "Here is my morning.", "why": "Linh viết \"Here is my morning.\" rồi kể các việc buổi sáng, nên đó là chủ đề chính."}, {"kind": "detail", "q": "What time does Linh get up?", "opts": ["At 6:00", "At 7:00", "At 7:30", "At 8:00"], "a": 0, "ev": "I get up at 6:00.", "why": "Bài ghi \"I get up at 6:00.\""}, {"kind": "detail", "q": "How does Linh go to school?", "opts": ["By bus", "By bike", "On foot", "By car"], "a": 1, "ev": "I go to school by bike.", "why": "Linh nói \"I go to school by bike.\" tức là đi bằng xe đạp."}, {"kind": "vocab", "q": "In the text, what does \"quiet\" mean?", "opts": ["Full of people", "Very dirty", "Not noisy", "Very long"], "a": 2, "ev": "the streets are quiet", "why": "Linh thích buổi sáng vì đường phố \"quiet\", nghĩa là yên tĩnh, ít tiếng ồn."}, {"kind": "tfng", "q": "Linh has breakfast alone.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "breakfast with my family", "why": "Linh ăn sáng \"with my family\", không phải một mình nên câu sai."}, {"kind": "tfng", "q": "Linh has a brother.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài chỉ nói \"my family\", không nhắc đến anh em trai."}], "notes": {"vocab": [["routine", "thói quen hằng ngày", "daily routine"], ["usually", "thường xuyên", "trạng từ chỉ tần suất"], ["brush", "đánh (răng)", "brush my teeth"], ["class", "tiết học", "first class"]], "grammar": [["Present simple (thì hiện tại đơn)", "I get up at 6:00.", "Dùng hiện tại đơn để nói về thói quen mỗi ngày."], ["Frequency adverb (trạng từ tần suất)", "I usually eat rice soup and drink tea.", "\"usually\" đứng trước động từ chính, chỉ việc thường làm."]], "tips": ["Blog cá nhân thường viết ở ngôi \"I\" và kể theo thứ tự thời gian.", "Chú ý các mốc giờ (6:00, 7:00, 7:30) để trả lời câu hỏi chi tiết."]}}, {"id": "rd5-a1-05", "lvl": "A1", "topic": "daily", "genre": "advert", "title": "Stall 7 at the Farm Market", "text": "FRESH FARM MARKET - STALL 7\n\nCome to our stall! Everything is fresh today.\n\nApples: 2 dollars a kilo\nBananas: 1 dollar a kilo\nTomatoes: 3 dollars a kilo\nCarrots: 1 dollar 50 a kilo\n\nSPECIAL OFFER: Buy two kilos of apples and get one kilo of bananas free!\n\nWe are open from 8:00 a.m. to 5:00 p.m., Monday to Saturday.\nCome early. The best fruit goes fast! Our farm is near the river, and we bring new fruit and vegetables every morning.", "gist": "Quảng cáo gian hàng số 7 bán trái cây và rau tươi kèm giá và khuyến mãi.", "qs": [{"kind": "main", "q": "What is this advert for?", "opts": ["A market stall", "A farm school", "A big supermarket", "A cooking class"], "a": 0, "ev": "FRESH FARM MARKET - STALL 7", "why": "Tiêu đề \"FRESH FARM MARKET - STALL 7\" cho thấy đây là quảng cáo gian hàng ở chợ."}, {"kind": "detail", "q": "How much are tomatoes?", "opts": ["1 dollar a kilo", "3 dollars a kilo", "2 dollars a kilo", "1 dollar 50 a kilo"], "a": 1, "ev": "Tomatoes: 3 dollars a kilo", "why": "Bài ghi \"Tomatoes: 3 dollars a kilo\"."}, {"kind": "detail", "q": "When is the stall open?", "opts": ["10:00 a.m. to 3:00 p.m.", "7:00 a.m. to 9:00 p.m.", "8:00 a.m. to 5:00 p.m.", "8:00 p.m. to 5:00 a.m."], "a": 2, "ev": "open from 8:00 a.m. to 5:00 p.m.", "why": "Giờ mở cửa là \"from 8:00 a.m. to 5:00 p.m.\""}, {"kind": "vocab", "q": "In the text, what does \"free\" mean in \"get one kilo of bananas free\"?", "opts": ["Very fresh", "Very big", "You must buy it", "You do not pay for it"], "a": 3, "ev": "get one kilo of bananas free", "why": "Mua hai ký táo thì được một ký chuối \"free\", nghĩa là không mất tiền."}, {"kind": "tfng", "q": "Bananas cost 2 dollars a kilo.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Bananas: 1 dollar a kilo", "why": "Chuối giá \"1 dollar a kilo\", không phải 2 đô la nên câu sai."}, {"kind": "tfng", "q": "You can pay by card at the stall.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói gì về cách thanh toán."}], "notes": {"vocab": [["stall", "gian hàng", "market stall"], ["fresh", "tươi", "fresh fruit"], ["special offer", "khuyến mãi đặc biệt", "offer = lời đề nghị, ưu đãi"], ["kilo", "ký (kg)", "two kilos of apples"]], "grammar": [["Imperative (câu mệnh lệnh)", "Come early.", "Quảng cáo hay dùng câu mệnh lệnh để mời gọi khách hàng."], ["Superlative: the best (so sánh nhất)", "The best fruit goes fast!", "\"the best\" là dạng so sánh nhất của good, nghĩa là tốt nhất."]], "tips": ["Quảng cáo thường liệt kê sản phẩm kèm giá; đọc từng dòng để tìm đúng món.", "Chú ý phần SPECIAL OFFER, thường chứa điều kiện đặc biệt."]}}, {"id": "rd5-a1-06", "lvl": "A1", "topic": "education", "genre": "notice", "title": "Room 12 Welcome Rules", "text": "CLASS RULES FOR ROOM 12\n\nWelcome, new students! Please read these rules.\n\n1. Come to class at 8:00. Do not be late.\n2. Turn off your phone in class.\n3. Speak English in the lesson.\n4. Listen to the teacher and to your friends.\n5. Do not eat in the room. You can drink water.\n6. Bring your book, a pen and a notebook every day.\n7. Put your chairs under the tables at the end of the lesson.\n\nIf you have a question, put up your hand. Your teacher, Ms Lan, is happy to help you.\n\nHave a good year!", "gist": "Thông báo nêu các quy tắc trong lớp cho học sinh mới, như đến đúng giờ, tắt điện thoại và nói tiếng Anh.", "qs": [{"kind": "main", "q": "What is this notice about?", "opts": ["Rules for new students in a class", "A list of books for the lesson", "The names of the teachers", "A plan for a school trip"], "a": 0, "ev": "Welcome, new students! Please read these rules.", "why": "Thông báo mở đầu bằng \"Welcome, new students! Please read these rules.\" nên nội dung chính là quy tắc lớp học."}, {"kind": "detail", "q": "What time does the class start?", "opts": ["At 7:00", "At 8:00", "At 9:00", "At 10:00"], "a": 1, "ev": "Come to class at 8:00.", "why": "Văn bản ghi \"Come to class at 8:00.\" nên lớp bắt đầu lúc 8:00."}, {"kind": "detail", "q": "What can students drink in the room?", "opts": ["Tea", "Milk", "Juice", "Water"], "a": 3, "ev": "You can drink water.", "why": "Câu \"You can drink water.\" cho biết học sinh được uống nước."}, {"kind": "vocab", "q": "In the text, what does \"bring\" mean?", "opts": ["Buy in a shop", "Give to a friend", "Take with you", "Leave at home"], "a": 2, "ev": "Bring your book, a pen and a notebook every day.", "why": "\"Bring your book...\" nghĩa là mang sách, bút, vở theo mỗi ngày, tức là take with you."}, {"kind": "tfng", "q": "Students can eat in the room.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Do not eat in the room.", "why": "Văn bản nói \"Do not eat in the room.\" nên câu này sai."}, {"kind": "tfng", "q": "The teacher gives homework every day.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản không nói gì về bài tập về nhà nên là Not given."}], "notes": {"vocab": [["rules", "luật, quy tắc", "a rule / rules of the class"], ["late", "muộn, trễ", "be late >< be on time"], ["notebook", "quyển vở", "note + book"], ["lesson", "bài học, buổi học", "at the end of the lesson"], ["hand", "bàn tay", "put up your hand = giơ tay"]], "grammar": [["Imperative (câu mệnh lệnh)", "Turn off your phone in class.", "Dùng động từ nguyên mẫu ở đầu câu để ra lệnh hoặc hướng dẫn, rất hay gặp trong thông báo."], ["Negative imperative (mệnh lệnh phủ định)", "Do not be late.", "Dùng Do not + động từ để nói điều không được làm."], ["Modal can (khả năng, cho phép)", "You can drink water.", "can + động từ nguyên mẫu diễn tả điều được phép làm."]], "tips": ["Thông báo thường có tiêu đề rõ ràng và danh sách đánh số; đọc tiêu đề trước để biết ý chính, rồi tìm từng quy tắc.", "Chú ý Do not và You can để phân biệt điều bị cấm với điều được phép."]}}, {"id": "rd5-a1-07", "lvl": "A1", "topic": "environment", "genre": "news", "title": "Three Cities Weather Report", "text": "TODAY'S WEATHER\n\nGood morning. Here is the weather for three cities.\n\nIn Hanoi, it is cloudy and cool. It is 18 degrees. There is a little rain in the afternoon, so take an umbrella.\n\nIn Da Nang, it is sunny and warm. It is 27 degrees. The sea is calm, and it is a good day for the beach.\n\nIn Ho Chi Minh City, it is hot and windy. It is 34 degrees. There is a big storm in the evening.\n\nThat is the weather. Have a nice day!", "gist": "Bản tin thời tiết hôm nay ở Hà Nội, Đà Nẵng và Thành phố Hồ Chí Minh.", "qs": [{"kind": "main", "q": "What is the report about?", "opts": ["Holidays in three cities", "The weather in three cities", "Food in three cities", "Trains to three cities"], "a": 1, "ev": "Here is the weather for three cities.", "why": "Câu \"Here is the weather for three cities.\" cho thấy bản tin nói về thời tiết ở ba thành phố."}, {"kind": "detail", "q": "How warm is it in Hanoi?", "opts": ["18 degrees", "27 degrees", "34 degrees", "20 degrees"], "a": 0, "ev": "In Hanoi, it is cloudy and cool. It is 18 degrees.", "why": "Văn bản ghi Hà Nội \"It is 18 degrees.\""}, {"kind": "detail", "q": "Which city is good for the beach today?", "opts": ["Hanoi", "Ho Chi Minh City", "Both cities in the south", "Da Nang"], "a": 3, "ev": "it is a good day for the beach", "why": "Chỉ Đà Nẵng có câu \"it is a good day for the beach\"."}, {"kind": "vocab", "q": "In the text, what does \"calm\" mean?", "opts": ["Very big", "Very cold", "Very dirty", "Quiet, not rough"], "a": 3, "ev": "The sea is calm", "why": "\"The sea is calm\" nghĩa là biển yên, không có sóng to."}, {"kind": "tfng", "q": "It is sunny in Hanoi.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "In Hanoi, it is cloudy and cool.", "why": "Hà Nội \"cloudy and cool\" (nhiều mây, mát) chứ không nắng, nên câu này sai."}, {"kind": "tfng", "q": "It will rain in Da Nang tomorrow.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản không nói về ngày mai ở Đà Nẵng nên là Not given."}], "notes": {"vocab": [["cloudy", "nhiều mây", "cloud -> cloudy; sun -> sunny"], ["umbrella", "cái ô, cái dù", "take an umbrella"], ["calm", "yên, lặng (biển)", "a calm sea"], ["windy", "có gió", "wind -> windy"], ["storm", "cơn bão, giông", "a big storm"]], "grammar": [["There is + noun (có...)", "There is a little rain in the afternoon, so take an umbrella.", "There is dùng để nói có cái gì đó ở một nơi hoặc thời điểm; a little đi với danh từ không đếm được như rain."], ["It is + adjective (thời tiết)", "In Ho Chi Minh City, it is hot and windy.", "Dùng it is + tính từ để mô tả thời tiết."], ["Linker so (vì vậy)", "There is a little rain in the afternoon, so take an umbrella.", "so nối kết quả hoặc lời khuyên với lý do đứng trước."]], "tips": ["Bản tin chia thành các đoạn, mỗi đoạn một thành phố; hãy gạch dưới tên thành phố và con số nhiệt độ.", "Từ chỉ thời tiết như sunny, cloudy, windy thường đứng sau it is; học theo nhóm sẽ dễ nhớ."]}}, {"id": "rd5-a1-08", "lvl": "A1", "topic": "travel", "genre": "dialogue", "title": "A Phone Call to Sunrise Hotel", "text": "Receptionist: Good afternoon, Sunrise Hotel. How can I help you?\nMr Brown: Hello. I want a room for two nights, please.\nReceptionist: Of course. Which nights?\nMr Brown: Friday and Saturday.\nReceptionist: Do you want a single room or a double room?\nMr Brown: A double room, please. We are two people.\nReceptionist: We have a double room for 40 dollars a night. Breakfast is free.\nMr Brown: That is good. What time is breakfast?\nReceptionist: From 6:30 to 9:30.\nMr Brown: Great. My name is Tom Brown.\nReceptionist: Thank you, Mr Brown. Your room is ready on Friday.", "gist": "Ông Brown gọi điện cho khách sạn để đặt một phòng đôi hai đêm và hỏi giá, giờ ăn sáng.", "qs": [{"kind": "main", "q": "Why does Mr Brown phone the hotel?", "opts": ["To ask about a room", "To ask for a taxi", "To change his name", "To order breakfast"], "a": 0, "ev": "I want a room for two nights, please.", "why": "Ông Brown nói \"I want a room for two nights, please.\" nên ông gọi để hỏi đặt phòng."}, {"kind": "detail", "q": "How many nights does Mr Brown want the room?", "opts": ["One night", "Three nights", "Two nights", "Four nights"], "a": 2, "ev": "a room for two nights", "why": "Ông nói muốn phòng cho \"two nights\" (hai đêm)."}, {"kind": "detail", "q": "How much is the double room for one night?", "opts": ["30 dollars", "40 dollars", "50 dollars", "60 dollars"], "a": 1, "ev": "a double room for 40 dollars a night", "why": "Lễ tân nói phòng đôi giá \"40 dollars a night\"."}, {"kind": "vocab", "q": "In the text, what does \"free\" mean?", "opts": ["Very cheap", "Open late", "You do not pay money", "Ready now"], "a": 2, "ev": "Breakfast is free.", "why": "\"Breakfast is free.\" nghĩa là bữa sáng miễn phí, không phải trả tiền."}, {"kind": "tfng", "q": "Mr Brown wants a single room.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "A double room, please.", "why": "Ông Brown nói \"A double room, please.\" nên ông muốn phòng đôi, câu này sai."}, {"kind": "tfng", "q": "Mr Brown will come by taxi.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Hội thoại không nói ông đến bằng phương tiện gì nên là Not given."}], "notes": {"vocab": [["receptionist", "nhân viên lễ tân", "reception = quầy lễ tân"], ["double room", "phòng đôi", "single room = phòng đơn"], ["night", "đêm (số đêm ở)", "two nights"], ["breakfast", "bữa sáng", "breakfast is free"], ["ready", "sẵn sàng", "Your room is ready."]], "grammar": [["Polite request I want... please", "I want a room for two nights, please.", "Thêm please để lời yêu cầu lịch sự hơn."], ["Question with Do you want...?", "Do you want a single room or a double room?", "Do + chủ ngữ + động từ nguyên mẫu để hỏi lựa chọn; or nối hai lựa chọn."], ["Prices with a (mỗi)", "We have a double room for 40 dollars a night.", "a night nghĩa là mỗi đêm; a ở đây mang nghĩa per."]], "tips": ["Hội thoại ghi tên người nói ở đầu mỗi dòng; hãy xác định ai hỏi, ai trả lời để tìm thông tin nhanh.", "Với số liệu như giá và giờ, hãy khoanh tròn các con số khi đọc rồi đối chiếu với câu hỏi."]}}, {"id": "rd5-a1-09", "lvl": "A1", "topic": "medical", "genre": "leaflet", "title": "My Body Poster", "text": "MY BODY\n\nLearn the parts of the body!\n\nHead: This is the top of your body.\nEye: You see with your eyes. You have two eyes.\nEar: You hear with your ears. You have two ears.\nMouth: You eat and speak with your mouth.\nArm: Your arm is between your shoulder and your hand.\nHand: You hold a pen with your hand.\nLeg: You walk with your legs.\nFoot: Your foot is at the bottom of your leg. You wear a shoe on each foot.\n\nLook after your body. Wash your hands every day!", "gist": "Tấm áp phích giới thiệu các bộ phận cơ thể như đầu, mắt, tai, miệng, tay, chân với mỗi bộ phận một câu đơn giản.", "qs": [{"kind": "main", "q": "What is the poster about?", "opts": ["Clothes for children", "Parts of the body", "Healthy food", "Sports at school"], "a": 1, "ev": "Learn the parts of the body!", "why": "Câu \"Learn the parts of the body!\" cho thấy áp phích dạy về các bộ phận cơ thể."}, {"kind": "detail", "q": "What do you hear with?", "opts": ["Your eyes", "Your mouth", "Your hands", "Your ears"], "a": 3, "ev": "You hear with your ears.", "why": "Văn bản ghi \"You hear with your ears.\" nên ta nghe bằng tai."}, {"kind": "detail", "q": "Where do you wear a shoe?", "opts": ["On your foot", "On your hand", "On your head", "On your arm"], "a": 0, "ev": "You wear a shoe on each foot.", "why": "Câu \"You wear a shoe on each foot.\" cho biết giày đi ở bàn chân."}, {"kind": "vocab", "q": "In the text, what does \"hold\" mean?", "opts": ["Throw far away", "Keep in your hand", "Look at", "Break in two"], "a": 1, "ev": "You hold a pen with your hand.", "why": "\"You hold a pen with your hand.\" nghĩa là cầm bút trong tay, tức keep in your hand."}, {"kind": "tfng", "q": "You have one eye.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "You have two eyes.", "why": "Văn bản nói \"You have two eyes.\" nên câu này sai."}, {"kind": "tfng", "q": "Each foot has five toes.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Áp phích không nhắc đến ngón chân nên là Not given."}], "notes": {"vocab": [["body", "cơ thể", "parts of the body"], ["hear", "nghe thấy", "hear with your ears"], ["between", "ở giữa", "between A and B"], ["hold", "cầm, giữ", "hold a pen"], ["bottom", "phần dưới cùng", "the bottom of your leg"]], "grammar": [["Imperative (câu mệnh lệnh)", "Wash your hands every day!", "Động từ nguyên mẫu đứng đầu câu để khuyên hoặc ra lệnh; every day chỉ thói quen."], ["Preposition with (dùng bằng)", "You see with your eyes.", "with + bộ phận cơ thể nói ta dùng bộ phận đó để làm gì."], ["Preposition between", "Your arm is between your shoulder and your hand.", "between A and B chỉ vị trí ở giữa hai thứ."]], "tips": ["Áp phích có dạng danh sách: mỗi dòng bắt đầu bằng tên bộ phận, hãy đọc từ khóa đầu dòng trước.", "Nhìn các cặp từ như eye - see, ear - hear để nhớ chức năng của từng bộ phận."]}}, {"id": "rd5-a1-10", "lvl": "A1", "topic": "medical", "genre": "dialogue", "title": "Checking In at the Clinic Desk", "text": "Receptionist: Good morning. Can I help you?\nPatient: Good morning. I have an appointment with Dr Hoa.\nReceptionist: What is your name, please?\nPatient: My name is Nam Tran.\nReceptionist: Can you spell your last name?\nPatient: Yes. T-R-A-N.\nReceptionist: Thank you. What is your date of birth?\nPatient: It is 5 March 1998.\nReceptionist: And your appointment is at 10:30 today. Is that right?\nPatient: Yes, that is right.\nReceptionist: Please sit down. The doctor will see you soon.\nPatient: Thank you.", "gist": "Một bệnh nhân đến quầy lễ tân phòng khám, nói tên, ngày sinh và xác nhận giờ hẹn với bác sĩ.", "qs": [{"kind": "main", "q": "Where does this conversation happen?", "opts": ["At a clinic reception desk", "At a bus station", "At a school", "At a shop"], "a": 0, "ev": "I have an appointment with Dr Hoa.", "why": "Bệnh nhân nói có hẹn với bác sĩ Hoa và lễ tân hỏi tên, ngày sinh, nên cuộc trò chuyện diễn ra ở quầy lễ tân phòng khám."}, {"kind": "detail", "q": "What time is the appointment?", "opts": ["9:30", "10:00", "11:30", "10:30"], "a": 3, "ev": "your appointment is at 10:30 today", "why": "Lễ tân nói \"your appointment is at 10:30 today\"."}, {"kind": "detail", "q": "What is the patient's date of birth?", "opts": ["5 March 1998", "15 March 1998", "5 May 1998", "5 March 1989"], "a": 0, "ev": "It is 5 March 1998.", "why": "Bệnh nhân trả lời \"It is 5 March 1998.\""}, {"kind": "vocab", "q": "In the text, what does \"appointment\" mean?", "opts": ["A kind of medicine", "A time to see someone", "A small room", "A phone number"], "a": 1, "ev": "I have an appointment with Dr Hoa.", "why": "\"I have an appointment with Dr Hoa.\" nghĩa là có lịch hẹn gặp bác sĩ, tức a time to see someone."}, {"kind": "tfng", "q": "The patient has an appointment with a nurse.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "I have an appointment with Dr Hoa.", "why": "Bệnh nhân hẹn với bác sĩ Hoa (Dr Hoa), không phải y tá, nên câu này sai."}, {"kind": "tfng", "q": "The patient has a headache.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Hội thoại không nói bệnh nhân bị đau gì nên là Not given."}], "notes": {"vocab": [["appointment", "cuộc hẹn, lịch hẹn", "make an appointment"], ["spell", "đánh vần", "Can you spell your name?"], ["date of birth", "ngày sinh", "thường viết tắt DOB"], ["patient", "bệnh nhân", "a patient at a clinic"], ["receptionist", "nhân viên lễ tân", "reception = quầy lễ tân"]], "grammar": [["Polite question with Can", "Can you spell your last name?", "Can you + động từ nguyên mẫu là cách lịch sự để nhờ ai làm gì."], ["Future with will", "The doctor will see you soon.", "will + động từ nguyên mẫu nói về việc sẽ xảy ra."], ["Wh- question", "What is your date of birth?", "What + is + danh từ để hỏi thông tin cá nhân."]], "tips": ["Trong hội thoại ở phòng khám, lễ tân thường hỏi tên, ngày sinh, giờ hẹn; hãy chú ý các con số và ngày tháng.", "Đọc câu hỏi của lễ tân trước, câu trả lời của bệnh nhân thường chứa thông tin cần tìm."]}}, {"id": "rd5-a1-11", "lvl": "A1", "topic": "medical", "genre": "leaflet", "title": "Five Habits for a Healthy Week", "text": "FIVE HEALTHY HABITS\n\nDo you want to feel good every day? Try these five habits.\n\n1. Sleep. Go to bed early. Adults need seven or eight hours of sleep.\n2. Water. Drink six glasses of water a day. Water is good for your body.\n3. Walk. Walk for thirty minutes every day. It is good for your heart.\n4. Fruit. Eat fruit every day. Apples and oranges are nice.\n5. Wash your hands. Wash them with soap before you eat.\n\nSmall habits make a big change.", "gist": "Tờ rơi giới thiệu năm thói quen tốt cho sức khỏe: ngủ, uống nước, đi bộ, ăn trái cây và rửa tay.", "qs": [{"kind": "main", "q": "What is this leaflet about?", "opts": ["Ways to stay healthy", "How to cook fruit", "Hospital opening times", "How to take medicine"], "a": 0, "ev": "Try these five habits.", "why": "Tờ rơi đưa ra năm thói quen tốt: \"Try these five habits.\" nên nội dung nói về cách giữ sức khỏe."}, {"kind": "detail", "q": "How many glasses of water should you drink a day?", "opts": ["Two", "Four", "Six", "Eight"], "a": 2, "ev": "Drink six glasses of water a day.", "why": "Văn bản nói \"Drink six glasses of water a day.\" nên đáp án là sáu."}, {"kind": "detail", "q": "How long should you walk every day?", "opts": ["Fifteen minutes", "Thirty minutes", "One hour", "Two hours"], "a": 1, "ev": "Walk for thirty minutes every day.", "why": "Câu \"Walk for thirty minutes every day.\" cho biết là ba mươi phút."}, {"kind": "vocab", "q": "In the text, what does \"habit\" mean?", "opts": ["A kind of fruit", "A place to sleep", "A type of soap", "Something you do often"], "a": 3, "ev": "Try these five habits.", "why": "Habit là thói quen, tức là việc bạn làm thường xuyên như ngủ sớm, đi bộ mỗi ngày."}, {"kind": "tfng", "q": "Adults need four hours of sleep.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Adults need seven or eight hours of sleep.", "why": "Văn bản nói \"Adults need seven or eight hours of sleep.\" chứ không phải bốn giờ nên câu này sai."}, {"kind": "tfng", "q": "Children should eat fruit three times a day.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản không nói gì về trẻ em hay số lần ăn trái cây nên là Not given."}], "notes": {"vocab": [["habits", "thói quen", "habit (n); good/bad habit"], ["Adults", "người lớn", "adult (n) >< child"], ["glasses", "những ly/cốc", "glass (n) số nhiều: glasses"], ["soap", "xà phòng", "wash with soap"], ["heart", "quả tim", "cơ quan bơm máu"]], "grammar": [["Imperative (câu mệnh lệnh)", "Go to bed early.", "Dạng nguyên mẫu không có chủ ngữ, dùng để khuyên hoặc ra lệnh."], ["Present simple for facts (hiện tại đơn)", "Water is good for your body.", "Dùng am/is/are + tính từ để nói một sự thật chung."]], "tips": ["Tờ rơi thường có tiêu đề và danh sách đánh số; đọc tiêu đề trước để biết ý chính.", "Mỗi mục bắt đầu bằng một từ khóa (Sleep, Water, Walk...), nên tìm từ khóa đó khi cần chi tiết."]}}, {"id": "rd5-a1-12", "lvl": "A1", "topic": "medical", "genre": "notice", "title": "Green Cross Pharmacy: Hours and What to Bring", "text": "GREEN CROSS PHARMACY\n\nOpening hours:\nMonday to Friday: 8 a.m. to 6 p.m.\nSaturday: 8 a.m. to 12 p.m.\nSunday: closed\n\nPlease bring your prescription. A prescription is a paper from your doctor. Please bring your ID card too. Please bring your health card if you have one. The pharmacist can find your name on the computer. If you are ill, ask a friend to come. We can help you with questions. Please wait in line. Thank you.", "gist": "Thông báo của hiệu thuốc nêu giờ mở cửa và những thứ cần mang theo.", "qs": [{"kind": "main", "q": "What is this notice about?", "opts": ["A new doctor at the clinic", "Rules for the car park", "A sale on soap", "The pharmacy's hours and what to bring"], "a": 3, "ev": "Please bring your prescription.", "why": "Thông báo cho biết giờ mở cửa và nhắc mang đơn thuốc, thẻ căn cước."}, {"kind": "detail", "q": "When is the pharmacy closed?", "opts": ["Saturday", "Friday", "Sunday", "Monday"], "a": 2, "ev": "Sunday: closed", "why": "Dòng \"Sunday: closed\" cho biết hiệu thuốc đóng cửa vào Chủ nhật."}, {"kind": "detail", "q": "What time does the pharmacy close on Saturday?", "opts": ["12 p.m.", "6 p.m.", "8 p.m.", "2 p.m."], "a": 0, "ev": "Saturday: 8 a.m. to 12 p.m.", "why": "Dòng \"Saturday: 8 a.m. to 12 p.m.\" cho biết 12 giờ trưa là giờ đóng cửa."}, {"kind": "vocab", "q": "In the text, what is a \"prescription\"?", "opts": ["A pharmacy shop", "A long queue", "A kind of ID card", "A paper from your doctor"], "a": 3, "ev": "A prescription is a paper from your doctor.", "why": "Văn bản tự giải thích: \"A prescription is a paper from your doctor.\" tức là đơn thuốc."}, {"kind": "tfng", "q": "The pharmacy is open on Sunday.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Sunday: closed", "why": "Văn bản ghi \"Sunday: closed\" nên câu này sai."}, {"kind": "tfng", "q": "The pharmacy sells vitamins.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản không nhắc đến vitamin hay sản phẩm bán nên là Not given."}], "notes": {"vocab": [["pharmacy", "hiệu thuốc", "pharmacist = dược sĩ"], ["prescription", "đơn thuốc", "a prescription from your doctor"], ["ID card", "thẻ căn cước/giấy tờ tùy thân", "ID = identity"], ["ill", "ốm, bệnh", "ill = sick"], ["wait in line", "xếp hàng chờ", "UK: queue"]], "grammar": [["Polite request: Please + verb (yêu cầu lịch sự)", "Please bring your prescription.", "Thêm Please trước động từ nguyên mẫu để yêu cầu một cách lịch sự."], ["Conditional with if (câu điều kiện)", "If you are ill, ask a friend to come.", "If + hiện tại đơn, rồi câu mệnh lệnh để đưa lời khuyên."]], "tips": ["Thông báo thường có tiêu đề in hoa; giờ giấc nằm ở phần liệt kê riêng, hãy đọc kỹ số và ngày.", "Từ Please cho biết đó là yêu cầu bạn cần làm."]}}, {"id": "rd5-a1-13", "lvl": "A1", "topic": "medical", "genre": "blog", "title": "Volunteer Diary: Day One at City Hospital", "text": "My First Day at the Hospital\n\nHello, everyone! Today was my first day as a volunteer at City Hospital. I was nervous, but the nurses were kind. My name tag says \"Volunteer\". I wore a white shirt and clean shoes.\n\nFirst, I washed my hands. Then I helped a nurse push a patient in a wheelchair. The patient smiled at me. I also took books to the children's ward. A little girl said, \"Thank you!\" I was very happy.\n\nI am tired now, but I want to go back tomorrow.", "gist": "Một tình nguyện viên kể về ngày đầu tiên ở bệnh viện: cô lo lắng nhưng vui và muốn quay lại.", "qs": [{"kind": "main", "q": "What is the blog about?", "opts": ["A nurse's job interview", "A long holiday", "A volunteer's first day at a hospital", "A new hospital building"], "a": 2, "ev": "Today was my first day as a volunteer at City Hospital.", "why": "Câu đầu cho biết đây là ngày đầu tiên làm tình nguyện viên ở bệnh viện."}, {"kind": "detail", "q": "What did she do first?", "opts": ["She took books to a ward", "She washed her hands", "She pushed a wheelchair", "She met a little girl"], "a": 1, "ev": "First, I washed my hands.", "why": "Văn bản nói \"First, I washed my hands.\" nên việc đầu tiên là rửa tay."}, {"kind": "detail", "q": "Where did she take books?", "opts": ["To the kitchen", "To the car park", "To the laboratory", "To the children's ward"], "a": 3, "ev": "I also took books to the children's ward.", "why": "Câu \"I also took books to the children's ward.\" cho biết cô mang sách đến khoa nhi."}, {"kind": "vocab", "q": "In the text, what does \"nervous\" mean?", "opts": ["A little afraid or worried", "Very happy", "Very tired", "Hungry"], "a": 0, "ev": "I was nervous, but the nurses were kind.", "why": "Nervous là lo lắng; từ \"but\" cho thấy sự đối lập với việc các y tá tốt bụng."}, {"kind": "tfng", "q": "The nurses were not kind.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "the nurses were kind", "why": "Văn bản nói \"the nurses were kind\" nên câu này sai."}, {"kind": "tfng", "q": "She is a medical student.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản không nói nghề nghiệp hay việc học của cô ấy nên là Not given."}], "notes": {"vocab": [["volunteer", "tình nguyện viên", "volunteer (n/v)"], ["nervous", "lo lắng, hồi hộp", "nervous about something"], ["wheelchair", "xe lăn", "wheel + chair"], ["ward", "khoa, buồng bệnh", "children's ward = khoa nhi"], ["patient", "bệnh nhân", "patient (n)"]], "grammar": [["Past simple (quá khứ đơn)", "I washed my hands.", "Động từ thêm -ed để kể việc đã xảy ra xong."], ["Irregular past (quá khứ bất quy tắc)", "I wore a white shirt and clean shoes.", "Wear thành wore, một động từ bất quy tắc cần học thuộc."], ["Sequence words (từ chỉ thứ tự)", "First, I washed my hands.", "First, Then, Also giúp nối các việc theo thứ tự."]], "tips": ["Blog kể chuyện cá nhân nên dùng I và quá khứ; ý chính thường nằm ở câu đầu.", "Chú ý các từ thứ tự như First và Then để theo dõi trình tự."]}}, {"id": "rd5-a1-14", "lvl": "A1", "topic": "medical", "genre": "notice", "title": "Ward 4 Visitor Guide", "text": "WARD 4: VISITING RULES\n\nVisiting hours are 2 p.m. to 4 p.m. and 6 p.m. to 8 p.m.\nOnly two visitors at one time.\nChildren under 12 cannot visit.\nWash your hands when you come in.\nSwitch off your phone or keep it quiet.\nDo not bring flowers or hot food.\nDo not sit on the bed.\nIf you have a cold or a fever, please do not visit.\nAsk the nurse if you have a question.\nThank you for your help.", "gist": "Thông báo nêu các quy định thăm bệnh nhân ở khoa 4 như giờ thăm, số người và vệ sinh.", "qs": [{"kind": "main", "q": "What is the main idea of the notice?", "opts": ["The rules for visiting patients", "A list of hospital jobs", "How to cook hospital food", "The history of the ward"], "a": 0, "ev": "WARD 4: VISITING RULES", "why": "Tiêu đề \"WARD 4: VISITING RULES\" cho biết đây là quy định thăm bệnh."}, {"kind": "detail", "q": "How many visitors can come at one time?", "opts": ["One", "Three", "Two", "Four"], "a": 2, "ev": "Only two visitors at one time.", "why": "Văn bản nói \"Only two visitors at one time.\" nên là hai người."}, {"kind": "detail", "q": "What must visitors do when they come in?", "opts": ["Take off their shoes", "Wash their hands", "Buy flowers", "Sign a paper"], "a": 1, "ev": "Wash your hands when you come in.", "why": "Câu \"Wash your hands when you come in.\" yêu cầu rửa tay khi vào."}, {"kind": "vocab", "q": "In the text, what does \"switch off\" mean?", "opts": ["Turn on", "Look at", "Throw away", "Turn off"], "a": 3, "ev": "Switch off your phone or keep it quiet.", "why": "Switch off là tắt (thiết bị); câu này yêu cầu tắt điện thoại hoặc để im lặng."}, {"kind": "tfng", "q": "Children of ten years can visit.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Children under 12 cannot visit.", "why": "Văn bản nói \"Children under 12 cannot visit.\" nên trẻ mười tuổi không được vào, câu này sai."}, {"kind": "tfng", "q": "Visitors can park their cars for free.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản không nhắc đến chỗ đậu xe nên là Not given."}], "notes": {"vocab": [["visiting hours", "giờ thăm bệnh", "visitor (n)"], ["switch off", "tắt (thiết bị)", "><switch on"], ["fever", "sốt", "have a fever"], ["cold", "cảm lạnh", "have a cold"], ["flowers", "những bông hoa", "flower (n)"]], "grammar": [["Negative imperative (mệnh lệnh phủ định)", "Do not sit on the bed.", "Do not + động từ để cấm hoặc nhắc không được làm."], ["Modal can/cannot (động từ khuyết thiếu)", "Children under 12 cannot visit.", "Cannot + động từ nguyên mẫu để nói điều không được phép."]], "tips": ["Nội quy thường là danh sách ngắn; chú ý từ phủ định như not và cannot vì chúng đổi nghĩa.", "Con số (2 p.m., two, 12) thường là đáp án của câu hỏi chi tiết."]}}, {"id": "rd5-a2-01", "lvl": "A2", "topic": "travel", "genre": "review", "title": "Three Quiet Nights at the Blue Door Hotel", "text": "Review: Lovely small hotel near the river (4 stars)\n\nWe stayed at the Blue Door Hotel for three nights in May. It is a small hotel with only twelve rooms, but the staff were very kind. When we arrived, the owner, Mrs Hale, gave us a cup of tea and showed us our room. The room was clean and quiet, and it had a big window with a view of the river.\n\nThe breakfast was good. There was fresh bread, eggs and fruit, and you can eat outside if the weather is nice. However, the Wi-Fi was slow, so I could not watch videos in the evening. Also, the bed was a little hard, but I slept well because the room was so quiet.\n\nThe hotel is ten minutes from the train station, so we walked there with our bags. It costs 60 euros a night, which is cheap for this city. I would stay here again, and I recommend it to anyone who wants a calm holiday.", "gist": "Người viết khen một khách sạn nhỏ, yên tĩnh, nhân viên thân thiện và giá rẻ, dù Wi-Fi chậm và giường hơi cứng.", "qs": [{"kind": "main", "q": "What is the writer's main opinion of the hotel?", "opts": ["It is too small for a holiday.", "It is a friendly, quiet hotel and the writer would go again.", "It is expensive and noisy.", "It is far from the train station."], "a": 1, "ev": "I would stay here again, and I recommend it to anyone who wants a calm holiday", "why": "Người viết nói sẽ ở lại lần nữa và giới thiệu cho người muốn kỳ nghỉ yên bình: \"I would stay here again...\"."}, {"kind": "detail", "q": "How many nights did the writer stay?", "opts": ["One", "Two", "Three", "Five"], "a": 2, "ev": "for three nights in May", "why": "Văn bản nói \"for three nights in May\", tức ba đêm."}, {"kind": "detail", "q": "What did the owner give the guests when they arrived?", "opts": ["A cup of tea", "A city map", "Fresh bread", "A free dinner"], "a": 0, "ev": "gave us a cup of tea", "why": "Chủ khách sạn \"gave us a cup of tea\" khi họ đến."}, {"kind": "vocab", "q": "In the text, what does 'calm' mean?", "opts": ["noisy", "expensive", "busy", "quiet and peaceful"], "a": 3, "ev": "a calm holiday", "why": "\"Calm holiday\" là kỳ nghỉ yên tĩnh, thanh bình, hợp với căn phòng \"so quiet\"."}, {"kind": "tfng", "q": "The Wi-Fi in the hotel was fast.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "the Wi-Fi was slow", "why": "Bài viết nói \"the Wi-Fi was slow\", nên câu này sai."}, {"kind": "tfng", "q": "The hotel has a swimming pool.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nhắc gì đến hồ bơi nên là Not given."}, {"kind": "tfng", "q": "The hotel is close to the train station.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "The hotel is ten minutes from the train station", "why": "Bài nói khách sạn cách ga mười phút đi bộ: \"ten minutes from the train station\"."}], "notes": {"vocab": [["recommend", "giới thiệu, khuyên dùng", "recommend sth to sb"], ["view", "tầm nhìn, cảnh nhìn thấy", "a view of the river"], ["fresh", "tươi, mới"], ["however", "tuy nhiên", "từ nối chỉ sự tương phản"], ["cheap", "rẻ", "trái nghĩa: expensive"], ["calm", "yên bình, thanh bình"]], "grammar": [["so for result (liên từ chỉ kết quả)", "However, the Wi-Fi was slow, so I could not watch videos in the evening.", "\"So\" nối nguyên nhân với kết quả: Wi-Fi chậm nên không xem được video."], ["First conditional (câu điều kiện loại 1)", "you can eat outside if the weather is nice", "Mệnh đề if dùng hiện tại đơn, mệnh đề chính dùng can để nói khả năng có thật."], ["Relative clause with which (mệnh đề quan hệ)", "It costs 60 euros a night, which is cheap for this city.", "\"Which\" thêm thông tin về cả mệnh đề trước, ở đây là giá tiền."]], "tips": ["Với bài review, đọc câu cuối trước vì người viết thường nêu ý kiến chung ở đó (recommend / would stay again).", "Chú ý từ nối however, but, also để tách ý khen và ý chê."]}}, {"id": "rd5-a2-02", "lvl": "A2", "topic": "daily", "genre": "email", "title": "A Cold Soup and the Wrong Burger", "text": "Subject: Wrong order on Saturday evening\n\nDear Manager,\n\nI am writing about my dinner at your restaurant, Green Spoon, last Saturday. My family and I came at about 7 p.m. and we were happy with the friendly waiter and the nice table by the window.\n\nUnfortunately, there was a problem with our order. I asked for the vegetable soup and a chicken salad, but the waiter brought a beef burger and chips. I told him about the mistake, and he said sorry. However, we waited another thirty minutes for the right food, and my soup was cold when it arrived.\n\nI understand that the restaurant was busy, so I am not angry. But I would like to ask for some money back for the extra waiting time. I have kept the bill, and I can send a photo of it.\n\nThank you for your help. I hope to hear from you soon.\n\nKind regards,\nLena Moreau", "gist": "Lena viết email lịch sự phàn nàn về món ăn bị mang nhầm và thời gian chờ lâu, rồi xin hoàn lại một ít tiền.", "qs": [{"kind": "main", "q": "Why does Lena write the email?", "opts": ["To book a table", "To thank the waiter", "To complain about a wrong order and ask for some money back", "To ask for a job"], "a": 2, "ev": "I would like to ask for some money back for the extra waiting time", "why": "Lena muốn phàn nàn về món sai và xin lại tiền: \"I would like to ask for some money back...\"."}, {"kind": "detail", "q": "What did Lena order?", "opts": ["A beef burger and chips", "Vegetable soup and a chicken salad", "Fish and rice", "A pizza"], "a": 1, "ev": "I asked for the vegetable soup and a chicken salad", "why": "Cô gọi súp rau và salad gà: \"the vegetable soup and a chicken salad\"."}, {"kind": "detail", "q": "How long did the family wait for the right food?", "opts": ["Ten minutes", "Twenty minutes", "One hour", "Thirty minutes"], "a": 3, "ev": "we waited another thirty minutes for the right food", "why": "Bài viết nói họ chờ thêm \"thirty minutes\", tức 30 phút."}, {"kind": "vocab", "q": "In the text, what does 'Unfortunately' mean?", "opts": ["Sadly; not luckily", "Happily", "Quickly", "Politely"], "a": 0, "ev": "Unfortunately, there was a problem with our order", "why": "\"Unfortunately\" mở đầu cho điều không may (có vấn đề với món ăn), nghĩa là đáng tiếc."}, {"kind": "tfng", "q": "Lena was angry with the restaurant.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "so I am not angry", "why": "Lena viết \"I am not angry\" nên câu này sai."}, {"kind": "tfng", "q": "Lena has been to the restaurant before.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói cô đã đến nhà hàng trước đó hay chưa nên là Not given."}, {"kind": "tfng", "q": "The waiter said sorry for the mistake.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "he said sorry", "why": "Bài viết nói người phục vụ \"said sorry\" nên câu này đúng."}], "notes": {"vocab": [["unfortunately", "đáng tiếc là", "trái nghĩa: luckily"], ["mistake", "lỗi, sự nhầm lẫn", "make a mistake"], ["extra", "thêm, phụ"], ["bill", "hóa đơn", "dùng trong nhà hàng"], ["busy", "đông, bận rộn"], ["kept", "giữ (quá khứ của keep)"]], "grammar": [["would like to (lời yêu cầu lịch sự)", "But I would like to ask for some money back for the extra waiting time.", "\"Would like to\" lịch sự hơn \"want to\", thường dùng trong email phàn nàn."], ["Past simple + but (quá khứ đơn và liên từ but)", "I asked for the vegetable soup and a chicken salad, but the waiter brought a beef burger and chips.", "Hai hành động quá khứ được nối bằng \"but\" để chỉ sự trái ngược giữa món gọi và món nhận."], ["Present perfect (hiện tại hoàn thành)", "I have kept the bill, and I can send a photo of it.", "Dùng have + quá khứ phân từ để nói điều đã làm và còn liên quan đến hiện tại."]], "tips": ["Trong email phàn nàn, tìm vấn đề ở đoạn giữa (Unfortunately, However) và yêu cầu ở đoạn sau (I would like to...).", "Đọc dòng Subject trước để đoán nội dung chính của email."]}}, {"id": "rd5-a2-03", "lvl": "A2", "topic": "work", "genre": "notice", "title": "Café Bloom: New Hours While the Kitchen Is Painted", "text": "NOTICE TO ALL STAFF\nChange to the work schedule: next week (Monday 10 to Friday 14)\n\nPlease read this notice carefully.\n\nBecause the main kitchen will be painted next week, the Café Bloom team will work different hours. The café will open at 10 a.m. instead of 8 a.m. from Monday to Wednesday. On Thursday and Friday, it will open at the normal time.\n\nEarly shift staff (Anna, Tom and Ravi) will start at 9 a.m. and finish at 5 p.m. Late shift staff (Mia and Omar) will not work on Monday, but they will work a full day on Saturday.\n\nIf you cannot work on your new day, please tell Ms Park before Friday this week. You can find her in the office or send her a message. Do not ask other staff to change with you until she says yes.\n\nThank you for your help.\nMs Park, Manager", "gist": "Thông báo cho nhân viên về việc đổi giờ làm việc tuần tới vì bếp chính được sơn lại.", "qs": [{"kind": "main", "q": "What is the notice mainly about?", "opts": ["A new menu", "A staff party", "New people joining the team", "Changes to work hours next week"], "a": 3, "ev": "the Café Bloom team will work different hours", "why": "Thông báo nói đội ngũ sẽ làm việc giờ khác: \"will work different hours\"."}, {"kind": "detail", "q": "Why is the schedule changing?", "opts": ["The kitchen will be painted.", "The café will close for a month.", "The manager is on holiday.", "There will be new machines."], "a": 0, "ev": "Because the main kitchen will be painted next week", "why": "Lý do là \"the main kitchen will be painted\", tức bếp chính sẽ được sơn."}, {"kind": "detail", "q": "When will the café open on Thursday and Friday?", "opts": ["At 10 a.m.", "At 9 a.m.", "At the normal time", "It will stay closed."], "a": 2, "ev": "On Thursday and Friday, it will open at the normal time.", "why": "Thứ Năm và thứ Sáu quán mở \"at the normal time\", tức giờ bình thường."}, {"kind": "vocab", "q": "In the text, what does 'normal' mean?", "opts": ["strange", "usual", "late", "short"], "a": 1, "ev": "it will open at the normal time", "why": "\"Normal time\" là giờ thường lệ, tức \"usual\"."}, {"kind": "tfng", "q": "Mia and Omar will work on Monday.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Late shift staff (Mia and Omar) will not work on Monday", "why": "Bài nói Mia và Omar \"will not work on Monday\" nên câu này sai."}, {"kind": "tfng", "q": "The painting will cost a lot of money.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói gì về chi phí sơn nên là Not given."}, {"kind": "tfng", "q": "Staff who cannot work on their new day must tell Ms Park before Friday this week.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "please tell Ms Park before Friday this week", "why": "Nhân viên không đi làm được phải báo cho Ms Park trước thứ Sáu tuần này."}], "notes": {"vocab": [["notice", "thông báo", "a notice board"], ["schedule", "lịch làm việc"], ["shift", "ca làm việc", "early shift / late shift"], ["instead of", "thay vì"], ["finish", "kết thúc"], ["carefully", "cẩn thận", "tính từ: careful"]], "grammar": [["Future passive (bị động tương lai)", "Because the main kitchen will be painted next week", "Cấu trúc will + be + quá khứ phân từ dùng cho việc sẽ được làm trong tương lai."], ["instead of (thay vì)", "The café will open at 10 a.m. instead of 8 a.m. from Monday to Wednesday.", "\"Instead of\" cho biết giờ mới thay cho giờ cũ."], ["Conditional + polite imperative (điều kiện và câu mệnh lệnh lịch sự)", "If you cannot work on your new day, please tell Ms Park before Friday this week.", "Mệnh đề if nêu tình huống, mệnh đề sau là chỉ dẫn với please."]], "tips": ["Với thông báo, đọc tiêu đề và câu đầu để biết chủ đề, rồi tìm ngày giờ và tên người.", "Chú ý các từ chỉ mốc thời gian như from Monday to Wednesday, before Friday để trả lời câu hỏi chi tiết."]}}, {"id": "rd5-a2-04", "lvl": "A2", "topic": "society", "genre": "blog", "title": "My Saturdays at the Riverside Food Bank", "text": "Last month I started volunteering at the Riverside Food Bank, and I want to tell you about it. A food bank collects food and gives it to families who cannot buy enough.\n\nEvery Saturday I arrive at nine o'clock. First, we open the boxes of rice, tins and vegetables that people gave us during the week. Then I check the dates on the tins, because we cannot give out old food. After that, I put the food in bags. Yesterday we made sixty bags!\n\nAt first I was nervous because I did not know anyone. But the other volunteers were friendly, and an older man called Mr Dang taught me everything. The best part is meeting the families. Last week a small girl said thank you and gave me a drawing. I felt very happy.\n\nIf you have a free morning, you should try it too. You do not need any special skills.", "gist": "Người viết kể về việc làm tình nguyện ở ngân hàng thực phẩm vào các sáng thứ Bảy và khuyến khích người khác thử.", "qs": [{"kind": "main", "q": "What is the blog mainly about?", "opts": ["The writer's experience as a food bank volunteer", "How to cook rice and vegetables", "A school project about families", "A new job in a shop"], "a": 0, "ev": "Last month I started volunteering at the Riverside Food Bank", "why": "Bài kể việc người viết làm tình nguyện ở ngân hàng thực phẩm: \"started volunteering at the Riverside Food Bank\"."}, {"kind": "detail", "q": "What does the writer do after checking the dates?", "opts": ["Cooks lunch", "Takes food to homes", "Puts the food in bags", "Counts money"], "a": 2, "ev": "After that, I put the food in bags.", "why": "Sau khi kiểm tra ngày, người viết \"put the food in bags\", tức cho thức ăn vào túi."}, {"kind": "detail", "q": "Who taught the writer what to do?", "opts": ["A small girl", "Mr Dang", "The manager", "A teacher"], "a": 1, "ev": "an older man called Mr Dang taught me everything", "why": "Ông Dang dạy mọi thứ: \"Mr Dang taught me everything\"."}, {"kind": "vocab", "q": "In the text, what does 'nervous' mean?", "opts": ["angry", "tired", "bored", "worried and a little afraid"], "a": 3, "ev": "At first I was nervous because I did not know anyone.", "why": "Người viết lo lắng vì không quen ai, nên \"nervous\" là lo lắng, hơi sợ."}, {"kind": "tfng", "q": "The writer works at the food bank every Sunday.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Every Saturday I arrive at nine o'clock.", "why": "Bài nói \"Every Saturday\", không phải Chủ nhật nên câu này sai."}, {"kind": "tfng", "q": "The food bank is open every day of the week.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói ngân hàng thực phẩm mở cửa những ngày nào nên là Not given."}, {"kind": "tfng", "q": "A small girl gave the writer a drawing.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "a small girl said thank you and gave me a drawing", "why": "Một bé gái nói cảm ơn và tặng bản vẽ: \"gave me a drawing\"."}], "notes": {"vocab": [["volunteering", "làm tình nguyện", "volunteer (n): tình nguyện viên"], ["collects", "thu thập, quyên góp"], ["tins", "hộp thiếc (đồ hộp)"], ["nervous", "lo lắng"], ["taught", "đã dạy (quá khứ của teach)"], ["special skills", "kỹ năng đặc biệt"]], "grammar": [["Past simple + verb-ing (quá khứ đơn và danh động từ)", "Last month I started volunteering at the Riverside Food Bank", "Sau start có thể dùng động từ thêm -ing; started là quá khứ đơn vì việc xảy ra tháng trước."], ["Past participle phrase (cụm quá khứ phân từ)", "an older man called Mr Dang taught me everything", "\"Called Mr Dang\" bổ nghĩa cho \"man\", nghĩa là người đàn ông tên là Dang."], ["First conditional with should (điều kiện và lời khuyên)", "If you have a free morning, you should try it too.", "If + hiện tại đơn, rồi dùng should để đưa ra lời khuyên."]], "tips": ["Blog cá nhân thường kể theo thứ tự thời gian, hãy chú ý các từ First, Then, After that, At first.", "Câu cuối bài thường là lời khuyên hoặc kết luận của người viết."]}}, {"id": "rd5-a2-05", "lvl": "A2", "topic": "education", "genre": "dialogue", "title": "Can I Hand In My History Project on Friday?", "text": "Ms Carter: Hello, Minh. Do you need something?\nMinh: Yes, Ms Carter. Can I ask about the history homework? The deadline is tomorrow, but I am not ready.\nMs Carter: What is the problem?\nMinh: I was ill on Monday and Tuesday, so I missed the lesson about the project. Also, my computer broke last night.\nMs Carter: I am sorry to hear that. Have you started writing?\nMinh: Yes, I have written one page, but I need two more.\nMs Carter: I see. Do you think you can finish by Friday?\nMinh: Yes, I think so. If I use the school library computer, I can finish by Thursday evening.\nMs Carter: Okay. You can hand it in on Friday morning, but please bring a note from your parents about your illness.\nMinh: Thank you very much. I will bring it.\nMs Carter: And next time, please ask me earlier. Teachers can often help if they know the problem in advance.\nMinh: I understand. I am sorry.\nMs Carter: No problem. Good luck with the project.", "gist": "Minh xin cô giáo gia hạn bài tập lịch sử vì bị ốm và hỏng máy tính, và cô đồng ý cho nộp vào thứ Sáu.", "qs": [{"kind": "main", "q": "What does Minh want from Ms Carter?", "opts": ["A better grade", "A new computer", "More time for his homework", "A different project"], "a": 2, "ev": "The deadline is tomorrow, but I am not ready.", "why": "Minh chưa sẵn sàng khi hạn nộp là ngày mai nên cần thêm thời gian cho bài tập."}, {"kind": "detail", "q": "Why did Minh miss the lesson about the project?", "opts": ["He was ill.", "He was late.", "He had a trip.", "He forgot."], "a": 0, "ev": "I was ill on Monday and Tuesday, so I missed the lesson about the project", "why": "Minh bị ốm hai ngày nên bỏ lỡ bài học: \"I was ill on Monday and Tuesday\"."}, {"kind": "detail", "q": "How many more pages does Minh need to write?", "opts": ["One", "Three", "Four", "Two"], "a": 3, "ev": "I have written one page, but I need two more.", "why": "Minh đã viết một trang và cần thêm \"two more\", tức hai trang."}, {"kind": "vocab", "q": "In the text, what does 'hand it in' mean?", "opts": ["throw it away", "give it to the teacher", "write it again", "read it aloud"], "a": 1, "ev": "You can hand it in on Friday morning", "why": "\"Hand it in\" là nộp bài cho giáo viên."}, {"kind": "tfng", "q": "Ms Carter says Minh cannot have more time.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "You can hand it in on Friday morning", "why": "Cô nói Minh có thể nộp vào sáng thứ Sáu nên câu này sai."}, {"kind": "tfng", "q": "Minh walks to school every day.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói Minh đến trường bằng cách nào nên là Not given."}, {"kind": "tfng", "q": "Ms Carter wants a note from Minh's parents.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "please bring a note from your parents about your illness", "why": "Cô yêu cầu Minh mang giấy của phụ huynh: \"bring a note from your parents\"."}], "notes": {"vocab": [["deadline", "hạn chót", "meet a deadline: kịp hạn"], ["missed", "bỏ lỡ"], ["hand it in", "nộp bài", "cụm động từ"], ["illness", "bệnh, sự ốm", "tính từ: ill"], ["in advance", "trước, sớm", "ask in advance"], ["library", "thư viện"]], "grammar": [["Present perfect question (câu hỏi hiện tại hoàn thành)", "Have you started writing?", "Have + chủ ngữ + quá khứ phân từ để hỏi về việc đã làm đến lúc này."], ["First conditional (điều kiện loại 1)", "If I use the school library computer, I can finish by Thursday evening.", "If + hiện tại đơn, mệnh đề chính dùng can để nói khả năng có thể xảy ra."], ["Present perfect with but (hiện tại hoàn thành và liên từ but)", "I have written one page, but I need two more.", "Nêu kết quả đã đạt, sau đó nói phần còn thiếu bằng \"but\"."]], "tips": ["Với hội thoại, theo dõi ai nói gì bằng tên ở đầu dòng và chú ý lý do, đề nghị, câu trả lời.", "Câu trả lời của giáo viên thường chứa quyết định cuối cùng; hãy đọc kỹ các câu có can, please."]}}, {"id": "rd5-a2-06", "lvl": "A2", "topic": "culture", "genre": "article", "title": "Taste of Harbour Town: A Weekend of Food", "text": "Every year, in the first weekend of September, the people of Harbour Town hold a food festival. This year it will be on 6 and 7 September, and more than fifty stalls will sell food from local farms and families.\n\nThe festival started twenty years ago, when a group of neighbours cooked soup in the main square. Now thousands of people come. Visitors can try fish stew, fresh bread, cheese and sweet cakes. Many stalls also give free small tastes, so you can try before you buy.\n\nThere is more than food. Children can join a cooking class on Saturday morning, and a local band plays music on both evenings. The festival is also good for the town because the money helps the school and the library.\n\nEntry is free, but you should bring cash because some stalls do not take cards. The festival opens at 10 a.m. and closes at 9 p.m. Try to arrive early, because the best food often finishes by the afternoon.", "gist": "Bài báo giới thiệu lễ hội ẩm thực hằng năm của thị trấn Harbour Town với nhiều gian hàng, lớp nấu ăn và âm nhạc.", "qs": [{"kind": "main", "q": "What is the article mainly about?", "opts": ["The history of fishing in a town", "A yearly food festival with food, classes and music", "A new school for cooking", "A farm that sells cheese"], "a": 1, "ev": "the people of Harbour Town hold a food festival", "why": "Bài giới thiệu lễ hội ẩm thực của thị trấn: \"hold a food festival\"."}, {"kind": "detail", "q": "How did the festival begin?", "opts": ["A band played music", "A cooking class opened", "A school asked for money", "Neighbours cooked soup in the main square"], "a": 3, "ev": "a group of neighbours cooked soup in the main square", "why": "Lễ hội bắt đầu khi hàng xóm nấu súp ở quảng trường chính."}, {"kind": "detail", "q": "Why should visitors bring cash?", "opts": ["Some stalls do not take cards.", "Entry costs a lot.", "The band asks for money.", "The library sells tickets."], "a": 0, "ev": "some stalls do not take cards", "why": "Một số gian hàng không nhận thẻ: \"some stalls do not take cards\"."}, {"kind": "vocab", "q": "In the text, what are 'stalls'?", "opts": ["classrooms", "farms", "small tables or shops where things are sold", "tickets"], "a": 2, "ev": "more than fifty stalls will sell food", "why": "\"Stalls\" là các gian hàng nhỏ bán đồ ăn tại lễ hội."}, {"kind": "tfng", "q": "Visitors must pay to enter the festival.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Entry is free", "why": "Bài nói \"Entry is free\" nên câu này sai."}, {"kind": "tfng", "q": "The festival has a prize for the best cook.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nhắc đến giải thưởng cho đầu bếp nên là Not given."}, {"kind": "tfng", "q": "Some stalls give free small tastes.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "Many stalls also give free small tastes", "why": "Nhiều gian hàng cho nếm thử miễn phí: \"give free small tastes\"."}], "notes": {"vocab": [["stalls", "gian hàng"], ["local", "thuộc địa phương"], ["neighbours", "hàng xóm"], ["visitors", "du khách"], ["entry", "việc vào cửa", "entry fee: phí vào cửa"], ["cash", "tiền mặt", "pay by cash / card"]], "grammar": [["so + can (kết quả)", "Many stalls also give free small tastes, so you can try before you buy.", "\"So\" cho biết kết quả: có nếm thử miễn phí nên bạn có thể thử trước khi mua."], ["Past simple with when (quá khứ đơn và mệnh đề when)", "The festival started twenty years ago, when a group of neighbours cooked soup in the main square.", "Mệnh đề when cho biết thời điểm trong quá khứ khi lễ hội bắt đầu."], ["Imperative + because (câu mệnh lệnh và lý do)", "Try to arrive early, because the best food often finishes by the afternoon.", "Lời khuyên dạng mệnh lệnh kèm lý do bắt đầu bằng because."]], "tips": ["Bài báo giới thiệu sự kiện thường có thông tin thực tế (ngày, giờ, giá vé) ở cuối bài, hãy đọc kỹ cho câu hỏi chi tiết.", "Mỗi đoạn có một ý chính: giới thiệu, lịch sử và món ăn, hoạt động khác, lời khuyên."]}}, {"id": "rd5-a2-07", "lvl": "A2", "topic": "technology", "genre": "forum", "title": "Help! My Phone Has Become So Slow", "text": "Question from Lan_92: My phone is very slow now. It was fast last year, but now apps open slowly and the battery finishes by afternoon. I have about 200 photos and many games. What can I do? I don't have much money for a new phone.\n\nReply from Mark_T: Check your storage first. When a phone is almost full, it becomes slow. Delete old photos or move them to a computer. Also delete games you don't play.\n\nReply from Hoa_Nguyen: I had the same problem. I turned the phone off and on every week, and it helped a lot. Also update your apps, because old apps can be slow.\n\nReply from Sam_K: Be careful with free \"speed\" apps. Some of them show many advertisements and make the phone slower. If nothing works, ask a shop to look at the battery. A new battery costs less than a new phone.\n\nLan_92: Thank you all! I deleted 60 photos and two games. My phone is faster today.", "gist": "Một người dùng hỏi cách làm điện thoại chạy nhanh hơn và nhận được vài lời khuyên hữu ích từ diễn đàn.", "qs": [{"kind": "main", "q": "What is the forum thread mainly about?", "opts": ["Where to buy a cheap new phone", "How to make a slow phone work better", "Which games are the best for phones", "Why photos are important"], "a": 1, "ev": "My phone is very slow now.", "why": "Chủ đề xoay quanh việc điện thoại chạy chậm và cách khắc phục: \"My phone is very slow now.\""}, {"kind": "detail", "q": "What happens when a phone is almost full, according to Mark_T?", "opts": ["It becomes slow", "It turns off", "The battery gets bigger", "The photos disappear"], "a": 0, "ev": "When a phone is almost full, it becomes slow.", "why": "Mark_T nói: \"When a phone is almost full, it becomes slow.\""}, {"kind": "detail", "q": "How often did Hoa_Nguyen turn her phone off and on?", "opts": ["Every day", "Every month", "Every two weeks", "Every week"], "a": 3, "ev": "I turned the phone off and on every week", "why": "Hoa viết: \"I turned the phone off and on every week\"."}, {"kind": "detail", "q": "What does Sam_K say about a new battery?", "opts": ["It is very difficult to find", "It is more expensive than a new phone", "It costs less than a new phone", "It makes the phone slower"], "a": 2, "ev": "A new battery costs less than a new phone.", "why": "Sam_K nói pin mới rẻ hơn điện thoại mới: \"A new battery costs less than a new phone.\""}, {"kind": "vocab", "q": "In the text, what does \"advertisements\" mean?", "opts": ["Messages from friends", "Short videos or pictures that try to sell things", "Warnings about the battery", "Free games"], "a": 1, "ev": "Some of them show many advertisements", "why": "\"Advertisements\" là quảng cáo, những thứ cố gắng bán hàng, như trong câu \"Some of them show many advertisements\"."}, {"kind": "tfng", "q": "Lan_92 has a lot of money for a new phone.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "I don't have much money for a new phone.", "why": "Lan viết: \"I don't have much money for a new phone.\" nên câu này sai."}, {"kind": "tfng", "q": "Lan_92 is a university student.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói Lan có phải sinh viên hay không nên đáp án là Not given."}], "notes": {"vocab": [["storage", "bộ nhớ, dung lượng lưu trữ", "check storage = kiểm tra dung lượng"], ["delete", "xóa", "trái nghĩa: save"], ["update", "cập nhật", "update your apps"], ["advertisements", "quảng cáo", "viết tắt: ads"], ["battery", "viên pin", "battery life = thời lượng pin"], ["faster", "nhanh hơn", "so sánh hơn của fast"]], "grammar": [["Comparative (so sánh hơn)", "My phone is faster today.", "faster là dạng so sánh hơn của fast, dùng để so sánh điện thoại hôm nay với trước đây."], ["Past simple (quá khứ đơn)", "I deleted 60 photos and two games.", "deleted là quá khứ đơn của delete, kể hành động đã xong."], ["Imperative (câu mệnh lệnh)", "Delete old photos or move them to a computer.", "Câu mệnh lệnh bắt đầu bằng động từ nguyên mẫu, dùng để đưa lời khuyên."]], "tips": ["Với bài diễn đàn, đọc câu hỏi đầu tiên để biết vấn đề, rồi mỗi câu trả lời thường đưa ra một giải pháp khác nhau.", "Chú ý tên người đăng (Mark_T, Hoa_Nguyen, Sam_K) để biết ai nói điều gì khi trả lời câu hỏi chi tiết."]}}, {"id": "rd5-a2-08", "lvl": "A2", "topic": "environment", "genre": "instructions", "title": "Five Easy Steps for Recycling in Your Home", "text": "Recycling at home is easy. Follow these steps.\n\nStep 1: Get three boxes or bags. Put one in the kitchen, one in the living room and one near the door.\n\nStep 2: Sort your rubbish. Put paper and cardboard in the first box. Put plastic bottles and cans in the second box. Put glass in the third box. Food waste goes in a different bin.\n\nStep 3: Clean everything. Wash bottles and cans with water. Dirty things can spoil the other items in the box.\n\nStep 4: Make things small. Flatten boxes and press plastic bottles, so they take less space.\n\nStep 5: Take the boxes outside every Tuesday. The recycling truck comes at 7 a.m., so don't be late.\n\nRemember: never put plastic bags in the paper box. If you are not sure about something, ask your local office.", "gist": "Hướng dẫn năm bước đơn giản để phân loại và tái chế rác tại nhà.", "qs": [{"kind": "main", "q": "What is the text mainly about?", "opts": ["How to cook with less food", "How to build a recycling truck", "How to recycle rubbish at home", "How to clean a kitchen"], "a": 2, "ev": "Recycling at home is easy. Follow these steps.", "why": "Câu đầu cho biết chủ đề: \"Recycling at home is easy. Follow these steps.\""}, {"kind": "detail", "q": "Where do you put plastic bottles and cans?", "opts": ["In the first box", "In the second box", "In the third box", "In a different bin"], "a": 1, "ev": "Put plastic bottles and cans in the second box.", "why": "Chai nhựa và lon bỏ vào hộp thứ hai: \"Put plastic bottles and cans in the second box.\""}, {"kind": "detail", "q": "When does the recycling truck come?", "opts": ["On Tuesday at 7 a.m.", "On Sunday at 7 a.m.", "On Tuesday at 7 p.m.", "Every day at noon"], "a": 0, "ev": "Take the boxes outside every Tuesday. The recycling truck comes at 7 a.m.", "why": "Bài nói \"every Tuesday\" và \"at 7 a.m.\"."}, {"kind": "detail", "q": "Why should you wash bottles and cans?", "opts": ["To make them heavier", "Because dirty things can spoil other items", "Because the truck driver asks for it", "To save water"], "a": 1, "ev": "Dirty things can spoil the other items in the box.", "why": "Bài giải thích: \"Dirty things can spoil the other items in the box.\""}, {"kind": "vocab", "q": "In the text, what does \"flatten\" mean?", "opts": ["Make something full", "Make something hot", "Make something flat", "Make something dirty"], "a": 2, "ev": "Flatten boxes and press plastic bottles", "why": "\"Flatten\" nghĩa là làm cho phẳng, giúp chiếm ít chỗ hơn."}, {"kind": "tfng", "q": "Food waste goes in the third box.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Food waste goes in a different bin.", "why": "Rác thực phẩm bỏ vào thùng khác: \"Food waste goes in a different bin.\" nên câu này sai."}, {"kind": "tfng", "q": "Recycling is free in every town.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói gì về chi phí tái chế nên đáp án là Not given."}], "notes": {"vocab": [["recycling", "tái chế", "recycle (v), recycling (n)"], ["sort", "phân loại", "sort rubbish = phân loại rác"], ["cardboard", "bìa các-tông", ""], ["spoil", "làm hỏng", "spoil the items = làm hỏng đồ"], ["flatten", "làm phẳng, dẹp lại", "flat (adj) + -en"], ["rubbish", "rác", "tiếng Anh Mỹ: trash/garbage"]], "grammar": [["Imperative (câu mệnh lệnh)", "Put paper and cardboard in the first box.", "Dùng động từ nguyên mẫu ở đầu câu để ra chỉ dẫn từng bước."], ["Negative imperative (mệnh lệnh phủ định)", "never put plastic bags in the paper box", "never + động từ nguyên mẫu để cấm hoặc cảnh báo."], ["so (chỉ kết quả)", "The recycling truck comes at 7 a.m., so don't be late.", "so nối kết quả: xe đến sớm nên đừng đến muộn."]], "tips": ["Văn bản hướng dẫn chia thành Step 1, 2, 3...; hãy dùng số bước để tìm nhanh thông tin chi tiết.", "Mỗi bước thường bắt đầu bằng một động từ (Get, Sort, Clean...), đọc động từ đầu câu là hiểu việc cần làm."]}}, {"id": "rd5-a2-09", "lvl": "A2", "topic": "daily", "genre": "story", "title": "The Brown Wallet on the Bus", "text": "Last Friday, Minh was on the bus after work. He was tired, and he sat near the window. At the next stop, an old man got off. Minh saw a brown wallet on the seat.\n\nMinh opened it. There was 500,000 dong and a small card inside. The card said, \"Mr Hung, 14 Lake Street.\" Minh felt worried. \"This man needs his money,\" he thought.\n\nHe got off at the next stop and walked to Lake Street. It took twenty minutes. Number 14 was a small blue house. Minh knocked on the door, and Mr Hung opened it.\n\n\"Is this your wallet?\" Minh asked.\n\nMr Hung looked at it and smiled. \"Yes! I lost it an hour ago. I was so afraid. Thank you!\"\n\nHe wanted to give Minh some money, but Minh said no. Then Mr Hung made tea for him, and they talked for a long time. Minh went home happy that night.", "gist": "Minh nhặt được một chiếc ví trên xe buýt và mang trả lại tận nhà cho chủ nhân.", "qs": [{"kind": "main", "q": "What is the story mainly about?", "opts": ["A man who loses his job", "A young man who returns a lost wallet", "A bus that is late", "A man who wins money"], "a": 1, "ev": "Minh saw a brown wallet on the seat.", "why": "Câu chuyện kể Minh thấy ví và mang trả lại cho người mất."}, {"kind": "detail", "q": "Where did Minh find the wallet?", "opts": ["On the street", "On a table at work", "On a seat on the bus", "In a blue house"], "a": 2, "ev": "Minh saw a brown wallet on the seat.", "why": "Minh thấy ví trên ghế: \"Minh saw a brown wallet on the seat.\""}, {"kind": "detail", "q": "How did Minh find the owner's address?", "opts": ["From a card inside the wallet", "From a friend", "From the bus driver", "From a phone book"], "a": 0, "ev": "The card said, \"Mr Hung, 14 Lake Street.\"", "why": "Thẻ trong ví ghi tên và địa chỉ: \"Mr Hung, 14 Lake Street.\""}, {"kind": "detail", "q": "How long did Minh walk to Lake Street?", "opts": ["Ten minutes", "Twenty minutes", "An hour", "Two hours"], "a": 1, "ev": "It took twenty minutes.", "why": "Bài nói rõ \"It took twenty minutes.\""}, {"kind": "vocab", "q": "In the text, what does \"worried\" mean?", "opts": ["Very happy", "Very angry", "Afraid or anxious about a problem", "Very hungry"], "a": 2, "ev": "Minh felt worried.", "why": "\"Worried\" nghĩa là lo lắng, vì Minh nghĩ người đàn ông cần tiền của mình."}, {"kind": "tfng", "q": "Minh kept the money from the wallet.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Minh opened it. There was 500,000 dong and a small card inside.", "why": "Minh mang cả ví đến trả cho ông Hùng và còn từ chối tiền thưởng nên câu này sai."}, {"kind": "tfng", "q": "Mr Hung is a teacher.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói nghề nghiệp của ông Hùng nên đáp án là Not given."}], "notes": {"vocab": [["wallet", "ví (tiền)", "khác với purse: ví của phụ nữ"], ["worried", "lo lắng", "worried about something"], ["knocked", "gõ (cửa)", "knock on the door"], ["afraid", "sợ, lo", "I was so afraid"], ["lost", "đã làm mất", "lose - lost - lost"], ["seat", "chỗ ngồi, ghế", ""]], "grammar": [["Past simple (quá khứ đơn)", "Minh opened it.", "Động từ có -ed kể lại hành động đã hoàn thành trong câu chuyện."], ["Past continuous (quá khứ tiếp diễn)", "He was tired, and he sat near the window.", "was tired mô tả trạng thái nền, còn sat là hành động chính."], ["Irregular verb (động từ bất quy tắc)", "I lost it an hour ago.", "lost là quá khứ của lose; ago dùng với quá khứ đơn."]], "tips": ["Truyện kể theo thứ tự thời gian; chú ý các từ như Last Friday, At the next stop, Then để theo dõi diễn biến.", "Câu hỏi detail thường hỏi nơi chốn, thời gian, con số; hãy gạch chân những chi tiết đó khi đọc."]}}, {"id": "rd5-a2-10", "lvl": "A2", "topic": "medical", "genre": "leaflet", "title": "Know Your Body: Heart, Vessels and Lungs", "text": "KNOW YOUR BODY: Heart, Blood Vessels and Lungs\n\nWhat does the heart do?\nYour heart is a strong muscle. It is about the size of your fist. It has four rooms. The two top rooms are called atria, and the two bottom rooms are called ventricles. The heart works like a pump and pushes blood around your body.\n\nWhat are blood vessels?\nBlood vessels are small tubes. Arteries carry blood away from the heart. Veins bring blood back to the heart. Blood carries oxygen and food to every part of the body.\n\nWhat do the lungs do?\nYou have two lungs in your chest. When you breathe in, air goes down a tube and into the lungs. Inside the lungs, there are very small air bags called alveoli. Oxygen moves from the alveoli into the blood. Then the blood goes to the heart, and the heart pumps it to the body.\n\nHealthy tip: Walk for thirty minutes every day. This helps your heart and lungs stay strong.", "gist": "Tờ rơi giải thích đơn giản về tim, mạch máu và phổi, cùng lời khuyên đi bộ mỗi ngày.", "qs": [{"kind": "main", "q": "What is the leaflet mainly about?", "opts": ["How to cook healthy food", "How the heart, blood vessels and lungs work", "How to treat a broken bone", "How to measure a fist"], "a": 1, "ev": "KNOW YOUR BODY: Heart, Blood Vessels and Lungs", "why": "Tiêu đề tờ rơi cho biết chủ đề: \"KNOW YOUR BODY: Heart, Blood Vessels and Lungs\"."}, {"kind": "detail", "q": "What are the two bottom rooms of the heart called?", "opts": ["Atria", "Veins", "Alveoli", "Ventricles"], "a": 3, "ev": "the two bottom rooms are called ventricles", "why": "Hai buồng dưới gọi là tâm thất: \"the two bottom rooms are called ventricles\"."}, {"kind": "detail", "q": "What do arteries do?", "opts": ["Carry blood away from the heart", "Bring blood back to the heart", "Make air bags", "Help you walk"], "a": 0, "ev": "Arteries carry blood away from the heart.", "why": "Động mạch đưa máu ra khỏi tim: \"Arteries carry blood away from the heart.\""}, {"kind": "detail", "q": "What moves from the alveoli into the blood?", "opts": ["Food", "Oxygen", "Water", "Heat"], "a": 1, "ev": "Oxygen moves from the alveoli into the blood.", "why": "Oxy đi từ phế nang vào máu: \"Oxygen moves from the alveoli into the blood.\""}, {"kind": "vocab", "q": "In the text, what does \"pump\" mean?", "opts": ["A machine or organ that pushes liquid", "A kind of food", "A small bone", "A sound"], "a": 0, "ev": "The heart works like a pump and pushes blood around your body.", "why": "\"Pump\" là cái bơm, đẩy chất lỏng đi, như tim đẩy máu."}, {"kind": "tfng", "q": "Your heart has two rooms.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "It has four rooms.", "why": "Bài viết \"It has four rooms.\" nên câu này sai."}, {"kind": "tfng", "q": "Smoking is the main cause of lung problems.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nhắc đến hút thuốc nên đáp án là Not given."}], "notes": {"vocab": [["ventricles", "tâm thất", "buồng dưới của tim"], ["atria", "tâm nhĩ (số nhiều)", "số ít: atrium"], ["arteries", "động mạch", "artery (số ít)"], ["veins", "tĩnh mạch", "vein (số ít)"], ["alveoli", "phế nang", "túi khí nhỏ trong phổi"], ["oxygen", "khí ô-xy", "chất khí cơ thể cần"]], "grammar": [["Passive voice (câu bị động)", "the two bottom rooms are called ventricles", "are called là bị động hiện tại, dùng khi nói tên gọi của sự vật."], ["Time clause (mệnh đề thời gian)", "When you breathe in, air goes down a tube and into the lungs.", "When + hiện tại đơn diễn tả sự thật luôn đúng."], ["Comparison with like", "The heart works like a pump", "like + danh từ dùng để so sánh hai thứ giống nhau."]], "tips": ["Tờ rơi thường có tiêu đề nhỏ dạng câu hỏi; hãy đọc các tiêu đề đó trước để nắm cấu trúc bài.", "Với bài giải phẫu, chú ý các cặp từ trái nghĩa như away from / back to, top / bottom để không nhầm vị trí và chức năng."]}}, {"id": "rd5-a2-11", "lvl": "A2", "topic": "medical", "genre": "dialogue", "title": "A Bad Headache at the Clinic", "text": "Nurse Ana: Good morning, Mr Lee. Please sit down. What's the problem today?\nMr Lee: Good morning. I have a bad headache.\nNurse Ana: I'm sorry to hear that. When did it start?\nMr Lee: It started two days ago. It was small at first, but yesterday it got worse.\nNurse Ana: Where is the pain exactly?\nMr Lee: It's on the right side of my head, near my eye. It's a strong, throbbing pain.\nNurse Ana: Do you feel sick or dizzy?\nMr Lee: Yes, a little sick. Bright light makes it worse, so I stayed in a dark room yesterday.\nNurse Ana: Have you taken any medicine?\nMr Lee: Yes, I took one tablet last night, but it didn't help much.\nNurse Ana: I see. Did you sleep well?\nMr Lee: Not really. I only slept four hours.\nNurse Ana: Thank you. I'll check your blood pressure now. Then the doctor will see you.", "gist": "Ông Lee mô tả cơn đau đầu của mình cho y tá, và y tá hỏi thêm rồi chuẩn bị đo huyết áp.", "qs": [{"kind": "main", "q": "What is the dialogue mainly about?", "opts": ["A nurse explaining a diet", "A patient describing his headache", "A doctor giving an operation", "A man buying medicine"], "a": 1, "ev": "I have a bad headache.", "why": "Ông Lee nói: \"I have a bad headache.\" và cả đoạn hội thoại xoay quanh cơn đau đầu."}, {"kind": "detail", "q": "When did the headache start?", "opts": ["Today", "Yesterday", "Two days ago", "A week ago"], "a": 2, "ev": "It started two days ago.", "why": "Ông nói: \"It started two days ago.\""}, {"kind": "detail", "q": "Where is the pain?", "opts": ["On the left side of the head", "On the right side of the head, near the eye", "At the back of the neck", "In the forehead only"], "a": 1, "ev": "It's on the right side of my head, near my eye.", "why": "Ông Lee nói đau ở bên phải gần mắt: \"It's on the right side of my head, near my eye.\""}, {"kind": "detail", "q": "What does Nurse Ana do at the end?", "opts": ["Gives Mr Lee a tablet", "Sends him home", "She will check his blood pressure", "Calls his family"], "a": 2, "ev": "I'll check your blood pressure now.", "why": "Y tá nói: \"I'll check your blood pressure now.\""}, {"kind": "vocab", "q": "In the text, what does \"dizzy\" mean?", "opts": ["Feeling that things are turning round", "Feeling very hungry", "Feeling very cold", "Feeling happy"], "a": 0, "ev": "Do you feel sick or dizzy?", "why": "\"Dizzy\" là chóng mặt, cảm giác mọi thứ quay vòng."}, {"kind": "tfng", "q": "The tablet helped Mr Lee a lot.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "I took one tablet last night, but it didn't help much.", "why": "Ông nói thuốc \"didn't help much\" nên câu này sai."}, {"kind": "tfng", "q": "Mr Lee works in a hospital.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói về nghề nghiệp của ông Lee nên đáp án là Not given."}], "notes": {"vocab": [["headache", "đau đầu", "a bad headache"], ["throbbing", "đau nhói theo nhịp", "throbbing pain"], ["dizzy", "chóng mặt", ""], ["tablet", "viên thuốc", "take a tablet"], ["blood pressure", "huyết áp", "check blood pressure"], ["worse", "tệ hơn", "so sánh hơn của bad"]], "grammar": [["Past simple (quá khứ đơn)", "It started two days ago.", "started là quá khứ đơn, dùng với ago để nói thời điểm bắt đầu triệu chứng."], ["Present perfect question", "Have you taken any medicine?", "Have + chủ ngữ + quá khứ phân từ, hỏi về trải nghiệm hoặc việc đã làm gần đây."], ["Future with will", "I'll check your blood pressure now.", "I'll + động từ dùng để đưa ra quyết định hoặc lời đề nghị ngay lúc nói."]], "tips": ["Với hội thoại, chú ý tên người nói (Nurse Ana, Mr Lee) để biết ai hỏi, ai trả lời.", "Y tá thường hỏi theo thứ tự: khi nào, ở đâu, kèm triệu chứng gì, đã dùng thuốc chưa; hãy dùng thứ tự này để tìm chi tiết."]}}, {"id": "rd5-a2-12", "lvl": "A2", "topic": "medical", "genre": "instructions", "title": "Six Safety Rules for Taking Medicine at Home", "text": "Taking medicine safely at home\n\nFollow these simple rules to stay safe.\n\n1. Read the label first. Check the name of the medicine and the date on the box. Do not use medicine after this date.\n\n2. Take the right amount. Your doctor or pharmacist will tell you how much to take. Never take more than they say. More medicine does not make you better faster.\n\n3. Take it at the right time. Some medicines are best after food, and some before. If you forget one, do not take two next time. Ask your pharmacist.\n\n4. Do not share your medicine. A medicine that helps you may not help your friend. It can even be dangerous.\n\n5. Keep medicine in a cool, dry place. Keep it away from children. A high cupboard is a good place.\n\n6. Tell your doctor if you feel strange after taking medicine, for example if you have a rash or feel dizzy. Stop taking it and call for help if you cannot breathe easily.", "gist": "Sáu quy tắc đơn giản để uống và cất giữ thuốc an toàn tại nhà.", "qs": [{"kind": "main", "q": "What is the text mainly about?", "opts": ["How doctors make medicine", "How to use medicine in a safe way at home", "How to buy medicine online", "How to exercise"], "a": 1, "ev": "Follow these simple rules to stay safe.", "why": "Câu mở đầu cho biết đây là các quy tắc an toàn: \"Follow these simple rules to stay safe.\""}, {"kind": "detail", "q": "What should you check on the box?", "opts": ["The price and the shop", "The colour and the size", "The name of the medicine and the date", "The doctor's phone number"], "a": 2, "ev": "Check the name of the medicine and the date on the box.", "why": "Bài nói: \"Check the name of the medicine and the date on the box.\""}, {"kind": "detail", "q": "Who tells you how much medicine to take?", "opts": ["Your doctor or pharmacist", "Your friend", "Your neighbour", "The label of another medicine"], "a": 0, "ev": "Your doctor or pharmacist will tell you how much to take.", "why": "Bài nói bác sĩ hoặc dược sĩ sẽ cho biết liều lượng bạn cần uống."}, {"kind": "detail", "q": "Where should you keep medicine?", "opts": ["In a hot kitchen", "In a bag", "In a cool, dry place away from children", "Next to the bed"], "a": 2, "ev": "Keep medicine in a cool, dry place.", "why": "Bài khuyên: \"Keep medicine in a cool, dry place.\""}, {"kind": "vocab", "q": "In the text, what does \"rash\" mean?", "opts": ["Red marks or spots on the skin", "A pain in the stomach", "A loud noise", "A kind of tablet"], "a": 0, "ev": "for example if you have a rash or feel dizzy", "why": "\"Rash\" là phát ban, đốm đỏ trên da, được nêu là một phản ứng lạ sau khi uống thuốc."}, {"kind": "tfng", "q": "More medicine makes you better faster.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "More medicine does not make you better faster.", "why": "Bài nói ngược lại: \"More medicine does not make you better faster.\""}, {"kind": "tfng", "q": "You should take all medicine with milk.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nhắc đến sữa nên đáp án là Not given."}], "notes": {"vocab": [["label", "nhãn thuốc", "read the label"], ["pharmacist", "dược sĩ", "pharmacy = hiệu thuốc"], ["amount", "lượng, liều", "the right amount"], ["dangerous", "nguy hiểm", "danger (n)"], ["cupboard", "tủ đựng đồ", ""], ["rash", "phát ban", "skin rash"]], "grammar": [["Imperative (câu mệnh lệnh)", "Read the label first.", "Dùng động từ nguyên mẫu để ra chỉ dẫn an toàn."], ["Negative imperative (mệnh lệnh phủ định)", "Do not share your medicine.", "Do not + động từ để cấm điều gì."], ["Conditional type 1 (câu điều kiện loại 1)", "If you forget one, do not take two next time.", "If + hiện tại đơn, mệnh lệnh: nói điều cần làm nếu tình huống xảy ra."]], "tips": ["Văn bản hướng dẫn có đánh số 1-6; mỗi số là một quy tắc, hãy đọc câu đầu mỗi mục để nắm ý chính.", "Chú ý các từ Never, Do not, Keep, vì chúng cho biết điều cấm hoặc điều bắt buộc, thường là đáp án của câu hỏi True/False."]}}, {"id": "rd5-a2-13", "lvl": "A2", "topic": "medical", "genre": "blog", "title": "A Nursing Student's Second Week at City Hospital", "text": "Hello everyone! This is my second week at City Hospital, and I am learning a lot.\n\nOn Monday I worked in the children's ward. I took the temperature of five children and I wrote the numbers in a book. A little boy was afraid of me, so I smiled and showed him my watch. After that he felt better.\n\nOn Wednesday I helped an older woman to walk to the bathroom. She had a bad knee, so we walked very slowly. She said thank you three times, and I felt happy.\n\nOn Friday I was very tired because I stood for eight hours. My feet hurt, but my teacher said I did a good job. Tomorrow I will not go to the hospital. I will sleep until ten o'clock and then I will meet my friends for lunch.\n\nNext week I will learn how to check blood pressure. I am a little nervous, but I am also excited!", "gist": "Một sinh viên điều dưỡng kể về những việc cô ấy làm và cảm nhận trong tuần thực tập thứ hai ở bệnh viện.", "qs": [{"kind": "main", "q": "What is the blog mainly about?", "opts": ["A student's work and feelings during her second week at a hospital", "How to take a child's temperature correctly", "Why nurses need to stand for eight hours", "A hospital's plans for next week"], "a": 0, "ev": "This is my second week at City Hospital, and I am learning a lot.", "why": "Bài kể về tuần thứ hai ở bệnh viện: \"This is my second week at City Hospital, and I am learning a lot.\""}, {"kind": "detail", "q": "What did the writer do when the little boy was afraid?", "opts": ["She called his mother", "She smiled and showed him her watch", "She gave him a book", "She took his temperature again"], "a": 1, "ev": "I smiled and showed him my watch", "why": "Cô ấy đã làm dịu cậu bé bằng cách \"I smiled and showed him my watch\"."}, {"kind": "detail", "q": "Why did the writer and the older woman walk slowly?", "opts": ["The woman was very tired", "The bathroom was far away", "The woman had a bad knee", "The writer was nervous"], "a": 2, "ev": "She had a bad knee", "why": "Bà cụ bị đau đầu gối: \"She had a bad knee, so we walked very slowly.\""}, {"kind": "vocab", "q": "In the text, what does \"nervous\" mean?", "opts": ["Very happy", "A little worried", "Very angry", "Bored"], "a": 1, "ev": "I am a little nervous", "why": "\"Nervous\" ở đây là hơi lo lắng, đối lập với \"excited\" trong câu \"I am a little nervous, but I am also excited!\""}, {"kind": "tfng", "q": "The writer stood for four hours on Friday.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "I stood for eight hours", "why": "Bài viết nói \"I stood for eight hours\", không phải bốn giờ."}, {"kind": "tfng", "q": "The hospital pays the writer a salary.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói gì về tiền lương, nên là Not given."}, {"kind": "inference", "q": "What can we infer about the writer's feelings about her work?", "opts": ["She wants to stop working in the hospital", "She finds the work hard but enjoys it", "She does not like the older patients", "She is angry with her teacher"], "a": 1, "ev": "She said thank you three times, and I felt happy.", "why": "Dù mệt (\"I was very tired\") cô ấy vẫn vui và háo hức, nên cô thích công việc dù khó."}], "notes": {"vocab": [["ward", "khoa, phòng bệnh", "the children's ward = khoa nhi"], ["temperature", "nhiệt độ cơ thể", "take someone's temperature = đo nhiệt độ"], ["blood pressure", "huyết áp", "check blood pressure = đo huyết áp"], ["nervous", "lo lắng", "nervous about + noun"], ["knee", "đầu gối", "bộ phận cơ thể"]], "grammar": [["Past simple (thì quá khứ đơn)", "A little boy was afraid of me, so I smiled and showed him my watch.", "Dùng quá khứ đơn để kể các việc đã xảy ra; \"so\" nối nguyên nhân với kết quả."], ["Future with will (tương lai với will)", "I will sleep until ten o'clock and then I will meet my friends for lunch.", "Dùng \"will\" + động từ nguyên mẫu để nói về kế hoạch hoặc việc sẽ làm."]], "tips": ["Blog thường kể theo thứ tự thời gian: để ý các từ chỉ ngày như Monday, Wednesday, Friday để nắm trình tự.", "Ý chính nằm ở câu mở đầu và câu kết, nơi tác giả nói về cảm xúc chung."]}}, {"id": "rd5-a2-14", "lvl": "A2", "topic": "medical", "genre": "article", "title": "Why Your Body Needs a Good Night's Sleep", "text": "Every person needs sleep, but many people do not sleep enough. Doctors say that adults need about seven or eight hours every night. Children need more, and teenagers need about nine hours.\n\nWhen you sleep, your body does important work. Your muscles rest and grow stronger. Your heart beats more slowly, so it can rest too. Your body also fights germs while you sleep, because the immune system is very active at night.\n\nSleep is also good for the brain. During sleep, the brain keeps the things you learned during the day. This is why students often remember more after a good night's sleep. If you do not sleep well, you may feel angry, tired or sad. You may also forget things easily.\n\nHere are some simple tips for better sleep. Go to bed at the same time every day. Do not drink coffee in the evening. Turn off your phone an hour before bed, because the light from the screen can make it difficult to fall asleep.", "gist": "Bài báo giải thích vì sao cơ thể và não bộ cần ngủ đủ và đưa ra vài mẹo để ngủ ngon hơn.", "qs": [{"kind": "main", "q": "What is the main idea of the article?", "opts": ["Coffee is bad for your health", "Sleep is important for the body and the brain, and we can improve it", "Teenagers sleep more than adults", "Phones are dangerous for children"], "a": 1, "ev": "Sleep is also good for the brain.", "why": "Bài nói ngủ tốt cho cơ thể và não, rồi cho mẹo ngủ tốt hơn."}, {"kind": "detail", "q": "How many hours of sleep do teenagers need?", "opts": ["About seven", "About eight", "About nine", "About ten"], "a": 2, "ev": "teenagers need about nine hours", "why": "Bài ghi \"teenagers need about nine hours\"."}, {"kind": "detail", "q": "Why can the heart rest during sleep?", "opts": ["It stops completely", "It beats more slowly", "It grows stronger muscles", "It fights germs"], "a": 1, "ev": "Your heart beats more slowly, so it can rest too.", "why": "Tim đập chậm hơn nên được nghỉ: \"Your heart beats more slowly, so it can rest too.\""}, {"kind": "vocab", "q": "In the text, what does \"active\" mean in \"very active at night\"?", "opts": ["Working a lot", "Sleeping deeply", "Very weak", "Painful"], "a": 0, "ev": "the immune system is very active at night", "why": "\"Active\" là hoạt động mạnh: hệ miễn dịch làm việc nhiều khi ngủ."}, {"kind": "tfng", "q": "Doctors say that adults need about nine hours of sleep.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "adults need about seven or eight hours every night", "why": "Người lớn cần khoảng bảy hoặc tám giờ, không phải chín."}, {"kind": "tfng", "q": "A short sleep in the afternoon improves memory.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói về ngủ trưa, nên là Not given."}, {"kind": "inference", "q": "Which statement is probably true?", "opts": ["A student who sleeps badly may remember less for an exam", "Students should study all night", "Good sleepers never feel sad", "The brain stops working during sleep"], "a": 0, "ev": "This is why students often remember more after a good night's sleep.", "why": "Vì ngủ ngon giúp nhớ nhiều hơn, ngủ kém có thể nhớ ít hơn."}], "notes": {"vocab": [["immune system", "hệ miễn dịch", "immune = miễn dịch"], ["germs", "vi trùng", "germs cause illness"], ["muscles", "cơ bắp", "muscle (n) /ˈmʌsl/"], ["fall asleep", "ngủ thiếp đi", "fall asleep ≠ be asleep"], ["adults", "người lớn", "adult (n)"]], "grammar": [["Present simple for facts (hiện tại đơn nêu sự thật)", "Your heart beats more slowly, so it can rest too.", "Dùng hiện tại đơn để nói sự thật khoa học; \"so\" nêu kết quả."], ["Modal may (khả năng với may)", "You may also forget things easily.", "\"May\" + động từ nguyên mẫu diễn tả điều có thể xảy ra."]], "tips": ["Bài viết thông tin thường có ý chính ở đoạn đầu, mỗi đoạn sau triển khai một ý.", "Đoạn cuối với các câu mệnh lệnh là lời khuyên; nhận ra nó giúp trả lời câu hỏi về mẹo."]}}, {"id": "rd5-a2-15", "lvl": "A2", "topic": "medical", "genre": "email", "title": "Reminder Email: Preparing for Your Blood Test", "text": "Subject: Reminder: your blood test on Thursday\n\nDear Mr Tran,\n\nThis is a reminder about your appointment at Lakeside Health Centre. Your blood test is on Thursday, 14 March, at 8:30 a.m. Please come to the second floor and go to Room 4.\n\nPlease read these instructions before you come.\n\n- Do not eat or drink anything except water for eight hours before the test. So please have dinner early on Wednesday evening.\n- Drink a glass of water in the morning. It makes it easier for the nurse to take the blood.\n- Wear a shirt with short sleeves, or sleeves that you can roll up easily.\n- Bring your appointment card.\n\nThe test is quick. It usually takes about five minutes. You may feel a small pain when the nurse puts the needle in your arm. Afterwards, you can eat and go to work as usual. The results will be ready in three days.\n\nIf you cannot come, please phone us at least one day before.\n\nKind regards,\nLinda Park\nReception, Lakeside Health Centre", "gist": "Email nhắc bệnh nhân lịch xét nghiệm máu và hướng dẫn cách chuẩn bị trước khi đến.", "qs": [{"kind": "main", "q": "Why did Linda Park write this email?", "opts": ["To tell Mr Tran his test results", "To remind him of his blood test and explain how to prepare", "To ask him to change his appointment", "To invite him to work at the centre"], "a": 1, "ev": "This is a reminder about your appointment at Lakeside Health Centre.", "why": "Email nhắc lịch hẹn và đưa hướng dẫn chuẩn bị."}, {"kind": "detail", "q": "What can Mr Tran have before the test?", "opts": ["Tea", "Coffee", "Water", "Breakfast"], "a": 2, "ev": "Do not eat or drink anything except water for eight hours before the test.", "why": "Chỉ được uống nước: \"except water\"."}, {"kind": "detail", "q": "Why should he drink a glass of water in the morning?", "opts": ["It makes the test cheaper", "It makes it easier for the nurse to take the blood", "It stops the pain completely", "It is the centre's rule for all visitors"], "a": 1, "ev": "It makes it easier for the nurse to take the blood.", "why": "Câu này nêu thẳng lý do."}, {"kind": "vocab", "q": "In the text, what is a \"reminder\"?", "opts": ["A bill", "Something that helps you remember", "A kind of test", "A prescription"], "a": 1, "ev": "This is a reminder about your appointment", "why": "\"Reminder\" là thư giúp nhớ lịch hẹn."}, {"kind": "tfng", "q": "The blood test takes about an hour.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "It usually takes about five minutes.", "why": "Xét nghiệm chỉ mất khoảng năm phút."}, {"kind": "tfng", "q": "There is free parking at the health centre.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Email không nhắc đến chỗ đậu xe, nên là Not given."}, {"kind": "inference", "q": "Why does the email ask Mr Tran to have dinner early on Wednesday?", "opts": ["The test is in the morning and he must not eat for eight hours before it", "He must go to bed at six o'clock", "The nurse eats dinner with patients", "The centre closes at night"], "a": 0, "ev": "So please have dinner early on Wednesday evening.", "why": "Xét nghiệm lúc 8:30 sáng, cần nhịn tám giờ nên phải ăn tối sớm."}], "notes": {"vocab": [["reminder", "thư/lời nhắc", "remind someone of something"], ["appointment", "cuộc hẹn", "make/cancel an appointment"], ["instructions", "hướng dẫn", "give/follow instructions"], ["sleeves", "tay áo", "roll up your sleeves"], ["needle", "cây kim", "a needle in your arm"]], "grammar": [["Imperative (câu mệnh lệnh)", "Do not eat or drink anything except water for eight hours before the test.", "Dùng động từ nguyên mẫu để hướng dẫn; \"Do not\" để cấm."], ["Future passive-like with will (tương lai)", "The results will be ready in three days.", "\"Will be ready\" nói về việc sẽ xảy ra trong tương lai."]], "tips": ["Email có dòng Subject: đọc nó trước để biết mục đích.", "Các gạch đầu dòng chứa chi tiết cần làm; đọc kỹ từng dòng khi trả lời câu hỏi chi tiết."]}}, {"id": "rd5-a2-16", "lvl": "A2", "topic": "medical", "genre": "dialogue", "title": "At the Pharmacy: Advice for a Cold", "text": "Pharmacist: Good morning. How can I help you?\nCustomer: Hello. I have a cold. My nose is blocked and I have a sore throat.\nPharmacist: I'm sorry to hear that. How long have you had these symptoms?\nCustomer: For two days. I also have a small cough, but I don't have a fever.\nPharmacist: That's good. Do you have any allergies to medicine?\nCustomer: No, I don't.\nPharmacist: OK. For your sore throat, you can try these sweets. For your nose, this spray can help, but please don't use it for more than five days.\nCustomer: Do I need antibiotics?\nPharmacist: No, you don't. Antibiotics don't work on colds because a cold is caused by a virus. The best medicine is rest. Drink a lot of warm water and try to sleep early.\nCustomer: How long will the cold last?\nPharmacist: Usually about a week. But if you get a high fever or have trouble breathing, please see a doctor immediately.\nCustomer: I will. Thanks for your help.\nPharmacist: You're welcome. Get well soon!", "gist": "Dược sĩ tư vấn cho một khách hàng bị cảm lạnh về thuốc, nghỉ ngơi và khi nào cần đi khám.", "qs": [{"kind": "main", "q": "What is the conversation mainly about?", "opts": ["A pharmacist advising a customer with a cold", "A doctor operating on a patient", "A customer buying vitamins", "A pharmacist selling antibiotics"], "a": 0, "ev": "I have a cold.", "why": "Khách nói bị cảm và dược sĩ tư vấn cách xử lý."}, {"kind": "detail", "q": "How long has the customer had the symptoms?", "opts": ["One day", "Two days", "Five days", "A week"], "a": 1, "ev": "For two days.", "why": "Khách trả lời \"For two days.\""}, {"kind": "detail", "q": "Why does the customer not need antibiotics?", "opts": ["He has no cough", "He is allergic to them", "A cold is caused by a virus", "They cost too much"], "a": 2, "ev": "a cold is caused by a virus", "why": "Kháng sinh không có tác dụng với virus."}, {"kind": "vocab", "q": "In the text, what does \"symptoms\" mean?", "opts": ["Types of medicine", "Shop prices", "Signs of an illness", "Hospital rooms"], "a": 2, "ev": "How long have you had these symptoms?", "why": "\"Symptoms\" là triệu chứng, như nghẹt mũi, đau họng."}, {"kind": "tfng", "q": "The customer has a fever.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "but I don't have a fever", "why": "Khách nói \"I don't have a fever\"."}, {"kind": "tfng", "q": "The customer took antibiotics last month.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Hội thoại không nhắc đến việc này, nên là Not given."}, {"kind": "inference", "q": "When would the pharmacist want the customer to see a doctor?", "opts": ["If he feels tired", "If he has trouble breathing", "If he drinks warm water", "If he sleeps early"], "a": 1, "ev": "if you get a high fever or have trouble breathing, please see a doctor immediately", "why": "Khó thở hoặc sốt cao là dấu hiệu cần đi khám ngay."}], "notes": {"vocab": [["symptoms", "triệu chứng", "symptom (n)"], ["sore throat", "đau họng", "sore = đau, rát"], ["allergies", "dị ứng", "allergic to + noun"], ["antibiotics", "thuốc kháng sinh", "chỉ trị vi khuẩn"], ["virus", "vi-rút", "a cold is caused by a virus"], ["fever", "sốt", "have a high fever"]], "grammar": [["Present perfect (hiện tại hoàn thành)", "How long have you had these symptoms?", "\"Have + quá khứ phân từ\" hỏi về khoảng thời gian kéo dài đến bây giờ."], ["Passive (bị động)", "a cold is caused by a virus", "\"Is caused by\" nhấn mạnh nguyên nhân thay vì người/vật gây ra."]], "tips": ["Hội thoại: chú ý tên người nói để biết ai nói gì khi trả lời câu hỏi.", "Lời khuyên thường nằm ở câu của dược sĩ; câu hỏi \"if\" thường chỉ điều kiện cần cẩn thận."]}}, {"id": "rd5-b1-01", "lvl": "B1", "topic": "work", "genre": "email", "title": "Interview Invitation from Brightway Travel", "text": "Subject: Interview invitation – Customer Support Assistant\n\nDear Ms Alvarez,\n\nThank you for applying for the position of Customer Support Assistant at Brightway Travel. We were impressed by your application, and we would like to invite you to an interview.\n\nThe interview will take place on Thursday, 14 March, at 10.30 a.m. in our office at 25 River Street, on the second floor. Please arrive about ten minutes early and ask for me at reception. The meeting will last around forty-five minutes. You will talk to me and to Mr Okafor, who manages the support team.\n\nHere is some advice to help you prepare. First, read about our company on our website, because we usually ask candidates what they know about us. Second, think about examples from your previous jobs that show how you solve problems. If you have worked with unhappy customers, for instance, be ready to explain what you did. Finally, bring a copy of your CV and one form of photo identification.\n\nGetting to our office is easy. The nearest station is Central Park, which is a five-minute walk away. If you come by car, please note that we have no parking spaces for visitors, but there is a public car park opposite the building.\n\nIf you cannot attend at this time, please reply by Monday and we will try to find another date. We look forward to meeting you.\n\nKind regards,\nDaniel Whitmore\nHuman Resources Manager\nBrightway Travel", "gist": "Email mời cô Alvarez đến phỏng vấn vị trí hỗ trợ khách hàng, kèm lời khuyên chuẩn bị và chỉ dẫn đường đi.", "qs": [{"kind": "main", "q": "What is the main purpose of the email?", "opts": ["To offer Ms Alvarez a job", "To invite Ms Alvarez to an interview and help her prepare", "To ask Ms Alvarez to change her application", "To explain how to get to Central Park"], "a": 1, "ev": "we would like to invite you to an interview", "why": "Mục đích chính là mời phỏng vấn và đưa lời khuyên chuẩn bị: \"we would like to invite you to an interview\"."}, {"kind": "detail", "q": "How long will the meeting last?", "opts": ["About ten minutes", "About thirty minutes", "About forty-five minutes", "About one hour"], "a": 2, "ev": "The meeting will last around forty-five minutes", "why": "Email nói rõ: \"The meeting will last around forty-five minutes\"."}, {"kind": "detail", "q": "Who is Mr Okafor?", "opts": ["The head of Human Resources", "The manager of the support team", "A candidate for the job", "The receptionist"], "a": 1, "ev": "who manages the support team", "why": "Văn bản viết \"who manages the support team\", tức ông là quản lý nhóm hỗ trợ."}, {"kind": "vocab", "q": "In the text, what does \"candidates\" mean?", "opts": ["People who apply for a job", "People who work in reception", "Customers of the company", "Teachers at a school"], "a": 0, "ev": "we usually ask candidates what they know about us", "why": "\"Candidates\" là những người ứng tuyển được phỏng vấn: \"we usually ask candidates what they know about us\"."}, {"kind": "tfng", "q": "The interview will take place on the second floor.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "in our office at 25 River Street, on the second floor", "why": "Đúng: \"in our office at 25 River Street, on the second floor\"."}, {"kind": "tfng", "q": "Visitors can park their cars at the company building.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "we have no parking spaces for visitors", "why": "Sai: \"we have no parking spaces for visitors\", chỉ có bãi đỗ công cộng đối diện."}, {"kind": "tfng", "q": "The company will pay Ms Alvarez's travel costs.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nhắc gì đến việc công ty trả chi phí đi lại, nên là Not given."}, {"kind": "inference", "q": "Why does Mr Whitmore advise reading about the company?", "opts": ["The interviewers are likely to ask about it", "The website lists the interview questions", "It is a rule of the train station", "Candidates must write a report about it"], "a": 0, "ev": "we usually ask candidates what they know about us", "why": "Vì \"we usually ask candidates what they know about us\" nên người phỏng vấn có thể hỏi về công ty."}], "notes": {"vocab": [["impressed", "ấn tượng, nể phục", "be impressed by sth"], ["candidates", "ứng viên"], ["previous", "trước đây", "previous jobs = những công việc trước"], ["identification", "giấy tờ tùy thân", "viết tắt: ID"], ["attend", "tham dự, có mặt"], ["reception", "quầy lễ tân"], ["opposite", "đối diện", "opposite the building"]], "grammar": [["Gerund after a preposition (V-ing sau giới từ)", "Thank you for applying for the position of Customer Support Assistant at Brightway Travel", "Sau giới từ \"for\" ta dùng V-ing (applying), không dùng động từ nguyên mẫu."], ["Conditional type 1 + imperative (câu điều kiện loại 1 + mệnh lệnh)", "If you have worked with unhappy customers, for instance, be ready to explain what you did.", "Mệnh đề If dùng hiện tại hoàn thành, mệnh đề chính là câu mệnh lệnh để đưa lời khuyên."], ["Non-defining relative clause (mệnh đề quan hệ không xác định)", "The nearest station is Central Park, which is a five-minute walk away.", "\"which\" bổ sung thông tin cho cả danh từ trước, tách bằng dấu phẩy."], ["Polite imperative (mệnh lệnh lịch sự)", "Please arrive about ten minutes early", "Thêm \"Please\" để lời yêu cầu trong email trang trọng nghe lịch sự."]], "tips": ["Với email, đọc dòng Subject và câu đầu tiên trước để biết mục đích chính, sau đó tìm ngày, giờ, địa điểm ở đoạn 2.", "Các từ trình tự như First, Second, Finally giúp bạn nhận ra từng lời khuyên riêng biệt."]}}, {"id": "rd5-b1-02", "lvl": "B1", "topic": "technology", "genre": "article", "title": "Smartphones and Children: Weighing Up the Risks", "text": "Should Children Have Smartphones?\n\nMany parents face the same difficult question: at what age should a child get a smartphone? Some families give one to their children at the age of eight, while others wait until they are fourteen. There are good arguments on both sides.\n\nOn the positive side, a smartphone helps parents stay in touch with their children. A child who walks to school alone can call home if the bus is late or if something goes wrong. Phones can also be useful for learning. There are apps that teach languages, maths and even music, and children can look up information in seconds when they do their homework. In addition, many young people say that a phone helps them keep friendships going, especially if their friends live far away.\n\nHowever, there are also serious disadvantages. Experts say that children who spend too much time on screens often sleep badly, because the light from a phone makes it harder to fall asleep. Some children also find it difficult to concentrate in class when they are checking messages. Another worry is safety. Without supervision, a child might see unsuitable content or talk to strangers online.\n\nSo what is the answer? Most specialists agree that there is no perfect age. Instead, they suggest that parents set clear rules, such as no phones at the dinner table or in the bedroom at night. Parents who show a good example by putting down their own phones are also likely to have more success. In the end, a smartphone is a tool, and the result depends on how it is used.", "gist": "Bài báo nêu lợi ích và tác hại của điện thoại thông minh với trẻ em và kết luận rằng cách sử dụng mới là điều quan trọng.", "qs": [{"kind": "main", "q": "What is the main idea of the article?", "opts": ["Children should never use smartphones", "Smartphones have both advantages and disadvantages for children", "Smartphones are the best way to teach children music", "Parents should buy phones for eight-year-olds"], "a": 1, "ev": "There are good arguments on both sides.", "why": "Bài trình bày cả hai mặt: \"There are good arguments on both sides.\""}, {"kind": "detail", "q": "According to experts, why do children with too much screen time sleep badly?", "opts": ["They are afraid of strangers", "They study too late at night", "The light from a phone makes it harder to fall asleep", "Their parents take the phones away"], "a": 2, "ev": "the light from a phone makes it harder to fall asleep", "why": "Bài nêu nguyên nhân: \"the light from a phone makes it harder to fall asleep\"."}, {"kind": "detail", "q": "Which rule do specialists suggest?", "opts": ["No phones at the dinner table", "No homework on phones", "Phones only at weekends", "Phones only for adults"], "a": 0, "ev": "no phones at the dinner table or in the bedroom at night", "why": "Các chuyên gia gợi ý: \"no phones at the dinner table or in the bedroom at night\"."}, {"kind": "vocab", "q": "In the text, what does \"supervision\" mean?", "opts": ["A kind of mobile app", "Watching and guiding what someone does", "A school lesson", "A type of phone screen"], "a": 1, "ev": "Without supervision, a child might see unsuitable content", "why": "\"Without supervision\" nghĩa là không có người giám sát, trông chừng trẻ."}, {"kind": "tfng", "q": "Some apps can teach children languages, maths and music.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "There are apps that teach languages, maths and even music", "why": "Đúng: \"There are apps that teach languages, maths and even music\"."}, {"kind": "tfng", "q": "Most specialists say there is a perfect age for a first smartphone.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "there is no perfect age", "why": "Sai: các chuyên gia nói \"there is no perfect age\"."}, {"kind": "tfng", "q": "Smartphones make children get worse marks in exams.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không đề cập đến điểm thi, nên là Not given."}, {"kind": "inference", "q": "What is the writer's overall opinion?", "opts": ["Smartphones are always dangerous", "Smartphones are always helpful", "Results depend on how a phone is used", "Parents should not set any rules"], "a": 2, "ev": "a smartphone is a tool, and the result depends on how it is used", "why": "Câu kết \"a smartphone is a tool, and the result depends on how it is used\" cho thấy quan điểm cân bằng."}], "notes": {"vocab": [["stay in touch", "giữ liên lạc", "stay in touch with sb"], ["disadvantages", "nhược điểm", "trái nghĩa: advantages"], ["concentrate", "tập trung", "concentrate on / in class"], ["supervision", "sự giám sát"], ["unsuitable", "không phù hợp", "un- + suitable"], ["specialists", "chuyên gia"], ["tool", "công cụ"]], "grammar": [["Contrast with while (đối chiếu với while)", "Some families give one to their children at the age of eight, while others wait until they are fourteen.", "\"while\" nối hai vế đối lập: một nhóm làm khác nhóm còn lại."], ["Defining relative clause (mệnh đề quan hệ xác định)", "A child who walks to school alone can call home", "\"who\" cho biết đang nói đến đứa trẻ nào, không có dấu phẩy."], ["Modal might (khả năng xảy ra)", "Without supervision, a child might see unsuitable content or talk to strangers online.", "\"might\" diễn tả điều có thể xảy ra, không chắc chắn."], ["be likely to (có khả năng)", "Parents who show a good example by putting down their own phones are also likely to have more success.", "Cấu trúc be likely to + V dùng để dự đoán điều có khả năng xảy ra."]], "tips": ["Bài báo dạng cân bằng thường có đoạn \"On the positive side\" và \"However\"; hãy gạch chân các từ nối này để tách ưu và nhược điểm.", "Ý kiến kết luận của tác giả thường nằm ở đoạn cuối, sau các từ như \"So\", \"In the end\"."]}}, {"id": "rd5-b1-03", "lvl": "B1", "topic": "travel", "genre": "blog", "title": "A Wrong Turn Above Sapa", "text": "Lost in the Mountains – and Found Again\n\nHello again, travellers! I promised an honest update from my backpacking trip in northern Vietnam, so here it is, including the bad parts.\n\nOn Tuesday I woke up early in the small town of Sapa and decided to walk to a village about eight kilometres away. The views were amazing, and I took so many photos that my phone battery fell to five per cent. Then, around noon, I realised I had taken a wrong turn. The path had split in two, and I had chosen the wrong one. My phone died just as I was trying to open the map.\n\nI was worried, but I tried to stay calm. I remembered a tip from an old guidebook: if you are lost, go back to the last place you recognised. So I walked back until I found the stream I had crossed earlier. Soon I met an old woman who was carrying wood. She did not speak English, and my Vietnamese is terrible, but we managed to communicate with gestures and a few words. She pointed at the sky, then at the path, and I understood that it would soon rain.\n\nShe took me to her house, where her family gave me hot tea and rice. Her grandson, who was learning English at school, translated for us. Later, he walked with me to the main road, and I caught the last minibus back to town by just five minutes!\n\nWhat did I learn? First, always carry a power bank. Second, download offline maps before you leave. Most importantly, people are usually kind when you need help. I'm sending the family a thank-you postcard this week.", "gist": "Người viết blog đi lạc khi điện thoại hết pin, được một gia đình địa phương giúp đỡ và kịp bắt chuyến xe cuối về thị trấn.", "qs": [{"kind": "main", "q": "What is the blog post mainly about?", "opts": ["A cheap hotel in Sapa", "A walk where the writer got lost and received help", "A lesson in the Vietnamese language", "A review of a guidebook"], "a": 1, "ev": "I realised I had taken a wrong turn", "why": "Bài kể việc đi lạc (\"I had taken a wrong turn\") và cách được giúp đỡ."}, {"kind": "detail", "q": "Why did the writer's phone stop working?", "opts": ["It fell into a stream", "It was stolen", "It was too old", "The battery was low after many photos"], "a": 3, "ev": "I took so many photos that my phone battery fell to five per cent", "why": "Do chụp quá nhiều ảnh nên pin còn năm phần trăm rồi tắt hẳn."}, {"kind": "detail", "q": "Who translated for the writer and the old woman?", "opts": ["Her grandson", "A minibus driver", "A guidebook", "A police officer"], "a": 0, "ev": "Her grandson, who was learning English at school, translated for us", "why": "Người dịch là cháu trai bà: \"Her grandson ... translated for us\"."}, {"kind": "vocab", "q": "In the text, what does \"gestures\" mean?", "opts": ["Written notes", "Photographs", "Movements of the hands or body that show a meaning", "Loud shouts"], "a": 2, "ev": "we managed to communicate with gestures and a few words", "why": "Hai người không chung ngôn ngữ nên dùng cử chỉ tay, người: \"communicate with gestures\"."}, {"kind": "tfng", "q": "The writer chose the wrong path at a split in the path.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "The path had split in two, and I had chosen the wrong one", "why": "Đúng: \"The path had split in two, and I had chosen the wrong one\"."}, {"kind": "tfng", "q": "The old woman spoke English well.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "She did not speak English", "why": "Sai: bà không nói được tiếng Anh, vì \"She did not speak English\"."}, {"kind": "tfng", "q": "The writer plans to visit Sapa again next year.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói gì về kế hoạch quay lại Sapa, nên là Not given."}, {"kind": "inference", "q": "Why did the old woman point at the sky?", "opts": ["She wanted to show the writer a bird", "She was warning the writer that rain was coming", "She was asking for a phone", "She was asking the time"], "a": 1, "ev": "I understood that it would soon rain", "why": "Tác giả hiểu rằng \"it would soon rain\", nên bà chỉ trời để báo sắp mưa."}], "notes": {"vocab": [["backpacking", "đi du lịch bụi, đeo ba lô"], ["realised", "nhận ra", "realise (UK) = realize (US)"], ["stream", "con suối"], ["gestures", "cử chỉ"], ["translated", "dịch (nói)", "translate sth into sth"], ["minibus", "xe buýt nhỏ"], ["offline maps", "bản đồ ngoại tuyến", "dùng được không cần mạng"]], "grammar": [["Past perfect (quá khứ hoàn thành)", "I realised I had taken a wrong turn", "Hành động đi nhầm xảy ra trước lúc nhận ra, nên dùng had + V3."], ["so ... that (quá ... đến nỗi)", "I took so many photos that my phone battery fell to five per cent.", "so + từ chỉ mức độ + that + kết quả."], ["Zero conditional + imperative (điều kiện + mệnh lệnh)", "if you are lost, go back to the last place you recognised", "If + hiện tại đơn, theo sau là lời khuyên ở dạng mệnh lệnh."], ["Non-defining relative clause (mệnh đề quan hệ không xác định)", "Her grandson, who was learning English at school, translated for us", "Thông tin thêm về người được đặt giữa hai dấu phẩy."]], "tips": ["Blog kể chuyện thường theo trình tự thời gian (On Tuesday, Then, Soon, Later); dùng các mốc này để theo dõi biến cố.", "Bài học rút ra thường ở đoạn cuối, sau câu hỏi tu từ như \"What did I learn?\"."]}}, {"id": "rd5-b1-04", "lvl": "B1", "topic": "society", "genre": "news", "title": "Millbrook Says Yes to Harbour Road Cycle Lane", "text": "Residents of Millbrook voted on Saturday to build a new cycle lane along Harbour Road, ending months of debate in the town.\n\nIn a local referendum, 4,120 people voted in favour of the plan, while 3,310 voted against. About sixty per cent of the town's adults took part, which is a higher turnout than in the last council election.\n\nThe new lane will be almost three kilometres long and will connect the railway station with the university. The town council says that construction will begin in September and should be finished within eight months. The project will cost about 1.2 million pounds, and most of the money will come from a government fund for greener transport.\n\nSupporters argue that the lane will make the road safer. \"Last year, three cyclists were injured on Harbour Road,\" said councillor Priya Nair. \"If we separate bikes from cars, accidents should become less common.\" Many students also welcomed the result, because cycling is cheaper than taking the bus.\n\nHowever, not everyone is pleased. Some shop owners fear that they will lose customers, since the lane will remove around forty parking spaces. \"People will not walk far with heavy bags,\" said Tom Hargreaves, who runs a hardware shop. He has asked the council to build a new car park nearby.\n\nThe council has promised to talk to local businesses before work starts. A public meeting will be held on 15 August, and residents will be able to ask questions about the plan.", "gist": "Cư dân thị trấn Millbrook bỏ phiếu ủng hộ làn đường xe đạp mới, nhưng một số chủ cửa hàng lo mất chỗ đỗ xe và khách hàng.", "qs": [{"kind": "main", "q": "What is the news report mainly about?", "opts": ["A new university building", "An accident on Harbour Road", "The result of a vote on a cycle lane", "The closure of a railway station"], "a": 2, "ev": "Residents of Millbrook voted on Saturday to build a new cycle lane", "why": "Câu đầu cho biết cư dân đã bỏ phiếu xây làn xe đạp."}, {"kind": "detail", "q": "What will the new lane connect?", "opts": ["The town centre and the harbour", "The railway station and the university", "Two shopping centres", "The car park and the school"], "a": 1, "ev": "will connect the railway station with the university", "why": "Bài viết: \"will connect the railway station with the university\"."}, {"kind": "detail", "q": "Why are some shop owners unhappy?", "opts": ["The lane will remove about forty parking spaces", "The lane will cost too much", "The lane will be too long", "Cyclists will damage the shops"], "a": 0, "ev": "the lane will remove around forty parking spaces", "why": "Họ lo vì \"the lane will remove around forty parking spaces\"."}, {"kind": "vocab", "q": "In the text, what does \"turnout\" mean?", "opts": ["The price of a project", "The number of people who go and vote", "A change of town council", "A type of bicycle"], "a": 1, "ev": "which is a higher turnout than in the last council election", "why": "\"Turnout\" là số người đi bỏ phiếu, được so sánh với cuộc bầu cử trước."}, {"kind": "tfng", "q": "Most of the money for the project will come from a government fund.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "most of the money will come from a government fund for greener transport", "why": "Đúng: \"most of the money will come from a government fund for greener transport\"."}, {"kind": "tfng", "q": "More people voted against the plan than in favour of it.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "4,120 people voted in favour of the plan, while 3,310 voted against", "why": "Sai: 4,120 phiếu ủng hộ nhiều hơn 3,310 phiếu phản đối."}, {"kind": "tfng", "q": "The council will pay money to shop owners who lose customers.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nhắc đến việc bồi thường, nên là Not given."}, {"kind": "inference", "q": "Why does Tom Hargreaves want a new car park nearby?", "opts": ["He thinks customers need to park close to his shop", "He wants to build a new shop", "He plans to cycle to work", "He does not like cars"], "a": 0, "ev": "People will not walk far with heavy bags", "why": "Ông nói khách mang đồ nặng sẽ không đi bộ xa, nên cần chỗ đỗ gần cửa hàng."}], "notes": {"vocab": [["referendum", "cuộc trưng cầu ý dân"], ["in favour of", "ủng hộ", "trái nghĩa: against"], ["turnout", "tỷ lệ/số người đi bầu"], ["construction", "việc xây dựng"], ["councillor", "ủy viên hội đồng địa phương"], ["injured", "bị thương", "injure (v)"], ["welcomed", "hoan nghênh, đón nhận"]], "grammar": [["Contrast with while (đối chiếu với while)", "In a local referendum, 4,120 people voted in favour of the plan, while 3,310 voted against.", "\"while\" đặt hai con số đối lập trong cùng một câu."], ["Future simple for plans (tương lai đơn)", "The new lane will be almost three kilometres long and will connect the railway station with the university.", "will + V dùng để nói về kế hoạch và dự đoán chắc chắn trong tin tức."], ["Conditional type 1 (câu điều kiện loại 1)", "If we separate bikes from cars, accidents should become less common.", "If + hiện tại đơn, kết quả dự đoán bằng should/will."], ["Reason with since (lý do với since)", "Some shop owners fear that they will lose customers, since the lane will remove around forty parking spaces.", "\"since\" ở đây nghĩa là \"vì\", giới thiệu lý do."]], "tips": ["Tin tức đặt thông tin quan trọng nhất ở câu đầu (ai, làm gì, khi nào); các đoạn sau bổ sung chi tiết và ý kiến.", "Chú ý các đoạn có \"However\" để tìm quan điểm trái chiều, thường kèm lời trích dẫn."]}}, {"id": "rd5-b1-05", "lvl": "B1", "topic": "education", "genre": "forum", "title": "Questions About Spending a Semester Abroad", "text": "Topic: Studying abroad – any advice?\n\nPosted by Linh_K:\nHi everyone! I'm in my second year of a business degree and I'd like to spend one semester abroad. I'm worried about two things: the cost and my English. Is it worth it? Does anyone have experience?\n\nReply from Marco88:\nI spent a semester in Ireland last year, and it was the best decision of my studies. The tuition was the same as at my home university, but living costs were higher. I applied for an exchange scholarship, which paid for my flights and part of my rent. Check with your international office, because deadlines are usually about six months before departure.\n\nReply from Sofia_T:\nAbout your English: don't panic! My English was only average when I arrived in Canada. The first month was hard because lectures were fast and I couldn't follow everything. However, I recorded the classes (with permission) and listened again at home. After two months I felt much more confident. Also, join clubs. You'll make friends and practise speaking without even noticing it.\n\nReply from Linh_K:\nThank you both! That's really helpful. Marco, did you find accommodation easily?\n\nReply from Marco88:\nThe university offered rooms in a student residence, so it was simple, though it was a bit noisy. If you prefer a quiet place, you could share a flat, but you'll need to search early. Good luck!", "gist": "Trên diễn đàn, một sinh viên hỏi về chi phí và tiếng Anh khi đi du học một học kỳ, và hai bạn khác chia sẻ kinh nghiệm.", "qs": [{"kind": "main", "q": "What is the forum thread mainly about?", "opts": ["Choosing a business degree", "Advice about studying abroad for a semester", "How to find a job in Canada", "The history of Irish universities"], "a": 1, "ev": "I'd like to spend one semester abroad", "why": "Linh muốn đi một học kỳ ở nước ngoài và hỏi lời khuyên."}, {"kind": "detail", "q": "What did Marco's scholarship pay for?", "opts": ["His tuition and books", "His food and clothes", "His flights and part of his rent", "His phone and internet"], "a": 2, "ev": "paid for my flights and part of my rent", "why": "Học bổng \"paid for my flights and part of my rent\"."}, {"kind": "detail", "q": "How did Sofia improve her understanding of lectures?", "opts": ["She recorded classes and listened again", "She stopped going to lectures", "She changed her course", "She moved to a quiet flat"], "a": 0, "ev": "I recorded the classes (with permission) and listened again at home", "why": "Sofia ghi âm lớp học rồi nghe lại ở nhà."}, {"kind": "vocab", "q": "In the text, what does \"tuition\" mean?", "opts": ["Money paid for rent", "Money paid for teaching at a university", "A type of scholarship", "A student club"], "a": 1, "ev": "The tuition was the same as at my home university", "why": "\"Tuition\" là học phí; Marco so sánh với trường ở quê nhà."}, {"kind": "tfng", "q": "Application deadlines are usually about six months before departure.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "deadlines are usually about six months before departure", "why": "Đúng: \"deadlines are usually about six months before departure\"."}, {"kind": "tfng", "q": "Marco found that living costs were lower in Ireland.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "living costs were higher", "why": "Sai: Marco nói \"living costs were higher\"."}, {"kind": "tfng", "q": "Sofia studied business in Canada.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không cho biết Sofia học ngành gì, nên là Not given."}, {"kind": "inference", "q": "Why does Sofia recommend joining clubs?", "opts": ["Clubs are free", "It helps you practise English naturally", "Clubs give scholarships", "It is required by the university"], "a": 1, "ev": "practise speaking without even noticing it", "why": "Tham gia câu lạc bộ giúp luyện nói mà không nhận ra, tức là luyện tập tự nhiên."}], "notes": {"vocab": [["semester", "học kỳ"], ["tuition", "học phí"], ["scholarship", "học bổng", "apply for a scholarship"], ["deadlines", "hạn chót"], ["lectures", "bài giảng"], ["confident", "tự tin", "confidence (n)"], ["accommodation", "chỗ ở", "danh từ không đếm được"], ["departure", "sự khởi hành", "depart (v)"]], "grammar": [["Superlative (so sánh nhất)", "I spent a semester in Ireland last year, and it was the best decision of my studies.", "the + best là dạng so sánh nhất của good."], ["Non-defining relative clause with which (mệnh đề quan hệ không xác định)", "I applied for an exchange scholarship, which paid for my flights and part of my rent.", "\"which\" thay cho cả danh từ \"scholarship\" và thêm thông tin."], ["Conditional type 1 with modal (điều kiện loại 1 + could)", "If you prefer a quiet place, you could share a flat, but you'll need to search early.", "If + hiện tại đơn, kết quả dùng could để gợi ý."], ["Past simple with when (quá khứ đơn + when)", "My English was only average when I arrived in Canada.", "Hai hành động quá khứ gắn với thời điểm đến Canada."]], "tips": ["Trên diễn đàn, mỗi bài trả lời thường trả lời một câu hỏi riêng; hãy tìm tên người đăng để biết ai nói gì.", "Câu hỏi đúng/sai thường dựa vào so sánh nhỏ như \"higher\" hay \"lower\"; đọc kỹ từ này."]}}, {"id": "rd5-b1-06", "lvl": "B1", "topic": "environment", "genre": "report", "title": "Greenfield School Energy-Saving Project Results", "text": "Report: Greenfield School Energy-Saving Project\n\nIntroduction\nIn September, the Eco Club at Greenfield School started a six-month project to reduce the amount of electricity used in the school building. The aim was to cut energy use by ten per cent. This report explains what we did and what we found.\n\nWhat we did\nFirst, students checked each classroom every afternoon and recorded which lights, computers and projectors were left on. Second, we put stickers next to the switches to remind everyone to turn them off. Third, the caretaker replaced forty old light bulbs in the corridors with LED bulbs, which use much less electricity. Finally, we held a short assembly to explain the project to all students and teachers.\n\nResults\nOver the six months, electricity use fell by 14 per cent compared with the same period last year. The biggest improvement was in the computer room, where the number of computers left on overnight dropped from an average of twelve to only two. The new LED bulbs alone were responsible for about a third of the savings. Together, the changes saved the school around 900 pounds. However, some problems remained. In the science building, equipment was often left running because teachers were busy, and the stickers were less effective there.\n\nConclusion and recommendations\nThe project exceeded its target, which shows that small changes can make a big difference. We recommend that the school continues the daily checks next year and asks the science teachers to appoint a student monitor. We also suggest spending part of the money saved on new plants for the school garden.", "gist": "Báo cáo về dự án tiết kiệm điện của trường, giảm 14% mức tiêu thụ điện, vượt mục tiêu, kèm các đề xuất cho năm sau.", "qs": [{"kind": "main", "q": "What is the main purpose of the report?", "opts": ["To describe the results of a project to save electricity", "To ask for money to buy solar panels", "To advertise LED light bulbs", "To explain how to grow plants"], "a": 0, "ev": "This report explains what we did and what we found.", "why": "Báo cáo tường thuật việc đã làm và kết quả dự án tiết kiệm điện."}, {"kind": "detail", "q": "By how much did electricity use fall?", "opts": ["10 per cent", "12 per cent", "14 per cent", "20 per cent"], "a": 2, "ev": "electricity use fell by 14 per cent", "why": "Văn bản ghi: \"electricity use fell by 14 per cent\"."}, {"kind": "detail", "q": "What improved most in the computer room?", "opts": ["Computers were faster", "Fewer computers were left on overnight", "More students used computers", "The room became cooler"], "a": 1, "ev": "the number of computers left on overnight dropped from an average of twelve to only two", "why": "Số máy tính bật qua đêm giảm từ mười hai xuống hai."}, {"kind": "vocab", "q": "In the text, what does \"exceeded\" mean?", "opts": ["Missed", "Copied", "Did better than", "Delayed"], "a": 2, "ev": "The project exceeded its target", "why": "Mục tiêu 10% nhưng đạt 14%, nên \"exceeded\" nghĩa là vượt qua."}, {"kind": "tfng", "q": "The caretaker replaced old light bulbs in the corridors.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "the caretaker replaced forty old light bulbs in the corridors", "why": "Đúng: \"the caretaker replaced forty old light bulbs in the corridors\"."}, {"kind": "tfng", "q": "The aim of the project was to cut energy use by twenty per cent.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "The aim was to cut energy use by ten per cent", "why": "Sai: mục tiêu là mười phần trăm, không phải hai mươi."}, {"kind": "tfng", "q": "Parents gave money to help the Eco Club.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nhắc đến việc phụ huynh đóng góp tiền, nên là Not given."}, {"kind": "inference", "q": "What can be inferred about the science building?", "opts": ["It uses no electricity", "Teachers there had less time to follow the reminders", "Students there refused to join the project", "It has no LED bulbs"], "a": 1, "ev": "equipment was often left running because teachers were busy", "why": "Thiết bị hay bị để chạy vì giáo viên bận, nên họ ít thời gian làm theo nhắc nhở."}], "notes": {"vocab": [["reduce", "giảm", "reduce sth by + số"], ["recorded", "ghi lại", "record (v) / record (n)"], ["caretaker", "người trông coi trường"], ["assembly", "buổi họp toàn trường"], ["exceeded", "vượt quá", "exceed the target"], ["target", "mục tiêu, chỉ tiêu"], ["overnight", "qua đêm"], ["monitor", "người giám sát, lớp trưởng phụ trách"]], "grammar": [["Infinitive of aim (to + V chỉ mục đích)", "The aim was to cut energy use by ten per cent.", "Sau \"aim was\" dùng to + V để nêu mục tiêu."], ["Passive voice (câu bị động)", "recorded which lights, computers and projectors were left on", "were left on là bị động: tập trung vào đồ vật, không quan trọng ai để lại."], ["Non-defining relative clause (mệnh đề quan hệ không xác định)", "replaced forty old light bulbs in the corridors with LED bulbs, which use much less electricity", "\"which\" giải thích thêm về bóng đèn LED."], ["Recommend that clause (mệnh đề sau recommend)", "We recommend that the school continues the daily checks next year", "Sau recommend that, báo cáo viết ra đề xuất cụ thể."]], "tips": ["Báo cáo có tiêu đề từng phần (Introduction, Results, Conclusion); hãy đọc tiêu đề trước để biết thông tin nằm ở đâu.", "Số liệu thường ở phần Results, còn kiến nghị ở phần cuối với các từ như recommend, suggest."]}}, {"id": "rd5-b1-07", "lvl": "B1", "topic": "culture", "genre": "interview", "title": "Six Years on the Pavement: A Busker Talks", "text": "Interviewer: Thanks for talking to me, Marco. How long have you been playing in the street?\nMarco: About six years now. I started when I lost my job at a warehouse. I had an old guitar, so I thought, why not try?\nInterviewer: Was it difficult at the beginning?\nMarco: Very. I was so nervous that my hands shook, and nobody stopped to listen. If I had known how hard it would be, I might have stayed at home! But after a few weeks, a woman gave me a few coins and a smile, and that changed everything.\nInterviewer: Where do you usually play?\nMarco: Mostly near the central station, because it is busy in the morning. Some days I play by the river instead, where tourists walk slowly and have more time to listen.\nInterviewer: Do you need a permit?\nMarco: Yes. The city gives permits to musicians, and I have to renew mine every year. The rule is that we can't use loud amplifiers, which I don't mind, because I prefer a natural sound.\nInterviewer: What do you enjoy most?\nMarco: The surprises. Once a little girl danced in front of me for ten minutes while her father filmed her. I've also met people who now come every Friday just to hear one song.\nInterviewer: Is it a good way to earn a living?\nMarco: Not really. On a good day I make about forty euros, but in winter it is much less. That's why I also teach guitar to children twice a week.\nInterviewer: What advice would you give to a beginner?\nMarco: Choose songs that people already know, and never stop smiling, even when nobody is listening.", "gist": "Một nghệ sĩ đường phố kể về lý do bắt đầu, nơi biểu diễn, thu nhập và lời khuyên cho người mới.", "qs": [{"kind": "main", "q": "What is the interview mainly about?", "opts": ["How to make a guitar", "Marco's life and work as a street musician", "The history of the city's central station", "Why tourists dislike loud music"], "a": 1, "ev": "How long have you been playing in the street?", "why": "Cả buổi phỏng vấn xoay quanh việc Marco chơi nhạc ngoài đường: lý do bắt đầu, nơi chơi, thu nhập. Câu mở đầu \"How long have you been playing in the street?\" cho thấy chủ đề."}, {"kind": "detail", "q": "Why did Marco start playing in the street?", "opts": ["He wanted to meet tourists", "His father was a musician", "He lost his job", "He needed a permit"], "a": 2, "ev": "I started when I lost my job at a warehouse.", "why": "Marco nói: \"I started when I lost my job at a warehouse.\" nên lý do là mất việc."}, {"kind": "detail", "q": "Why does Marco sometimes play by the river?", "opts": ["Tourists walk slowly and have more time to listen", "The city requires it", "It is quieter in winter", "There are no permits there"], "a": 0, "ev": "tourists walk slowly and have more time to listen", "why": "Anh ấy giải thích: \"tourists walk slowly and have more time to listen\"."}, {"kind": "vocab", "q": "In the text, what does 'renew' mean?", "opts": ["To make a new one from nothing", "To pay money back", "To change into something different", "To make valid again for another period"], "a": 3, "ev": "I have to renew mine every year", "why": "\"Renew a permit\" là gia hạn để giấy phép còn hiệu lực; Marco phải làm việc này \"every year\"."}, {"kind": "tfng", "q": "Marco found the first weeks easy.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Very. I was so nervous that my hands shook", "why": "Marco trả lời \"Very\" khi được hỏi có khó không và nói tay run vì lo lắng, nên câu này sai."}, {"kind": "tfng", "q": "Marco has played music in other countries.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nhắc gì đến việc Marco chơi nhạc ở nước khác nên là Not given."}, {"kind": "inference", "q": "Why does Marco also teach guitar?", "opts": ["He no longer enjoys the street", "Street music alone does not give him a steady income", "The city forbids him from playing in winter", "He wants to open a school"], "a": 1, "ev": "Not really. On a good day I make about forty euros, but in winter it is much less.", "why": "Anh nói kiếm sống bằng nhạc đường phố \"Not really\" và mùa đông thu nhập ít hơn, nên có thể suy ra anh dạy guitar để có thêm thu nhập."}, {"kind": "tfng", "q": "Musicians in the city must not use loud amplifiers.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "we can't use loud amplifiers", "why": "Marco nói \"we can't use loud amplifiers\" nên câu này đúng."}], "notes": {"vocab": [["warehouse", "nhà kho", "work at a warehouse = làm ở kho"], ["nervous", "lo lắng, hồi hộp", "nervous about/of; danh từ: nervousness"], ["permit", "giấy phép", "đọc /ˈpɜːmɪt/ (danh từ), động từ permit /pəˈmɪt/"], ["renew", "gia hạn, làm mới", "renew a passport/licence"], ["amplifiers", "bộ khuếch đại âm thanh", "amplify (v) = khuếch đại"], ["tourists", "khách du lịch", "tourism (n), tourist attraction"], ["earn a living", "kiếm sống", "collocation cố định: earn a living"]], "grammar": [["Third conditional (câu điều kiện loại 3)", "If I had known how hard it would be, I might have stayed at home!", "If + had + V3, would/might have + V3: nói về điều không có thật trong quá khứ và kết quả tưởng tượng."], ["Present perfect continuous (hiện tại hoàn thành tiếp diễn)", "How long have you been playing in the street?", "have/has been + V-ing, hỏi \"how long\" về hoạt động bắt đầu trong quá khứ và vẫn tiếp tục."], ["so ... that (quá ... đến nỗi)", "I was so nervous that my hands shook", "so + tính từ + that + mệnh đề: diễn tả kết quả của mức độ cao."]], "tips": ["Bài phỏng vấn gồm các cặp hỏi-đáp; đọc câu hỏi của Interviewer trước để biết từng đoạn nói về chủ đề gì.", "Với câu True/False/Not given, tìm đúng câu của Marco rồi so sánh từng chi tiết; nếu không có thông tin thì chọn Not given."]}}, {"id": "rd5-b1-08", "lvl": "B1", "topic": "daily", "genre": "story", "title": "Linh's Rainy Arrival in Da Nang", "text": "When Linh stepped off the train in Da Nang, it was raining, and she had two heavy bags and no umbrella. She had moved there for a new job at a small design company, but she knew nobody in the city.\n\nOn Monday, she got lost twice on her way to work. A shop owner drew a map on a napkin for her, but she still arrived ten minutes late. Her manager, Mr Tran, only laughed. \"Everybody gets lost in the first week,\" he said.\n\nOn Tuesday, she tried to cook in her tiny kitchen, but the gas cooker did not work, so she ate bread and bananas for dinner. On Wednesday, a neighbour called Mai knocked on her door and showed her how to turn on the gas. Mai also took her to a cheap noodle stall nearby, which soon became Linh's favourite place to eat.\n\nBy Thursday, Linh was learning the bus routes, and she no longer needed her phone to find the office. On Friday evening, her colleagues invited her to the beach. She had been feeling lonely all week, but as she watched the sun go down over the sea, she realised that the city was starting to feel like home. That night she called her mother. \"It was hard at first,\" she said, \"but I think I'm going to be fine.\"", "gist": "Câu chuyện về tuần đầu tiên của Linh ở thành phố mới, từ lạc đường và cô đơn đến cảm thấy như ở nhà.", "qs": [{"kind": "main", "q": "What is the story mainly about?", "opts": ["A woman who loses her job", "A woman's difficult but improving first week in a new city", "A manager who is angry with a new worker", "A trip to the beach with friends"], "a": 1, "ev": "she realised that the city was starting to feel like home", "why": "Qua cả tuần, Linh từ khó khăn đến cảm thấy thành phố \"was starting to feel like home\", nên ý chính là tuần đầu khó khăn nhưng dần tốt lên."}, {"kind": "detail", "q": "Why was Linh late on Monday?", "opts": ["It was raining too hard", "She missed the bus", "She got lost on the way", "She forgot her phone"], "a": 2, "ev": "she got lost twice on her way to work", "why": "Văn bản nói \"she got lost twice on her way to work\" nên cô đến muộn vì lạc đường."}, {"kind": "detail", "q": "Who showed Linh how to turn on the gas?", "opts": ["Her manager", "Her neighbour Mai", "A shop owner", "Her mother"], "a": 1, "ev": "a neighbour called Mai knocked on her door and showed her how to turn on the gas", "why": "Đoạn 3 viết: \"a neighbour called Mai ... showed her how to turn on the gas\"."}, {"kind": "vocab", "q": "In the text, what does 'stall' mean?", "opts": ["A small place for selling food outdoors", "A large restaurant", "A kind of kitchen", "A bus station"], "a": 0, "ev": "a cheap noodle stall nearby", "why": "\"Noodle stall\" là quầy/hàng bán mì nhỏ, nên stall là nơi bán đồ ăn ngoài trời."}, {"kind": "tfng", "q": "Linh arrived at work on time on Monday.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "she still arrived ten minutes late", "why": "Bài ghi \"she still arrived ten minutes late\" nên câu này sai."}, {"kind": "tfng", "q": "Mai works at the noodle stall.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài chỉ nói Mai đưa Linh đến quầy mì, không nói Mai làm ở đó nên là Not given."}, {"kind": "inference", "q": "How did Linh probably feel at the end of the week?", "opts": ["Hopeful about her new life", "Angry with her colleagues", "Ready to leave the city", "Proud of her cooking"], "a": 0, "ev": "I think I'm going to be fine", "why": "Cô nói với mẹ \"I think I'm going to be fine\" và thấy thành phố như nhà, nên cô cảm thấy hy vọng."}, {"kind": "detail", "q": "Where did Linh's colleagues take her on Friday evening?", "opts": ["To a noodle stall", "To the beach", "To the office", "To the train station"], "a": 1, "ev": "her colleagues invited her to the beach", "why": "Đoạn cuối: \"her colleagues invited her to the beach\"."}], "notes": {"vocab": [["napkin", "khăn giấy ăn", "draw a map on a napkin"], ["manager", "quản lý", "manage (v), management (n)"], ["neighbour", "hàng xóm", "neighbourhood = khu phố"], ["stall", "quầy, sạp hàng", "noodle stall, market stall"], ["routes", "tuyến đường", "bus route, route map"], ["colleagues", "đồng nghiệp", "colleague = co-worker"], ["lonely", "cô đơn", "lonely ≠ alone (alone: chỉ một mình)"]], "grammar": [["Past perfect (quá khứ hoàn thành)", "She had moved there for a new job at a small design company", "had + V3 diễn tả việc xảy ra trước một mốc trong quá khứ (trước khi cô bước xuống tàu)."], ["Past perfect continuous (quá khứ hoàn thành tiếp diễn)", "She had been feeling lonely all week", "had been + V-ing: nhấn mạnh trạng thái kéo dài đến một thời điểm trong quá khứ."], ["Result clause with so (mệnh đề chỉ kết quả)", "the gas cooker did not work, so she ate bread and bananas for dinner", "so + mệnh đề: nêu kết quả của sự việc trước đó."]], "tips": ["Truyện kể theo trình tự thời gian: để ý các mốc Monday, Tuesday, Wednesday... để tìm chi tiết nhanh.", "Cảm xúc của nhân vật thường thể hiện ở đoạn cuối; đọc kỹ để trả lời câu suy luận."]}}, {"id": "rd5-b1-09", "lvl": "B1", "topic": "science", "genre": "article", "title": "Pulled by the Moon: Why the Sea Rises and Falls", "text": "Anyone who has spent a day at the beach has seen the sea rise and fall. These changes are called tides, and they are mostly caused by the moon.\n\nThe moon pulls on everything on Earth with a force called gravity. The pull is strongest on the side of the planet that is closest to the moon. Because water can move easily, the ocean on that side rises into a bulge, and this bulge is the high tide. Surprisingly, a second bulge forms on the opposite side of the Earth, because the planet itself is pulled towards the moon more strongly than the water far away. Between the two bulges, the sea level is lower, and this is low tide.\n\nThe Earth turns once every 24 hours, so most coasts have two high tides and two low tides each day. The gap between one high tide and the next is a little more than twelve hours, which means that each tide arrives about an hour later every day.\n\nThe sun also pulls on the oceans, but it is much further away, so its effect is weaker. When the sun, Earth and moon form a straight line, at new moon and full moon, their pulls work together and produce very high and very low tides, called spring tides. If the moon is at a right angle to the sun, the tides are smaller.\n\nLocal conditions matter too. In some narrow bays, the water is forced into a small space, so the tides can be more than ten metres high. Sailors and fishermen have always checked tide tables before they go out to sea.", "gist": "Bài viết giải thích mặt trăng và mặt trời tạo ra thủy triều bằng lực hấp dẫn như thế nào và vì sao độ cao thủy triều khác nhau.", "qs": [{"kind": "main", "q": "What is the main idea of the article?", "opts": ["The sun is the biggest force on the oceans", "Fishermen need tide tables", "The moon's gravity mainly causes the tides", "The Earth turns once every 24 hours"], "a": 2, "ev": "These changes are called tides, and they are mostly caused by the moon.", "why": "Câu thứ hai nêu ý chính: thủy triều \"are mostly caused by the moon\", và cả bài giải thích cơ chế này."}, {"kind": "detail", "q": "How many high tides do most coasts have each day?", "opts": ["One", "Four", "Three", "Two"], "a": 3, "ev": "most coasts have two high tides and two low tides each day", "why": "Bài nói rõ \"two high tides and two low tides each day\"."}, {"kind": "detail", "q": "When do spring tides happen?", "opts": ["When the sun, Earth and moon form a straight line", "When the moon is far from the Earth", "When the sea is very narrow", "When it is summer"], "a": 0, "ev": "When the sun, Earth and moon form a straight line", "why": "Spring tides xuất hiện khi mặt trời, Trái Đất và mặt trăng thẳng hàng, lúc trăng mới và trăng tròn."}, {"kind": "vocab", "q": "In the text, what does 'bulge' mean?", "opts": ["A deep hole", "A rounded part that sticks out", "A very strong wave", "A kind of boat"], "a": 1, "ev": "the ocean on that side rises into a bulge", "why": "Nước biển \"rises into a bulge\" nghĩa là dâng lên thành một chỗ phình ra."}, {"kind": "tfng", "q": "The sun has a stronger effect on the tides than the moon.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "it is much further away, so its effect is weaker", "why": "Bài nói tác động của mặt trời yếu hơn vì ở xa hơn, nên câu này sai."}, {"kind": "tfng", "q": "Tides are higher in summer than in winter.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không so sánh thủy triều theo mùa nên là Not given."}, {"kind": "inference", "q": "Why do sailors and fishermen check tide tables?", "opts": ["Tides can be predicted and affect their work at sea", "They want to study the moon", "Tide tables show where fish live", "Tides only happen at night"], "a": 0, "ev": "Sailors and fishermen have always checked tide tables before they go out to sea.", "why": "Họ luôn xem bảng thủy triều trước khi ra khơi, nên có thể suy ra thủy triều dự đoán được và ảnh hưởng đến công việc."}, {"kind": "tfng", "q": "In some narrow bays the tides can be more than ten metres high.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "the tides can be more than ten metres high", "why": "Bài nói ở một số vịnh hẹp \"the tides can be more than ten metres high\" nên câu này đúng."}], "notes": {"vocab": [["gravity", "lực hấp dẫn, trọng lực", "gravitational (adj)"], ["bulge", "chỗ phình ra", "a bulge of water"], ["opposite", "đối diện", "on the opposite side of..."], ["coasts", "bờ biển", "coastal (adj), coastline"], ["spring tides", "triều cường", "không liên quan đến mùa xuân"], ["right angle", "góc vuông", "90 độ"], ["sailors", "thủy thủ", "sail (v), sailing (n)"], ["tide tables", "bảng thủy triều", "bảng ghi giờ nước lên xuống"]], "grammar": [["Passive voice (câu bị động)", "These changes are called tides, and they are mostly caused by the moon.", "be + V3 (+ by ...): nhấn mạnh sự việc/kết quả hơn người hay vật gây ra."], ["Relative clause (mệnh đề quan hệ)", "Anyone who has spent a day at the beach has seen the sea rise and fall.", "who + mệnh đề bổ nghĩa cho \"anyone\", nói rõ ai đang được nhắc đến."], ["First conditional (điều kiện loại 1)", "If the moon is at a right angle to the sun, the tides are smaller.", "If + hiện tại đơn, hiện tại đơn: dùng cho quy luật khoa học luôn đúng."]], "tips": ["Bài khoa học thường nêu hiện tượng ở đoạn đầu rồi giải thích theo từng đoạn; câu đầu mỗi đoạn cho biết nội dung đoạn đó.", "Chú ý các từ chỉ so sánh (stronger, weaker, much further) để phân biệt đúng/sai."]}}, {"id": "rd5-b1-10", "lvl": "B1", "topic": "work", "genre": "instructions", "title": "Seven Steps to a Clear Work Email", "text": "How to Write a Clear Professional Email\n\nA good work email is short, polite and easy to act on. Follow these steps.\n\nStep 1: Write a specific subject line. Instead of 'Question', write 'Question about Friday's meeting time'. Readers often decide whether to open a message from the subject alone.\n\nStep 2: Begin with a suitable greeting. Use 'Dear Ms Nguyen' for someone you do not know well, and 'Hi Sam' for a colleague you talk to every day.\n\nStep 3: State your purpose in the first sentence. For example: 'I am writing to ask whether we can move the meeting to Thursday.' Do not make the reader search for your point.\n\nStep 4: Keep the body brief. Use short paragraphs, and give only the details the reader needs. If you have several requests, put them in a list so that none of them is missed.\n\nStep 5: Say clearly what you want and when. 'Could you reply by Wednesday noon?' is much more useful than 'Please reply soon.'\n\nStep 6: Finish politely. Thank the reader, and use an ending such as 'Kind regards' or 'Best wishes', followed by your full name.\n\nStep 7: Check before you send. Read the email aloud, look for spelling mistakes, and make sure that any attachment is really attached. Many people forget this, which can look careless.\n\nRemember: if the message is angry or emotional, wait an hour before sending it. You will usually write something better.", "gist": "Hướng dẫn bảy bước để viết một email công việc rõ ràng, lịch sự và dễ hành động.", "qs": [{"kind": "main", "q": "What is the purpose of the text?", "opts": ["To explain how to write an effective work email", "To describe a company's email rules", "To argue that emails are better than phone calls", "To teach spelling and grammar"], "a": 0, "ev": "A good work email is short, polite and easy to act on. Follow these steps.", "why": "Đoạn mở đầu nói email tốt cần ngắn, lịch sự, dễ hành động và đưa ra các bước, nên mục đích là hướng dẫn cách viết email."}, {"kind": "detail", "q": "What should a good subject line be?", "opts": ["As short as possible", "Specific", "A single word like 'Question'", "Left empty"], "a": 1, "ev": "Write a specific subject line.", "why": "Bước 1 yêu cầu \"Write a specific subject line.\" thay vì từ chung chung như 'Question'."}, {"kind": "detail", "q": "When should you use 'Dear Ms Nguyen'?", "opts": ["For a close friend", "For your manager only", "For someone you do not know well", "At the end of the email"], "a": 2, "ev": "Use 'Dear Ms Nguyen' for someone you do not know well", "why": "Bài nói dùng 'Dear Ms Nguyen' cho người bạn chưa biết rõ."}, {"kind": "vocab", "q": "In the text, what does 'careless' mean?", "opts": ["Very polite", "Not paying enough attention", "Too short", "Friendly"], "a": 1, "ev": "Many people forget this, which can look careless.", "why": "Quên đính kèm tệp trông là thiếu chú ý, nên careless là cẩu thả, thiếu cẩn thận."}, {"kind": "tfng", "q": "You should put several requests in one long paragraph.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "put them in a list so that none of them is missed", "why": "Bài khuyên đặt nhiều yêu cầu vào một danh sách, không phải một đoạn dài, nên câu này sai."}, {"kind": "tfng", "q": "An email should never be longer than 100 words.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài chỉ nói giữ nội dung ngắn gọn, không đưa ra giới hạn số từ nên là Not given."}, {"kind": "inference", "q": "Why does the writer advise waiting an hour before sending an angry email?", "opts": ["Because emails are slow to send", "Because you may write a better message after calming down", "Because the reader will be busy", "Because angry emails are not allowed"], "a": 1, "ev": "wait an hour before sending it. You will usually write something better.", "why": "Bài nói sau một giờ \"You will usually write something better\", nên có thể suy ra bạn bình tĩnh hơn và viết tốt hơn."}, {"kind": "detail", "q": "According to Step 5, which sentence is more useful?", "opts": ["Please reply soon.", "Could you reply by Wednesday noon?", "Write back when you can.", "Answer me."], "a": 1, "ev": "'Could you reply by Wednesday noon?' is much more useful than 'Please reply soon.'", "why": "Bước 5 nói câu có thời hạn cụ thể \"Could you reply by Wednesday noon?\" hữu ích hơn nhiều."}], "notes": {"vocab": [["subject line", "dòng tiêu đề email", "write a clear subject line"], ["greeting", "lời chào", "greet (v)"], ["purpose", "mục đích", "for the purpose of; on purpose = cố ý"], ["brief", "ngắn gọn", "in brief = tóm lại"], ["requests", "yêu cầu", "make a request, request sth from sb"], ["attachment", "tệp đính kèm", "attach (v)"], ["careless", "cẩu thả", "care + less; ≠ careful"], ["Kind regards", "trân trọng (kết thư)", "cách kết thư lịch sự, trung tính"]], "grammar": [["Imperative (câu mệnh lệnh)", "Write a specific subject line.", "Động từ nguyên mẫu ở đầu câu, thường dùng trong hướng dẫn để bảo người đọc làm gì."], ["Purpose clause with so that (mệnh đề chỉ mục đích)", "put them in a list so that none of them is missed", "so that + mệnh đề: nêu mục đích; ở đây dùng thêm thể bị động (is missed)."], ["Participle phrase (cụm phân từ)", "followed by your full name", "V3 + by ...: cụm phân từ quá khứ mang nghĩa bị động, nghĩa là \"và sau đó là\"."]], "tips": ["Văn bản hướng dẫn chia thành các bước đánh số; hãy gạch chân động từ đầu câu để nắm việc cần làm ở mỗi bước.", "Phần ví dụ trong ngoặc đơn giúp hiểu và kiểm tra đáp án chi tiết rất nhanh."]}}, {"id": "rd5-b1-11", "lvl": "B1", "topic": "medical", "genre": "article", "title": "From Mouth to Anus: Following Food Through the Body", "text": "The digestive system breaks down the food we eat so that the body can use it for energy, growth and repair. The process takes about one to two days and has several steps.\n\nDigestion begins in the mouth. The teeth cut and crush the food, while saliva makes it wet and starts to break down starch. Then the tongue pushes the soft food to the back of the throat, and it is swallowed. The food travels down a muscular tube called the oesophagus, which squeezes it towards the stomach.\n\nIn the stomach, the food is mixed with acid and churned by strong muscles for about two to four hours. The result is a thick liquid. This liquid then moves slowly into the small intestine, which is about six metres long. Here, most digestion is finished, helped by bile from the liver and juices from the pancreas. The walls of the small intestine are covered with tiny folds, and through them nutrients pass into the blood. The blood then carries the nutrients to every part of the body.\n\nWhat is left, mainly water and fibre, enters the large intestine. This organ absorbs most of the water, and the remaining waste becomes solid. Finally, the waste is stored in the rectum and leaves the body through the anus.\n\nEating plenty of fibre and drinking enough water help the whole system to work well.", "gist": "Bài viết mô tả từng bước của hệ tiêu hóa, từ miệng, thực quản, dạ dày, ruột non đến ruột già và trực tràng.", "qs": [{"kind": "main", "q": "What is the passage mainly about?", "opts": ["How the stomach makes acid", "The steps by which the body digests food", "Why fibre is important", "How blood moves around the body"], "a": 1, "ev": "The digestive system breaks down the food we eat so that the body can use it for energy, growth and repair.", "why": "Câu đầu cho thấy bài mô tả hệ tiêu hóa phân giải thức ăn và các bước của quá trình đó."}, {"kind": "detail", "q": "How long does food stay in the stomach?", "opts": ["About one hour", "About two to four hours", "About six hours", "About one to two days"], "a": 1, "ev": "for about two to four hours", "why": "Bài nói thức ăn được trộn \"for about two to four hours\" trong dạ dày."}, {"kind": "detail", "q": "Where do nutrients pass into the blood?", "opts": ["In the small intestine", "In the stomach", "In the oesophagus", "In the rectum"], "a": 0, "ev": "The walls of the small intestine are covered with tiny folds, and through them nutrients pass into the blood.", "why": "Chất dinh dưỡng đi vào máu qua các nếp gấp nhỏ ở thành ruột non."}, {"kind": "vocab", "q": "In the text, what does 'absorbs' mean?", "opts": ["Pushes out", "Cuts into small pieces", "Takes in", "Stores for a long time"], "a": 2, "ev": "This organ absorbs most of the water", "why": "Ruột già \"absorbs most of the water\" nghĩa là hấp thu, tức lấy nước vào."}, {"kind": "tfng", "q": "Most of the water is absorbed in the small intestine.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "This organ absorbs most of the water", "why": "Bài nói ruột già (large intestine) hấp thu phần lớn nước, không phải ruột non, nên câu này sai."}, {"kind": "tfng", "q": "Eating fibre prevents stomach ulcers.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài chỉ nói chất xơ giúp hệ tiêu hóa hoạt động tốt, không nói về loét dạ dày nên là Not given."}, {"kind": "inference", "q": "What is the likely function of the tiny folds in the small intestine?", "opts": ["To crush food", "To help the body take in nutrients", "To make saliva", "To store waste"], "a": 1, "ev": "The walls of the small intestine are covered with tiny folds, and through them nutrients pass into the blood.", "why": "Chất dinh dưỡng đi vào máu qua các nếp gấp, nên có thể suy ra chúng giúp cơ thể hấp thu dưỡng chất."}, {"kind": "detail", "q": "What does saliva do?", "opts": ["It mixes food with acid", "It carries nutrients to the blood", "It makes food wet and starts to break down starch", "It squeezes food towards the stomach"], "a": 2, "ev": "saliva makes it wet and starts to break down starch", "why": "Nước bọt \"makes it wet and starts to break down starch\"."}], "notes": {"vocab": [["saliva", "nước bọt", "salivary glands = tuyến nước bọt"], ["starch", "tinh bột", "có nhiều trong gạo, khoai"], ["oesophagus", "thực quản", "Mỹ: esophagus"], ["churned", "khuấy trộn mạnh", "churn (v)"], ["small intestine", "ruột non", "large intestine = ruột già"], ["pancreas", "tuyến tụy", "pancreatic (adj)"], ["nutrients", "chất dinh dưỡng", "nutrition (n), nutritious (adj)"], ["absorbs", "hấp thu", "absorb (v), absorption (n)"]], "grammar": [["Purpose clause with so that (mệnh đề chỉ mục đích)", "so that the body can use it for energy, growth and repair", "so that + chủ ngữ + can: nêu mục đích của việc tiêu hóa."], ["Passive voice (câu bị động)", "the food is mixed with acid and churned by strong muscles", "be + V3 (+ by ...): quy trình sinh học thường dùng bị động vì trọng tâm là thức ăn."], ["Non-defining relative clause (mệnh đề quan hệ không xác định)", "which squeezes it towards the stomach", "which + động từ, bổ sung thông tin cho \"the oesophagus\", đặt sau dấu phẩy."], ["Nominal relative clause (mệnh đề danh từ)", "What is left, mainly water and fibre, enters the large intestine.", "What + mệnh đề làm chủ ngữ, nghĩa là \"phần còn lại\"."]], "tips": ["Bài mô tả quy trình theo thứ tự: miệng, dạ dày, ruột non, ruột già. Hãy đánh dấu từ chỉ trình tự như then, finally.", "Với bài giải phẫu, ghi nhớ mỗi cơ quan đi kèm một chức năng chính (ví dụ ruột non: hấp thu chất dinh dưỡng)."]}}, {"id": "rd5-b1-12", "lvl": "B1", "topic": "medical", "genre": "dialogue", "title": "Allergies and Tablets: A Nurse's Questions", "text": "Nurse Hanna: Good morning, Mr Brown. My name is Hanna, and I'm the nurse who will take your medical history today. Is it all right if I ask you a few questions?\nMr Brown: Of course.\nNurse Hanna: Thank you. First, do you have any allergies to medicines, food or anything else?\nMr Brown: Yes, I'm allergic to penicillin. I had a rash all over my body when I took it as a child.\nNurse Hanna: Thank you, that's very important. Have you had any other reaction, such as swelling or difficulty breathing?\nMr Brown: No, only the rash. I'm also allergic to peanuts, but they just make my mouth itchy.\nNurse Hanna: I see. I've written both down. Now, are you taking any medication at the moment, including vitamins or herbal products?\nMr Brown: I take a tablet for my blood pressure every morning. And I use an inhaler when I feel short of breath, usually about twice a week.\nNurse Hanna: Do you remember the names of these medicines?\nMr Brown: Not exactly. I have the boxes in my bag, though. Would you like to see them?\nNurse Hanna: Yes, please. That would be very helpful. Do you ever forget to take your tablet?\nMr Brown: Sometimes, if I'm in a hurry. My wife usually reminds me.\nNurse Hanna: That's understandable. Thank you for being so clear, Mr Brown. The doctor will see you in about ten minutes, and she will go through everything with you.", "gist": "Y tá hỏi bệnh sử của ông Brown về dị ứng và thuốc đang dùng bằng những câu hỏi lịch sự, rõ ràng.", "qs": [{"kind": "main", "q": "What is the nurse's main purpose in this conversation?", "opts": ["To give Mr Brown a new medicine", "To collect information about his allergies and medication", "To explain a surgery", "To ask him to pay a bill"], "a": 1, "ev": "I'm the nurse who will take your medical history today.", "why": "Y tá nói mình sẽ \"take your medical history\" và hỏi về dị ứng, thuốc, nên mục đích là thu thập thông tin."}, {"kind": "detail", "q": "What happened when Mr Brown took penicillin as a child?", "opts": ["He had difficulty breathing", "He had a rash", "His mouth became itchy", "He felt sleepy"], "a": 1, "ev": "I had a rash all over my body when I took it as a child.", "why": "Ông Brown kể: \"I had a rash all over my body\" khi dùng penicillin."}, {"kind": "detail", "q": "How often does Mr Brown use his inhaler?", "opts": ["Every morning", "Every day after meals", "Only in winter", "About twice a week"], "a": 3, "ev": "usually about twice a week", "why": "Ông nói dùng ống hít \"usually about twice a week\"."}, {"kind": "vocab", "q": "In the text, what does 'inhaler' mean?", "opts": ["A device for breathing medicine into the lungs", "A tablet for blood pressure", "A kind of vitamin", "A machine that measures breathing"], "a": 0, "ev": "I use an inhaler when I feel short of breath", "why": "Ông dùng inhaler khi khó thở, tức là dụng cụ đưa thuốc vào phổi bằng đường hít."}, {"kind": "tfng", "q": "Mr Brown had trouble breathing after taking penicillin.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "No, only the rash.", "why": "Ông trả lời \"No, only the rash\" nên không bị khó thở, câu này sai."}, {"kind": "tfng", "q": "Mr Brown has had an operation before.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Cuộc hội thoại không nhắc đến phẫu thuật nên là Not given."}, {"kind": "inference", "q": "Why does the nurse want to see the medicine boxes?", "opts": ["To check the exact names of his medicines", "To throw them away", "To give them to his wife", "To test his allergies"], "a": 0, "ev": "Not exactly. I have the boxes in my bag, though. Would you like to see them?", "why": "Ông Brown không nhớ chính xác tên thuốc nhưng có hộp thuốc; y tá đồng ý xem, nên có thể suy ra để kiểm tra tên thuốc."}, {"kind": "detail", "q": "Who usually reminds Mr Brown to take his tablet?", "opts": ["The doctor", "His wife", "The nurse", "His neighbour"], "a": 1, "ev": "My wife usually reminds me.", "why": "Ông nói: \"My wife usually reminds me.\""}], "notes": {"vocab": [["medical history", "bệnh sử", "take a medical history = hỏi bệnh sử"], ["allergic", "dị ứng", "allergic to + danh từ; allergy (n)"], ["rash", "phát ban", "skin rash"], ["swelling", "sưng", "swell (v), swollen (adj)"], ["itchy", "ngứa", "itch (v/n)"], ["medication", "thuốc (nói chung)", "không đếm được; medicine cũng gần nghĩa"], ["inhaler", "ống hít", "inhale = hít vào"], ["blood pressure", "huyết áp", "high/low blood pressure"]], "grammar": [["Polite permission (xin phép lịch sự)", "Is it all right if I ask you a few questions?", "Is it all right if + mệnh đề: cách xin phép nhẹ nhàng trước khi hỏi bệnh nhân."], ["Polite offer (lời đề nghị lịch sự)", "Would you like to see them?", "Would you like to + V: đề nghị lịch sự, trang trọng hơn \"Do you want to\"."], ["Present perfect (hiện tại hoàn thành)", "Have you had any other reaction, such as swelling or difficulty breathing?", "have + V3: hỏi về trải nghiệm từ trước đến nay mà không nói rõ thời điểm."]], "tips": ["Trong hội thoại y khoa, y tá hỏi lần lượt từng chủ đề (dị ứng, rồi thuốc); xác định chủ đề của mỗi câu hỏi để tìm đáp án nhanh.", "Để ý cách y tá dùng những câu lịch sự (Is it all right if..., Would you like...) vì rất hữu ích khi giao tiếp với bệnh nhân."]}}, {"id": "rd5-b1-13", "lvl": "B1", "topic": "medical", "genre": "leaflet", "title": "Living Well with High Blood Pressure: A Patient Guide", "text": "Patient Information: Living Well with High Blood Pressure\n\nWhat is high blood pressure?\nBlood pressure is the force of blood pushing against the walls of your arteries. When this force stays too high for a long time, your heart has to work harder, and your arteries can become damaged. Many people feel completely well, so the problem is often found only during a check-up.\n\nWhat can you do?\n- Eat less salt. Read food labels, and try herbs instead of salt when you cook.\n- Eat more vegetables and fruit every day.\n- Walk, cycle or swim for about 30 minutes on most days. If you have not exercised for a long time, start slowly.\n- Keep a healthy weight. Even losing a few kilos can help.\n- Do not smoke, and drink little alcohol.\n\nTaking your medicine\nIf your doctor has prescribed tablets, take them at the same time each day. Do not stop taking them just because you feel better. If you notice side effects, such as a dry cough or dizziness, speak to your doctor or pharmacist before you make any changes.\n\nChecking at home\nMany patients measure their blood pressure at home. Sit quietly for five minutes before you start, and write down each result. Bring your notes to your next appointment.\n\nWhen to get help\nCall your doctor at once if you have a severe headache, chest pain or sudden weakness in one arm.", "gist": "Tờ rơi giải thích huyết áp cao là gì và hướng dẫn thay đổi lối sống, uống thuốc, theo dõi tại nhà và khi nào cần gọi bác sĩ.", "qs": [{"kind": "main", "q": "What is the main purpose of this leaflet?", "opts": ["To explain high blood pressure and give advice for daily life", "To describe how doctors perform heart operations", "To advertise a new blood pressure medicine", "To teach students the parts of an artery"], "a": 0, "ev": "Blood pressure is the force of blood pushing against the walls of your arteries.", "why": "Tờ rơi giải thích huyết áp là gì rồi đưa ra lời khuyên về ăn uống, vận động, thuốc và theo dõi tại nhà."}, {"kind": "detail", "q": "What can happen if blood pressure stays too high for a long time?", "opts": ["The blood becomes too thick to move", "The lungs stop taking in air", "The heart works harder and the arteries may be damaged", "The patient always feels very ill"], "a": 2, "ev": "your heart has to work harder, and your arteries can become damaged", "why": "Văn bản nói \"your heart has to work harder, and your arteries can become damaged\": tim làm việc nhiều hơn và động mạch có thể bị tổn thương."}, {"kind": "detail", "q": "What should a patient do before measuring blood pressure at home?", "opts": ["Drink a cup of coffee", "Sit quietly for five minutes", "Walk around the house", "Take an extra tablet"], "a": 1, "ev": "Sit quietly for five minutes before you start", "why": "Câu \"Sit quietly for five minutes before you start\" cho biết cần ngồi yên 5 phút trước khi đo."}, {"kind": "vocab", "q": "In the text, what does 'prescribed' mean?", "opts": ["Bought without advice", "Mixed with food", "Taken away from a patient", "Officially ordered by a doctor"], "a": 3, "ev": "If your doctor has prescribed tablets", "why": "\"prescribed\" nghĩa là bác sĩ kê đơn, như trong \"If your doctor has prescribed tablets\"."}, {"kind": "inference", "q": "Why does the leaflet say not to stop taking tablets when you feel better?", "opts": ["Feeling well does not always mean the pressure is normal", "Tablets are cheaper when taken for longer", "Doctors dislike changing treatment", "Side effects only happen after stopping"], "a": 0, "ev": "Many people feel completely well, so the problem is often found only during a check-up.", "why": "Đoạn đầu nói nhiều người cảm thấy hoàn toàn khỏe dù huyết áp cao, nên cảm giác khỏe không chứng tỏ huyết áp đã bình thường."}, {"kind": "tfng", "q": "The leaflet advises people who have not exercised for a long time to begin with hard exercise.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "start slowly", "why": "Tờ rơi nói \"start slowly\" (bắt đầu từ từ), nên phát biểu này sai."}, {"kind": "tfng", "q": "The leaflet recommends one particular brand of home blood pressure monitor.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản không nhắc đến bất kỳ nhãn hiệu máy đo nào."}, {"kind": "tfng", "q": "Sudden weakness in one arm is a reason to call a doctor immediately.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "Call your doctor at once if you have a severe headache, chest pain or sudden weakness in one arm.", "why": "Câu \"Call your doctor at once if ... sudden weakness in one arm\" xác nhận phát biểu đúng."}], "notes": {"vocab": [["force", "lực (đẩy của máu)", "blood pressure = lực máu tác động lên thành động mạch"], ["damaged", "bị tổn thương", "damage (n/v)"], ["herbs", "các loại thảo mộc", "dùng thay muối khi nấu ăn"], ["prescribed", "(bác sĩ) kê đơn", "prescription (n) = đơn thuốc"], ["side effects", "tác dụng phụ", "thường đi với 'notice/cause'"], ["dizziness", "cảm giác chóng mặt", "tính từ: dizzy"], ["pharmacist", "dược sĩ", "pharmacy = hiệu thuốc"]], "grammar": [["Time clause with 'when' (mệnh đề thời gian)", "When this force stays too high for a long time, your heart has to work harder", "Mệnh đề 'when' + hiện tại đơn nói về điều xảy ra thường xuyên hoặc luôn đúng; mệnh đề chính cũng ở hiện tại."], ["First conditional with imperative (câu điều kiện loại 1 + mệnh lệnh)", "If your doctor has prescribed tablets, take them at the same time each day.", "Mệnh đề 'if' dùng hiện tại hoàn thành, mệnh đề chính là câu mệnh lệnh để đưa hướng dẫn."], ["Negative imperative + -ing (mệnh lệnh phủ định)", "Do not stop taking them just because you feel better.", "'stop + V-ing' nghĩa là ngừng làm gì; 'Do not' tạo lời khuyên cấm đoán rõ ràng."], ["Gerund as subject (danh động từ làm chủ ngữ)", "Even losing a few kilos can help.", "V-ing đứng đầu câu làm chủ ngữ; 'even' nhấn mạnh rằng một thay đổi nhỏ cũng có ích."]], "tips": ["Tờ rơi chia thành các tiêu đề nhỏ: đọc tiêu đề trước để biết mỗi phần trả lời câu hỏi nào, rồi quét tìm chi tiết.", "Các gạch đầu dòng thường là lời khuyên; chú ý động từ mệnh lệnh ở đầu câu (Eat, Walk, Keep)."]}}, {"id": "rd5-b1-14", "lvl": "B1", "topic": "medical", "genre": "blog", "title": "What I Learned at a Weekend First-Aid Course", "text": "My Weekend at a First-Aid Course\n\nLast Saturday I finally did something I had planned for months: a two-day first-aid course at my local community centre. I am a second-year student, and I wanted to feel useful if someone collapsed in front of me.\n\nThe instructor, a retired paramedic called Mr Hale, began by saying that most people freeze in an emergency. \"Your first job is to stay calm and check that the area is safe,\" he told us. Then we learned the basics: how to check if a person is breathing, how to put someone in the recovery position, and how to stop bleeding by pressing firmly on a clean cloth.\n\nThe part I found hardest was CPR. We practised on plastic dummies, pushing hard and fast in the centre of the chest. After two minutes my arms were shaking! Mr Hale explained that if the rescuer gets tired, another person should take over. He also said that the emergency number should be called before starting, or by someone else, because help arrives faster that way.\n\nI was surprised by how much I enjoyed it. Everyone laughed a lot, even though the topic was serious. Of course, one weekend does not make me an expert, and I will need to repeat the course every few years to stay up to date. Still, I now feel much more confident.\n\nIf you have never tried a course like this, I would recommend it. Ask at your local community centre or hospital.", "gist": "Bài blog kể về hai ngày học sơ cứu: giữ bình tĩnh, tư thế hồi phục, cầm máu và hồi sinh tim phổi, cùng cảm nhận tự tin hơn của tác giả.", "qs": [{"kind": "main", "q": "What is the blog mainly about?", "opts": ["How to become a paramedic", "The writer's experience of learning first aid", "A new emergency phone number", "Why community centres are closing"], "a": 1, "ev": "Last Saturday I finally did something I had planned for months: a two-day first-aid course", "why": "Bài kể lại trải nghiệm học khóa sơ cứu hai ngày của tác giả."}, {"kind": "detail", "q": "According to Mr Hale, what is a person's first job in an emergency?", "opts": ["To phone the writer's family", "To start CPR immediately", "To move the patient to a car", "To stay calm and check the area is safe"], "a": 3, "ev": "Your first job is to stay calm and check that the area is safe", "why": "Mr Hale nói \"Your first job is to stay calm and check that the area is safe\"."}, {"kind": "detail", "q": "Which part of the course did the writer find hardest?", "opts": ["CPR", "The recovery position", "Stopping bleeding", "Checking breathing"], "a": 0, "ev": "The part I found hardest was CPR.", "why": "Câu \"The part I found hardest was CPR\" cho đáp án trực tiếp."}, {"kind": "vocab", "q": "In the text, what does 'freeze' mean?", "opts": ["Become very cold", "Stop talking politely", "Be unable to move or act", "Run away quickly"], "a": 2, "ev": "most people freeze in an emergency", "why": "Trong ngữ cảnh khẩn cấp, \"freeze\" nghĩa là đứng sững, không biết làm gì."}, {"kind": "inference", "q": "What can be inferred about the writer after the course?", "opts": ["She thinks she can now replace a paramedic", "She feels more confident but knows she is not an expert", "She regrets attending the course", "She wants to leave her studies"], "a": 1, "ev": "Still, I now feel much more confident.", "why": "Tác giả nói tự tin hơn nhưng cũng thừa nhận \"one weekend does not make me an expert\"."}, {"kind": "tfng", "q": "The first-aid course lasted for one day.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "a two-day first-aid course", "why": "Văn bản nói khóa học kéo dài hai ngày (\"a two-day first-aid course\"), nên sai."}, {"kind": "tfng", "q": "The writer plans to work as a paramedic in the future.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản không nói gì về kế hoạch làm nhân viên cấp cứu."}, {"kind": "tfng", "q": "The students practised CPR on plastic dummies.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "We practised on plastic dummies", "why": "Câu \"We practised on plastic dummies\" xác nhận phát biểu đúng."}], "notes": {"vocab": [["collapsed", "ngã quỵ, ngất đột ngột", "collapse (n/v)"], ["paramedic", "nhân viên cấp cứu y tế", "para- + medic"], ["recovery position", "tư thế hồi phục (nằm nghiêng)", "thuật ngữ sơ cứu"], ["firmly", "một cách chắc, mạnh", "firm (adj)"], ["rescuer", "người cứu hộ", "rescue (v/n)"], ["take over", "tiếp quản, thay phiên", "phrasal verb"], ["up to date", "cập nhật, mới nhất", "stay/keep up to date"]], "grammar": [["Past perfect (quá khứ hoàn thành)", "something I had planned for months", "Thì quá khứ hoàn thành cho thấy việc lên kế hoạch xảy ra trước thời điểm kể chuyện (thứ Bảy vừa rồi)."], ["Reported speech (câu gián tiếp)", "Mr Hale explained that if the rescuer gets tired, another person should take over.", "Động từ tường thuật 'explained that' + mệnh đề; ở đây là sự thật luôn đúng nên giữ hiện tại."], ["Question word + infinitive (từ nghi vấn + to V)", "how to put someone in the recovery position", "'how to + V' diễn đạt cách làm một việc, thường dùng khi nói về điều đã học."], ["Concession with 'even though' (nhượng bộ)", "Everyone laughed a lot, even though the topic was serious.", "'even though' giới thiệu điều trái ngược với mong đợi: chủ đề nghiêm túc nhưng mọi người vẫn cười."]], "tips": ["Blog thường viết ngôi thứ nhất và theo trình tự thời gian; chú ý từ nối (Then, After, Still) để theo dõi diễn biến.", "Ý kiến và cảm xúc của tác giả hay nằm ở đoạn cuối; đọc đoạn này để trả lời câu hỏi suy luận."]}}, {"id": "rd5-b1-15", "lvl": "B1", "topic": "medical", "genre": "news", "title": "Brook Valley Welcomes Its First Health Clinic", "text": "New Clinic Brings Care Closer to Rural Families\n\nA new health clinic opened its doors yesterday in the small town of Brook Valley, giving around 6,000 local residents access to a doctor for the first time in years. Until now, many people had to travel more than 40 kilometres to the nearest hospital, which was difficult for elderly patients and for families without a car.\n\nThe clinic, which cost about two million pounds to build, has two doctors, three nurses and a part-time midwife. It offers vaccinations, check-ups for children and treatment for common illnesses such as chest infections. Patients with serious problems will still be sent to the city hospital, but a new video link means specialists can advise the local team quickly.\n\n\"I used to take two buses to see a doctor, and the journey made me feel worse,\" said Margaret Ellis, 72, who was the first patient through the door. \"Now I can walk here in ten minutes.\"\n\nThe mayor, Daniel Cross, said the project had only been possible because local people raised money and volunteered to help with the building work. However, some residents are worried that the clinic will find it hard to keep its staff. Dr Priya Nair, the lead doctor, admitted that recruiting nurses for rural areas is difficult. \"Young professionals often prefer to live in cities,\" she said. \"We hope that good working conditions will persuade them to stay.\"\n\nThe clinic is open from Monday to Saturday, and an evening service will start next month.", "gist": "Bản tin về phòng khám mới ở thị trấn nông thôn Brook Valley: dịch vụ cung cấp, niềm vui của người dân và nỗi lo giữ chân nhân viên y tế.", "qs": [{"kind": "main", "q": "What is the news report mainly about?", "opts": ["A hospital closing in a big city", "A mayor's election campaign", "The opening of a clinic in a rural town and its challenges", "A new vaccine for children"], "a": 2, "ev": "A new health clinic opened its doors yesterday in the small town of Brook Valley", "why": "Bài báo nói về việc phòng khám mới mở ở thị trấn nhỏ và những khó khăn đi kèm."}, {"kind": "detail", "q": "How far did many people have to travel to reach a hospital before?", "opts": ["More than 40 kilometres", "About six kilometres", "Around 6,000 metres", "Ten minutes by bus"], "a": 0, "ev": "more than 40 kilometres", "why": "Câu \"more than 40 kilometres\" nêu khoảng cách trước đây."}, {"kind": "detail", "q": "What does the new video link allow?", "opts": ["Patients can see doctors from home", "Nurses can train in the city", "The mayor can speak to residents", "Specialists can advise the local team quickly"], "a": 3, "ev": "specialists can advise the local team quickly", "why": "Văn bản nói \"specialists can advise the local team quickly\" nhờ kết nối video."}, {"kind": "vocab", "q": "In the text, what does 'recruiting' mean?", "opts": ["Teaching young people", "Finding and employing new staff", "Sending patients away", "Paying for equipment"], "a": 1, "ev": "recruiting nurses for rural areas is difficult", "why": "\"recruiting nurses\" là tuyển dụng y tá, tức tìm và thuê nhân viên mới."}, {"kind": "inference", "q": "Why might the clinic have trouble keeping its staff?", "opts": ["The clinic pays no salaries", "The building is too small", "Young professionals often prefer living in cities", "Nurses dislike video links"], "a": 2, "ev": "Young professionals often prefer to live in cities", "why": "Bác sĩ Nair nói người trẻ thích sống ở thành phố, nên khó giữ nhân viên ở vùng nông thôn."}, {"kind": "tfng", "q": "Patients with serious problems will be treated fully at the new clinic.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Patients with serious problems will still be sent to the city hospital", "why": "Bệnh nhân nặng \"will still be sent to the city hospital\", nên phát biểu sai."}, {"kind": "tfng", "q": "The government paid for the clinic's building.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản chỉ nói người dân gây quỹ và tình nguyện, không nhắc đến chính phủ."}, {"kind": "tfng", "q": "An evening service will be added at the clinic.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "an evening service will start next month", "why": "Câu cuối nói \"an evening service will start next month\", nên đúng."}], "notes": {"vocab": [["residents", "cư dân", "resident (n/adj)"], ["vaccinations", "việc tiêm chủng", "vaccine (n), vaccinate (v)"], ["midwife", "nữ hộ sinh", "số nhiều: midwives"], ["specialists", "bác sĩ chuyên khoa", "special -> specialist"], ["volunteered", "tình nguyện", "volunteer (n/v)"], ["recruiting", "tuyển dụng", "recruitment (n)"], ["persuade", "thuyết phục", "persuade someone to do"]], "grammar": [["Non-defining relative clause (mệnh đề quan hệ không xác định)", "The clinic, which cost about two million pounds to build, has two doctors", "Mệnh đề giữa hai dấu phẩy chỉ thêm thông tin phụ về 'The clinic'; có thể bỏ đi mà câu vẫn đủ nghĩa."], ["Used to + infinitive (thói quen trong quá khứ)", "I used to take two buses to see a doctor", "'used to + V' nói về thói quen đã chấm dứt; so sánh với tình hình hiện tại ('Now I can walk')."], ["Past perfect (quá khứ hoàn thành)", "the project had only been possible because local people raised money", "Quá khứ hoàn thành nhấn mạnh điều kiện đã có trước thời điểm thị trưởng nói."], ["Passive with will (bị động tương lai)", "Patients with serious problems will still be sent to the city hospital", "'will be + V3' là bị động tương lai; người gửi không quan trọng nên không nêu."]], "tips": ["Bản tin đưa thông tin quan trọng nhất ở đoạn đầu (ai, ở đâu, cái gì); đọc kỹ đoạn đầu để nắm ý chính.", "Trích dẫn trong ngoặc kép cho biết ý kiến của từng nhân vật; xem ai nói gì để làm câu suy luận."]}}, {"id": "rd5-b1-16", "lvl": "B1", "topic": "medical", "genre": "article", "title": "The Skeleton: Your Body's Frame, Shield and Store", "text": "The Skeleton: Your Body's Frame\n\nThe adult human skeleton has 206 bones, and it does far more than hold the body up. Its work can be divided into four main jobs: support, protection, movement and storage.\n\nFirst, the skeleton gives the body its shape. Without it, we would collapse like a tent without poles. The long bones of the legs, such as the femur, carry our weight when we stand and walk.\n\nSecond, bones protect soft organs that are easily damaged. The skull surrounds the brain, the ribs form a cage around the heart and lungs, and the vertebrae of the spine protect the spinal cord, which carries messages between the brain and the rest of the body.\n\nThird, bones make movement possible. Muscles are attached to bones by strong cords called tendons. When a muscle contracts, it pulls on a bone, and the bone moves at a joint, such as the knee or the elbow. Joints are covered with smooth cartilage, which lets the bones slide easily against each other.\n\nFinally, bones store minerals, especially calcium, and release them into the blood when the body needs them. Inside some bones there is soft bone marrow, where new blood cells are made.\n\nAlthough bone feels hard and dead, it is a living tissue. It can repair itself after a fracture, provided that the broken pieces are held in the correct position. Regular exercise and enough calcium in the diet help keep bones strong throughout life.", "gist": "Bài viết giải thích bốn chức năng của bộ xương người: nâng đỡ, bảo vệ, vận động và dự trữ khoáng chất, cùng khả năng tự lành của xương.", "qs": [{"kind": "main", "q": "What is the main idea of the article?", "opts": ["Bones are hard and cannot change", "The skeleton has several important jobs besides holding the body up", "Only the legs need strong bones", "Muscles are more useful than bones"], "a": 1, "ev": "it does far more than hold the body up", "why": "Câu đầu nói bộ xương làm nhiều việc hơn là nâng đỡ cơ thể, rồi liệt kê bốn chức năng."}, {"kind": "detail", "q": "What connects muscles to bones?", "opts": ["Tendons", "Cartilage", "Marrow", "Vertebrae"], "a": 0, "ev": "Muscles are attached to bones by strong cords called tendons.", "why": "Văn bản nói cơ gắn vào xương bằng \"strong cords called tendons\"."}, {"kind": "detail", "q": "What does the spinal cord do?", "opts": ["It stores calcium for the blood", "It makes new blood cells", "It covers the joints with cartilage", "It carries messages between the brain and the body"], "a": 3, "ev": "which carries messages between the brain and the rest of the body", "why": "Tủy sống \"carries messages between the brain and the rest of the body\"."}, {"kind": "vocab", "q": "In the text, what does 'contracts' mean?", "opts": ["Signs an agreement", "Grows longer", "Becomes shorter and tighter", "Becomes weaker"], "a": 2, "ev": "When a muscle contracts, it pulls on a bone", "why": "Khi cơ co lại thì kéo xương; \"contracts\" nghĩa là co ngắn và căng lên."}, {"kind": "inference", "q": "What can be inferred about a broken bone?", "opts": ["It can never heal", "It heals best when the pieces are in the right position", "It heals only in children", "It needs no care at all"], "a": 1, "ev": "provided that the broken pieces are held in the correct position", "why": "Cụm \"provided that the broken pieces are held in the correct position\" ngụ ý xương lành tốt khi các mảnh được giữ đúng vị trí."}, {"kind": "tfng", "q": "The ribs protect the spinal cord.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "the ribs form a cage around the heart and lungs", "why": "Xương sườn bảo vệ tim và phổi; tủy sống được bảo vệ bởi đốt sống, nên sai."}, {"kind": "tfng", "q": "Babies are born with more bones than adults.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản chỉ nói người lớn có 206 xương, không nói về trẻ sơ sinh."}, {"kind": "tfng", "q": "Blood cells are made inside some bones.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "Inside some bones there is soft bone marrow, where new blood cells are made.", "why": "Câu trên xác nhận tế bào máu được tạo ra trong tủy xương."}], "notes": {"vocab": [["vertebrae", "các đốt sống", "số ít: vertebra"], ["spinal cord", "tủy sống", "spine = cột sống"], ["tendons", "gân", "nối cơ với xương"], ["cartilage", "sụn", "lót ở khớp"], ["calcium", "khoáng chất canxi (Ca)", "khoáng chất cho xương chắc"], ["bone marrow", "tủy xương", "nơi tạo tế bào máu"], ["fracture", "gãy xương", "= a break in a bone"], ["tissue", "mô", "living tissue"]], "grammar": [["Second conditional with 'without' (câu điều kiện loại 2)", "Without it, we would collapse like a tent without poles.", "'Without it' thay cho mệnh đề 'if' (nếu không có nó); 'would + V' nói về tình huống giả định."], ["Passive with agent (bị động có tác nhân)", "Muscles are attached to bones by strong cords called tendons.", "'are attached ... by' nhấn mạnh cái được gắn (cơ); 'called tendons' là mệnh đề quan hệ rút gọn."], ["Concession with 'although' (nhượng bộ)", "Although bone feels hard and dead, it is a living tissue.", "'Although' nối hai ý đối lập: cảm giác cứng như chết nhưng thật ra là mô sống."], ["Condition with 'provided that' (điều kiện)", "provided that the broken pieces are held in the correct position", "'provided that' = chỉ khi/miễn là; đưa ra điều kiện cần cho việc xương tự lành."]], "tips": ["Bài viết dùng các từ thứ tự (First, Second, Third, Finally) để chia ý; đọc các từ này để thấy cấu trúc và tìm chi tiết nhanh.", "Câu đầu nêu ý chính và số lượng chức năng; dùng nó trả lời câu hỏi ý chính."]}}, {"id": "rd5-b1-17", "lvl": "B1", "topic": "medical", "genre": "letter", "title": "Going Home After Your Small Operation", "text": "Dear Mr Tran,\n\nThank you for visiting our day surgery unit on Tuesday. You had a small operation to remove a lump from your left forearm, and it went well. This letter explains how to look after yourself at home.\n\nThe wound is covered with a waterproof dressing. Please keep it clean and dry for the first two days, and do not take it off yourself. After that, you may shower, but do not rub the area. The stitches will be taken out by your practice nurse in ten days' time; please call your GP surgery to book an appointment.\n\nIt is normal to feel some pain, swelling and tiredness for a few days. You can take the pain relief we gave you, following the instructions on the packet. Try to rest your arm on a cushion when you sit, as this reduces the swelling. Avoid lifting heavy objects or playing sport until the wound has healed completely.\n\nPlease contact us if you notice redness that is spreading, a bad smell or yellow liquid coming from the wound, bleeding that does not stop, or a high temperature. These could be signs of an infection, and you may need treatment.\n\nIf you are worried about anything, you can phone the ward at any time, day or night. If the problem is severe, go to the nearest emergency department.\n\nWe wish you a speedy recovery.\n\nYours sincerely,\n\nAnna Moore\nSenior Nurse, Day Surgery Unit", "gist": "Thư dặn dò sau phẫu thuật nhỏ: chăm sóc vết thương, cắt chỉ, giảm đau, hạn chế vận động và các dấu hiệu nhiễm trùng cần liên hệ.", "qs": [{"kind": "main", "q": "Why was this letter written?", "opts": ["To invite the patient to a new operation", "To ask the patient for payment", "To explain how a patient should care for himself after surgery", "To describe how stitches are made"], "a": 2, "ev": "This letter explains how to look after yourself at home.", "why": "Thư nói rõ mục đích: hướng dẫn cách tự chăm sóc tại nhà."}, {"kind": "detail", "q": "How long must the dressing be kept clean and dry?", "opts": ["For the first two days", "For ten days", "Until the stitches are removed", "For one hour"], "a": 0, "ev": "Please keep it clean and dry for the first two days", "why": "Thư nói \"for the first two days\"."}, {"kind": "detail", "q": "Who will take out the stitches?", "opts": ["The patient himself", "The surgeon on the ward", "A pharmacist", "The practice nurse"], "a": 3, "ev": "The stitches will be taken out by your practice nurse", "why": "Câu \"will be taken out by your practice nurse\" cho biết y tá phòng khám sẽ cắt chỉ."}, {"kind": "vocab", "q": "In the text, what does 'severe' mean?", "opts": ["Slightly annoying", "Very serious", "Completely new", "Easy to treat"], "a": 1, "ev": "If the problem is severe", "why": "\"severe\" nghĩa là nghiêm trọng; khi vấn đề nghiêm trọng thì đến khoa cấp cứu."}, {"kind": "inference", "q": "Why does the letter say to avoid heavy lifting and sport?", "opts": ["The patient is too old for exercise", "The dressing would become wet", "These activities could harm the healing wound", "The nurse wants to avoid paperwork"], "a": 2, "ev": "Avoid lifting heavy objects or playing sport until the wound has healed completely.", "why": "Cấm nâng nặng và chơi thể thao \"until the wound has healed\" ngụ ý các hoạt động này có thể làm tổn thương vết thương."}, {"kind": "tfng", "q": "After two days, the patient should remove the dressing himself.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "do not take it off yourself", "why": "Thư nói \"do not take it off yourself\", nên phát biểu sai."}, {"kind": "tfng", "q": "The operation was done under general anaesthetic.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Thư không đề cập đến loại gây mê."}, {"kind": "tfng", "q": "The patient can phone the ward during the night.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "you can phone the ward at any time, day or night", "why": "Câu \"at any time, day or night\" cho biết có thể gọi cả ban đêm."}], "notes": {"vocab": [["day surgery", "phẫu thuật trong ngày", "không nằm viện qua đêm"], ["lump", "khối u nhỏ, cục", "a lump on the arm"], ["waterproof", "chống nước", "water + proof"], ["dressing", "băng gạc che vết thương", "change a dressing"], ["stitches", "mũi khâu, chỉ khâu", "take out stitches"], ["swelling", "sự sưng", "swell (v)"], ["infection", "nhiễm trùng", "signs of infection"], ["severe", "nghiêm trọng", "severe pain"]], "grammar": [["Infinitive of purpose (to + V chỉ mục đích)", "You had a small operation to remove a lump from your left forearm", "'to remove' giải thích mục đích của ca mổ."], ["Future passive (bị động tương lai)", "The stitches will be taken out by your practice nurse in ten days' time", "Dùng bị động vì quan tâm đến việc cắt chỉ hơn là người làm; 'in ten days' time' = sau mười ngày."], ["Participle clause (mệnh đề phân từ)", "You can take the pain relief we gave you, following the instructions on the packet.", "'following ...' rút gọn 'and follow ...'; làm lời dặn trang trọng, ngắn gọn."], ["Present perfect after 'until' (hiện tại hoàn thành sau until)", "until the wound has healed completely", "Sau 'until' về tương lai dùng hiện tại hoàn thành để nhấn mạnh vết thương đã lành xong."]], "tips": ["Thư xuất viện thường có bố cục: lời chào, lý do viết, hướng dẫn theo nhóm, dấu hiệu cảnh báo, liên hệ; tìm đúng đoạn theo chủ đề câu hỏi.", "Chú ý các động từ mệnh lệnh lịch sự (Please keep, Avoid, Try to) vì chúng là hướng dẫn quan trọng."]}}, {"id": "rd5-b1-18", "lvl": "B1", "topic": "medical", "genre": "forum", "title": "Surviving Placement: Student Nurses Share Advice", "text": "Stress on placement: how do you cope?\n\nPosted by Lan_K\n\nHi everyone. I'm in my first year of nursing school and I feel exhausted. Between lectures, hospital placements and night shifts as a part-time carer, I barely sleep. Last week I cried in the toilets after a patient shouted at me. Does it get easier? What do you do to cope?\n\nReply from Marcus_R\n\nIt does get easier, I promise. In my first year I tried to do everything perfectly, which made me anxious. Now I accept that I will make small mistakes and learn from them. I also keep a short diary every evening, writing down one thing that went well. It sounds silly, but it works.\n\nReply from Joy_N\n\nPlease talk to your tutor. Mine arranged a weekly meeting for me when I was struggling, and I wish I had asked earlier. Also, try to protect your sleep. I switch off my phone at ten o'clock, and I take a short walk between classes, even if it is only ten minutes.\n\nReply from Lan_K\n\nThank you both! I didn't realise so many people felt the same. I'll speak to my tutor tomorrow and try the diary idea. Maybe I should also stop saying yes to extra shifts.", "gist": "Chủ đề diễn đàn: một sinh viên điều dưỡng năm nhất kiệt sức và nhận lời khuyên về nhật ký, nói chuyện với giáo viên, bảo vệ giấc ngủ và đi bộ.", "qs": [{"kind": "main", "q": "What is the main topic of the forum thread?", "opts": ["How to find a part-time job", "Which hospital is the best to work in", "How to pass nursing exams quickly", "How student nurses can cope with stress"], "a": 3, "ev": "Does it get easier? What do you do to cope?", "why": "Chủ đề xoay quanh việc đối phó với căng thẳng của sinh viên điều dưỡng."}, {"kind": "detail", "q": "What does Marcus do every evening?", "opts": ["He phones his tutor", "He writes down one thing that went well", "He goes for a long walk", "He reads about anxiety"], "a": 1, "ev": "I also keep a short diary every evening, writing down one thing that went well.", "why": "Marcus viết nhật ký ngắn mỗi tối, ghi một điều tốt đẹp."}, {"kind": "detail", "q": "What did Joy's tutor do when she was struggling?", "opts": ["Arranged a weekly meeting", "Gave her extra shifts", "Told her to leave the course", "Lent her a diary"], "a": 0, "ev": "Mine arranged a weekly meeting for me when I was struggling", "why": "Joy nói giáo viên \"arranged a weekly meeting\" cho cô ấy."}, {"kind": "vocab", "q": "In the text, what does 'struggling' mean?", "opts": ["Winning easily", "Travelling abroad", "Having great difficulty", "Studying quietly"], "a": 2, "ev": "when I was struggling", "why": "\"struggling\" nghĩa là gặp nhiều khó khăn, như khi Joy gặp áp lực."}, {"kind": "inference", "q": "What does Lan_K realise at the end?", "opts": ["Her tutor caused her problems", "Her extra shifts may be adding to her stress", "Diaries are silly", "Placements are not important"], "a": 1, "ev": "Maybe I should also stop saying yes to extra shifts.", "why": "Lan nghĩ nên ngừng nhận thêm ca, cho thấy cô nhận ra ca làm thêm góp phần gây kiệt sức."}, {"kind": "tfng", "q": "Marcus still tries to do everything perfectly.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Now I accept that I will make small mistakes and learn from them.", "why": "Marcus nói bây giờ anh chấp nhận mắc lỗi nhỏ, nên sai."}, {"kind": "tfng", "q": "Joy's tutor used to work as a nurse.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản không nói gì về nghề trước đây của giáo viên Joy."}, {"kind": "tfng", "q": "Joy turns off her phone at ten o'clock.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "I switch off my phone at ten o'clock", "why": "Câu \"I switch off my phone at ten o'clock\" xác nhận đúng."}], "notes": {"vocab": [["exhausted", "kiệt sức", "exhaust (v)"], ["placement", "đợt thực tập lâm sàng", "hospital placement"], ["barely", "hầu như không", "= hardly"], ["anxious", "lo âu", "anxiety (n)"], ["struggling", "đang vật lộn, gặp khó khăn", "struggle (v/n)"], ["protect", "bảo vệ, giữ gìn", "protect your sleep"], ["switch off", "tắt (thiết bị)", "phrasal verb"], ["realise", "nhận ra", "realise that..."]], "grammar": [["Non-restrictive 'which' for a whole clause (which nói về cả mệnh đề trước)", "In my first year I tried to do everything perfectly, which made me anxious.", "'which' thay cho cả ý trước (cố làm mọi thứ hoàn hảo) và nêu hậu quả của nó."], ["Wish + past perfect (ước về quá khứ)", "I wish I had asked earlier", "'wish + had + V3' diễn tả sự tiếc nuối về điều đã không làm trong quá khứ."], ["Stop + V-ing", "Maybe I should also stop saying yes to extra shifts.", "'stop + V-ing' nghĩa là ngừng hẳn thói quen; 'should' đưa ra gợi ý nhẹ nhàng."], ["Past simple and past continuous (quá khứ đơn và tiếp diễn)", "Mine arranged a weekly meeting for me when I was struggling", "Quá khứ tiếp diễn 'was struggling' là bối cảnh kéo dài, quá khứ đơn 'arranged' là hành động xảy ra trong lúc đó."]], "tips": ["Diễn đàn gồm bài đăng và các phản hồi; xác định ai nói gì (tên người dùng) trước khi trả lời câu chi tiết.", "Câu hỏi của người mở chủ đề thường là ý chính; các phản hồi là lời khuyên cụ thể."]}}, {"id": "rd5-b2-01", "lvl": "B2", "topic": "work", "genre": "article", "title": "Home Offices and Hidden Costs", "text": "Few workplace changes have been as sudden or as lasting as the shift towards remote working. Once a rare privilege granted to senior staff, working from home is now a standard option in many industries, and employees increasingly regard it as a right rather than a perk.\n\nThe benefits are easy to list. Without a daily commute, workers save time and money, and many report that they can concentrate better without the constant interruptions of an open-plan office. Employers, too, have discovered advantages: they can recruit talent from anywhere in the country, and they spend less on rented office space. A study of one insurance company found that staff who worked from home completed more tasks per week than their colleagues in the building, although the researchers admitted that the volunteers may have been more motivated to begin with.\n\nHowever, the risks deserve equal attention. Isolation is the most frequently cited problem. Casual conversations by the coffee machine, which seem trivial, often spark ideas and build trust, and video calls rarely reproduce them. Younger employees may suffer most, since they learn by watching experienced colleagues and are less likely to be noticed by managers who rarely see them. There is also the blurred boundary between work and home. When the laptop sits permanently on the kitchen table, it becomes tempting to answer one more email at ten o'clock at night, and many remote workers end up working longer hours than they did in the office.\n\nCompanies have responded in different ways. Some have insisted that everyone return to the office for at least three days a week, arguing that creativity depends on physical proximity. Others have gone fully remote, closing their headquarters altogether. The most popular compromise, known as hybrid working, tries to combine the strengths of both models, though it demands careful planning so that teams are not divided between those who are present and those who are not.\n\nWhatever the arrangement, experts agree that success depends less on location than on management. Clear goals, regular feedback and respect for personal time matter far more than where a laptop happens to be open. If employers measure results instead of hours, remote working is likely to remain a lasting feature of modern life rather than a passing trend.", "gist": "Bài báo cân nhắc lợi ích và rủi ro của làm việc từ xa và cho rằng thành công phụ thuộc vào cách quản lý.", "qs": [{"kind": "main", "q": "What is the main purpose of the article?", "opts": ["To persuade companies to close their offices immediately", "To prove that remote workers are more productive than office workers", "To weigh the advantages and drawbacks of remote working and suggest what makes it succeed", "To describe how video calls have replaced all face-to-face meetings"], "a": 2, "ev": "experts agree that success depends less on location than on management", "why": "Bài viết nêu cả lợi ích lẫn rủi ro rồi kết luận: \"success depends less on location than on management\", nên mục đích là cân nhắc hai mặt và chỉ ra điều kiện thành công."}, {"kind": "detail", "q": "According to the article, how do employers benefit from remote working?", "opts": ["They can hire people from anywhere and pay less for office space", "They can pay lower salaries to staff at home", "They can reduce the number of managers they need", "They can avoid giving employees feedback"], "a": 0, "ev": "they can recruit talent from anywhere in the country, and they spend less on rented office space", "why": "Bài viết nói nhà tuyển dụng \"can recruit talent from anywhere in the country, and they spend less on rented office space\"."}, {"kind": "detail", "q": "Why does the writer treat the insurance company study with caution?", "opts": ["The study was carried out in only one country", "The researchers were paid by the company", "The staff in the office finished more tasks", "The people studied may already have been more motivated"], "a": 3, "ev": "the volunteers may have been more motivated to begin with", "why": "Các nhà nghiên cứu thừa nhận \"the volunteers may have been more motivated to begin with\", nên kết quả có thể bị thiên lệch."}, {"kind": "vocab", "q": "In the text, what does \"proximity\" mean?", "opts": ["Having a similar opinion", "Being physically close to someone", "Working at a higher level", "Using modern technology"], "a": 1, "ev": "creativity depends on physical proximity", "why": "\"physical proximity\" trong ngữ cảnh làm việc tại văn phòng nghĩa là ở gần nhau về mặt vật lý."}, {"kind": "inference", "q": "Which statement would the writer most likely support?", "opts": ["Hybrid working should be banned because it divides teams", "Younger employees should never be allowed to work from home", "Staff should be judged on what they achieve rather than on the hours they log", "Managers should check on remote workers every hour"], "a": 2, "ev": "If employers measure results instead of hours", "why": "Câu cuối nói nếu nhà tuyển dụng \"measure results instead of hours\" thì làm việc từ xa sẽ bền vững, nên tác giả ủng hộ đánh giá theo kết quả."}, {"kind": "inference", "q": "The phrase \"a right rather than a perk\" suggests that employees now...", "opts": ["expect remote working as a normal entitlement, not a special favour", "are given extra payment for working at home", "distrust employers who offer flexible hours", "prefer perks to higher salaries"], "a": 0, "ev": "employees increasingly regard it as a right rather than a perk", "why": "\"perk\" là đặc quyền thêm, còn \"right\" là quyền đương nhiên; nhân viên ngày càng xem làm việc từ xa là điều họ được hưởng."}, {"kind": "tfng", "q": "Working from home was originally available to all employees.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Once a rare privilege granted to senior staff", "why": "Bài viết nói trước đây đó là \"a rare privilege granted to senior staff\", tức không dành cho mọi nhân viên."}, {"kind": "tfng", "q": "Remote workers generally earn lower salaries than office workers.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài viết không đề cập đến mức lương của người làm việc từ xa."}, {"kind": "tfng", "q": "Hybrid working needs careful planning.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "it demands careful planning", "why": "Bài viết nói hybrid working \"demands careful planning\" nên câu này đúng."}], "notes": {"vocab": [["perk", "đặc quyền, phúc lợi thêm", "a perk of the job"], ["commute", "việc đi lại hằng ngày từ nhà đến chỗ làm", "vừa là danh từ vừa là động từ"], ["open-plan", "(văn phòng) không có vách ngăn", "open-plan office"], ["recruit", "tuyển dụng", "recruit talent; danh từ: recruitment"], ["blurred", "mờ đi, không rõ ranh giới", "blurred boundary / blurred line"], ["proximity", "sự gần nhau", "in close proximity to"], ["compromise", "giải pháp dung hòa", "reach a compromise"]], "grammar": [["Reduced participle clause (mệnh đề phân từ rút gọn)", "Once a rare privilege granted to senior staff, working from home is now a standard option in many industries", "Cụm \"granted to senior staff\" là phân từ quá khứ bổ nghĩa cho \"privilege\", rút gọn từ \"which was granted\" để câu gọn và trang trọng hơn."], ["Modal perfect (could/may have + V3: suy đoán quá khứ)", "the volunteers may have been more motivated to begin with", "\"may have been\" diễn tả khả năng về điều đã xảy ra trong quá khứ nhưng chưa chắc chắn."], ["First conditional (câu điều kiện loại 1)", "If employers measure results instead of hours, remote working is likely to remain a lasting feature of modern life rather than a passing trend", "If + hiện tại đơn, mệnh đề chính nói về kết quả có khả năng xảy ra trong tương lai; ở đây dùng \"is likely to\" thay cho \"will\"."], ["Comparative with \"less ... than\" (so sánh kém)", "success depends less on location than on management", "Cấu trúc \"less X than Y\" nhấn mạnh Y quan trọng hơn X."]], "tips": ["Bài article thường nêu vấn đề ở đoạn đầu và kết luận ở đoạn cuối; hãy đọc kỹ đoạn đầu và đoạn cuối để nắm ý chính.", "Chú ý các từ nối tương phản như \"However\", \"although\" để nhận ra chỗ tác giả chuyển từ lợi ích sang rủi ro."]}}, {"id": "rd5-b2-02", "lvl": "B2", "topic": "technology", "genre": "report", "title": "Scrolling Habits on Campus", "text": "Report: Social Media Use among University Students\n\nIntroduction\n\nThis report summarises the results of a survey carried out in March among 412 undergraduates at a mid-sized university. The aim was to find out how much time students spend on social media, which platforms they prefer and how they feel about their habits.\n\nFindings\n\nThe average student reported spending three hours and ten minutes a day on social media, which is considerably higher than the two hours that were estimated in a similar survey five years ago. Video-sharing platforms were by far the most popular, used daily by 81 per cent of respondents, while text-based networks attracted only 23 per cent. Female students were slightly more likely to post their own content, whereas male students tended to watch or comment rather than publish.\n\nPerhaps the most striking result concerns attitudes. Although 64 per cent of participants said they believed they used social media too much, only 19 per cent had ever tried to limit their screen time. Those who had done so reported that the effort was short-lived, mainly because friends expected immediate replies to messages. Moreover, nearly half of the respondents admitted checking their phones during lectures, a habit that several lecturers have identified as a barrier to concentration.\n\nNot all findings were negative. More than two thirds of students said that social media helped them stay in touch with relatives living abroad, and a significant minority had found study groups or part-time jobs through online communities. It should be noted, however, that the survey relied on self-reported data, so actual usage may differ from the figures presented here.\n\nConclusion and Recommendations\n\nThe results suggest that students are aware of the potential drawbacks of social media but lack practical strategies for reducing their use. It is therefore recommended that the university offer workshops on digital wellbeing and that lecturers agree clear guidelines on phone use in class. A follow-up survey, using usage data recorded automatically by phones, would provide a more reliable picture of the situation.", "gist": "Báo cáo tóm tắt khảo sát thói quen dùng mạng xã hội của sinh viên đại học và đưa ra các kiến nghị.", "qs": [{"kind": "main", "q": "What is the main purpose of the report?", "opts": ["To argue that social media should be banned in lectures", "To present survey findings on students' social media habits and recommend action", "To compare two universities in terms of student behaviour", "To advertise a new platform designed for students"], "a": 1, "ev": "This report summarises the results of a survey", "why": "Báo cáo mở đầu bằng \"summarises the results of a survey\" và kết thúc bằng các kiến nghị, nên mục đích là trình bày kết quả và đề xuất hành động."}, {"kind": "detail", "q": "How much time did the average student spend on social media each day?", "opts": ["About three hours and ten minutes", "About two hours", "About four hours and ten minutes", "About one hour and thirty minutes"], "a": 0, "ev": "three hours and ten minutes a day", "why": "Báo cáo ghi mức trung bình là \"three hours and ten minutes a day\"; hai giờ là con số của cuộc khảo sát cách đây năm năm."}, {"kind": "detail", "q": "Why did students who limited their screen time often stop?", "opts": ["They lost interest in their studies", "Their phones stopped working properly", "Lecturers asked them to continue using social media", "Their friends expected quick answers to messages"], "a": 3, "ev": "friends expected immediate replies to messages", "why": "Báo cáo giải thích nỗ lực đó ngắn ngủi vì \"friends expected immediate replies to messages\"."}, {"kind": "vocab", "q": "In the text, what does \"striking\" mean in \"the most striking result\"?", "opts": ["Very expensive", "Very violent", "Very noticeable and surprising", "Very recent"], "a": 2, "ev": "Perhaps the most striking result concerns attitudes", "why": "\"striking\" ở đây nghĩa là gây ấn tượng mạnh, đáng chú ý, vì kết quả nói về sự mâu thuẫn giữa suy nghĩ và hành động."}, {"kind": "inference", "q": "Why does the report recommend a follow-up survey using automatically recorded data?", "opts": ["Phones record more information than students want to share", "Students may not report their own usage accurately", "The first survey included too few students", "Lecturers asked for a longer survey"], "a": 1, "ev": "the survey relied on self-reported data, so actual usage may differ", "why": "Vì khảo sát dựa trên \"self-reported data\" nên số liệu thực có thể khác; dữ liệu tự động sẽ đáng tin hơn."}, {"kind": "inference", "q": "What can be inferred about students' attitude to their own social media use?", "opts": ["Many think they overuse it but do little to change", "Most believe that social media improves their grades", "Few are worried about the time they spend online", "They are unwilling to answer questions about it"], "a": 0, "ev": "only 19 per cent had ever tried to limit their screen time", "why": "64% nghĩ mình dùng quá nhiều nhưng chỉ 19% từng thử hạn chế, nên có thể suy ra nhiều người biết nhưng ít hành động."}, {"kind": "tfng", "q": "Text-based networks were more popular than video-sharing platforms.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Video-sharing platforms were by far the most popular", "why": "Báo cáo nói nền tảng video \"by far the most popular\", còn mạng dạng văn bản chỉ có 23%, nên câu này sai."}, {"kind": "tfng", "q": "Students who use social media for more than four hours a day get lower grades.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Báo cáo không đề cập đến mối liên hệ giữa thời gian dùng mạng xã hội và điểm số."}, {"kind": "tfng", "q": "Some students found study groups or work through online communities.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "a significant minority had found study groups or part-time jobs through online communities", "why": "Báo cáo nói một thiểu số đáng kể đã tìm được nhóm học hoặc việc làm thêm qua cộng đồng trực tuyến."}], "notes": {"vocab": [["undergraduates", "sinh viên đại học (chưa tốt nghiệp)", "đối lập với graduates / postgraduates"], ["respondents", "người trả lời khảo sát", "động từ: respond"], ["striking", "nổi bật, gây ấn tượng", "a striking contrast"], ["short-lived", "ngắn ngủi, không kéo dài", "tính từ ghép: short + lived"], ["self-reported", "tự báo cáo (do chính người tham gia khai)", "self-reported data"], ["drawbacks", "nhược điểm, mặt hạn chế", "đồng nghĩa: disadvantages"], ["barrier", "rào cản", "a barrier to concentration"], ["guidelines", "hướng dẫn, quy định chung", "lúc nào cũng dạng số nhiều"]], "grammar": [["Concession with \"although\" + past perfect (nhượng bộ)", "Although 64 per cent of participants said they believed they used social media too much, only 19 per cent had ever tried to limit their screen time", "\"Although\" nối hai ý trái ngược; \"had ever tried\" dùng past perfect vì hành động xảy ra trước thời điểm được báo cáo."], ["Present perfect in a relative clause (hiện tại hoàn thành)", "a habit that several lecturers have identified as a barrier to concentration", "\"have identified\" cho thấy hành động đã xảy ra và còn liên quan đến hiện tại; \"that\" mở mệnh đề quan hệ bổ nghĩa cho \"habit\"."], ["Subjunctive after \"recommend\" (thức giả định)", "It is therefore recommended that the university offer workshops on digital wellbeing", "Sau \"recommended that\", động từ dùng nguyên mẫu (offer), không chia ngôi; cấu trúc bị động \"It is recommended that\" rất phổ biến trong báo cáo."], ["Reduced passive participle (phân từ bị động)", "the figures presented here", "\"presented here\" là rút gọn của \"which are presented here\", làm câu ngắn gọn hơn."]], "tips": ["Báo cáo có tiêu đề các phần (Introduction, Findings, Conclusion) – hãy đọc tiêu đề trước để biết thông tin nằm ở đâu.", "Với số liệu, đọc chậm các con số và từ so sánh (more than, only, nearly half) vì câu hỏi thường kiểm tra chi tiết này."]}}, {"id": "rd5-b2-03", "lvl": "B2", "topic": "society", "genre": "speech", "title": "A Comma, Not a Full Stop", "text": "Good morning, graduates, families and faculty. Thank you for inviting me to stand here, although I must confess that I'm more nervous now than I was before my first job interview.\n\nLet me begin with a confession. When I was your age, I failed a course that I was convinced I would pass easily. I remember staring at the result on the screen and thinking that my future had been ruined. It had not, of course, but it took me years to understand why.\n\nToday I want to talk about resilience. People often imagine it as a kind of toughness, a thick skin that lets some lucky individuals shrug off every setback. I no longer believe that. In my experience, resilience is not something you either have or lack; it is a set of habits that anyone can build, and, like a muscle, it grows only when it is used.\n\nWhat are those habits? First, resilient people tell themselves an accurate story. They do not say, \"I am a failure.\" They say, \"This attempt did not work, so what can I change?\" The difference seems small, yet it determines whether a setback becomes a full stop or a comma.\n\nSecond, they ask for help without shame. Had I spoken to my tutor after that failed exam, instead of hiding for a month, I would have saved myself a great deal of misery. Nobody in this hall has ever succeeded entirely alone, and those who claim otherwise have simply forgotten who helped them.\n\nThird, they keep a long view. Careers are not straight lines. Several of the people I admire most changed direction two or three times before they found work that suited them, and every detour taught them something that a smooth road never could.\n\nYou will, I promise, face disappointment. A job will not come, a friendship will fade, a plan will collapse. When that happens, remember that the question is never whether you will fall, but how you will rise. So be kind to yourselves, be generous with each other, and be patient with your own progress.\n\nCongratulations, graduates. The world is waiting, and it is lucky to have you. Thank you.", "gist": "Diễn giả nói với sinh viên tốt nghiệp rằng khả năng phục hồi là một tập hợp thói quen có thể rèn luyện, không phải bẩm sinh.", "qs": [{"kind": "main", "q": "What is the speaker's central message?", "opts": ["Failure should be avoided at all costs", "Resilience is a set of habits that can be developed, not an inborn trait", "Only talented people can recover from setbacks", "Graduates should change careers as often as possible"], "a": 1, "ev": "resilience is not something you either have or lack; it is a set of habits that anyone can build", "why": "Diễn giả khẳng định resilience \"is a set of habits that anyone can build\", không phải thứ có sẵn hay không."}, {"kind": "detail", "q": "What did the speaker do after failing the exam?", "opts": ["He asked his tutor for extra lessons", "He retook the course immediately", "He avoided his tutor for a month", "He left the university"], "a": 2, "ev": "instead of hiding for a month", "why": "Diễn giả nói lẽ ra nên nói chuyện với gia sư \"instead of hiding for a month\", nghĩa là ông đã trốn tránh suốt một tháng."}, {"kind": "detail", "q": "How do resilient people describe a failed attempt, according to the speaker?", "opts": ["As something that did not work and can be changed", "As proof that they are not clever enough", "As bad luck that nobody could prevent", "As a lesson they must forget quickly"], "a": 0, "ev": "This attempt did not work, so what can I change?", "why": "Người kiên cường nói \"This attempt did not work, so what can I change?\", tức xem đó là lần thử chưa thành công và có thể điều chỉnh."}, {"kind": "vocab", "q": "In the text, what does \"detour\" mean?", "opts": ["A sudden and total failure", "A short holiday from work", "A promotion to a better job", "An indirect route that differs from the planned one"], "a": 3, "ev": "every detour taught them something that a smooth road never could", "why": "\"detour\" đối lập với \"a smooth road\", nghĩa là đường vòng, hướng đi khác với kế hoạch ban đầu."}, {"kind": "inference", "q": "What does the image of \"a full stop or a comma\" suggest?", "opts": ["Writing skills are important for graduates", "A setback need not end the story, because it can continue", "Mistakes in punctuation are common", "A setback always ends a career"], "a": 1, "ev": "whether a setback becomes a full stop or a comma", "why": "Dấu chấm kết thúc câu còn dấu phẩy cho phép câu tiếp tục; hình ảnh này ngụ ý thất bại có thể không phải là kết thúc."}, {"kind": "inference", "q": "What does the speaker imply about people who say they succeeded alone?", "opts": ["They are the most resilient people", "They have never experienced failure", "They are overlooking the help they received", "They deserve more respect than others"], "a": 2, "ev": "those who claim otherwise have simply forgotten who helped them", "why": "Diễn giả nói họ \"have simply forgotten who helped them\", tức đã quên sự giúp đỡ mình nhận được."}, {"kind": "tfng", "q": "The speaker was worried about failing the course before he took it.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "I failed a course that I was convinced I would pass easily", "why": "Ông \"was convinced I would pass easily\", tức tin chắc sẽ qua, nên không lo lắng trước; câu này sai."}, {"kind": "tfng", "q": "The speaker is a professor at the graduates' university.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài nói không cho biết nghề nghiệp hay nơi làm việc của diễn giả."}, {"kind": "tfng", "q": "The speaker compares resilience to a muscle.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "like a muscle, it grows only when it is used", "why": "Diễn giả nói \"like a muscle, it grows only when it is used\", nên câu này đúng."}], "notes": {"vocab": [["resilience", "khả năng phục hồi, sức bền tinh thần", "tính từ: resilient"], ["setback", "thất bại, trở ngại", "a setback in one's career"], ["shrug off", "phớt lờ, gạt đi", "cụm động từ"], ["shame", "sự xấu hổ", "without shame"], ["misery", "nỗi khổ, sự khốn khổ", "a great deal of misery"], ["detour", "đường vòng, hướng đi khác", "nghĩa bóng: con đường không thẳng"], ["confess", "thú nhận", "danh từ: confession"]], "grammar": [["Inverted third conditional (điều kiện loại 3 đảo ngữ)", "Had I spoken to my tutor after that failed exam, instead of hiding for a month, I would have saved myself a great deal of misery", "\"Had I spoken\" thay cho \"If I had spoken\"; diễn tả điều kiện không có thật trong quá khứ và kết quả tiếc nuối."], ["Cleft-like contrast: not whether..., but how... (cấu trúc đối lập)", "the question is never whether you will fall, but how you will rise", "Cấu trúc \"not whether..., but how...\" chuyển trọng tâm từ khả năng xảy ra sang cách đối mặt, tạo hiệu ứng hùng biện."], ["Relative clause with \"those who\" (mệnh đề quan hệ)", "those who claim otherwise have simply forgotten who helped them", "\"those who\" nghĩa là \"những người mà\"; thường dùng trong diễn văn để nói chung về một nhóm người."], ["Rhetorical list of three (liệt kê ba)", "A job will not come, a friendship will fade, a plan will collapse", "Ba mệnh đề song song cùng cấu trúc tạo nhịp điệu mạnh, đặc trưng của văn nói."]], "tips": ["Bài diễn văn thường có mở đầu, vài ý chính được đánh số (First, Second, Third) và lời kết; theo dõi các từ này để nắm cấu trúc.", "Diễn giả hay dùng hình ảnh ẩn dụ (muscle, comma, detour); hãy hiểu nghĩa bóng để trả lời câu suy luận."]}}, {"id": "rd5-b2-04", "lvl": "B2", "topic": "environment", "genre": "article", "title": "Parks as Preventive Medicine", "text": "For most of the twentieth century, city planners treated parks as decoration: pleasant extras to be added once the roads, offices and housing had been settled. A growing body of research now suggests that this view was mistaken. Green spaces, it appears, are not a luxury but a form of preventive healthcare.\n\nThe evidence comes from several directions. In a large study of urban residents, those living within five hundred metres of a park reported lower levels of stress and were less likely to be prescribed medication for anxiety than people who lived farther away. Other researchers have measured the physical effects directly, finding that a twenty-minute walk among trees reduces levels of cortisol, a hormone associated with stress. Even looking at greenery through a window seems to help: hospital patients in rooms with a view of trees have, in some trials, recovered more quickly than those facing a brick wall.\n\nWhy should this be so? One explanation, known as attention restoration theory, holds that city life constantly demands our focus, with traffic, noise and screens competing for attention. Natural environments, by contrast, engage us gently, allowing the mind to rest. Another explanation is social: parks provide places where neighbours meet, children play and elderly people avoid loneliness. A third is simply that green spaces encourage exercise, which is itself known to improve mood.\n\nNevertheless, the benefits are not shared equally. Wealthier districts tend to have larger, better-maintained parks, whereas poorer neighbourhoods often have only a strip of grass beside a busy road. Critics also point out that much of the research shows correlation rather than causation; people who feel well may simply be more inclined to walk in parks, rather than parks making them well. Researchers acknowledge the difficulty but note that experiments, in which volunteers are randomly assigned to walk in nature or in a built-up area, point in the same direction.\n\nThe practical implications are considerable. Some cities now plant trees along streets, convert empty lots into community gardens and even require new buildings to include green roofs. Such measures are inexpensive compared with the cost of treating mental illness, and they make cities more pleasant for everyone. If the findings continue to hold, urban green space may deserve to be planned with the same seriousness as hospitals and schools.", "gist": "Bài báo trình bày bằng chứng cho thấy không gian xanh đô thị tốt cho sức khỏe tâm thần và nên được quy hoạch nghiêm túc.", "qs": [{"kind": "main", "q": "What is the main idea of the article?", "opts": ["Parks are too expensive for most cities to build", "City planners have always valued nature highly", "Exercise is the only reason parks help people", "Evidence suggests urban green spaces improve mental health and deserve serious planning"], "a": 3, "ev": "urban green space may deserve to be planned with the same seriousness as hospitals and schools", "why": "Bài viết dẫn bằng chứng rồi kết luận không gian xanh nên được quy hoạch nghiêm túc như bệnh viện và trường học."}, {"kind": "detail", "q": "What did researchers find about a twenty-minute walk among trees?", "opts": ["It lowers the level of a stress-related hormone", "It makes people sleep for longer", "It cures anxiety completely", "It increases appetite and energy"], "a": 0, "ev": "a twenty-minute walk among trees reduces levels of cortisol, a hormone associated with stress", "why": "Bài viết nói đi bộ hai mươi phút giữa cây xanh \"reduces levels of cortisol\", một hormone liên quan đến căng thẳng."}, {"kind": "detail", "q": "According to attention restoration theory, why are natural settings helpful?", "opts": ["They contain fewer people than city streets", "They force people to concentrate harder", "They demand little effort and let the mind rest", "They make traffic noise louder"], "a": 2, "ev": "Natural environments, by contrast, engage us gently, allowing the mind to rest", "why": "Lý thuyết cho rằng thiên nhiên \"engage us gently, allowing the mind to rest\", trái với thành phố luôn đòi hỏi sự tập trung."}, {"kind": "vocab", "q": "In the text, what does \"inclined\" mean in \"more inclined to walk in parks\"?", "opts": ["Forced", "Likely or willing", "Unable", "Trained"], "a": 1, "ev": "people who feel well may simply be more inclined to walk in parks", "why": "\"more inclined to walk\" nghĩa là có xu hướng, sẵn lòng đi bộ hơn; ý của các nhà phê bình là người khỏe mạnh thích đi công viên hơn."}, {"kind": "inference", "q": "What do the critics' comments imply?", "opts": ["It is unclear whether parks cause better wellbeing or simply attract healthier people", "Parks have no effect on people's health", "Research on parks should be stopped", "Wealthy people are less healthy than poor people"], "a": 0, "ev": "much of the research shows correlation rather than causation", "why": "Phê bình cho rằng nhiều nghiên cứu chỉ cho thấy tương quan chứ không phải nhân quả, nên chưa rõ công viên có thực sự là nguyên nhân hay không."}, {"kind": "inference", "q": "What does the writer imply about poorer neighbourhoods?", "opts": ["They do not need parks because they have many friends", "The people who could benefit most may have the least access to green space", "They have refused to build parks", "They have better parks than wealthy areas"], "a": 1, "ev": "Wealthier districts tend to have larger, better-maintained parks", "why": "Khu giàu có công viên lớn và được chăm sóc tốt, còn khu nghèo chỉ có dải cỏ bên đường, nên người cần nhất lại ít được hưởng."}, {"kind": "tfng", "q": "Patients facing a brick wall recovered faster than those with a view of trees.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "recovered more quickly than those facing a brick wall", "why": "Bệnh nhân có tầm nhìn ra cây xanh hồi phục nhanh hơn \"those facing a brick wall\", nên câu này sai."}, {"kind": "tfng", "q": "Green roofs reduce energy costs in buildings.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài viết chỉ nói một số thành phố yêu cầu mái xanh, không nói gì về chi phí năng lượng."}, {"kind": "tfng", "q": "Twentieth-century planners generally regarded parks as a secondary matter.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "city planners treated parks as decoration", "why": "Bài viết nói các nhà quy hoạch \"treated parks as decoration\", tức coi công viên là phần phụ thêm."}], "notes": {"vocab": [["preventive", "mang tính phòng ngừa", "preventive healthcare / medicine"], ["prescribed", "(bác sĩ) kê đơn", "prescribe medication"], ["greenery", "cây cối xanh, thảm thực vật", "danh từ không đếm được"], ["correlation", "mối tương quan", "đối lập với causation (quan hệ nhân quả)"], ["inclined", "có xu hướng, sẵn lòng", "be inclined to do sth"], ["acknowledge", "thừa nhận", "acknowledge the difficulty"], ["implications", "hàm ý, hệ quả", "practical implications"]], "grammar": [["Appositive phrase (cụm đồng vị)", "One explanation, known as attention restoration theory, holds that city life constantly demands our focus", "Cụm \"known as...\" nằm giữa hai dấu phẩy bổ sung thông tin về chủ ngữ mà không làm thay đổi cấu trúc chính."], ["Participle clause as post-modifier (phân từ hiện tại)", "those living within five hundred metres of a park reported lower levels of stress", "\"living within...\" rút gọn từ \"who lived\" để bổ nghĩa cho \"those\"."], ["Contrast with \"whereas\" (liên từ tương phản)", "Wealthier districts tend to have larger, better-maintained parks, whereas poorer neighbourhoods often have only a strip of grass beside a busy road", "\"whereas\" nối hai vế đối lập trong cùng một câu; dùng nhiều trong văn học thuật."], ["Adjective + \"compared with\" (so sánh)", "Such measures are inexpensive compared with the cost of treating mental illness", "\"compared with\" đặt hai đối tượng cạnh nhau để làm nổi bật mức độ rẻ của biện pháp."]], "tips": ["Mỗi đoạn thường bắt đầu bằng câu chủ đề (ví dụ \"The evidence comes from several directions\"); đọc câu đầu đoạn để nắm khung bài.", "Từ như \"Nevertheless\", \"Critics also point out\" báo hiệu ý kiến trái chiều; đây thường là nơi ra câu hỏi suy luận."]}}, {"id": "rd5-b2-05", "lvl": "B2", "topic": "culture", "genre": "review", "title": "Last Speakers of a Mountain Tongue", "text": "Review: 'Words at Dusk' (documentary, 94 minutes)\n\nLinguists estimate that a language falls silent somewhere in the world roughly every two weeks. 'Words at Dusk', a quietly devastating documentary by the director Imre Halden, puts faces to that statistic. The film spends a year with the last fluent speakers of Tahuan, a mountain language now used daily by fewer than forty elderly people, and asks what disappears when such a language does.\n\nThe strongest section follows Marta, a retired shepherd who is reluctant to be called an expert yet knows more than a dozen words for different kinds of snow. Her grandchildren, who live in the capital, understand only a few phrases. In one memorable scene, she tries to teach them a lullaby, and the children's polite confusion says more about generational change than any statistic could. Halden wisely avoids commentary; he lets silences and unfinished sentences carry the emotion.\n\nThe film also deserves praise for its intellectual honesty. Rather than portraying a simple villain, it shows how a language declines through many small pressures: schools that teach only the national language, the lure of jobs in the cities, and the understandable wish of parents to give their children every advantage. A linguist interviewed midway argues that the loss is not merely sentimental, since each language preserves unique knowledge about plants, weather and local history that cannot be fully translated.\n\nNot everything succeeds. The middle third drifts, repeating scenes of villagers cooking and walking without adding much new insight, and a brief attempt to discuss revival programmes in other countries feels rushed. Viewers hoping for practical solutions may leave unsatisfied, as the film offers sympathy rather than strategy. The soundtrack, moreover, occasionally becomes overly sentimental, telling us how to feel at moments when the images alone would have sufficed.\n\nNevertheless, these flaws are minor beside the film's achievement. 'Words at Dusk' is less an argument than an act of listening, and it leaves the audience with an uncomfortable realisation: that the sounds we hear in this film may soon exist only in recordings. Highly recommended for anyone curious about language, memory and identity.", "gist": "Bài đánh giá khen phim tài liệu về sự mai một ngôn ngữ vì sự trung thực và cảm xúc, dù có vài điểm yếu.", "qs": [{"kind": "main", "q": "What is the reviewer's overall opinion of the documentary?", "opts": ["Entirely negative because of its slow pace", "Neutral, with no clear opinion", "Mostly positive, despite some weaknesses", "Positive only about the soundtrack"], "a": 2, "ev": "Nevertheless, these flaws are minor beside the film's achievement", "why": "Sau khi nêu điểm yếu, người viết kết luận \"these flaws are minor beside the film's achievement\" và \"Highly recommended\", nên đánh giá nhìn chung tích cực."}, {"kind": "detail", "q": "What does Marta know a lot about?", "opts": ["Different words for snow", "Teaching children to read", "Government language policy", "Recording old songs"], "a": 0, "ev": "knows more than a dozen words for different kinds of snow", "why": "Bài viết nói Marta \"knows more than a dozen words for different kinds of snow\", tức biết nhiều từ chỉ các loại tuyết."}, {"kind": "detail", "q": "What is the reviewer's criticism of the soundtrack?", "opts": ["It is too quiet to hear", "It uses too many languages", "It repeats the same song", "It tells viewers how to feel when the images are enough"], "a": 3, "ev": "telling us how to feel at moments when the images alone would have sufficed", "why": "Người viết phê bình nhạc nền vì nó \"telling us how to feel\" ở những lúc hình ảnh đã đủ sức diễn đạt."}, {"kind": "vocab", "q": "In the text, what does \"lure\" mean in \"the lure of jobs in the cities\"?", "opts": ["Shortage", "Attraction", "Danger", "Insult"], "a": 1, "ev": "the lure of jobs in the cities", "why": "\"lure\" là sức hấp dẫn; công việc ở thành phố thu hút người trẻ rời quê và bỏ ngôn ngữ."}, {"kind": "inference", "q": "What does the scene with Marta's grandchildren suggest?", "opts": ["The children refuse to speak to their grandmother", "Marta no longer wants to teach anyone", "Tahuan is unlikely to survive in the next generation", "Lullabies are the hardest part of the language"], "a": 2, "ev": "Her grandchildren, who live in the capital, understand only a few phrases", "why": "Cháu chỉ hiểu vài cụm từ và bối rối trước bài ru, nên có thể suy ra ngôn ngữ khó được truyền sang thế hệ sau."}, {"kind": "inference", "q": "What does \"less an argument than an act of listening\" imply about the film?", "opts": ["It observes and records rather than trying to persuade", "It presents a strong political argument", "It contains no interviews", "It is mainly about music"], "a": 0, "ev": "is less an argument than an act of listening", "why": "Cấu trúc \"less ... than\" cho thấy phim thiên về lắng nghe, ghi lại hơn là tranh luận hay thuyết phục."}, {"kind": "tfng", "q": "The film blames schools as the single cause of language decline.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Rather than portraying a simple villain", "why": "Bài đánh giá nói phim không dựng lên \"a simple villain\" mà chỉ ra nhiều áp lực nhỏ, nên câu này sai."}, {"kind": "tfng", "q": "The documentary won an award at an international festival.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài đánh giá không nhắc đến giải thưởng hay liên hoan phim nào."}, {"kind": "tfng", "q": "The reviewer finds part of the middle of the film repetitive.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "repeating scenes of villagers cooking and walking", "why": "Người viết nói đoạn giữa phim \"drifts, repeating scenes of villagers cooking and walking\", tức lặp lại."}], "notes": {"vocab": [["devastating", "gây xúc động mạnh, tàn khốc", "a devastating blow"], ["reluctant", "miễn cưỡng, ngần ngại", "be reluctant to do sth"], ["lullaby", "bài hát ru", "hát cho em bé ngủ"], ["lure", "sức cuốn hút", "the lure of the city"], ["sentimental", "ủy mị, đa cảm", "hơi tiêu cực khi dùng trong đánh giá"], ["drifts", "(phim) đi chệch, mất tập trung", "drift off / drift away"], ["rushed", "vội vàng, sơ sài", "a rushed ending"], ["sufficed", "đủ, thỏa đáng", "động từ: suffice"]], "grammar": [["Present simple for generalisations (hiện tại đơn nêu nhận định)", "Linguists estimate that a language falls silent somewhere in the world roughly every two weeks", "Hiện tại đơn dùng cho sự thật hay thống kê chung; \"estimate that\" là cách đưa ra con số ước tính."], ["\"Rather than\" + -ing (thay vì)", "Rather than portraying a simple villain, it shows how a language declines through many small pressures", "\"Rather than\" + V-ing đặt hai cách tiếp cận cạnh nhau, nhấn mạnh phim chọn cách thứ hai."], ["Participle clause for reduced relative (phân từ rút gọn)", "Viewers hoping for practical solutions may leave unsatisfied", "\"hoping for...\" rút gọn từ \"who hope for\", bổ nghĩa cho \"Viewers\"."], ["Would have + V3 in a relative clause (would have + V3)", "when the images alone would have sufficed", "\"would have sufficed\" diễn tả điều lẽ ra đã đủ nếu không có nhạc nền, hàm ý chê trách."]], "tips": ["Bài review thường có phần khen, phần chê và kết luận; chú ý các từ như \"Not everything succeeds\", \"Nevertheless\" để tìm quan điểm cuối cùng.", "Để biết thái độ người viết, tìm các tính từ đánh giá (strongest, rushed, overly sentimental) và câu có từ \"recommended\"."]}}, {"id": "rd5-b2-06", "lvl": "B2", "topic": "education", "genre": "interview", "title": "Learning by Investigating: A History Teacher on Projects", "text": "Interviewer: Today I'm speaking with Ms Hana Petrov, who teaches history at a secondary school and has spent six years running project-based learning in her classes. Ms Petrov, what does that mean in practice?\nHana Petrov: Instead of teaching a topic through lectures and then testing it, I give students a real question to investigate over several weeks. Last term, for example, they were asked to find out why their town's old market had closed, and what could be done to reopen it.\nInterviewer: That sounds ambitious. Don't students simply waste time?\nHana Petrov: Some do at first, I won't pretend otherwise. They are used to being told exactly what to do, so the freedom can feel uncomfortable. But once they realise the final presentation is going to a panel of local business owners, most of them become surprisingly serious.\nInterviewer: How do you make sure they actually learn the curriculum?\nHana Petrov: I map the required content onto the project before it begins. To answer the market question, they had to study the industrial revolution, read primary sources, and analyse population data. The knowledge is the same; the route is different. Their exam results have been no worse than those of traditional classes, and their writing has improved noticeably.\nInterviewer: What are the drawbacks?\nHana Petrov: Assessment is the hardest part. Group work makes it difficult to judge each individual fairly, so I now use reflection journals and short one-to-one interviews as well as the final product. It also takes far more preparation time than a conventional lesson, which is why I would not recommend that a teacher convert an entire course in one year.\nInterviewer: What advice would you give a colleague who wants to try?\nHana Petrov: Start small. Choose one unit, find a genuine audience outside the classroom, and expect the first attempt to be messy. If students are slightly frustrated, that usually means they are thinking rather than copying.", "gist": "Một giáo viên lịch sử giải thích cách dạy học theo dự án mang lại kết quả tốt nhưng đòi hỏi chuẩn bị kỹ và đánh giá công bằng.", "qs": [{"kind": "main", "q": "What is the main point of the interview?", "opts": ["Traditional lectures are always better than student projects.", "Project-based learning can work as well as traditional teaching, but it needs careful planning and fair assessment.", "Students should be allowed to choose any topic they like.", "Exams should be replaced by group presentations."], "a": 1, "ev": "The knowledge is the same; the route is different.", "why": "Cô Petrov nói 'The knowledge is the same; the route is different', và nêu cả lợi ích lẫn khó khăn (đánh giá, thời gian chuẩn bị)."}, {"kind": "detail", "q": "What question did students investigate last term?", "opts": ["How to organise a school exam", "Why the industrial revolution began", "How to start a new business", "Why the town's old market had closed"], "a": 3, "ev": "why their town's old market had closed", "why": "Văn bản nêu 'find out why their town's old market had closed'."}, {"kind": "detail", "q": "Why do most students become serious about the project?", "opts": ["Their final presentation is given to local business owners.", "Their teacher threatens to lower their grades.", "They are paid for their work.", "They want to avoid group work."], "a": 0, "ev": "the final presentation is going to a panel of local business owners", "why": "Cô nói khi học sinh biết bài thuyết trình cuối được trình bày trước 'a panel of local business owners' thì họ trở nên nghiêm túc."}, {"kind": "detail", "q": "How does Ms Petrov judge individual students fairly?", "opts": ["She asks the group to vote for the best member.", "She gives every group member the same mark.", "She uses reflection journals and short one-to-one interviews.", "She only looks at the final exam."], "a": 2, "ev": "reflection journals and short one-to-one interviews", "why": "Để đánh giá từng cá nhân, cô dùng 'reflection journals and short one-to-one interviews'."}, {"kind": "vocab", "q": "In the text, what does 'genuine' mean in 'a genuine audience'?", "opts": ["Famous", "Young", "Friendly", "Real"], "a": 3, "ev": "find a genuine audience outside the classroom", "why": "'Genuine' ở đây nghĩa là thật sự, không phải khán giả giả định trong lớp học."}, {"kind": "tfng", "q": "Ms Petrov has been using project-based learning for six years.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "has spent six years running project-based learning in her classes", "why": "Người dẫn chương trình nói cô 'has spent six years running project-based learning'."}, {"kind": "tfng", "q": "Students in project classes get worse exam results than students in traditional classes.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Their exam results have been no worse than those of traditional classes", "why": "Kết quả thi 'no worse' nghĩa là không kém hơn, nên câu này sai."}, {"kind": "tfng", "q": "The school principal strongly supports Ms Petrov's methods.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản không đề cập đến ý kiến của hiệu trưởng."}, {"kind": "inference", "q": "What does Ms Petrov suggest about students who feel a little frustrated?", "opts": ["They are probably thinking for themselves.", "They need a different teacher.", "They are not suited to project work.", "They have not read the instructions."], "a": 0, "ev": "that usually means they are thinking rather than copying", "why": "Cô nói sự bực bối nhẹ 'usually means they are thinking rather than copying', tức là các em đang tự suy nghĩ."}], "notes": {"vocab": [["ambitious", "tham vọng, đầy hoài bão (đòi hỏi nhiều nỗ lực)", "ambition (n)"], ["curriculum", "chương trình học", "the national curriculum"], ["primary sources", "tài liệu gốc, nguồn sơ cấp", "dùng trong môn lịch sử"], ["assessment", "sự đánh giá (kết quả học tập)", "assess (v)"], ["conventional", "thông thường, truyền thống", "conventional lesson"], ["genuine", "thật sự, chân thật", "a genuine audience"], ["drawbacks", "nhược điểm", "advantages and drawbacks"]], "grammar": [["Preposition + gerund (giới từ + V-ing)", "Instead of teaching a topic through lectures and then testing it", "Sau giới từ 'instead of' dùng V-ing (teaching, testing) để nói điều được thay thế."], ["Present perfect (hiện tại hoàn thành)", "Their exam results have been no worse than those of traditional classes", "Dùng have been để nói về kết quả kéo dài từ quá khứ đến hiện tại; 'those of' thay cho 'the results of'."], ["Subjunctive after recommend (giả định)", "which is why I would not recommend that a teacher convert an entire course in one year", "Sau 'recommend that' dùng động từ nguyên mẫu không 'to' (convert), không chia theo ngôi."], ["Dummy object 'it' (it làm tân ngữ giả)", "Group work makes it difficult to judge each individual fairly", "'it' đứng thay cho cụm 'to judge each individual fairly' phía sau tính từ difficult."]], "tips": ["Với bài phỏng vấn, mỗi câu hỏi của người dẫn thường là một chủ đề nhỏ; đọc câu hỏi trước sẽ biết câu trả lời nói về điều gì.", "Câu hỏi về 'drawbacks' hay 'advice' thường nằm gần cuối; hãy chú ý các từ chỉ sự nhượng bộ như 'but', 'hardest part'."]}}, {"id": "rd5-b2-07", "lvl": "B2", "topic": "science", "genre": "article", "title": "The Night Shift: How Sleep Turns Experience into Memory", "text": "For decades, sleep was regarded as little more than a period of rest, during which the brain simply switched off. Research over the past thirty years has overturned that assumption. It is now widely accepted that sleep plays an active role in turning fresh experiences into lasting memories, a process known as consolidation.\n\nWhen we learn something new, the information is initially stored in a fragile form, largely in a region called the hippocampus. During deep sleep, the hippocampus appears to replay the day's activity, and these patterns are gradually transferred to the cortex, where they can be stored for the long term. Studies in which volunteers memorised lists of word pairs found that those who slept afterwards recalled around 20 per cent more than those who stayed awake for the same period.\n\nDifferent stages of sleep seem to serve different purposes. Deep, slow-wave sleep, which dominates the first half of the night, is thought to strengthen factual knowledge. Rapid eye movement (REM) sleep, which is more common towards morning, may help the brain combine memories creatively and strip away emotional intensity from difficult events. This could explain why a problem often looks more manageable after a night's sleep.\n\nThe practical implications are considerable. Students who sacrifice sleep to revise before an exam may be undermining their own efforts, since material studied late at night is less likely to be retained if sleep is cut short. Researchers also caution that napping is no substitute for a full night, although a short nap of around twenty minutes can help temporarily.\n\nNevertheless, scientists remain divided on some questions. It is not yet clear whether sleep strengthens all memories equally or selects those that seem most important. Some evidence suggests that the brain prioritises information it expects to need again, but this has been difficult to prove outside the laboratory. Until such questions are settled, the safest advice is the simplest: protect your sleep, particularly in the days after you have learned something important.", "gist": "Bài báo giải thích giấc ngủ chủ động củng cố trí nhớ như thế nào, các giai đoạn ngủ khác nhau và những điều khoa học còn chưa chắc chắn.", "qs": [{"kind": "main", "q": "What is the main idea of the article?", "opts": ["Sleep is only a passive period of rest for the brain.", "Napping is a better way to learn than sleeping at night.", "Sleep actively helps turn new experiences into lasting memories, although some details are still uncertain.", "Scientists have fully explained how memories are stored."], "a": 2, "ev": "sleep plays an active role in turning fresh experiences into lasting memories", "why": "Bài mở đầu khẳng định 'sleep plays an active role' trong việc tạo trí nhớ lâu dài và kết thúc bằng những câu hỏi còn bỏ ngỏ."}, {"kind": "detail", "q": "Where is new information first stored, according to the article?", "opts": ["In the hippocampus", "In the cortex", "In the eyes", "In the spinal cord"], "a": 0, "ev": "largely in a region called the hippocampus", "why": "Văn bản nói thông tin mới được lưu 'largely in a region called the hippocampus'."}, {"kind": "detail", "q": "Which stage of sleep dominates the first half of the night?", "opts": ["REM sleep", "Light dozing", "Daydreaming", "Slow-wave sleep"], "a": 3, "ev": "Deep, slow-wave sleep, which dominates the first half of the night", "why": "Giấc ngủ sâu 'slow-wave' chiếm ưu thế trong nửa đầu đêm."}, {"kind": "detail", "q": "What did the word-pair studies find?", "opts": ["People who stayed awake remembered more.", "People who slept afterwards remembered more.", "Sleep made no difference to memory.", "Only older volunteers improved."], "a": 1, "ev": "those who slept afterwards recalled around 20 per cent more", "why": "Nhóm ngủ sau khi học 'recalled around 20 per cent more' so với nhóm thức."}, {"kind": "vocab", "q": "In the text, what does 'undermining' mean?", "opts": ["Carefully planning", "Strongly supporting", "Gradually weakening", "Quickly finishing"], "a": 2, "ev": "may be undermining their own efforts", "why": "'Undermining their own efforts' nghĩa là làm suy yếu dần nỗ lực của chính mình."}, {"kind": "tfng", "q": "REM sleep is more common towards the morning.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "which is more common towards morning", "why": "Bài viết nói REM sleep 'is more common towards morning'."}, {"kind": "tfng", "q": "A short nap can fully replace a night of sleep.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "napping is no substitute for a full night", "why": "Bài nói 'napping is no substitute for a full night', nên câu này sai."}, {"kind": "tfng", "q": "Most adults need at least eight hours of sleep each night.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không đưa ra con số giờ ngủ cần thiết."}, {"kind": "inference", "q": "What advice would the writer most likely give to a student with an exam tomorrow?", "opts": ["Skip sleep and revise until morning.", "Go to bed at a reasonable hour rather than study all night.", "Take a long nap in the afternoon instead of sleeping.", "Avoid revising anything the day before."], "a": 1, "ev": "Students who sacrifice sleep to revise before an exam may be undermining their own efforts", "why": "Người viết cảnh báo hy sinh giấc ngủ để ôn thi có thể phản tác dụng, nên lời khuyên là ngủ đủ."}], "notes": {"vocab": [["consolidation", "sự củng cố (trí nhớ)", "consolidate (v)"], ["fragile", "mong manh, dễ tổn hại", "a fragile form"], ["transferred", "được chuyển giao", "transfer (v)"], ["undermining", "làm suy yếu dần", "undermine one's efforts"], ["retained", "được giữ lại, ghi nhớ", "retain information"], ["prioritises", "ưu tiên", "priority (n)"], ["implications", "hệ quả, ý nghĩa thực tiễn", "practical implications"]], "grammar": [["Impersonal passive (bị động khách quan)", "It is now widely accepted that sleep plays an active role", "Cấu trúc 'It is + V3 + that' dùng để trình bày một quan điểm chung mà không nêu ai tin."], ["Preposition + which (mệnh đề quan hệ)", "Studies in which volunteers memorised lists of word pairs", "'in which' = trong đó; dùng trong văn học thuật để nối danh từ với mệnh đề mô tả."], ["Modal + continuous (động từ khuyết thiếu tiếp diễn)", "Students who sacrifice sleep to revise before an exam may be undermining their own efforts", "'may be + V-ing' diễn tả khả năng đang xảy ra ở hiện tại."], ["Whether clause (mệnh đề whether)", "It is not yet clear whether sleep strengthens all memories equally", "'whether' giới thiệu một câu hỏi gián tiếp có/không, thường đi sau 'not clear/know'."]], "tips": ["Bài báo khoa học phổ thông thường mở bằng quan niệm cũ rồi đảo ngược ('overturned that assumption'); câu đó cho biết ý chính.", "Đoạn cuối với 'Nevertheless' và 'not yet clear' báo hiệu những điều còn chưa chắc chắn, thường là nguồn của câu hỏi Not given."]}}, {"id": "rd5-b2-08", "lvl": "B2", "topic": "travel", "genre": "blog", "title": "Three Weeks, One Town: What Slow Travel Taught Me", "text": "Last spring I did something that my younger self would have found baffling: I booked a single small town in northern Portugal for three weeks and promised myself I would not rush anywhere. For years I had travelled the way many people do, trying to fit seven cities into ten days and returning home needing a holiday to recover. This time, I wanted to find out what 'slow travel' really means, and whether it lives up to its reputation.\n\nThe first week was surprisingly difficult. Without a list of sights to tick off, I felt oddly guilty, as if I were wasting money by sitting in a cafe. By the second week, however, something shifted. I began to recognise faces: the baker who set aside a roll for me, an elderly man who played cards in the square every afternoon. They stopped treating me as a tourist and started asking about my day. I learned more about the town from these brief conversations than any guidebook could have taught me.\n\nSlow travel also changed how I spent money. Because I was renting a room by the month and cooking with ingredients from the market, my costs were lower than on any previous trip, even though I stayed far longer. More importantly, my money went to local people rather than to large chains. I also took trains instead of flights, which made the journey part of the trip rather than something to endure.\n\nThat said, I would be dishonest if I claimed it suits everyone. You need flexible work or plenty of leave, and some people simply get bored without constant stimulation. I also missed out on famous places nearby, which I may never see. Whether that matters depends on what you want from travel.\n\nFor me, the biggest change was internal. I stopped collecting experiences and started noticing them. On my last evening, I realised I could name the street, the smell of bread and the sound of the church bell, none of which I had planned to remember. If you have ever returned from a trip more exhausted than when you left, I would encourage you to try staying put, even if only for a long weekend.", "gist": "Tác giả blog kể về ba tuần ở một thị trấn Bồ Đào Nha và những thay đổi mà du lịch chậm mang lại, cùng với một số hạn chế.", "qs": [{"kind": "main", "q": "What is the main purpose of the blog post?", "opts": ["To describe the writer's experience of slow travel, including its benefits and limits", "To persuade readers to move to Portugal", "To compare the cost of trains and flights", "To list the best sights in northern Portugal"], "a": 0, "ev": "I wanted to find out what 'slow travel' really means", "why": "Tác giả kể trải nghiệm ba tuần, nêu lợi ích (tiết kiệm, kết nối) và cả hạn chế (không hợp với mọi người)."}, {"kind": "detail", "q": "How did the writer feel during the first week?", "opts": ["Delighted to have free time", "Angry about the high prices", "Lonely because nobody spoke to her", "Guilty about not sightseeing"], "a": 3, "ev": "I felt oddly guilty, as if I were wasting money by sitting in a cafe", "why": "Tuần đầu tác giả 'felt oddly guilty' vì không có danh sách điểm tham quan."}, {"kind": "detail", "q": "Why were the writer's costs lower than on earlier trips?", "opts": ["She stayed with friends for free.", "She rented a room monthly and cooked with market ingredients.", "She ate only in restaurants with discounts.", "She travelled with a large group."], "a": 1, "ev": "renting a room by the month and cooking with ingredients from the market", "why": "Chi phí thấp vì thuê phòng theo tháng và tự nấu ăn bằng nguyên liệu chợ."}, {"kind": "detail", "q": "How did the writer travel to and from the town?", "opts": ["By plane", "By coach", "By train", "By bicycle"], "a": 2, "ev": "I also took trains instead of flights", "why": "Tác giả viết 'I also took trains instead of flights'."}, {"kind": "vocab", "q": "In the text, what does 'baffling' mean?", "opts": ["Very confusing", "Very cheap", "Very exciting", "Very boring"], "a": 0, "ev": "something that my younger self would have found baffling", "why": "'Baffling' nghĩa là khó hiểu, gây bối rối: bản thân trẻ hơn sẽ không hiểu nổi."}, {"kind": "tfng", "q": "The writer stayed in one town for three weeks.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "booked a single small town in northern Portugal for three weeks", "why": "Tác giả 'booked a single small town ... for three weeks'."}, {"kind": "tfng", "q": "The writer says slow travel is suitable for everyone.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "I would be dishonest if I claimed it suits everyone", "why": "Tác giả nói sẽ 'dishonest' nếu cho rằng nó hợp với mọi người, nên câu này sai."}, {"kind": "tfng", "q": "The writer plans to return to the same town next year.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói gì về kế hoạch quay lại thị trấn."}, {"kind": "inference", "q": "What can be inferred about the writer's earlier trips?", "opts": ["They were always very cheap.", "They lasted several months.", "They were rushed and tiring.", "They were taken with local friends."], "a": 2, "ev": "returning home needing a holiday to recover", "why": "Việc về nhà 'needing a holiday to recover' cho thấy các chuyến trước vội vàng và mệt mỏi."}], "notes": {"vocab": [["baffling", "gây bối rối, khó hiểu", "baffle (v)"], ["lives up to", "đáp ứng được (kỳ vọng)", "live up to its reputation"], ["tick off", "đánh dấu hoàn thành", "tick off a list"], ["set aside", "để dành, giữ lại", "set aside a roll"], ["endure", "chịu đựng", "endure a long journey"], ["stimulation", "sự kích thích, sự thú vị", "constant stimulation"], ["staying put", "ở yên một chỗ", "informal phrase"]], "grammar": [["Would have + past participle (khả năng giả định trong quá khứ)", "something that my younger self would have found baffling", "Diễn tả điều mà bản thân ngày trước chắc chắn đã thấy khó hiểu nếu nó xảy ra."], ["As if + were (như thể)", "as if I were wasting money by sitting in a cafe", "Sau 'as if' dùng 'were' để nói về cảm giác không có thật."], ["Past continuous for reason (quá khứ tiếp diễn)", "Because I was renting a room by the month", "Dùng quá khứ tiếp diễn để chỉ tình trạng đang diễn ra làm nguyên nhân."], ["Second conditional (câu điều kiện loại 2)", "I would be dishonest if I claimed it suits everyone", "Cấu trúc would + V ... if + quá khứ đơn nói về tình huống giả định, tác giả tự nhận xét."]], "tips": ["Bài blog dùng ngôi thứ nhất và kể theo trình tự thời gian; các cụm 'The first week', 'By the second week' giúp theo dõi diễn biến.", "Cụm 'That said' báo hiệu một đoạn nhượng bộ, nêu mặt hạn chế; câu hỏi True/False thường dựa vào đoạn này."]}}, {"id": "rd5-b2-09", "lvl": "B2", "topic": "work", "genre": "report", "title": "Incident Report: Duplicated Charges at Brightline Energy", "text": "Incident Report: Customer Billing Data Error, 14 March\n\nSummary\nOn 14 March, a software update caused the billing system of Brightline Energy to send incorrect invoices to 2,300 customers. Approximately 340 of these customers were charged up to twice their usual amount. This report outlines how the error was detected, how it was contained, and what changes are recommended.\n\nDetection and response\nThe error was first reported by a customer service adviser at 9.40 a.m., after three callers raised the same complaint within twenty minutes. The adviser escalated the issue to the technical team, who confirmed within an hour that a configuration fault introduced during the previous night's update was duplicating certain charges. Automated billing was suspended at 11.15 a.m., preventing further invoices from being issued.\n\nBy midday, a message had been sent to all affected customers explaining the error, apologising, and assuring them that no payment would be taken until corrected invoices had been issued. Refunds for the 340 customers who had already paid were processed within 48 hours. No personal or financial information was exposed, as the fault affected only the amounts displayed and not data security.\n\nFindings\nThe investigation concluded that the update had not been tested against accounts with multiple meters, which represent a small but significant proportion of customers. Furthermore, the monitoring system had not been configured to flag unusual increases in invoice totals, so the problem was identified by customers rather than by the company.\n\nRecommendations\nIt is recommended that (1) all updates be tested against a representative sample of account types before release; (2) automatic alerts be introduced for invoice totals that deviate sharply from historical patterns; and (3) customer service staff be given a direct channel to report recurring complaints. Had these measures been in place, the error would probably have been caught before any invoices were sent.\n\nPrepared by: Operations Review Team", "gist": "Báo cáo sự cố mô tả cách một công ty phát hiện, xử lý lỗi hóa đơn khách hàng và đề xuất các biện pháp phòng ngừa.", "qs": [{"kind": "main", "q": "What is the main purpose of the report?", "opts": ["To apologise to customers for a data leak", "To advertise a new billing system", "To announce that staff will be dismissed", "To explain what happened in a billing error, how it was handled, and how to prevent a repeat"], "a": 3, "ev": "This report outlines how the error was detected, how it was contained, and what changes are recommended.", "why": "Phần Summary nêu rõ mục đích: cách phát hiện, kiểm soát lỗi và các thay đổi được đề xuất."}, {"kind": "detail", "q": "How was the error first noticed?", "opts": ["Three customers made the same complaint within twenty minutes.", "An automatic alert warned the technical team.", "A manager read the invoices before they were sent.", "A newspaper reported the problem."], "a": 0, "ev": "after three callers raised the same complaint within twenty minutes", "why": "Lỗi được phát hiện khi 'three callers raised the same complaint within twenty minutes'."}, {"kind": "detail", "q": "What caused the duplicated charges?", "opts": ["A mistake by a customer service adviser", "A cyber attack on the company", "A configuration fault from the previous night's update", "A failure in the customers' banks"], "a": 2, "ev": "a configuration fault introduced during the previous night's update was duplicating certain charges", "why": "Nguyên nhân là 'a configuration fault' do bản cập nhật tối hôm trước."}, {"kind": "detail", "q": "How quickly were refunds processed for customers who had already paid?", "opts": ["Within one hour", "Within 48 hours", "Within one week", "By the end of the month"], "a": 1, "ev": "processed within 48 hours", "why": "Văn bản nêu hoàn tiền 'processed within 48 hours'."}, {"kind": "vocab", "q": "In the text, what does 'escalated' mean in 'escalated the issue'?", "opts": ["Passed it to a higher level for action", "Ignored it for a while", "Explained it to the customers", "Solved it immediately"], "a": 0, "ev": "The adviser escalated the issue to the technical team", "why": "'Escalated' nghĩa là chuyển vấn đề lên cấp cao hơn (đội kỹ thuật) để xử lý."}, {"kind": "tfng", "q": "Automated billing was suspended at 11.15 a.m.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "Automated billing was suspended at 11.15 a.m.", "why": "Văn bản ghi rõ thời điểm 11.15 a.m."}, {"kind": "tfng", "q": "Customers' personal and financial information was exposed.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "No personal or financial information was exposed", "why": "Báo cáo nói 'No personal or financial information was exposed', nên câu này sai."}, {"kind": "tfng", "q": "Brightline Energy lost many customers after the incident.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Báo cáo không đề cập đến việc mất khách hàng."}, {"kind": "inference", "q": "What does the report suggest about the company's monitoring system?", "opts": ["It worked perfectly and detected the error early.", "It failed to warn the company about the problem.", "It was designed to stop all updates.", "It only monitored customer complaints."], "a": 1, "ev": "the problem was identified by customers rather than by the company", "why": "Vấn đề do khách hàng phát hiện chứ không phải công ty, cho thấy hệ thống giám sát không cảnh báo được."}], "notes": {"vocab": [["contained", "được kiểm soát, ngăn lan rộng", "contain a problem"], ["escalated", "chuyển lên cấp cao hơn", "escalate an issue"], ["duplicating", "nhân đôi, lặp lại", "duplicate (v)"], ["suspended", "bị tạm dừng", "suspend (v)"], ["exposed", "bị lộ, bị phơi bày", "exposed data"], ["deviate", "lệch khỏi", "deviate from a pattern"], ["representative", "mang tính đại diện", "a representative sample"]], "grammar": [["Inverted third conditional (đảo ngữ điều kiện loại 3)", "Had these measures been in place, the error would probably have been caught before any invoices were sent.", "'Had + S + V3' thay cho 'If these measures had been...'; dùng trong văn trang trọng để nói điều không xảy ra trong quá khứ."], ["Subjunctive in recommendations (giả định)", "all updates be tested against a representative sample of account types before release", "Sau 'It is recommended that' dùng 'be + V3' (không chia theo chủ ngữ), kiểu văn bản trang trọng."], ["Past perfect passive (quá khứ hoàn thành bị động)", "By midday, a message had been sent to all affected customers", "'had been + V3' diễn tả hành động đã hoàn tất trước một mốc trong quá khứ (midday), không cần nêu người làm."], ["Passive with report verbs (bị động)", "Automated billing was suspended at 11.15 a.m.", "Báo cáo dùng bị động để tập trung vào sự việc thay vì người thực hiện, tạo giọng khách quan."]], "tips": ["Báo cáo có tiêu đề các phần (Summary, Findings, Recommendations); hãy đọc phần Summary trước để nắm mục đích, rồi tìm chi tiết ở phần tương ứng.", "Chú ý số liệu và mốc thời gian (9.40 a.m., 11.15 a.m., 48 hours) vì câu hỏi chi tiết thường hỏi trực tiếp."]}}, {"id": "rd5-b2-10", "lvl": "B2", "topic": "daily", "genre": "story", "title": "The Hedge Between Us", "text": "For eight months, the hedge between our gardens was the only thing Mr Okafor and I had in common, and we disagreed about that too. It grew thick and tall on his side, and every summer it blocked the light from my vegetable beds. I had mentioned it twice, politely, and both times he had nodded without actually promising anything.\n\nThe situation came to a head one Saturday in June, when I found a pile of cut branches dumped on my side of the fence. Without thinking, I stormed round to his door and said some things I would rather forget. He replied, coldly, that I had no right to tell him how to manage his own property. Neither of us spoke to the other for the next three weeks.\n\nIt was his wife who broke the silence. She knocked on my door one evening holding a plate of cake and said, simply, 'My husband won't say this, so I will: he's sorry about the branches. He'd been trimming in a hurry because of his back, and he didn't know where to put them.' I had not known that he had back problems. I had never asked.\n\nThat cake led to a conversation over the fence, awkward at first, then easier. It turned out that Mr Okafor had planted the hedge years ago for privacy after a burglary, and was reluctant to cut it back. We agreed on a compromise: the hedge would be lowered by half a metre, and I would do the trimming myself, since his back made it hard for him. In return, I would share the tomatoes that grew better in the extra sunlight, and he accepted them, rather grumpily, every August.\n\nLooking back, I am struck by how much of the dispute was built on assumptions. I had decided he was inconsiderate; he had decided I was interfering. Neither of us had checked. If I had asked about the hedge instead of complaining about it, the whole quarrel might never have happened. I now try, not always successfully, to ask a question before forming a judgement. It is a small habit, but it has made the street a friendlier place.", "gist": "Câu chuyện hai người hàng xóm cãi nhau vì hàng rào cây, được hòa giải nhờ vợ ông Okafor, và người kể rút ra bài học về việc đừng vội phán xét.", "qs": [{"kind": "main", "q": "What is the main idea of the story?", "opts": ["A hedge was cut down because it was dangerous.", "A family moved house to escape their neighbours.", "A quarrel between neighbours was resolved, and the narrator learned how assumptions cause conflict.", "A burglary was solved with the help of a neighbour."], "a": 2, "ev": "how much of the dispute was built on assumptions", "why": "Câu chuyện kể hòa giải và người kể nhận ra mâu thuẫn xuất phát từ 'assumptions'."}, {"kind": "detail", "q": "What was the narrator's problem with the hedge?", "opts": ["It grew into her house.", "It blocked light from her vegetable beds.", "It made too much noise.", "It hid her front door."], "a": 1, "ev": "it blocked the light from my vegetable beds", "why": "Hàng rào 'blocked the light from my vegetable beds'."}, {"kind": "detail", "q": "Who ended the silence between the neighbours?", "opts": ["The narrator's friend", "A local councillor", "Mr Okafor's wife", "Mr Okafor's son"], "a": 3, "ev": "It was his wife who broke the silence.", "why": "Vợ của ông Okafor mang bánh sang và phá vỡ im lặng."}, {"kind": "detail", "q": "Why had Mr Okafor planted the hedge?", "opts": ["For privacy after a burglary", "To protect his tomatoes", "To mark the edge of the street", "To block the wind"], "a": 0, "ev": "planted the hedge years ago for privacy after a burglary", "why": "Ông trồng hàng rào 'for privacy after a burglary'."}, {"kind": "vocab", "q": "In the text, what does 'reluctant' mean?", "opts": ["Eager", "Unwilling", "Able", "Forced"], "a": 1, "ev": "was reluctant to cut it back", "why": "'Reluctant' nghĩa là miễn cưỡng, không sẵn lòng cắt tỉa hàng rào."}, {"kind": "tfng", "q": "The narrator had mentioned the hedge to Mr Okafor before the argument.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "I had mentioned it twice, politely", "why": "Người kể nói 'I had mentioned it twice, politely' trước cuộc cãi vã."}, {"kind": "tfng", "q": "The two neighbours did not speak for a whole year.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Neither of us spoke to the other for the next three weeks.", "why": "Họ không nói chuyện 'for the next three weeks', không phải cả năm."}, {"kind": "tfng", "q": "Mr Okafor has since had an operation on his back.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản chỉ nói ông có vấn đề về lưng, không nói gì về phẫu thuật."}, {"kind": "inference", "q": "What does the narrator imply about the quarrel?", "opts": ["It was entirely Mr Okafor's fault.", "It was impossible to settle without lawyers.", "It could have been avoided if they had communicated better.", "It happened because of the weather."], "a": 2, "ev": "If I had asked about the hedge instead of complaining about it, the whole quarrel might never have happened.", "why": "Người kể thừa nhận nếu đã hỏi thay vì phàn nàn thì 'the whole quarrel might never have happened'."}], "notes": {"vocab": [["came to a head", "lên đến đỉnh điểm", "idiom"], ["stormed", "hùng hổ đi, xông tới", "storm round to his door"], ["reluctant", "miễn cưỡng", "reluctant to + V"], ["compromise", "sự thỏa hiệp", "reach a compromise"], ["inconsiderate", "thiếu quan tâm đến người khác", "considerate (adj)"], ["interfering", "hay can thiệp, xen vào chuyện người khác", "interfere (v)"], ["grumpily", "một cách cáu kỉnh", "grumpy (adj)"]], "grammar": [["Past perfect (quá khứ hoàn thành)", "I had mentioned it twice, politely", "Dùng had + V3 để nói về hành động xảy ra trước thời điểm kể chuyện chính."], ["Cleft sentence (câu chẻ)", "It was his wife who broke the silence.", "Cấu trúc 'It was ... who' nhấn mạnh người thực hiện hành động."], ["Would rather (thà ... còn hơn)", "some things I would rather forget", "'would rather + V' diễn tả điều mình muốn hơn, ở đây là muốn quên những lời đã nói."], ["Third conditional (câu điều kiện loại 3)", "If I had asked about the hedge instead of complaining about it, the whole quarrel might never have happened.", "If + had V3, ... might have V3 nói về điều đã không xảy ra và kết quả khác có thể xảy ra."]], "tips": ["Truyện kể theo ngôi thứ nhất thường có đoạn cuối là suy ngẫm; thông điệp chính thường nằm ở đây ('built on assumptions').", "Chú ý các mốc thời gian (eight months, three weeks, every August) để trả lời đúng câu hỏi chi tiết và Đúng/Sai."]}}, {"id": "rd5-b2-11", "lvl": "B2", "topic": "medical", "genre": "article", "title": "From Reflex to Decision: How the Nervous System Works", "text": "Every second, your nervous system receives millions of signals and decides which ones matter. It has two main parts. The central nervous system consists of the brain and the spinal cord, while the peripheral nervous system includes all the nerves that run through the rest of the body. Together they allow us to sense, think and move.\n\nThe basic unit of this network is the neuron. A neuron has a cell body, short branches that receive messages, and a long fibre called an axon that carries the message onward. Sensory neurons bring information from the skin, eyes and other organs towards the spinal cord and brain, whereas motor neurons carry instructions outwards to the muscles. Between them, countless connecting neurons link one pathway to another.\n\nThe simplest response is a reflex. If you touch a hot pan, sensory neurons send a signal to the spinal cord, where a connecting neuron passes it directly to a motor neuron. The muscle contracts and your hand pulls away before the brain has even registered the pain. Because the pathway bypasses the brain, the reflex is extremely fast, which protects tissue from serious damage. Only afterwards does the signal reach the brain, and you realise what has happened.\n\nDecisions are far more complex. The cerebrum, the largest part of the brain, is divided into regions with different roles. The frontal lobe, which lies behind the forehead, is mainly responsible for planning and judgement. The cerebellum, located at the back and below, coordinates balance and smooth movement. The brain stem connects the brain to the spinal cord and regulates automatic functions such as breathing and heart rate, which continue even while we sleep.\n\nWhen we choose a course of action, information from many regions is compared, memories are consulted, and the outcome is weighed up in a fraction of a second. The result is then sent down the spinal cord to the muscles. Although conscious choices are slower than reflexes, they allow us to respond flexibly to situations that no reflex could have anticipated. Damage to any part of this system, for example after a stroke or a spinal injury, can therefore affect movement, sensation or thinking, depending on where it occurs.", "gist": "Bài viết giải thích cấu trúc hệ thần kinh và so sánh phản xạ nhanh với các quyết định có ý thức do não xử lý.", "qs": [{"kind": "main", "q": "What is the main purpose of the text?", "opts": ["To describe how to treat a spinal injury", "To explain how the nervous system is organised and how reflexes differ from conscious decisions", "To argue that reflexes are more important than thinking", "To list the diseases that affect the brain"], "a": 1, "ev": "Together they allow us to sense, think and move.", "why": "Bài giới thiệu các phần của hệ thần kinh rồi so sánh phản xạ với quyết định có ý thức; câu \"Together they allow us to sense, think and move.\" nêu vai trò chung."}, {"kind": "detail", "q": "According to the text, what does the central nervous system consist of?", "opts": ["The brain and all the nerves in the body", "The spinal cord and the muscles", "The brain and the spinal cord", "The cerebrum and the cerebellum only"], "a": 2, "ev": "The central nervous system consists of the brain and the spinal cord", "why": "Văn bản nêu rõ \"The central nervous system consists of the brain and the spinal cord\"."}, {"kind": "detail", "q": "Why is a reflex so fast?", "opts": ["The pathway bypasses the brain", "The brain makes the decision in advance", "Motor neurons are longer than sensory neurons", "Pain signals travel through the cerebellum"], "a": 0, "ev": "Because the pathway bypasses the brain, the reflex is extremely fast", "why": "Văn bản nói \"Because the pathway bypasses the brain, the reflex is extremely fast\": đường dẫn truyền không đi qua não."}, {"kind": "detail", "q": "Which part of the brain coordinates balance and smooth movement?", "opts": ["The frontal lobe", "The brain stem", "The cerebrum", "The cerebellum"], "a": 3, "ev": "The cerebellum, located at the back and below, coordinates balance and smooth movement", "why": "Câu \"The cerebellum, located at the back and below, coordinates balance and smooth movement\" cho đáp án là tiểu não."}, {"kind": "vocab", "q": "In the text, what does 'regulates' mean?", "opts": ["Repairs", "Stops", "Controls", "Replaces"], "a": 2, "ev": "regulates automatic functions such as breathing and heart rate", "why": "\"Regulates\" ở đây nghĩa là điều khiển/điều hòa các chức năng tự động như thở và nhịp tim."}, {"kind": "tfng", "q": "The brain stem keeps controlling breathing during sleep.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "which continue even while we sleep", "why": "Câu \"which continue even while we sleep\" cho thấy các chức năng như thở vẫn tiếp tục khi ngủ."}, {"kind": "tfng", "q": "Motor neurons carry information from the skin to the spinal cord.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "motor neurons carry instructions outwards to the muscles", "why": "Sai: \"motor neurons carry instructions outwards to the muscles\"; chính neuron cảm giác mới đưa thông tin từ da vào."}, {"kind": "tfng", "q": "Reflexes become slower as people grow older.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản không đề cập đến việc phản xạ chậm đi theo tuổi nên đáp án là Not given."}, {"kind": "inference", "q": "What can be inferred about a patient with a spinal injury?", "opts": ["Their brain can no longer think", "Signals between the brain and the body may be disrupted", "They will lose all reflexes immediately", "Their cerebellum will stop working"], "a": 1, "ev": "Damage to any part of this system, for example after a stroke or a spinal injury, can therefore affect movement, sensation or thinking", "why": "Câu \"Damage to any part of this system, for example after a stroke or a spinal injury, can therefore affect movement, sensation or thinking\" gợi ý tín hiệu giữa não và cơ thể có thể bị gián đoạn."}], "notes": {"vocab": [["bypasses", "đi vòng qua, không đi qua", "bypass a stage; heart bypass surgery"], ["regulates", "điều hòa, kiểm soát", "regulation (n), regulatory (adj)"], ["coordinates", "phối hợp, điều phối", "coordination (n)"], ["judgement", "sự phán đoán, óc xét đoán", "make a good judgement"], ["countless", "vô số", "= too many to count"], ["weighed up", "cân nhắc", "weigh up the options"], ["anticipated", "lường trước, dự đoán", "anticipate (v), anticipation (n)"]], "grammar": [["Contrast with whereas (liên từ chỉ sự tương phản)", "Sensory neurons bring information from the skin, eyes and other organs towards the spinal cord and brain, whereas motor neurons carry instructions outwards to the muscles.", "\"Whereas\" nối hai mệnh đề đối lập (neuron cảm giác và neuron vận động), thường dùng khi so sánh hai nhóm."], ["Non-defining relative clause (mệnh đề quan hệ không xác định)", "The frontal lobe, which lies behind the forehead, is mainly responsible for planning and judgement.", "Mệnh đề \"which...\" nằm giữa hai dấu phẩy, thêm thông tin phụ mà không cần để xác định danh từ."], ["Modal perfect (động từ khuyết thiếu hoàn thành)", "situations that no reflex could have anticipated", "could have + V3 nói về điều lẽ ra có thể xảy ra/ được dự đoán trong quá khứ; ở đây nhấn mạnh phản xạ không thể lường trước tình huống."], ["Inversion with Only afterwards (đảo ngữ)", "Only afterwards does the signal reach the brain, and you realise what has happened.", "Trạng từ phủ định/hạn định \"Only afterwards\" đứng đầu câu nên trợ động từ does đảo lên trước chủ ngữ, tạo nhấn mạnh."]], "tips": ["Bài báo khoa học phổ thông thường đi từ khái quát đến chi tiết: đoạn 1 nêu hai phần chính, các đoạn sau mô tả từng phần, nên đọc câu đầu mỗi đoạn để nắm ý chính.", "Chú ý từ nối đối lập như whereas, although để nhận ra các so sánh (phản xạ và quyết định có ý thức)."]}}, {"id": "rd5-b2-12", "lvl": "B2", "topic": "medical", "genre": "dialogue", "title": "Breaking the News: A Diabetes Consultation", "text": "Dr Hall: Please come in and sit down, Mr Tran. How are you feeling today?\nMr Tran: Honestly, doctor, I haven't slept properly since you called me. I keep imagining the worst. Is it serious?\nDr Hall: I understand why you're worried, and I'll explain everything clearly. Your blood tests show that your blood sugar has been high for several months. This means you have type 2 diabetes.\nMr Tran: Diabetes? My uncle had it, and he lost his sight in the end. Does that mean the same will happen to me?\nDr Hall: Not necessarily. Your uncle's condition may have gone untreated for many years. In your case we have found it early, which is very encouraging. Diabetes means that your body can't use sugar from food properly, so it stays in the blood instead of being used for energy.\nMr Tran: So it's like my body has stopped working?\nDr Hall: Not at all. Your pancreas still makes insulin, but your cells don't respond to it as well as they should. Over time, high sugar can damage small blood vessels and nerves, which is why we take it seriously. However, it can be controlled well, and many people live full lives with it.\nMr Tran: What do I have to do? Will I need injections?\nDr Hall: Probably not at the moment. For most people the first step is changing daily habits: eating more vegetables and less sugar, walking for thirty minutes a day, and losing a little weight. If these changes aren't enough after three months, we can discuss tablets.\nMr Tran: That sounds manageable. I was afraid you would say I had to give up everything I enjoy.\nDr Hall: You don't have to. We'll work out a plan together, and a dietitian can help you. I'd also like to see you again in four weeks to check your progress. Is there anything else that's worrying you?\nMr Tran: Just one thing. Should I tell my family?\nDr Hall: I'd encourage it. Their support will make a real difference, and they may want to have their own sugar levels checked, since diabetes can run in families.\nMr Tran: Thank you, doctor. I feel much calmer now.\nDr Hall: I'm glad. Please call the clinic if you have any questions before our next appointment.", "gist": "Bác sĩ giải thích chẩn đoán tiểu đường típ 2 cho bệnh nhân đang lo lắng, trấn an và hướng dẫn các bước kiểm soát bệnh.", "qs": [{"kind": "main", "q": "What is the main purpose of the conversation?", "opts": ["The doctor explains a diagnosis, reassures the patient and outlines the next steps", "The patient asks for injections to treat diabetes", "The doctor compares two treatments for kidney disease", "The patient reports that his uncle has lost his sight"], "a": 0, "ev": "I understand why you're worried, and I'll explain everything clearly.", "why": "Bác sĩ nói \"I understand why you're worried, and I'll explain everything clearly.\" rồi giải thích bệnh và kế hoạch xử trí."}, {"kind": "detail", "q": "What did the blood tests show?", "opts": ["Low levels of insulin since birth", "Damage to the kidneys", "Normal sugar levels in the morning", "Blood sugar that has been high for several months"], "a": 3, "ev": "your blood sugar has been high for several months", "why": "Bác sĩ nói \"your blood sugar has been high for several months\"."}, {"kind": "detail", "q": "According to Dr Hall, what is the first step for most people?", "opts": ["Starting injections", "Changing daily habits", "Stopping all sugar and exercise", "Taking tablets for three months"], "a": 1, "ev": "For most people the first step is changing daily habits", "why": "Câu \"For most people the first step is changing daily habits\" trả lời trực tiếp."}, {"kind": "detail", "q": "When does Dr Hall want to see Mr Tran again?", "opts": ["In three months", "The next day", "In four weeks", "In one year"], "a": 2, "ev": "I'd also like to see you again in four weeks to check your progress.", "why": "Bác sĩ nói \"in four weeks\" (sau bốn tuần) để kiểm tra tiến triển."}, {"kind": "vocab", "q": "In the text, what does 'manageable' mean?", "opts": ["Impossible to do", "Possible to deal with", "Very expensive", "Painful to experience"], "a": 1, "ev": "That sounds manageable.", "why": "\"Manageable\" nghĩa là có thể xoay xở/thực hiện được; ông Tran nhẹ nhõm vì kế hoạch nghe khả thi."}, {"kind": "tfng", "q": "Mr Tran's uncle also had diabetes.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "My uncle had it, and he lost his sight in the end.", "why": "Ông Tran nói \"My uncle had it\", nghĩa là chú ông cũng bị tiểu đường."}, {"kind": "tfng", "q": "Dr Hall says Mr Tran will need injections immediately.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Probably not at the moment.", "why": "Sai: khi được hỏi về tiêm, bác sĩ trả lời \"Probably not at the moment.\""}, {"kind": "tfng", "q": "Mr Tran has a family history of heart disease.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Cuộc hội thoại không nhắc đến bệnh tim trong gia đình nên là Not given."}, {"kind": "inference", "q": "What can be inferred from Dr Hall's comment about Mr Tran's uncle?", "opts": ["The uncle's problems were probably linked to late or missing treatment", "Diabetes always causes blindness", "The uncle never visited a doctor", "Mr Tran will certainly lose his sight"], "a": 0, "ev": "Your uncle's condition may have gone untreated for many years.", "why": "Câu \"Your uncle's condition may have gone untreated for many years.\" ngụ ý biến chứng của người chú có thể do không được điều trị lâu năm."}], "notes": {"vocab": [["encouraging", "đáng khích lệ, tích cực", "encourage (v), encouragement (n)"], ["untreated", "không được điều trị", "un- + treated"], ["respond", "đáp ứng, phản ứng", "respond to insulin/treatment"], ["blood vessels", "mạch máu", "artery, vein, capillary"], ["dietitian", "chuyên gia dinh dưỡng", "khác với nutritionist"], ["manageable", "có thể kiểm soát được", "manage (v)"], ["run in families", "di truyền trong gia đình", "= be hereditary"]], "grammar": [["Modal perfect for possibility (khả năng trong quá khứ)", "Your uncle's condition may have gone untreated for many years.", "may have + V3 diễn đạt suy đoán về quá khứ; bác sĩ dùng để trấn an một cách thận trọng, không khẳng định."], ["First conditional (câu điều kiện loại 1)", "If these changes aren't enough after three months, we can discuss tablets.", "If + hiện tại đơn, mệnh đề chính dùng can/will để nói về khả năng thật trong tương lai."], ["Non-defining clause with which is why (mệnh đề chỉ lý do)", "Over time, high sugar can damage small blood vessels and nerves, which is why we take it seriously.", "\"which\" thay cho cả mệnh đề trước; \"which is why\" nêu kết quả/lý do của điều vừa nói."], ["Instead of + V-ing (passive gerund)", "so it stays in the blood instead of being used for energy", "Sau giới từ instead of dùng dạng V-ing; \"being used\" là bị động, chỉ đường đi bình thường của đường bị thay thế."]], "tips": ["Với hội thoại y khoa, chú ý cách bác sĩ trấn an (Not necessarily, Not at all) vì thường đi kèm thông tin đính chính quan trọng.", "Ghi nhớ ai nói gì: câu hỏi của bệnh nhân thường báo hiệu điều ông lo lắng, và câu trả lời của bác sĩ chứa đáp án."]}}, {"id": "rd5-b2-13", "lvl": "B2", "topic": "medical", "genre": "report", "title": "Hand-Hygiene Audit Report: Third Quarter Results", "text": "Hand-Hygiene Audit Report: Medical and Surgical Wards, Third Quarter\n\nPurpose\nThis report presents the results of a hand-hygiene audit carried out in the hospital's medical and surgical wards between July and September. The aim was to measure how often staff clean their hands at the moments recommended by the infection-control team, and to identify areas for improvement.\n\nMethod\nTrained observers watched staff discreetly during routine care, without announcing the exact times of their visits. In total, 1,200 opportunities for hand hygiene were recorded across 4 wards. An opportunity was counted as compliant only if the member of staff used soap and water or alcohol gel at the correct moment, for example before touching a patient or after contact with body fluids.\n\nFindings\nOverall compliance reached 78 per cent, an increase from 69 per cent in the previous quarter. Nurses performed best, with 84 per cent compliance, followed by doctors at 71 per cent. Compliance was highest after contact with body fluids and lowest before touching a patient, which suggests that staff protect themselves more consistently than they protect patients. Compliance was also noticeably lower on weekends and during night shifts. Observers noted that gel dispensers were empty at three bedsides on the surgical ward.\n\nDiscussion\nThe improvement is probably linked to the new training sessions introduced in June, although the audit was not designed to prove this. The low rate before patient contact is concerning, since that moment is considered the most important for preventing infections spread by hands. Staff shortages at night may partly explain the weekend and night-shift results, but this was not investigated.\n\nRecommendations\nFirst, dispensers should be checked daily and refilled when necessary. Second, short refresher sessions should be offered to doctors. Third, the audit should be repeated in January, with extra observations at night, to see whether the gains are maintained.", "gist": "Báo cáo kiểm tra vệ sinh tay ở các khoa nội và ngoại cho thấy tỷ lệ tuân thủ tăng lên nhưng còn thấp ở một số thời điểm, kèm các khuyến nghị.", "qs": [{"kind": "main", "q": "What is the main purpose of the report?", "opts": ["To announce new rules for visitors", "To compare the salaries of nurses and doctors", "To present compliance results and recommend improvements", "To prove that training sessions prevent infection"], "a": 2, "ev": "The aim was to measure how often staff clean their hands at the moments recommended by the infection-control team, and to identify areas for improvement.", "why": "Mục đích được nêu: \"to measure how often staff clean their hands... and to identify areas for improvement\"."}, {"kind": "detail", "q": "How many opportunities for hand hygiene were recorded?", "opts": ["1,200", "69", "4,000", "84"], "a": 0, "ev": "1,200 opportunities for hand hygiene were recorded across 4 wards", "why": "Văn bản nói \"1,200 opportunities for hand hygiene were recorded across 4 wards\"."}, {"kind": "detail", "q": "Which group of staff had the highest compliance?", "opts": ["Doctors", "Cleaners", "Surgeons", "Nurses"], "a": 3, "ev": "Nurses performed best, with 84 per cent compliance", "why": "Câu \"Nurses performed best, with 84 per cent compliance\" cho thấy điều dưỡng cao nhất."}, {"kind": "detail", "q": "When was compliance lowest?", "opts": ["After contact with body fluids", "Before touching a patient", "After using the toilet", "During the training sessions"], "a": 1, "ev": "lowest before touching a patient", "why": "Báo cáo nêu \"lowest before touching a patient\"."}, {"kind": "vocab", "q": "In the text, what does 'compliant' mean?", "opts": ["Dirty", "Late", "Following the required rules", "Willing to complain"], "a": 2, "ev": "An opportunity was counted as compliant only if the member of staff used soap and water or alcohol gel at the correct moment", "why": "\"Compliant\" nghĩa là tuân thủ quy định, ở đây là dùng xà phòng hoặc gel đúng thời điểm."}, {"kind": "tfng", "q": "Compliance was lower on weekends and night shifts.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "Compliance was also noticeably lower on weekends and during night shifts.", "why": "Câu \"Compliance was also noticeably lower on weekends and during night shifts.\" khẳng định điều này."}, {"kind": "tfng", "q": "Overall compliance fell compared with the previous quarter.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "an increase from 69 per cent in the previous quarter", "why": "Sai: \"an increase from 69 per cent in the previous quarter\" cho thấy tỷ lệ tăng, không giảm."}, {"kind": "tfng", "q": "The hospital board has approved the purchase of new gel dispensers.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Báo cáo không nói gì về việc ban giám đốc phê duyệt mua thiết bị mới nên là Not given."}, {"kind": "inference", "q": "What does the report suggest about the link between training and the improvement?", "opts": ["Training definitely caused the improvement", "Training made no difference", "Training was only given to nurses", "The link is likely but not proven"], "a": 3, "ev": "although the audit was not designed to prove this", "why": "Báo cáo nói cải thiện \"probably linked\" tới đào tạo, \"although the audit was not designed to prove this\": có khả năng nhưng chưa được chứng minh."}], "notes": {"vocab": [["discreetly", "một cách kín đáo", "discreet (adj), discretion (n)"], ["compliant", "tuân thủ", "compliance (n); comply with"], ["body fluids", "dịch cơ thể", "blood, saliva, urine..."], ["dispensers", "bình/hộp phân phối (gel, xà phòng)", "dispense (v)"], ["refresher", "(khóa) ôn tập, bồi dưỡng lại", "refresher course"], ["shortages", "tình trạng thiếu hụt", "staff shortage"], ["consistently", "một cách nhất quán, đều đặn", "consistent (adj)"]], "grammar": [["Passive voice in reports (bị động trong văn bản báo cáo)", "An opportunity was counted as compliant only if the member of staff used soap and water or alcohol gel at the correct moment", "Bị động \"was counted\" giữ giọng khách quan, tập trung vào đối tượng đo lường thay vì người quan sát."], ["Participle phrase (cụm phân từ)", "Nurses performed best, with 84 per cent compliance, followed by doctors at 71 per cent.", "\"followed by...\" là phân từ quá khứ bổ sung thông tin xếp hạng mà không cần mệnh đề đầy đủ."], ["Which referring to a clause (which chỉ cả mệnh đề)", "which suggests that staff protect themselves more consistently than they protect patients", "\"which\" thay cho cả phát hiện phía trước, rồi suy ra kết luận; thường gặp trong phần Findings/Discussion."], ["Passive modal (bị động với should)", "dispensers should be checked daily and refilled when necessary", "should be + V3 dùng trong khuyến nghị, không nêu rõ ai thực hiện."]], "tips": ["Báo cáo có tiêu đề từng phần (Purpose, Method, Findings...), nên nhìn tiêu đề để tìm nhanh thông tin: số liệu nằm ở Findings, lý giải ở Discussion.", "Chú ý từ chỉ mức độ chắc chắn như probably, may, suggests để phân biệt kết quả đo được với phỏng đoán."]}}, {"id": "rd5-b2-14", "lvl": "B2", "topic": "medical", "genre": "article", "title": "Why Antibiotics Are Losing Their Power", "text": "Antibiotics rank among the greatest achievements of modern medicine. Before they became widely available in the 1940s, a simple infected cut or a case of pneumonia could kill. Today, however, doctors warn that these drugs are gradually losing their effectiveness, a problem known as antibiotic resistance.\n\nResistance does not mean that the human body becomes resistant to the drugs. It is the bacteria that change. In any large population of bacteria, a few individuals may carry genetic changes that allow them to survive an antibiotic. When the drug kills the susceptible bacteria, these survivors multiply without competition and pass on their protection to their offspring. Bacteria can even share resistance genes with unrelated species, so the problem can spread quickly.\n\nSeveral human habits accelerate this process. Antibiotics only work against bacteria, yet they are frequently prescribed, or demanded by patients, for colds and influenza, which are caused by viruses. Patients who stop taking a course early because they feel better may leave the strongest bacteria alive. In some countries, antibiotics can be bought without a prescription, and they are also widely used in farming to prevent disease in animals. Each of these practices exposes bacteria to the drugs more often than necessary, giving resistant strains more chances to emerge.\n\nThe consequences are serious. Infections that were once easy to treat now require longer hospital stays, more expensive drugs and, in some cases, cannot be cured at all. Surgery, cancer treatment and care for premature babies all depend on effective antibiotics, so rising resistance threatens much of modern healthcare.\n\nThere is no single solution, but experts agree on several measures. Doctors should prescribe antibiotics only when they are truly needed, and patients should complete the full course exactly as instructed. Good hygiene and vaccination reduce the number of infections in the first place. Finally, governments must support research into new drugs, since few have been developed in recent decades. If these steps are taken together, the effectiveness of existing antibiotics may be preserved for future generations.", "gist": "Bài viết giải thích kháng kháng sinh xảy ra do vi khuẩn biến đổi, bị thúc đẩy bởi thói quen dùng thuốc sai, và nêu các biện pháp ngăn chặn.", "qs": [{"kind": "main", "q": "What is the main idea of the text?", "opts": ["Antibiotics are harmful to the human body", "Bacteria become resistant to antibiotics, partly because of human behaviour, which threatens healthcare", "Viruses cause more disease than bacteria", "New antibiotics are developed every year"], "a": 1, "ev": "doctors warn that these drugs are gradually losing their effectiveness, a problem known as antibiotic resistance", "why": "Bài mở đầu bằng cảnh báo thuốc đang mất tác dụng (\"antibiotic resistance\"), sau đó phân tích nguyên nhân, hậu quả và biện pháp."}, {"kind": "detail", "q": "According to the text, what actually changes in antibiotic resistance?", "opts": ["The human immune system", "The dose of the drug", "The patient's genes", "The bacteria"], "a": 3, "ev": "It is the bacteria that change.", "why": "Văn bản nhấn mạnh \"It is the bacteria that change.\""}, {"kind": "detail", "q": "Why are antibiotics not effective against colds and influenza?", "opts": ["They are too expensive", "They only work against bacteria", "They are taken too late", "They damage the lungs"], "a": 1, "ev": "Antibiotics only work against bacteria", "why": "Câu \"Antibiotics only work against bacteria\" giải thích vì sao không dùng cho bệnh do virus."}, {"kind": "detail", "q": "Which habit is described as helping resistant bacteria survive?", "opts": ["Washing hands too often", "Eating too much meat", "Stopping a course of treatment early", "Taking antibiotics with food"], "a": 2, "ev": "Patients who stop taking a course early because they feel better may leave the strongest bacteria alive.", "why": "Bệnh nhân ngừng thuốc sớm \"may leave the strongest bacteria alive\" nên vi khuẩn mạnh còn sống sót."}, {"kind": "vocab", "q": "In the text, what does 'susceptible' mean?", "opts": ["Easily affected", "Completely harmless", "Very large", "Unable to reproduce"], "a": 0, "ev": "When the drug kills the susceptible bacteria", "why": "\"Susceptible\" nghĩa là dễ bị ảnh hưởng; những vi khuẩn dễ bị thuốc giết khác với những vi khuẩn kháng thuốc sống sót."}, {"kind": "tfng", "q": "Bacteria can share resistance genes with different species.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "Bacteria can even share resistance genes with unrelated species", "why": "Câu \"Bacteria can even share resistance genes with unrelated species\" xác nhận điều này."}, {"kind": "tfng", "q": "The human body becomes resistant to antibiotics.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Resistance does not mean that the human body becomes resistant to the drugs.", "why": "Sai: văn bản phủ nhận \"Resistance does not mean that the human body becomes resistant to the drugs.\""}, {"kind": "tfng", "q": "Antibiotic resistance is more common in children than in adults.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản không so sánh trẻ em và người lớn nên là Not given."}, {"kind": "inference", "q": "Why does rising resistance threaten surgery and cancer treatment?", "opts": ["These treatments are cheaper than antibiotics", "These patients are vulnerable to infections that might no longer be treatable", "Surgeons refuse to operate on children", "Antibiotics are the main treatment for cancer"], "a": 1, "ev": "Surgery, cancer treatment and care for premature babies all depend on effective antibiotics", "why": "Vì các lĩnh vực này \"all depend on effective antibiotics\", nếu thuốc mất tác dụng thì nhiễm trùng ở bệnh nhân yếu sẽ khó điều trị."}], "notes": {"vocab": [["resistance", "sự kháng (thuốc)", "resist (v), resistant (adj)"], ["susceptible", "dễ bị ảnh hưởng, nhạy cảm", "susceptible to infection"], ["multiply", "nhân lên, sinh sôi", "multiplication (n)"], ["offspring", "thế hệ con, đời sau", "không đổi số nhiều"], ["accelerate", "đẩy nhanh", "acceleration (n)"], ["strains", "chủng (vi khuẩn)", "resistant strain"], ["emerge", "xuất hiện, nổi lên", "emergence (n)"], ["preserved", "được bảo tồn, giữ gìn", "preserve (v)"]], "grammar": [["Cleft sentence (câu chẻ)", "It is the bacteria that change.", "Cấu trúc It is ... that nhấn mạnh thành phần được đặt ở giữa (vi khuẩn chứ không phải cơ thể người)."], ["Defining relative clause (mệnh đề quan hệ xác định)", "Patients who stop taking a course early because they feel better may leave the strongest bacteria alive.", "\"who stop...\" xác định nhóm bệnh nhân cụ thể; không có dấu phẩy vì thông tin cần thiết."], ["Participle clause (mệnh đề phân từ)", "giving resistant strains more chances to emerge", "V-ing nối kết quả với mệnh đề trước, gọn hơn so với \"and this gives...\"."], ["Conditional with passive (điều kiện + bị động)", "If these steps are taken together, the effectiveness of existing antibiotics may be preserved for future generations.", "Điều kiện loại 1 dùng bị động ở cả hai vế để tập trung vào hành động và kết quả, không nói ai làm."]], "tips": ["Bài báo vấn đề - nguyên nhân - hậu quả - giải pháp: đoạn đầu nêu vấn đề, đoạn cuối thường chứa các biện pháp, giúp tìm ý chính nhanh.", "Với câu True/False, tìm câu có phủ định (does not mean, only) vì thường là chỗ bài kiểm tra bẫy."]}}, {"id": "rd5-b2-15", "lvl": "B2", "topic": "medical", "genre": "case", "title": "Case Report: Chest Pain on Climbing Stairs", "text": "Presentation\nMr Pham, a 58-year-old taxi driver, attended the outpatient clinic complaining of chest pain for three weeks.\n\nHistory\nThe pain was central, heavy and tight, and sometimes spread to his left arm. It appeared when he climbed stairs or walked quickly uphill and disappeared within five minutes of resting. He had not experienced pain at night. He smoked fifteen cigarettes a day, had been told by a previous doctor that his blood pressure was high, and had a father who died of a heart attack at 60. He denied shortness of breath, fainting or palpitations.\n\nExamination\nHe looked comfortable at rest. His pulse was 78 beats per minute and regular, and his blood pressure was 150/92 mmHg. Heart sounds were normal and his lungs were clear. There was no swelling of the legs, and the chest wall was not tender when pressed.\n\nInvestigations\nAn electrocardiogram (ECG) taken at rest was normal. Blood tests showed no sign of damage to the heart muscle, but his cholesterol was raised. Because his symptoms were typical, an exercise test was arranged, which showed changes in the ECG when he walked on a treadmill.\n\nDiagnosis\nThe doctors concluded that Mr Pham had angina. This occurs when the coronary arteries, which supply the heart muscle with blood, become narrowed, so that the heart does not receive enough oxygen during effort. Resting relieves the pain because the heart's demand falls.\n\nManagement\nMr Pham was advised to stop smoking, to eat less fat, and to exercise gradually. He was prescribed medication to ease the pain and to protect his arteries, and he was referred to a cardiologist for further tests. He was told to call an ambulance immediately if the pain ever lasted longer than fifteen minutes or occurred at rest.\n\nOutcome\nAt follow-up two months later, he had stopped smoking and his episodes of pain were less frequent.", "gist": "Ca lâm sàng về một người đàn ông 58 tuổi đau ngực khi gắng sức, được chẩn đoán đau thắt ngực và hướng dẫn xử trí.", "qs": [{"kind": "main", "q": "What is the case mainly about?", "opts": ["A man whose chest pain on effort is diagnosed as angina and managed", "A heart attack treated in the emergency room", "A lung infection in a taxi driver", "A child with a heart murmur"], "a": 0, "ev": "The doctors concluded that Mr Pham had angina.", "why": "Kết luận của ca bệnh: \"The doctors concluded that Mr Pham had angina.\" và phần xử trí đi kèm."}, {"kind": "detail", "q": "What brought on Mr Pham's pain?", "opts": ["Eating a large meal", "Lying down at night", "Driving for a long time", "Climbing stairs or walking quickly uphill"], "a": 3, "ev": "It appeared when he climbed stairs or walked quickly uphill", "why": "Câu \"It appeared when he climbed stairs or walked quickly uphill\" nêu yếu tố gây đau."}, {"kind": "detail", "q": "What did the exercise test show?", "opts": ["Normal ECG results throughout", "Changes in the ECG when he walked on a treadmill", "Damage to the lungs", "A very slow pulse"], "a": 1, "ev": "showed changes in the ECG when he walked on a treadmill", "why": "Kết quả: \"showed changes in the ECG when he walked on a treadmill\"."}, {"kind": "detail", "q": "What was noted about his family history?", "opts": ["His mother had diabetes", "His brother smoked", "His father died of a heart attack at 60", "There was no relevant history"], "a": 2, "ev": "had a father who died of a heart attack at 60", "why": "Tiền sử gia đình: \"a father who died of a heart attack at 60\"."}, {"kind": "vocab", "q": "In the text, what does 'relieves' mean?", "opts": ["Eases", "Causes", "Hides", "Measures"], "a": 0, "ev": "Resting relieves the pain because the heart's demand falls.", "why": "\"Relieves\" nghĩa là làm dịu bớt; nghỉ ngơi làm giảm đau vì tim cần ít oxy hơn."}, {"kind": "tfng", "q": "The ECG taken at rest was normal.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "An electrocardiogram (ECG) taken at rest was normal.", "why": "Câu \"An electrocardiogram (ECG) taken at rest was normal.\" khẳng định điều này."}, {"kind": "tfng", "q": "Mr Pham's pain continued for hours after he rested.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "disappeared within five minutes of resting", "why": "Sai: cơn đau \"disappeared within five minutes of resting\"."}, {"kind": "tfng", "q": "Mr Pham needed heart surgery.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản chỉ nói ông được chuyển đến bác sĩ tim mạch, không đề cập phẫu thuật nên là Not given."}, {"kind": "inference", "q": "What does the normal result for heart muscle damage in the blood tests suggest?", "opts": ["He has no heart problem at all", "He has probably not had a heart attack recently", "His cholesterol is normal", "He should stop exercising"], "a": 1, "ev": "Blood tests showed no sign of damage to the heart muscle", "why": "Vì \"no sign of damage to the heart muscle\", có thể suy ra ông chưa bị nhồi máu cơ tim gần đây, dù vẫn có đau thắt ngực."}], "notes": {"vocab": [["outpatient", "bệnh nhân ngoại trú", "inpatient (nội trú)"], ["palpitations", "hồi hộp, đánh trống ngực", "a sensation of the heart beating fast"], ["tender", "đau khi ấn, nhạy cảm", "tender to touch"], ["cholesterol", "cholesterol (mỡ máu)", "raised cholesterol"], ["coronary arteries", "động mạch vành", "supply blood to the heart"], ["narrowed", "bị hẹp lại", "narrow (v/adj)"], ["referred", "được chuyển (đến chuyên khoa)", "refer a patient to a specialist"], ["follow-up", "tái khám, theo dõi", "a follow-up visit"]], "grammar": [["Past perfect passive (quá khứ hoàn thành bị động)", "had been told by a previous doctor that his blood pressure was high", "had been + V3 nói về việc xảy ra trước thời điểm kể trong ca bệnh; dạng bị động vì người nhận thông tin là trọng tâm."], ["Non-defining relative clause (mệnh đề quan hệ không xác định)", "the coronary arteries, which supply the heart muscle with blood, become narrowed", "Mệnh đề giữa hai dấu phẩy bổ sung thông tin về chức năng của động mạch vành."], ["Purpose with so that (mục đích)", "so that the heart does not receive enough oxygen during effort", "\"so that\" nối kết quả hoặc mục đích; ở đây diễn tả hậu quả của việc động mạch bị hẹp."], ["Passive with reporting verbs (bị động: advise/prescribe)", "Mr Pham was advised to stop smoking, to eat less fat, and to exercise gradually.", "was advised + to V là bị động thường dùng trong ghi chép ca bệnh, giữ giọng khách quan."]], "tips": ["Ca bệnh có cấu trúc cố định (Presentation, History, Examination, Investigations, Diagnosis, Management, Outcome): hãy xác định đáp án nằm ở phần nào trước khi đọc kỹ.", "Chú ý phủ định trong History (had not experienced, denied) vì đó là thông tin loại trừ, hay được dùng làm câu hỏi True/False."]}}, {"id": "rd5-b2-16", "lvl": "B2", "topic": "medical", "genre": "interview", "title": "Beyond Massage: A Physiotherapist Explains Her Work", "text": "Interviewer: Today we are talking to Hana Beck, a physiotherapist who has worked in a city hospital for twelve years. Hana, what does a physiotherapist actually do?\nHana: Many people think we only give massages, but that is a myth. Our main aim is to help patients move better and live with less pain. We assess how a joint or muscle is working, and then we design an exercise programme that suits the person.\nInterviewer: Who usually comes to see you?\nHana: It is a mixed group. I treat footballers with knee injuries, but also elderly patients who have had a hip replacement, and office workers whose backs have been aching for months. Last week, I even met a man who had been unable to lift his arm since a stroke.\nInterviewer: What is the hardest part of the job?\nHana: Motivation, without a doubt. Exercises are often dull, and progress can be painfully slow. If patients were told that recovery takes only a week, they would be disappointed, so I try to be honest from the start. I explain that a torn ligament, for instance, may need several months to heal properly.\nInterviewer: How do you keep people motivated?\nHana: I set small goals. Instead of saying 'walk normally again', we aim to climb three stairs without a handrail. When a patient reaches that target, they see that the effort is worthwhile. I also ask them to keep a diary, which shows improvement more clearly than memory does.\nInterviewer: Is there anything you wish patients did differently?\nHana: Yes. Many people stop doing their exercises as soon as the pain disappears. That is a mistake, because the muscles around the joint are still weak, and the injury can easily return. I also wish people would seek help earlier. A problem that is treated in the first weeks is usually far easier to fix.\nInterviewer: Finally, what advice would you give to someone who sits at a desk all day?\nHana: Stand up and walk around every thirty minutes, and stretch your neck and shoulders. It sounds simple, yet it prevents a surprising number of problems.", "gist": "Một nhà vật lý trị liệu giải thích công việc của mình, những khó khăn trong việc giữ động lực cho bệnh nhân và lời khuyên cho dân văn phòng.", "qs": [{"kind": "main", "q": "What is the main purpose of the interview?", "opts": ["To advertise exercise machines to hospital patients", "To describe what a physiotherapist does and the challenges of treatment", "To compare physiotherapy with surgery", "To explain how to become a physiotherapist"], "a": 1, "ev": "Our main aim is to help patients move better and live with less pain.", "why": "Hana mô tả công việc ('help patients move better...') và các thách thức như động lực, nên đáp án B."}, {"kind": "detail", "q": "According to Hana, what is the hardest part of her job?", "opts": ["Treating elderly patients", "Writing reports", "Keeping patients motivated", "Learning new techniques"], "a": 2, "ev": "Motivation, without a doubt.", "why": "Hana nói rõ: 'Motivation, without a doubt.' là phần khó nhất."}, {"kind": "detail", "q": "How does a diary help patients?", "opts": ["It shows improvement more clearly than memory", "It replaces the need for exercises", "It lets the doctor read their feelings", "It reduces pain directly"], "a": 0, "ev": "which shows improvement more clearly than memory does", "why": "Câu 'which shows improvement more clearly than memory does' cho biết nhật ký thể hiện tiến bộ rõ hơn trí nhớ."}, {"kind": "detail", "q": "Why is it a mistake to stop exercising when the pain disappears?", "opts": ["The doctor will be angry", "The pain always returns the next day", "Exercises are free of charge", "The muscles around the joint are still weak"], "a": 3, "ev": "the muscles around the joint are still weak", "why": "Hana nói 'the muscles around the joint are still weak' nên chấn thương dễ tái phát."}, {"kind": "vocab", "q": "In the text, what does 'worthwhile' mean?", "opts": ["Very expensive", "Useful enough to justify the effort", "Easy to complete", "Difficult to measure"], "a": 1, "ev": "the effort is worthwhile", "why": "Bệnh nhân thấy mục tiêu đạt được nên thấy 'the effort is worthwhile' - đáng công sức bỏ ra."}, {"kind": "tfng", "q": "Hana has worked in a hospital for twelve years.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "has worked in a city hospital for twelve years", "why": "Người dẫn nói Hana 'has worked in a city hospital for twelve years'."}, {"kind": "tfng", "q": "Hana says that physiotherapists mainly give massages.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Many people think we only give massages, but that is a myth.", "why": "Hana gọi quan niệm đó là 'a myth' (hiểu lầm), nên câu sai."}, {"kind": "tfng", "q": "Hana's patients pay for their sessions themselves.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không đề cập ai trả tiền cho các buổi trị liệu."}, {"kind": "inference", "q": "Which statement would Hana most probably agree with?", "opts": ["Patients should be told that recovery is always quick", "Pain is the best guide to when exercises can stop", "Honest information about recovery time prevents disappointment", "Small goals are less useful than long ones"], "a": 2, "ev": "so I try to be honest from the start", "why": "Hana nói bệnh nhân sẽ thất vọng nếu nghe hồi phục chỉ một tuần, nên 'I try to be honest from the start'."}], "notes": {"vocab": [["myth", "quan niệm sai lầm", "a common myth; không phải 'sự thật'"], ["assess", "đánh giá (tình trạng)", "assess - assessment"], ["programme", "chương trình (luyện tập)", "Anh-Mỹ: program"], ["ligament", "dây chằng", "torn ligament: rách dây chằng"], ["motivation", "động lực", "motivate - motivated - motivation"], ["handrail", "tay vịn cầu thang", ""], ["worthwhile", "đáng công sức", "worth + V-ing / worthwhile"]], "grammar": [["Second conditional + passive (câu điều kiện loại 2, bị động)", "If patients were told that recovery takes only a week, they would be disappointed", "If + quá khứ (bị động 'were told'), would + V: nói về tình huống giả định, không có thật."], ["Present perfect + relative clause (hiện tại hoàn thành, mệnh đề quan hệ)", "a physiotherapist who has worked in a city hospital for twelve years", "'has worked ... for twelve years' nói về việc kéo dài đến hiện tại; 'who' bổ nghĩa cho 'physiotherapist'."], ["Wish + would (ước muốn)", "I also wish people would seek help earlier.", "'wish + would' diễn tả mong người khác thay đổi hành vi, thường kèm chút phàn nàn."], ["Past perfect (quá khứ hoàn thành)", "a man who had been unable to lift his arm since a stroke", "'had been' nhấn mạnh tình trạng đã xảy ra trước thời điểm gặp trong quá khứ."]], "tips": ["Trong bài phỏng vấn, đọc câu hỏi của người dẫn trước để đoán chủ đề từng đoạn trả lời; ý chính nằm ở câu đầu của mỗi lời đáp.", "Chú ý các từ nhấn mạnh như 'without a doubt', 'a mistake' vì chúng thường là đáp án cho câu hỏi chi tiết."]}}, {"id": "rd5-b2-17", "lvl": "B2", "topic": "medical", "genre": "article", "title": "Thin Air: How the Lungs and Blood Adjust to Altitude", "text": "Every time we breathe in, air travels through the nose and mouth, down the trachea, and into two bronchi that divide into thousands of smaller tubes. At the end of the smallest tubes lie the alveoli, tiny air sacs wrapped in a net of capillaries. Here, oxygen passes into the blood, while carbon dioxide moves in the opposite direction and is breathed out. An adult's lungs contain several hundred million alveoli, which together offer a surface area roughly the size of a tennis court.\n\nThe percentage of oxygen in the air is about 21 per cent at every height. What changes with altitude is the air pressure. At the top of a high mountain, the pressure is much lower, so each breath delivers fewer oxygen molecules to the alveoli than the same breath would at sea level. Consequently, the body receives less oxygen even though the lungs work as usual.\n\nClimbers who rise too quickly may suffer from altitude sickness, whose symptoms include headache, nausea and unusual tiredness. In serious cases, fluid collects in the lungs or the brain, which is a medical emergency.\n\nFortunately, the body can adapt, although this takes time. Within minutes, breathing becomes faster and deeper, and the heart beats more quickly to move blood around. Over several days, the kidneys signal the bone marrow to produce more red blood cells, which carry oxygen. After a few weeks, the blood can carry more oxygen, and the tissues extract it more efficiently. People who have lived in the Andes or the Himalayas for generations often show further adaptations, such as a larger chest.\n\nBecause of this process, doctors advise mountaineers to ascend gradually and to rest for a day after every large gain in height. Drinking enough water and avoiding alcohol also help. Anyone whose symptoms get worse should descend immediately, as going down is the most effective treatment.", "gist": "Bài viết giải thích cấu tạo hô hấp và cách cơ thể thích nghi với không khí loãng ở độ cao.", "qs": [{"kind": "main", "q": "What is the main idea of the article?", "opts": ["Mountain climbing is too dangerous for most people", "Air contains less oxygen on high mountains", "The respiratory system works the same at all heights", "The lungs and blood adapt to lower oxygen pressure at altitude"], "a": 3, "ev": "What changes with altitude is the air pressure.", "why": "Bài mô tả phổi và cách cơ thể thích nghi khi áp suất giảm ở độ cao."}, {"kind": "detail", "q": "What happens in the alveoli?", "opts": ["Air is warmed and cleaned", "Oxygen enters the blood and carbon dioxide leaves it", "Blood cells are produced", "Air is divided into two bronchi"], "a": 1, "ev": "oxygen passes into the blood, while carbon dioxide moves in the opposite direction", "why": "Bài nói oxy đi vào máu còn carbon dioxide đi theo chiều ngược lại."}, {"kind": "detail", "q": "Why do climbers receive less oxygen at the top of a high mountain?", "opts": ["The air has a lower percentage of oxygen", "The lungs stop working normally", "The air pressure is much lower", "The heart beats too slowly"], "a": 2, "ev": "the pressure is much lower", "why": "Tỉ lệ oxy không đổi; 'the pressure is much lower' nên mỗi hơi thở chứa ít phân tử oxy hơn."}, {"kind": "detail", "q": "What do the kidneys signal the bone marrow to do?", "opts": ["Produce more red blood cells", "Make the blood thinner", "Slow down the heart", "Create more alveoli"], "a": 0, "ev": "produce more red blood cells", "why": "Thận báo cho tủy xương 'produce more red blood cells'."}, {"kind": "vocab", "q": "In the text, what does 'consequently' mean?", "opts": ["Fortunately", "However", "As a result", "In contrast"], "a": 2, "ev": "Consequently, the body receives less oxygen", "why": "'Consequently' chỉ kết quả của áp suất thấp: cơ thể nhận ít oxy hơn, tức 'as a result'."}, {"kind": "tfng", "q": "The percentage of oxygen in the air is about 21 per cent at every height.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "about 21 per cent at every height", "why": "Câu này trích gần nguyên văn từ bài."}, {"kind": "tfng", "q": "At altitude, breathing becomes slower within minutes.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "breathing becomes faster and deeper", "why": "Bài nói hô hấp trở nên 'faster and deeper', không phải chậm hơn."}, {"kind": "tfng", "q": "Altitude sickness is more common in men than in women.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không so sánh nam và nữ."}, {"kind": "inference", "q": "Why do doctors advise mountaineers to ascend gradually?", "opts": ["Because the body needs time to adapt", "Because climbing slowly burns more energy", "Because the air is warmer at lower heights", "Because red blood cells die at high altitude"], "a": 0, "ev": "Fortunately, the body can adapt, although this takes time.", "why": "Sự thích nghi cần thời gian ('this takes time'), nên leo từ từ giúp cơ thể kịp thích nghi."}], "notes": {"vocab": [["alveoli", "phế nang", "số ít: alveolus"], ["capillaries", "mao mạch", ""], ["bone marrow", "tủy xương", ""], ["adapt", "thích nghi", "adapt to - adaptation"], ["efficiently", "một cách hiệu quả", "efficient - efficiency"], ["gradually", "dần dần", "gradual - gradually"], ["nausea", "buồn nôn", ""], ["ascend", "đi lên, leo lên", "trái nghĩa: descend"]], "grammar": [["Non-defining relative clause (mệnh đề quan hệ không xác định)", "which together offer a surface area roughly the size of a tennis court", "Mệnh đề 'which' thêm thông tin về 'alveoli', ngăn bằng dấu phẩy."], ["Comparison with ellipsis (so sánh rút gọn)", "so each breath delivers fewer oxygen molecules to the alveoli than the same breath would at sea level", "'than ... would' rút gọn động từ lặp lại; so sánh cùng một hơi thở ở hai điều kiện."], ["Whose in relative clause (whose chỉ sở hữu)", "whose symptoms include headache, nausea and unusual tiredness", "'whose' thay cho 'altitude sickness's' để nối thêm thông tin."], ["Advise + object + to-infinitive", "doctors advise mountaineers to ascend gradually", "Cấu trúc 'advise somebody to do something' dùng để đưa lời khuyên."]], "tips": ["Bài báo khoa học thường có đoạn đầu giải thích cơ chế, đoạn sau nêu vấn đề và giải pháp; xác định chức năng từng đoạn để tìm ý chính.", "Gặp từ nối như 'Consequently', 'Fortunately', 'Because of this', hãy dùng chúng để thấy quan hệ nguyên nhân - kết quả."]}}, {"id": "rd5-b2-18", "lvl": "B2", "topic": "medical", "genre": "leaflet", "title": "Reading Your Blood Report: A Patient Guide", "text": "Understanding Your Blood Test Results\nA guide for patients\n\nWhy have I had a blood test?\nBlood tests help your doctor to check your general health, to find the cause of symptoms, and to see whether a treatment is working. A small sample is taken from a vein in your arm, usually in less than five minutes, and it is then sent to a laboratory.\n\nWhat do the numbers mean?\nYour report lists each test, your result, and a 'reference range'. The reference range shows the values that are typical for most healthy adults. Ranges can differ slightly between laboratories, so always compare your result with the range printed on your own report.\n\nWhat is measured most often?\n- Haemoglobin: the protein in red blood cells that carries oxygen. A low level may suggest anaemia, which can make you feel tired and pale.\n- White blood cells: these fight infection. A raised count is often seen when the body is dealing with an infection, although it can have other causes.\n- Platelets: small cell fragments that help the blood to clot after an injury.\n- Glucose: the sugar in your blood, which gives your body energy. Your doctor may use it to check for diabetes.\n- Cholesterol: a fatty substance. Too much of it can raise the risk of heart disease over time.\n\nDoes an abnormal result mean I am ill?\nNot necessarily. Many things can move a result outside the reference range, including a recent illness, not drinking enough water, or having eaten before a test that requires fasting. For this reason, a single result is rarely used alone; doctors look at the overall pattern and, if necessary, repeat the test.\n\nWhat should I do next?\n- Do not try to diagnose yourself using the internet.\n- Write down your questions before your appointment.\n- Ask your doctor to explain any result you do not understand.\n- Tell the doctor about all the medicines and supplements you take, as these may affect results.\n\nRemember: your results belong to you, and you have the right to ask for a copy.", "gist": "Tờ rơi giúp bệnh nhân hiểu kết quả xét nghiệm máu, các chỉ số thường gặp và việc nên làm tiếp theo.", "qs": [{"kind": "main", "q": "What is the main purpose of this leaflet?", "opts": ["To help patients understand blood test results and what to do next", "To teach nurses how to take blood", "To advertise a private laboratory", "To explain how to treat diabetes"], "a": 0, "ev": "Blood tests help your doctor to check your general health", "why": "Tờ rơi giải thích mục đích xét nghiệm, các chỉ số và bước tiếp theo cho bệnh nhân."}, {"kind": "detail", "q": "How long does taking the blood sample usually take?", "opts": ["About an hour", "Less than five minutes", "Around fifteen minutes", "One whole day"], "a": 1, "ev": "usually in less than five minutes", "why": "Bài ghi 'usually in less than five minutes'."}, {"kind": "detail", "q": "What is the function of haemoglobin?", "opts": ["It fights infection", "It helps blood to clot", "It carries oxygen in red blood cells", "It gives the body sugar"], "a": 2, "ev": "the protein in red blood cells that carries oxygen", "why": "Haemoglobin là 'the protein in red blood cells that carries oxygen'."}, {"kind": "detail", "q": "Why is a single result rarely used alone?", "opts": ["Laboratories are not reliable", "Doctors look at the overall pattern", "Patients prefer a second opinion", "Reports are always printed twice"], "a": 1, "ev": "doctors look at the overall pattern", "why": "Bác sĩ xem 'the overall pattern' và có thể làm lại xét nghiệm."}, {"kind": "vocab", "q": "In the text, what does 'clot' mean?", "opts": ["Become thick and solid to stop bleeding", "Become red and warm", "Move quickly through a vein", "Break into smaller parts"], "a": 0, "ev": "help the blood to clot after an injury", "why": "Tiểu cầu giúp máu đông lại sau chấn thương, tức 'clot'."}, {"kind": "tfng", "q": "Reference ranges can differ slightly between laboratories.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "Ranges can differ slightly between laboratories", "why": "Câu này gần như nguyên văn trong bài."}, {"kind": "tfng", "q": "A raised white blood cell count always means an infection.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "although it can have other causes", "why": "Bài nói tăng bạch cầu 'can have other causes', nên không phải luôn là nhiễm trùng."}, {"kind": "tfng", "q": "Blood tests must always be done in the morning.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói về thời điểm lấy máu trong ngày."}, {"kind": "inference", "q": "What should a patient do after finding one result slightly outside the range?", "opts": ["Stop taking all medicines", "Look up the cause on the internet", "Ignore the result completely", "Stay calm and ask the doctor to explain it"], "a": 3, "ev": "a single result is rarely used alone", "why": "Một kết quả đơn lẻ ít khi đủ kết luận, và bài khuyên hỏi bác sĩ giải thích, nên cần bình tĩnh."}], "notes": {"vocab": [["reference range", "khoảng tham chiếu", "giá trị bình thường của xét nghiệm"], ["haemoglobin", "huyết sắc tố", "Anh-Mỹ: hemoglobin"], ["anaemia", "thiếu máu", "Anh-Mỹ: anemia"], ["platelets", "tiểu cầu", ""], ["clot", "đông lại (máu)", "blood clot: cục máu đông"], ["fasting", "nhịn ăn (trước xét nghiệm)", "fast - fasting"], ["supplements", "thực phẩm bổ sung", "dietary supplements"], ["abnormal", "bất thường", "trái nghĩa: normal"]], "grammar": [["Passive voice (câu bị động)", "A small sample is taken from a vein in your arm", "Dùng bị động vì quan trọng là hành động và mẫu máu, không cần nói ai lấy."], ["Gerund list after 'including' (liệt kê danh động từ)", "including a recent illness, not drinking enough water, or having eaten before a test that requires fasting", "Sau 'including' có thể liệt kê danh từ và V-ing (kể cả dạng phủ định, hoàn thành)."], ["Imperative + contact relative clause (mệnh lệnh, mệnh đề quan hệ rút gọn)", "Ask your doctor to explain any result you do not understand.", "Câu mệnh lệnh phù hợp với tờ rơi; 'any result you do not understand' lược bỏ 'that'."], ["Quantifier + modal (từ chỉ lượng + động từ khuyết thiếu)", "Too much of it can raise the risk of heart disease over time.", "'Too much of it' làm chủ ngữ; 'can' nói về khả năng, không chắc chắn."]], "tips": ["Tờ rơi chia thành các tiêu đề dạng câu hỏi; đọc tiêu đề trước để tìm nhanh thông tin cần.", "Danh sách gạch đầu dòng thường giải thích từng thuật ngữ sau dấu hai chấm; câu hỏi từ vựng hay lấy từ những phần này."]}}, {"id": "rd5-c1-01", "lvl": "C1", "topic": "society", "genre": "article", "title": "Who Answers for the Algorithm?", "text": "Few developments in public administration have been welcomed with as much enthusiasm, and scrutinised with as much suspicion, as the delegation of consequential decisions to algorithms. Proponents argue that automated systems, unlike weary human officials, apply the same criteria to every case, thereby eliminating the capriciousness that has long afflicted hiring, lending and sentencing. Sceptics counter that such consistency is hardly a virtue when the underlying criteria are flawed.\n\nThe difficulty lies partly in the data. A model trained on historical records inevitably absorbs the prejudices embedded in them. If a bank has, for decades, refused loans to residents of certain neighbourhoods, an algorithm instructed to predict creditworthiness from past outcomes will learn to treat those postcodes as a proxy for risk, and it will do so without any malicious intent. The resulting discrimination is no less real for being unintended; indeed, it is arguably harder to challenge, since no individual can be held to account for it.\n\nOpacity compounds the problem. Many contemporary systems, particularly those built on deep learning, arrive at conclusions through calculations so intricate that even their designers cannot fully reconstruct the reasoning. A citizen denied a housing benefit may therefore receive a verdict but no explanation, leaving her unable to correct an error or to appeal meaningfully. Legal scholars have begun to argue that a genuine right to contest a decision presupposes a right to understand it.\n\nDefenders of automation rightly note that human judgement is hardly transparent either. Judges are swayed by fatigue and hunger; recruiters favour candidates who resemble themselves. The relevant question, they insist, is not whether algorithms are perfect but whether they outperform the alternative. Yet this framing can be misleading. A biased person affects dozens of cases; a biased system, replicated across a national agency, can affect millions before anyone notices the pattern.\n\nSeveral remedies have been proposed. Regular audits by independent bodies could detect disparities in outcomes between groups. Developers might be required to publish plain-language descriptions of what their systems do and what they cannot do. Crucially, many ethicists maintain that decisions with profound consequences for a person's liberty or livelihood should never be fully automated; a human reviewer, empowered to overrule the machine, ought to remain in the loop. Whether such oversight is meaningful, however, depends on whether reviewers feel able to disagree with a system that is presented as objective.\n\nUltimately, the ethics of algorithmic decision-making cannot be reduced to a technical problem awaiting a technical solution. Choices about which errors are tolerable, and who should bear them, are political and moral judgements, and they deserve public debate rather than quiet delegation to engineers.", "gist": "Bài báo bàn về những vấn đề đạo đức khi giao quyết định quan trọng cho thuật toán và cho rằng cần giám sát của con người cùng tranh luận công khai.", "qs": [{"kind": "main", "q": "Which statement best summarises the author's position?", "opts": ["Algorithms should be abandoned because human officials are always more accurate.", "Automated decisions raise ethical problems that call for human oversight and public debate, not merely technical fixes.", "Bias in algorithms is a minor flaw that audits have already solved.", "Consistency is the only quality that matters in public decision-making."], "a": 1, "ev": "cannot be reduced to a technical problem awaiting a technical solution", "why": "Kết luận của tác giả là đạo đức thuật toán \"cannot be reduced to a technical problem awaiting a technical solution\", nên cần giám sát và tranh luận công khai; đáp án B."}, {"kind": "detail", "q": "According to the text, why might a loan algorithm discriminate against some neighbourhoods?", "opts": ["Its designers deliberately programmed it to exclude them.", "It cannot read postcodes accurately.", "It learns from past outcomes to treat certain postcodes as an indicator of risk.", "It is only used by banks with a history of fairness."], "a": 2, "ev": "will learn to treat those postcodes as a proxy for risk", "why": "Thuật toán học từ dữ liệu quá khứ nên \"will learn to treat those postcodes as a proxy for risk\"; không phải do cố ý."}, {"kind": "detail", "q": "What problem does opacity cause for a citizen refused a housing benefit?", "opts": ["She may get a decision without any explanation, so she cannot properly appeal.", "She is told the algorithm's source code is illegal.", "She must wait for a human judge to be hired.", "She is automatically given a second benefit."], "a": 0, "ev": "may therefore receive a verdict but no explanation", "why": "Văn bản nói người dân \"may therefore receive a verdict but no explanation\", nên không thể sửa lỗi hay kháng nghị hiệu quả."}, {"kind": "vocab", "q": "In the text, what does \"capriciousness\" mean?", "opts": ["Careful planning", "Unpredictable, inconsistent behaviour", "Strict obedience to rules", "Excessive generosity"], "a": 1, "ev": "eliminating the capriciousness that has long afflicted hiring, lending and sentencing", "why": "\"Capriciousness\" là sự thất thường, thiếu nhất quán; thuật toán được cho là loại bỏ nó nhờ áp dụng cùng tiêu chí cho mọi trường hợp."}, {"kind": "tfng", "q": "An algorithm can produce discriminatory results even when nobody intends it to.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "and it will do so without any malicious intent", "why": "Đoạn 2 nói thuật toán học định kiến \"without any malicious intent\", tức là không cần ý đồ xấu; câu đúng."}, {"kind": "tfng", "q": "The author claims that a biased human decision-maker can harm as many people as a biased national system.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "A biased person affects dozens of cases; a biased system, replicated across a national agency, can affect millions", "why": "Người thiên vị chỉ ảnh hưởng \"dozens of cases\", còn hệ thống thì có thể ảnh hưởng \"millions\"; câu sai."}, {"kind": "tfng", "q": "Most public agencies already use independent audits to check their algorithms.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Văn bản chỉ nói kiểm toán độc lập \"could\" phát hiện chênh lệch, không nói cơ quan nào đã áp dụng; thông tin không được đề cập."}, {"kind": "detail", "q": "Which measure does the text suggest for making systems easier to understand?", "opts": ["Banning deep learning entirely", "Publishing plain-language descriptions of what the systems can and cannot do", "Replacing all designers with legal scholars", "Hiding the calculations from the public"], "a": 3, "ev": "publish plain-language descriptions of what their systems do and what they cannot do", "why": "Biện pháp được nêu là \"publish plain-language descriptions\" về chức năng và giới hạn của hệ thống."}, {"kind": "inference", "q": "Why does the author doubt that a human reviewer is a complete safeguard?", "opts": ["Reviewers are usually paid less than engineers.", "Reviewers may hesitate to challenge a system that is portrayed as objective.", "Reviewers are not allowed to overrule the machine.", "Reviewers always agree with the public."], "a": 1, "ev": "depends on whether reviewers feel able to disagree with a system that is presented as objective", "why": "Hiệu quả của giám sát phụ thuộc vào việc người duyệt có dám phản đối hệ thống được trình bày là khách quan hay không; đây là suy luận."}, {"kind": "inference", "q": "What does the final paragraph imply about deciding which errors a system may make?", "opts": ["It is a value-laden question that should not be left to technicians alone.", "It is purely a matter of mathematics.", "It has already been settled by legal scholars.", "It is irrelevant to public administration."], "a": 0, "ev": "are political and moral judgements, and they deserve public debate rather than quiet delegation to engineers", "why": "Tác giả coi việc chọn lỗi nào chấp nhận được là phán đoán chính trị và đạo đức, nên không thể giao riêng cho kỹ sư."}], "notes": {"vocab": [["capriciousness", "tính thất thường, thiếu nhất quán", "tính từ: capricious"], ["scrutinised", "bị xem xét kỹ lưỡng", "danh từ: scrutiny"], ["proxy", "chỉ báo thay thế, đại diện", "a proxy for + N"], ["opacity", "sự thiếu minh bạch, khó hiểu", "trái nghĩa: transparency"], ["presupposes", "giả định trước, đòi hỏi trước", "presuppose + N/that"], ["compounds", "làm trầm trọng thêm", "compound the problem"], ["replicated", "bị nhân rộng, lặp lại", "replicate = sao chép"], ["audits", "các cuộc kiểm toán, rà soát", "audit + N"]], "grammar": [["Comparative correlative with 'as much ... as' (so sánh đồng mức)", "Few developments in public administration have been welcomed with as much enthusiasm, and scrutinised with as much suspicion, as the delegation of consequential decisions to algorithms", "Cấu trúc as much ... as so sánh hai mức độ; mệnh đề chủ ngữ \"Few developments\" mang nghĩa phủ định nhẹ, nhấn mạnh sự việc này gây cả hứng khởi lẫn nghi ngờ."], ["Past participle clause (mệnh đề quá khứ phân từ)", "A model trained on historical records inevitably absorbs the prejudices embedded in them", "\"trained on...\" và \"embedded in them\" là cụm quá khứ phân từ rút gọn mệnh đề quan hệ bị động, giúp câu gọn và trang trọng."], ["no less ... for being + adj (không kém... dù là)", "The resulting discrimination is no less real for being unintended", "Cấu trúc no less + adj + for + V-ing nghĩa là \"không kém phần... dù cho...\", dùng để nhượng bộ trong văn học thuật."], ["Participle phrase as apposition (cụm phân từ bổ nghĩa)", "a human reviewer, empowered to overrule the machine, ought to remain in the loop", "Cụm \"empowered to overrule the machine\" nằm giữa hai dấu phẩy, bổ sung thông tin về chủ ngữ; \"ought to\" diễn đạt điều nên làm."]], "tips": ["Bài luận lập luận thường có cấu trúc: nêu vấn đề, phản biện, giải pháp, kết luận; hãy đọc câu đầu và đoạn cuối để nắm ý chính.", "Chú ý các từ chỉ đối lập như 'Yet', 'however', 'Sceptics counter' để biết tác giả đang chuyển sang quan điểm nào."]}}, {"id": "rd5-c1-02", "lvl": "C1", "topic": "science", "genre": "article", "title": "Trusting the Crowd with the Field Notebook", "text": "When thousands of volunteers armed with smartphones set out to count birds, photograph insects or measure rainfall, the scale of the data they generate is something no university laboratory could hope to match. Citizen science, as this practice is known, has transformed fields from ornithology to astronomy, and its influence on environmental policy continues to grow. Yet its very breadth provokes a persistent question: can observations gathered by amateurs be trusted?\n\nThe scepticism is not groundless. Volunteers differ enormously in expertise, and a novice may misidentify a common species as a rare one, or vice versa. Moreover, participants tend to record what is convenient rather than what is representative. Birdwatchers cluster near roads and car parks, and they report spectacular sightings more eagerly than mundane ones. A dataset assembled this way may reveal as much about human behaviour as about the creatures being observed.\n\nResearchers have nevertheless devised ingenious safeguards. One approach is redundancy: if a photograph of a moth is classified independently by several volunteers, the consensus tends to be remarkably reliable, often rivalling that of a single expert. Another is calibration. Projects may begin by asking newcomers to identify specimens whose true identity is already known, and weight their later contributions according to their accuracy. Statistical models can also correct for uneven effort, adjusting for the fact that some regions are visited far more frequently than others.\n\nTechnology has further narrowed the gap. Image-recognition software now flags implausible entries, such as a tropical bird reported in an Arctic village, and prompts the volunteer to supply a photograph. Such automated checks do not replace human scrutiny, but they allow experts to concentrate on the ambiguous cases rather than wade through thousands of routine ones.\n\nInterestingly, the benefits of participation extend beyond the data. Volunteers who contribute regularly often develop a keener appreciation of local ecosystems, and some go on to advocate for conservation in their communities. Several coordinators concede, however, that this educational mission can pull against scientific rigour. Rigorous training protocols deter casual participants, whereas an open invitation attracts enthusiasm at the expense of precision. Striking the balance is as much a matter of institutional philosophy as of statistics.\n\nThe emerging consensus, then, is neither naive celebration nor blanket dismissal. Volunteer-collected data are best regarded as a powerful but imperfect instrument, whose limitations must be characterised honestly and corrected where possible. Used with that humility, they have already revealed shifts in migration, flowering times and insect decline that formal surveys, constrained by budgets, would almost certainly have missed.", "gist": "Bài báo xem xét độ tin cậy của dữ liệu do tình nguyện viên thu thập trong khoa học công dân và các cách khắc phục hạn chế.", "qs": [{"kind": "main", "q": "What is the main point of the article?", "opts": ["Amateur observations are worthless and should be ignored.", "Citizen science is only useful for teaching volunteers.", "Professional surveys will soon be abandoned.", "Volunteer data have weaknesses, but with safeguards they are a valuable if imperfect tool."], "a": 3, "ev": "Volunteer-collected data are best regarded as a powerful but imperfect instrument", "why": "Kết luận của bài: dữ liệu tình nguyện là \"a powerful but imperfect instrument\", cần sửa sai chứ không bác bỏ hay tin tuyệt đối."}, {"kind": "detail", "q": "Why might a dataset reveal as much about human behaviour as about animals?", "opts": ["Volunteers often cluster where it is easy to observe and prefer to report striking sightings.", "Volunteers are trained to avoid roads.", "Animals refuse to appear near people.", "Software changes the species names."], "a": 0, "ev": "Birdwatchers cluster near roads and car parks", "why": "Người quan sát tập trung gần đường và bãi đỗ xe (\"cluster near roads and car parks\") nên dữ liệu phản ánh hành vi con người."}, {"kind": "detail", "q": "What does the text say about redundancy?", "opts": ["It makes experts unnecessary.", "It lets one volunteer classify the same photo many times.", "Several volunteers classifying the same photo independently can give a very reliable result.", "It only works for astronomical data."], "a": 2, "ev": "classified independently by several volunteers, the consensus tends to be remarkably reliable", "why": "Nhiều người phân loại độc lập thì \"the consensus tends to be remarkably reliable\"; đó là ý của redundancy."}, {"kind": "detail", "q": "What do image-recognition programs do in citizen science projects?", "opts": ["They pay volunteers for each photograph.", "They identify every species without human help.", "They flag unlikely records and ask for a photo as proof.", "They remove all rare species from the database."], "a": 2, "ev": "flags implausible entries", "why": "Phần mềm nhận dạng ảnh \"flags implausible entries\" và yêu cầu ảnh, để chuyên gia tập trung vào ca khó."}, {"kind": "vocab", "q": "In the text, what does \"mundane\" mean?", "opts": ["Dangerous", "Ordinary and unexciting", "Expensive", "Mysterious"], "a": 1, "ev": "report spectacular sightings more eagerly than mundane ones", "why": "\"Mundane\" đối lập với \"spectacular\", nghĩa là bình thường, không có gì nổi bật."}, {"kind": "tfng", "q": "Newcomers' later contributions may be given weight according to how accurate they were on specimens with known identities.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "weight their later contributions according to their accuracy", "why": "Văn bản nói dự án \"weight their later contributions according to their accuracy\"; câu đúng."}, {"kind": "tfng", "q": "The author states that automated checks make expert review unnecessary.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Such automated checks do not replace human scrutiny", "why": "Tác giả viết \"do not replace human scrutiny\", tức là kiểm tra tự động không thay thế chuyên gia; câu sai."}, {"kind": "tfng", "q": "Most citizen science volunteers hold a university degree.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không đề cập trình độ học vấn của tình nguyện viên, chỉ nói họ khác nhau về chuyên môn; không có thông tin."}, {"kind": "inference", "q": "What can be inferred from coordinators' admission that education \"can pull against scientific rigour\"?", "opts": ["Open participation may lower precision, while strict training may discourage people from joining.", "Education always improves data quality.", "Coordinators dislike teaching volunteers.", "Rigorous training attracts more casual participants."], "a": 0, "ev": "this educational mission can pull against scientific rigour", "why": "Bài nêu rằng đào tạo nghiêm ngặt \"deter casual participants\" còn mời mở thì mất độ chính xác, nên có sự đánh đổi giữa hai mục tiêu."}, {"kind": "inference", "q": "The final sentence suggests that formal surveys:", "opts": ["are more accurate than all volunteer data.", "may be limited in coverage because of funding.", "cannot detect changes in insect numbers.", "were designed by volunteers."], "a": 1, "ev": "constrained by budgets, would almost certainly have missed", "why": "Khảo sát chính thức \"constrained by budgets\" nên có thể bỏ sót các xu hướng mà dữ liệu tình nguyện phát hiện được."}], "notes": {"vocab": [["groundless", "vô căn cứ", "ground = cơ sở"], ["novice", "người mới vào nghề", "trái nghĩa: expert"], ["mundane", "tầm thường, bình thường", "trái nghĩa: spectacular"], ["redundancy", "sự dư thừa có chủ ý (nhiều lần kiểm tra)", "nghĩa khác: sự sa thải"], ["calibration", "sự hiệu chỉnh", "calibrate (v)"], ["implausible", "khó tin, không hợp lý", "trái nghĩa: plausible"], ["rigour", "sự nghiêm ngặt, chặt chẽ", "tính từ: rigorous"], ["constrained", "bị hạn chế", "constrain by + N"]], "grammar": [["Passive reduced clause (mệnh đề bị động rút gọn)", "A dataset assembled this way may reveal as much about human behaviour as about the creatures being observed", "\"assembled this way\" và \"being observed\" là cụm phân từ bổ nghĩa danh từ; \"as much ... as\" so sánh hai khía cạnh."], ["Colon introducing an explanation (dấu hai chấm giải thích)", "One approach is redundancy: if a photograph of a moth is classified independently by several volunteers, the consensus tends to be remarkably reliable", "Dấu hai chấm giới thiệu phần giải thích cụ thể cho \"redundancy\", kèm câu điều kiện thực tế \"if + present passive\"."], ["Perfect infinitive-like contrast with 'whereas' (liên từ đối lập)", "Rigorous training protocols deter casual participants, whereas an open invitation attracts enthusiasm at the expense of precision", "\"whereas\" nối hai vế tương phản; \"at the expense of\" nghĩa là hy sinh cái gì để đạt cái khác."], ["Non-defining relative with possessive 'whose' (mệnh đề quan hệ với whose)", "whose limitations must be characterised honestly and corrected where possible", "\"whose\" chỉ sở hữu của \"instrument\"; \"must be characterised\" là bị động với động từ khuyết thiếu chỉ sự cần thiết."]], "tips": ["Bài báo khoa học phổ thông thường nêu vấn đề ở đoạn 1, phản biện ở đoạn 2, rồi giải pháp; hãy tìm các từ chuyển như 'Yet', 'nevertheless'.", "Khi gặp câu hỏi suy luận, hãy xác định đoạn liên quan rồi diễn đạt lại ý bằng từ khác thay vì tìm từ trùng khớp."]}}, {"id": "rd5-c1-03", "lvl": "C1", "topic": "culture", "genre": "article", "title": "The Curated Past", "text": "Nostalgia was once classified as a medical affliction. In the seventeenth century, a Swiss physician coined the term to describe the debilitating homesickness of mercenaries serving far from their mountain villages, attributing it, rather implausibly, to damage in the brain caused by the incessant clanging of cowbells. Today the word has shed its clinical overtones and denotes a gentle, bittersweet longing for the past, yet the question of what it is and whether it is good for us remains unsettled.\n\nPsychologists who study the phenomenon have complicated the old assumption that nostalgia is a form of escapism. Experiments suggest that recalling cherished episodes tends to bolster a person's sense of continuity, the feeling that one's life is a coherent story rather than a series of disconnected events. Participants induced to feel nostalgic often report greater optimism and stronger ties to others, perhaps because the memories that surface most readily are those involving friends, family and shared rituals.\n\nMemory itself, however, is a treacherous foundation. Far from replaying events like a recording, the brain reconstructs them each time they are recalled, and in doing so it inevitably edits. Unpleasant details fade, ambiguous moments are tidied into satisfying narratives, and the emotional tone is frequently adjusted to match the person's present mood. Nostalgia is therefore less an archive than an act of curation, in which the past is arranged to flatter the present self, or to console it.\n\nThis curatorial quality explains why nostalgia can be exploited. Advertisers have long understood that a jingle from childhood or a reissued toy can bypass sceptical judgement and induce warm feelings towards a product. Politicians, too, invoke a golden age, promising to restore a mythical era of stability and respect, though the era in question may never have existed in the form they describe. Those who yearn for it are seldom recalling the whole of it; they are recalling a selection of its pleasures, stripped of the hardships that the same period imposed on many.\n\nNone of this renders nostalgia illegitimate. Provided it is held lightly, it can sustain people through upheaval, whether a bereavement, a migration or a career change, by reminding them that they have survived discontinuity before. The danger arises when longing hardens into grievance, when the past becomes a standard against which every present is condemned. Scholars therefore distinguish between a reflective variety, which acknowledges that what is lost cannot return and savours it nonetheless, and a restorative variety, which insists that the lost world can and should be rebuilt.\n\nPerhaps the healthiest stance lies between the two: to cherish memories without mistaking them for blueprints.", "gist": "Bài báo phân tích hoài niệm: từ một căn bệnh thời xưa đến lợi ích tâm lý, tính chọn lọc của ký ức và nguy cơ bị lợi dụng.", "qs": [{"kind": "main", "q": "What is the article mainly about?", "opts": ["How to cure homesickness in soldiers", "Why advertisers should stop using old jingles", "Nostalgia as a double-edged experience shaped by selective memory", "The history of Swiss medicine"], "a": 2, "ev": "Nostalgia is therefore less an archive than an act of curation", "why": "Bài bàn về hoài niệm vừa có lợi vừa có hại, do ký ức bị chọn lọc (\"less an archive than an act of curation\")."}, {"kind": "detail", "q": "What did the seventeenth-century physician blame for nostalgia?", "opts": ["Damage to the brain from the constant noise of cowbells", "A lack of mountain air", "Stress caused by mercenary pay", "Too many bittersweet songs"], "a": 0, "ev": "attributing it, rather implausibly, to damage in the brain caused by the incessant clanging of cowbells", "why": "Bác sĩ cho rằng nguyên nhân là tổn thương não do tiếng chuông bò liên tục (\"incessant clanging of cowbells\")."}, {"kind": "detail", "q": "What effect do experiments suggest nostalgic recollection has?", "opts": ["It weakens relationships.", "It makes people forget their past.", "It reduces optimism.", "It strengthens the sense that one's life is a continuous story."], "a": 3, "ev": "bolster a person's sense of continuity", "why": "Các thí nghiệm cho thấy hồi tưởng \"bolster a person's sense of continuity\", tức củng cố cảm giác liền mạch của cuộc đời."}, {"kind": "detail", "q": "How does a reflective form of nostalgia differ from a restorative one?", "opts": ["It wants to rebuild the lost world.", "It accepts that the lost past cannot return yet still enjoys it.", "It is only felt by scholars.", "It rejects all memories."], "a": 1, "ev": "which acknowledges that what is lost cannot return and savours it nonetheless", "why": "Loại reflective \"acknowledges that what is lost cannot return\" nhưng vẫn trân trọng, còn restorative muốn xây lại quá khứ."}, {"kind": "vocab", "q": "In the text, what does \"treacherous\" mean in the phrase \"a treacherous foundation\"?", "opts": ["Unreliable and potentially misleading", "Extremely old", "Emotionally warm", "Easy to measure"], "a": 0, "ev": "Memory itself, however, is a treacherous foundation", "why": "\"Treacherous\" ở đây là không đáng tin, dễ gây lầm lạc, vì sau đó bài nói não \"reconstructs\" và chỉnh sửa ký ức."}, {"kind": "tfng", "q": "The brain reconstructs a memory each time it is recalled.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "the brain reconstructs them each time they are recalled", "why": "Bài nói rõ não \"reconstructs them each time they are recalled\"; câu đúng."}, {"kind": "tfng", "q": "The text states that psychologists have confirmed nostalgia is merely a form of escapism.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "have complicated the old assumption that nostalgia is a form of escapism", "why": "Các nhà tâm lý học \"have complicated the old assumption\", tức làm phức tạp chứ không xác nhận giả định đó; câu sai."}, {"kind": "tfng", "q": "Older people feel nostalgia more intensely than younger people do.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không so sánh mức độ hoài niệm giữa người già và người trẻ; không có thông tin."}, {"kind": "inference", "q": "What does the author imply about politicians who invoke a golden age?", "opts": ["They are always historians.", "They may be presenting a selective and idealised version of the past.", "They have personally lived in that era.", "They never use advertising techniques."], "a": 1, "ev": "the era in question may never have existed in the form they describe", "why": "Tác giả gợi ý thời hoàng kim có thể \"never have existed in the form they describe\" và bị lược bỏ khó khăn, tức là hình ảnh lý tưởng hóa."}, {"kind": "inference", "q": "What does the last sentence suggest about how memories should be treated?", "opts": ["They should be erased.", "They should be trusted as exact records.", "They should be used as accurate plans for the future.", "They can be valued without being treated as models to reproduce."], "a": 3, "ev": "to cherish memories without mistaking them for blueprints", "why": "Câu cuối khuyên trân trọng ký ức nhưng không coi chúng là \"blueprints\" (bản thiết kế) để dựng lại."}], "notes": {"vocab": [["debilitating", "làm suy nhược", "debilitate (v)"], ["incessant", "không ngừng, liên miên", "đồng nghĩa: constant"], ["bolster", "củng cố, tăng cường", "bolster confidence"], ["treacherous", "không đáng tin, nguy hiểm", "trái nghĩa: reliable"], ["curation", "sự chọn lọc và sắp xếp", "curate (v), curator"], ["yearn", "khao khát, mong mỏi", "yearn for + N"], ["grievance", "nỗi bất bình, oán giận", "nurse a grievance"], ["savours", "thưởng thức, trân trọng", "savour the moment"]], "grammar": [["Participial phrase (cụm phân từ)", "attributing it, rather implausibly, to damage in the brain caused by the incessant clanging of cowbells", "Cụm V-ing \"attributing...\" bổ sung hành động đi kèm \"coined the term\"; \"caused by\" là phân từ quá khứ rút gọn mệnh đề quan hệ."], ["Contrast pattern 'less ... than' (ít... hơn là)", "Nostalgia is therefore less an archive than an act of curation", "\"less A than B\" nghĩa là bản chất gần B hơn A; cách nói nhấn mạnh quan điểm của tác giả."], ["Participle clause with 'Provided' (liên từ điều kiện)", "Provided it is held lightly, it can sustain people through upheaval", "\"Provided (that)\" tương đương \"if\" nhưng nhấn mạnh điều kiện bắt buộc; \"is held\" là thể bị động."], ["Cleft-like emphasis with 'seldom' (phó từ phủ định)", "Those who yearn for it are seldom recalling the whole of it", "\"seldom\" là phó từ tần suất mang nghĩa phủ định, đứng giữa trợ động từ và động từ chính; cho thấy hoài niệm thường mang tính chọn lọc."]], "tips": ["Bài luận văn hóa thường đi từ định nghĩa, sang tranh luận, rồi đánh giá; hãy theo dõi từ nối như 'however', 'therefore', 'None of this'.", "Với câu hỏi suy luận, hãy đọc kỹ giọng điệu của tác giả: các từ như 'mythical', 'flatter' cho biết thái độ phê phán nhẹ."]}}, {"id": "rd5-c1-04", "lvl": "C1", "topic": "work", "genre": "report", "title": "Report on the Hybrid Productivity Paradox", "text": "Executive summary\n\nThis report examines why many organisations that adopted hybrid working report high individual output yet disappointing collective performance. Drawing on a survey of 1,200 employees across eleven mid-sized firms, together with interviews with twenty-six managers, it identifies a productivity paradox: people feel more productive at home, but the benefits fail to materialise at team and company level.\n\nFindings\n\nRespondents overwhelmingly reported that uninterrupted days at home allow them to complete demanding tasks more swiftly. Two thirds estimated that their output of focused work had risen since the introduction of hybrid arrangements. Managers, however, were considerably less sanguine. Only a minority believed that projects were being delivered faster, and many observed that decisions now take longer because the relevant people are rarely present at once.\n\nCloser analysis suggests that the discrepancy stems from the nature of the tasks involved. Individual tasks such as drafting, coding or analysis benefit from solitude, and respondents were generally candid about this advantage. Collaborative work, by contrast, depends on informal exchanges that are difficult to replicate remotely: the overheard remark, the spontaneous question at a colleague's desk, the quick clarification that prevents a week of wasted effort. When employees are scheduled in the office on different days, these exchanges are not merely reduced but, in some teams, effectively eliminated.\n\nA further finding concerns coordination costs. Respondents reported attending more scheduled meetings than before, partly to compensate for the loss of casual contact. Several interviewees described a perverse cycle in which time saved on commuting was consumed by video calls that existed only to synchronise colleagues who no longer shared a space.\n\nDiscussion\n\nIt would be misleading to conclude that hybrid working is inherently inefficient. The firms that fared best had not simply allowed staff to choose their days; they had synchronised attendance so that teams overlapped in the office, reserving those days for collaboration and leaving solitary work for home. Conversely, firms that imposed arbitrary attendance quotas, irrespective of the work being done, reported the lowest satisfaction among both staff and managers. Mentoring also emerged as a casualty of these arrangements, and several managers admitted that they had not anticipated the problem: junior employees, who acquire tacit knowledge largely through observation, felt notably less supported.\n\nRecommendations\n\nOrganisations should therefore review their hybrid policies at regular intervals. In particular, they should align in-office days within teams, designate meeting-free periods to protect concentration, and evaluate performance by outcomes rather than visible presence. Should they fail to address coordination costs, the gains in individual focus are likely to be squandered.", "gist": "Báo cáo giải thích nghịch lý năng suất ở văn phòng kết hợp: cá nhân làm việc hiệu quả hơn nhưng phối hợp nhóm lại kém, kèm khuyến nghị.", "qs": [{"kind": "main", "q": "What is the central finding of the report?", "opts": ["Hybrid working has made every employee less productive.", "Individuals feel more productive, but team-level performance has not improved correspondingly.", "Managers prefer remote work to office work.", "Commuting is the only cause of low output."], "a": 1, "ev": "people feel more productive at home, but the benefits fail to materialise at team and company level", "why": "Nghịch lý là cá nhân cảm thấy hiệu quả hơn nhưng lợi ích không thể hiện ở cấp nhóm và công ty."}, {"kind": "detail", "q": "How many managers were interviewed?", "opts": ["Eleven", "Twelve hundred", "Twenty-six", "Two thirds"], "a": 2, "ev": "interviews with twenty-six managers", "why": "Báo cáo nêu rõ \"interviews with twenty-six managers\"; 1,200 là số nhân viên và eleven là số công ty."}, {"kind": "detail", "q": "According to the managers, why do decisions take longer now?", "opts": ["The relevant people are seldom in the same place at the same time.", "Employees refuse to attend meetings.", "Managers have less authority.", "Video calls are banned."], "a": 0, "ev": "because the relevant people are rarely present at once", "why": "Quản lý cho rằng quyết định chậm hơn \"because the relevant people are rarely present at once\"."}, {"kind": "detail", "q": "What did the best-performing firms do?", "opts": ["They allowed staff to pick any days they wished.", "They abolished meetings.", "They banned working from home.", "They synchronised attendance so teams were in the office together."], "a": 3, "ev": "they had synchronised attendance so that teams overlapped in the office", "why": "Các công ty tốt nhất \"had synchronised attendance\", để nhóm cùng có mặt khi cần cộng tác."}, {"kind": "vocab", "q": "In the report, what does \"sanguine\" mean?", "opts": ["Angry", "Confused", "Optimistic", "Indifferent"], "a": 2, "ev": "Managers, however, were considerably less sanguine.", "why": "\"Less sanguine\" nghĩa là ít lạc quan hơn, phù hợp với việc chỉ \"a minority\" quản lý tin dự án nhanh hơn."}, {"kind": "tfng", "q": "Respondents said they attended more scheduled meetings partly to make up for less casual contact.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "attending more scheduled meetings than before, partly to compensate for the loss of casual contact", "why": "Báo cáo ghi người trả lời dự nhiều cuộc họp hơn, \"partly to compensate for the loss of casual contact\"; câu đúng."}, {"kind": "tfng", "q": "The report concludes that hybrid working is inherently inefficient.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "It would be misleading to conclude that hybrid working is inherently inefficient.", "why": "Báo cáo nói kết luận như vậy là \"misleading\", nên câu này sai."}, {"kind": "tfng", "q": "Employees at the largest firms reported lower productivity than those at smaller firms.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Báo cáo chỉ khảo sát các công ty cỡ vừa và không so sánh theo quy mô; không có thông tin."}, {"kind": "inference", "q": "What does the report imply about junior employees?", "opts": ["They lose out on learning that happens by watching colleagues.", "They are less skilled than managers at remote work.", "They prefer meeting-free periods.", "They caused the coordination problems."], "a": 0, "ev": "junior employees, who acquire tacit knowledge largely through observation, felt notably less supported", "why": "Nhân viên mới học kiến thức ngầm chủ yếu qua quan sát, nên khi ít gặp trực tiếp họ thấy được hỗ trợ ít hơn."}, {"kind": "inference", "q": "What is implied by the \"perverse cycle\" described by interviewees?", "opts": ["Commuting time is always wasted.", "Video calls are the best way to save time.", "Employees enjoy synchronising with colleagues.", "Time gained from not commuting can be cancelled out by extra coordination meetings."], "a": 3, "ev": "time saved on commuting was consumed by video calls", "why": "Thời gian tiết kiệm do không đi lại \"was consumed by video calls\", tức lợi ích bị triệt tiêu bởi các cuộc họp phối hợp."}], "notes": {"vocab": [["paradox", "nghịch lý", "tính từ: paradoxical"], ["materialise", "trở thành hiện thực, xuất hiện", "fail to materialise"], ["sanguine", "lạc quan", "less sanguine = bớt lạc quan"], ["discrepancy", "sự chênh lệch, không nhất quán", "discrepancy between A and B"], ["perverse", "trớ trêu, ngược với mong đợi", "a perverse cycle"], ["synchronised", "được đồng bộ hóa", "synchronise (v)"], ["tacit", "ngầm, không nói ra", "tacit knowledge"], ["squandered", "bị lãng phí", "squander + N"]], "grammar": [["Dummy 'it' with infinitive (chủ ngữ giả 'it')", "It would be misleading to conclude that hybrid working is inherently inefficient", "Dùng it làm chủ ngữ giả, mệnh đề \"to conclude...\" là chủ ngữ thật; \"would\" làm lời nhận định thận trọng."], ["Inverted conditional with 'Should' (câu điều kiện đảo ngữ)", "Should they fail to address coordination costs, the gains in individual focus are likely to be squandered", "Đảo \"Should + chủ ngữ\" thay cho \"If they should fail\", mang sắc thái trang trọng, thường gặp trong báo cáo và khuyến nghị."], ["Not merely ... but (cặp liên từ nhấn mạnh)", "these exchanges are not merely reduced but, in some teams, effectively eliminated", "Cấu trúc not merely A but B nhấn mạnh B mạnh hơn A; cụm chèn \"in some teams\" làm rõ phạm vi."], ["Past perfect for earlier action (quá khứ hoàn thành)", "they had synchronised attendance so that teams overlapped in the office", "Quá khứ hoàn thành \"had synchronised\" chỉ việc xảy ra trước kết quả \"fared best\"; \"so that\" chỉ mục đích."]], "tips": ["Báo cáo có các tiêu đề rõ ràng (Executive summary, Findings, Discussion, Recommendations); hãy đọc phần tóm tắt đầu tiên để nắm ý chính trước.", "Chú ý các từ so sánh như 'however', 'by contrast', 'conversely' để xác định hai nhóm quan điểm hoặc số liệu đối lập."]}}, {"id": "rd5-c1-05", "lvl": "C1", "topic": "environment", "genre": "article", "title": "Wolves, Willows and the Limits of Letting Go", "text": "Few conservation ideas have divided opinion as sharply as rewilding. Its advocates, who tend to speak with evangelical conviction, argue that the most effective way to restore damaged ecosystems is to step back: remove fences, reintroduce lost species, and let natural processes resume. Its critics, by contrast, regard the approach as romantic at best and reckless at worst.\n\nThe case for rewilding rests largely on the concept of trophic cascades. When wolves returned to one North American park in the 1990s, so the story goes, elk began to avoid open valleys, willows and aspens recovered along the riverbanks, beavers returned, and the rivers themselves changed course. Whether the wolves deserve all of the credit remains contested, since later studies suggest that other factors, including climate and hunting policy, played a part. Nonetheless, the narrative has proved remarkably persuasive, and it has inspired projects from the Scottish Highlands to the Carpathian Mountains.\n\nOpponents raise objections that are not easily dismissed. Farmers in upland regions point out that those who bear the costs of rewilding, namely the loss of grazing land and livestock to predators, are seldom those who enjoy its benefits. Some ecologists, meanwhile, question the very notion of a baseline to which an ecosystem can be returned. Landscapes that look wild, they note, have often been shaped by centuries of human management, so restoring \"nature\" frequently means choosing which historical period to treat as authentic. A further worry is that enthusiasm for dramatic predators diverts scarce funding from humbler, less photogenic species whose survival is equally precarious. Even sympathetic observers admit that predator reintroductions can provoke fierce resentment in communities that were never consulted, and that such resentment may undermine the very projects it targets.\n\nYet the debate is rarely as binary as its loudest participants imply. Hardly had the first large-scale projects begun when practitioners started adopting more modest, hybrid approaches. In several European valleys, conservation groups now pay farmers to manage land less intensively rather than to abandon it altogether, an arrangement that preserves rural livelihoods while allowing hedgerows, wetlands, and woodland to expand. Early results suggest that insect and bird populations respond quickly, though it is too soon to judge whether these gains will endure.\n\nWhat the controversy ultimately exposes is a disagreement about values rather than facts. Should a landscape be judged by the diversity of life it supports, by the productivity it offers people, or by the degree to which it is free of human control? Science can measure outcomes, but it cannot settle which of these goals deserves priority. Were the debate conducted with that recognition, it might generate rather less heat and considerably more cooperation.", "gist": "Bài báo phân tích cuộc tranh luận về tái hoang dã hóa, cho thấy đó chủ yếu là bất đồng về giá trị chứ không chỉ về dữ kiện khoa học.", "qs": [{"kind": "main", "q": "What is the main point of the article?", "opts": ["Rewilding has been proved to fail in most European countries.", "Wolves are the only species capable of restoring damaged ecosystems.", "The rewilding debate reflects differing values as much as scientific facts, and compromise approaches are emerging.", "Farmers should be banned from managing upland landscapes."], "a": 2, "ev": "What the controversy ultimately exposes is a disagreement about values rather than facts.", "why": "Câu kết luận nêu rõ cuộc tranh cãi là bất đồng về giá trị chứ không phải dữ kiện: \"What the controversy ultimately exposes is a disagreement about values rather than facts.\""}, {"kind": "detail", "q": "According to the article, what happened after wolves returned to the North American park?", "opts": ["Elk avoided open valleys and plants recovered beside the rivers.", "Elk numbers rose sharply because hunting stopped.", "Beavers left the area and the rivers dried up.", "Farmers moved their livestock into the valleys."], "a": 0, "ev": "elk began to avoid open valleys, willows and aspens recovered along the riverbanks", "why": "Bài kể rằng nai sừng tấm tránh các thung lũng trống và cây liễu, cây dương phục hồi ven sông: \"elk began to avoid open valleys, willows and aspens recovered along the riverbanks\"."}, {"kind": "detail", "q": "Why do upland farmers object to rewilding?", "opts": ["They believe predators are harmless to livestock.", "They think rewilding projects are too expensive for governments.", "They dislike photogenic species.", "They bear the costs while others enjoy the benefits."], "a": 3, "ev": "those who bear the costs of rewilding, namely the loss of grazing land and livestock to predators, are seldom those who enjoy its benefits", "why": "Nông dân chịu mất đất chăn thả và gia súc nhưng ít được hưởng lợi: \"those who bear the costs of rewilding ... are seldom those who enjoy its benefits\"."}, {"kind": "vocab", "q": "In the text, what does \"contested\" mean in \"remains contested\"?", "opts": ["proved beyond doubt", "disputed", "ignored completely", "celebrated"], "a": 1, "ev": "Whether the wolves deserve all of the credit remains contested", "why": "Sau đó bài nêu các nghiên cứu cho rằng còn nhân tố khác, nên việc công lao thuộc về sói vẫn bị tranh cãi (disputed)."}, {"kind": "vocab", "q": "In the text, what does \"precarious\" mean in \"equally precarious\"?", "opts": ["well protected", "widely admired", "uncertain and under threat", "easy to photograph"], "a": 2, "ev": "whose survival is equally precarious", "why": "Các loài ít được chú ý có sự tồn tại mong manh, đang bị đe dọa: \"whose survival is equally precarious\"."}, {"kind": "tfng", "q": "Later studies have confirmed that wolves alone caused the changes in the park.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "later studies suggest that other factors, including climate and hunting policy, played a part", "why": "Sai: các nghiên cứu sau cho thấy còn các yếu tố khác như khí hậu và chính sách săn bắn: \"other factors, including climate and hunting policy, played a part\"."}, {"kind": "tfng", "q": "Rewilding projects in the Scottish Highlands have increased tourism income.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài chỉ nói mô hình này đã truyền cảm hứng cho các dự án ở Cao nguyên Scotland, không đề cập thu nhập du lịch nên là Not given."}, {"kind": "tfng", "q": "Some ecologists doubt that there is one natural state to which an ecosystem can be restored.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "question the very notion of a baseline to which an ecosystem can be returned", "why": "Đúng: một số nhà sinh thái học nghi ngờ khái niệm \"baseline\" để đưa hệ sinh thái trở về: \"question the very notion of a baseline\"."}, {"kind": "inference", "q": "What can be inferred about the hybrid approaches described in the fourth paragraph?", "opts": ["They have already been shown to be a permanent success.", "They are opposed by all conservation groups.", "They eliminate the need for scientific research.", "They try to lessen conflict with rural communities."], "a": 3, "ev": "an arrangement that preserves rural livelihoods while allowing hedgerows, wetlands, and woodland to expand", "why": "Cách tiếp cận lai vừa giữ sinh kế nông thôn vừa mở rộng thiên nhiên, nên có thể suy ra nó giảm xung đột với cộng đồng nông thôn: \"preserves rural livelihoods\"."}, {"kind": "inference", "q": "What is the author's attitude towards the debate?", "opts": ["Strongly in favour of rewilding", "Balanced, and hopeful that recognising the real issue would improve cooperation", "Dismissive of both sides", "Convinced that science will soon settle it"], "a": 1, "ev": "Were the debate conducted with that recognition, it might generate rather less heat and considerably more cooperation.", "why": "Tác giả không bênh vực phe nào mà hy vọng nếu thừa nhận bản chất vấn đề thì sẽ bớt nóng và hợp tác hơn: \"rather less heat and considerably more cooperation\"."}], "notes": {"vocab": [["evangelical", "mang tính nhiệt thành như truyền đạo", "evangelical conviction = niềm tin cuồng nhiệt"], ["trophic cascades", "chuỗi tác động dây chuyền trong lưới thức ăn", "thuật ngữ sinh thái học"], ["contested", "bị tranh cãi", "a contested claim"], ["baseline", "mốc chuẩn ban đầu để so sánh", "dùng nhiều trong khoa học"], ["photogenic", "ăn ảnh, nổi bật trên hình ảnh", ""], ["precarious", "mong manh, bấp bênh", "a precarious existence"], ["livelihoods", "sinh kế", "earn a livelihood"], ["hybrid", "lai, kết hợp", "a hybrid approach"]], "grammar": [["Negative inversion with 'Hardly... when' (đảo ngữ)", "Hardly had the first large-scale projects begun when practitioners started adopting more modest, hybrid approaches.", "Hardly + had + chủ ngữ + V3 ... when diễn tả việc này vừa xảy ra thì việc kia xảy ra; đảo ngữ làm câu trang trọng, nhấn mạnh."], ["Inverted conditional with 'Were' (câu điều kiện đảo)", "Were the debate conducted with that recognition, it might generate rather less heat and considerably more cooperation.", "Were + chủ ngữ ... thay cho 'If the debate were conducted...'; dùng trong văn viết trang trọng để nói về tình huống giả định."], ["Cleft sentence with 'What' (câu chẻ)", "What the controversy ultimately exposes is a disagreement about values rather than facts.", "Cấu trúc What + mệnh đề + is ... dùng để nhấn mạnh thông tin quan trọng nhất ở cuối câu."]], "tips": ["Bài báo bàn luận thường nêu hai phe ở đầu, rồi dùng 'Yet' hoặc 'However' để chuyển sang quan điểm của tác giả; hãy đọc kỹ đoạn đầu và đoạn cuối để nắm ý chính.", "Chú ý các từ nhượng bộ như 'Nonetheless', 'meanwhile', 'Still' để nhận ra chỗ tác giả đổi hướng lập luận."]}}, {"id": "rd5-c1-06", "lvl": "C1", "topic": "education", "genre": "speech", "title": "Beyond the Certificate: What Universities Are For", "text": "Good evening, everyone, and thank you for that generous introduction. I should begin with a confession: when the organisers asked me to speak about the purpose of the university, my first instinct was to decline. It is, after all, a question that every generation of academics believes it has answered, and that every subsequent generation promptly reopens.\n\nLet me start with the answer you hear most often these days. A university, we are told, exists to prepare people for employment. I do not wish to sneer at this. Many of you are in debt, and you are entitled to expect that your degree will lead somewhere. But I want to suggest that if employability is the whole of our ambition, we have set our sights remarkably low. Employers' needs change faster than any syllabus can follow. The skills that are prized today may well be automated by the time you reach forty.\n\nWhat, then, endures? I would argue that it is the capacity to think carefully when thinking is hard. Consider what happens in a good seminar. Someone makes a claim, someone else challenges it, and a third person points out that both have misunderstood the question. Nobody leaves with a certificate for that. Yet it is precisely this habit of disciplined disagreement that a healthy society cannot do without.\n\nNow, I am not suggesting that universities should retreat into an ivory tower. Quite the opposite. Our research has eradicated diseases, and our graduates run hospitals, courts, and newspapers. The point is that these benefits arrive as by-products of a deeper commitment, namely the pursuit of understanding for its own sake. Those who demand that every project justify itself in advance forget that the most transformative discoveries were rarely planned. Few of the pioneers who studied the behaviour of light imagined that their curiosity would one day make surgery and global communication possible.\n\nI must also be honest about our failings. Too often we have behaved as though knowledge were a private possession to be guarded rather than a public good to be shared. Too often we have admitted students whose families already had every advantage and then congratulated ourselves on our excellence. A university that serves only the fortunate cannot claim to serve the truth, because truth does not recognise social class.\n\nSo here is my proposal. Let us stop asking whether a degree is worth the money, as though education were a product like any other, and ask instead what kind of people, and what kind of public, we hope to create. If we can answer that, the questions about funding, curricula, and technology will, I suspect, become easier to resolve.\n\nTo the students in this hall: be demanding of us. Insist on being challenged rather than merely entertained. And to my colleagues: let us deserve that demand. Thank you.", "gist": "Bài diễn văn lập luận rằng mục đích của đại học không chỉ là chuẩn bị việc làm mà còn là rèn tư duy nghiêm túc và phục vụ lợi ích chung.", "qs": [{"kind": "main", "q": "What is the speaker's central argument?", "opts": ["Universities should concentrate on preparing students for jobs.", "Universities should move away from research altogether.", "Degrees are no longer worth the money.", "Universities should aim to develop careful thinkers and serve the public, not just provide job training."], "a": 3, "ev": "what kind of people, and what kind of public, we hope to create", "why": "Diễn giả đề nghị hỏi đại học muốn tạo ra những con người và công chúng như thế nào, chứ không chỉ hỏi bằng cấp có đáng tiền: \"what kind of people, and what kind of public, we hope to create\"."}, {"kind": "detail", "q": "Why does the speaker consider employability alone a low ambition?", "opts": ["Because students are not in debt.", "Because employers no longer hire graduates.", "Because employers' needs change faster than any syllabus can follow.", "Because seminars are too difficult."], "a": 2, "ev": "Employers' needs change faster than any syllabus can follow.", "why": "Nhu cầu của nhà tuyển dụng thay đổi nhanh hơn giáo trình nên chỉ nhắm vào việc làm là tầm nhìn thấp: \"Employers' needs change faster than any syllabus can follow.\""}, {"kind": "detail", "q": "What happens in a good seminar, according to the speaker?", "opts": ["People challenge claims and even question the question itself.", "Students listen silently to a lecturer.", "Everyone agrees on a single answer.", "Participants receive a certificate."], "a": 0, "ev": "a third person points out that both have misunderstood the question", "why": "Trong buổi seminar tốt, người ta phản biện nhau và có người chỉ ra cả hai hiểu sai câu hỏi: \"a third person points out that both have misunderstood the question\"."}, {"kind": "detail", "q": "Which failing of universities does the speaker admit?", "opts": ["They have charged too little for degrees.", "They have taught too many practical skills.", "They have ignored the needs of employers.", "They have often admitted students who were already advantaged."], "a": 3, "ev": "admitted students whose families already had every advantage", "why": "Diễn giả thừa nhận đại học thường nhận sinh viên vốn đã có nhiều lợi thế: \"admitted students whose families already had every advantage\"."}, {"kind": "vocab", "q": "In the text, what does \"sneer at\" mean in \"I do not wish to sneer at this\"?", "opts": ["agree with", "show contempt for", "argue about", "write about"], "a": 1, "ev": "I do not wish to sneer at this.", "why": "Diễn giả nói không muốn chế giễu quan điểm đó và thừa nhận sinh viên có quyền mong có việc làm, nên sneer at = coi thường."}, {"kind": "vocab", "q": "In the text, what does \"by-products\" mean?", "opts": ["main goals", "expensive tools", "public speeches", "secondary results of something else"], "a": 3, "ev": "these benefits arrive as by-products of a deeper commitment", "why": "Lợi ích xuất hiện như hệ quả phụ của cam kết sâu hơn là theo đuổi hiểu biết: \"by-products of a deeper commitment\"."}, {"kind": "tfng", "q": "The speaker thinks students should not expect their degree to help them find work.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "you are entitled to expect that your degree will lead somewhere", "why": "Sai: diễn giả nói sinh viên có quyền mong bằng cấp dẫn đến một con đường nào đó: \"you are entitled to expect that your degree will lead somewhere\"."}, {"kind": "tfng", "q": "The speaker has worked as a university administrator.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói gì về nghề nghiệp trước đây của diễn giả, nên là Not given."}, {"kind": "tfng", "q": "The speaker believes the most transformative discoveries were seldom planned in advance.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "the most transformative discoveries were rarely planned", "why": "Đúng: \"the most transformative discoveries were rarely planned\" tức là hiếm khi được lên kế hoạch trước."}, {"kind": "inference", "q": "What does the speaker imply by saying that truth does not recognise social class?", "opts": ["Only wealthy students can understand the truth.", "Excluding disadvantaged people damages a university's claim to seek truth.", "Social class is irrelevant to university funding.", "Truth changes depending on who studies it."], "a": 1, "ev": "A university that serves only the fortunate cannot claim to serve the truth", "why": "Đại học chỉ phục vụ người may mắn thì không thể nói là phục vụ chân lý, hàm ý loại trừ người thiệt thòi làm tổn hại sứ mệnh đó."}], "notes": {"vocab": [["sneer at", "chế giễu, coi thường", "sneer at someone/something"], ["prized", "được đánh giá cao", "prized skills"], ["automated", "được tự động hóa", "automate (v), automation (n)"], ["ivory tower", "tháp ngà (xa rời thực tế)", "thành ngữ"], ["eradicated", "xóa sổ, diệt trừ hoàn toàn", "eradicate a disease"], ["transformative", "có sức làm thay đổi sâu sắc", "transform (v)"], ["by-products", "sản phẩm phụ, hệ quả phụ", ""], ["curricula", "các chương trình học (số nhiều của curriculum)", "số ít: curriculum"]], "grammar": [["'as though' + past subjunctive (giả định)", "Too often we have behaved as though knowledge were a private possession to be guarded rather than a public good to be shared.", "As though + were diễn tả cách cư xử như thể điều không có thật; 'were' dùng cho mọi ngôi trong văn trang trọng."], ["Mandative subjunctive (thức giả định sau 'demand')", "Those who demand that every project justify itself in advance forget that the most transformative discoveries were rarely planned.", "Sau demand that, động từ ở dạng nguyên mẫu (justify, không thêm -s) dù chủ ngữ là số ít."], ["Cleft sentence with 'it is... that' (câu chẻ)", "Yet it is precisely this habit of disciplined disagreement that a healthy society cannot do without.", "It is + thành phần nhấn mạnh + that ...; 'precisely' làm mạnh thêm, đặc trưng của diễn văn thuyết phục."]], "tips": ["Diễn văn thường có cấu trúc: mở đầu thân mật, nêu quan điểm phổ biến, phản bác bằng 'But', rồi đề xuất ở gần cuối; hãy tìm câu bắt đầu bằng 'So here is my proposal'.", "Chú ý các câu hỏi tu từ như 'What, then, endures?' vì câu trả lời ngay sau đó thường là luận điểm chính."]}}, {"id": "rd5-c1-07", "lvl": "C1", "topic": "technology", "genre": "review", "title": "The Hollow Glow: A Review of Marsh's Attention Exposé", "text": "In The Hollow Glow, the technology journalist Daniel Marsh sets out to explain how the contest for human attention has become the organising principle of the modern internet. His thesis is both simple and alarming: when a service costs nothing, it is the user's time that is being sold, and the companies concerned have every incentive to extract as much of it as possible. The book is at its strongest when it stays close to this argument, and rather weaker when it strays from it.\n\nMarsh's early chapters are the best. Drawing on interviews with former designers, he shows how features that seem trivial, such as infinite scrolling, autoplaying video, and the red notification badge, were refined through thousands of small experiments until they became difficult to resist. One engineer, speaking anonymously, describes the process with chilling candour: nobody in the room ever asked whether a feature was good for people, only whether it kept them there for another minute. The accumulation of such testimony is damning, and Marsh wisely lets his sources speak without embellishment.\n\nThe middle of the book is less convincing. Having established that the platforms are engineered to capture attention, Marsh proceeds to blame them for almost every social ailment of the past decade, from political polarisation to teenage anxiety. The evidence he marshals is mostly anecdotal, and he is dismissive of researchers who find the effects smaller or more uneven than he claims. A more cautious writer would have acknowledged that correlation does not establish causation, and that people existed in states of distraction long before smartphones. Marsh does gesture at these objections, but only in order to brush them aside.\n\nThe final chapters redeem some of this lost ground. Rather than calling for a wholesale rejection of technology, an impractical demand he rightly dismisses, Marsh proposes modest regulatory measures: limits on manipulative design, greater transparency about how recommendation systems work, and a right to use services without being tracked. These suggestions are not novel, and readers familiar with the policy debate will find little to surprise them. Still, they are presented with a pragmatism that the preceding chapters sometimes lack.\n\nStylistically, the book is lively, though occasionally given to hyperbole. Marsh has a gift for the telling image, yet he cannot resist a rhetorical flourish where a plain sentence would serve better. Anyone seeking a rigorous review of the scientific literature should look elsewhere. But as an accessible and often troubling account of how our habits are shaped by commercial design, The Hollow Glow deserves a wide readership, provided its more sweeping claims are read with a healthy measure of scepticism.", "gist": "Bài điểm sách đánh giá một cuốn sách về nền kinh tế chú ý: phần phóng sự rất thuyết phục nhưng phần quy kết nguyên nhân thì quá đà.", "qs": [{"kind": "main", "q": "What is the reviewer's overall judgement of the book?", "opts": ["It is entirely unreliable and should be ignored.", "It is a rigorous scientific study with no weaknesses.", "It is mainly a guide to deleting social media accounts.", "It is persuasive in its reporting but overreaches in places, though still worth reading."], "a": 3, "ev": "The book is at its strongest when it stays close to this argument, and rather weaker when it strays from it.", "why": "Người điểm sách nói sách mạnh khi bám luận điểm chính, yếu khi đi lạc, và cuối cùng vẫn đáng đọc với thái độ hoài nghi lành mạnh."}, {"kind": "detail", "q": "What did the anonymous engineer reveal about the design process?", "opts": ["The team focused on keeping users on the platform for longer.", "The team tested every feature on children.", "The team refused to release addictive features.", "The team asked users what they wanted."], "a": 0, "ev": "only whether it kept them there for another minute", "why": "Kỹ sư cho biết nhóm chỉ quan tâm liệu tính năng có giữ người dùng thêm một phút hay không: \"only whether it kept them there for another minute\"."}, {"kind": "detail", "q": "What is the reviewer's main criticism of the middle section?", "opts": ["It contains too many interviews.", "It is written in a dull style.", "It focuses too heavily on teenagers.", "Its evidence is largely anecdotal."], "a": 3, "ev": "The evidence he marshals is mostly anecdotal", "why": "Người điểm sách phê bình phần giữa vì bằng chứng chủ yếu là giai thoại: \"The evidence he marshals is mostly anecdotal\"."}, {"kind": "detail", "q": "Which of the following does Marsh propose?", "opts": ["A ban on smartphones", "Greater openness about how recommendation systems work", "Free internet access for everyone", "Higher taxes on all technology companies"], "a": 1, "ev": "greater transparency about how recommendation systems work", "why": "Marsh đề xuất tăng tính minh bạch về cách hệ thống gợi ý hoạt động: \"greater transparency about how recommendation systems work\"."}, {"kind": "vocab", "q": "In the text, what does \"candour\" mean in \"chilling candour\"?", "opts": ["secrecy", "humour", "honesty", "anger"], "a": 2, "ev": "describes the process with chilling candour", "why": "Kỹ sư kể thẳng thắn, không che giấu nên candour = sự thẳng thắn, trung thực."}, {"kind": "vocab", "q": "In the text, what does \"damning\" mean in \"is damning\"?", "opts": ["strongly suggesting guilt or fault", "boring and repetitive", "hard to believe", "pleasantly surprising"], "a": 0, "ev": "The accumulation of such testimony is damning", "why": "Nhiều lời chứng cộng lại là bằng chứng buộc tội mạnh mẽ đối với các công ty, nên damning = có tính buộc tội."}, {"kind": "tfng", "q": "Marsh argues that people should stop using technology entirely.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Rather than calling for a wholesale rejection of technology", "why": "Sai: Marsh không kêu gọi từ bỏ hoàn toàn công nghệ: \"Rather than calling for a wholesale rejection of technology\"."}, {"kind": "tfng", "q": "The Hollow Glow has sold more copies than Marsh's previous book.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không đề cập doanh số hay cuốn sách trước của Marsh, nên là Not given."}, {"kind": "tfng", "q": "The reviewer finds Marsh's writing occasionally exaggerated.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "occasionally given to hyperbole", "why": "Đúng: người điểm sách nói văn phong đôi khi hay phóng đại: \"occasionally given to hyperbole\"."}, {"kind": "inference", "q": "What can be inferred about who would benefit most from reading the book?", "opts": ["Scientists wanting detailed statistical analysis", "Policy experts already familiar with every proposal", "Engineers who designed the platforms", "General readers wanting an accessible introduction to the topic"], "a": 3, "ev": "Anyone seeking a rigorous review of the scientific literature should look elsewhere.", "why": "Người muốn tổng quan khoa học nghiêm ngặt nên tìm chỗ khác, còn sách là bản trình bày dễ tiếp cận, nên hợp với độc giả phổ thông."}], "notes": {"vocab": [["candour", "sự thẳng thắn", "candid (adj)"], ["embellishment", "sự thêm thắt, tô vẽ", "embellish (v)"], ["damning", "có tính buộc tội mạnh", "damning evidence"], ["anecdotal", "mang tính giai thoại, thiếu số liệu", "anecdotal evidence"], ["polarisation", "sự phân cực", "political polarisation"], ["marshals", "tập hợp, huy động (bằng chứng)", "marshal arguments/facts"], ["hyperbole", "sự cường điệu", "given to hyperbole"], ["pragmatism", "chủ nghĩa thực dụng, sự thực tế", "pragmatic (adj)"]], "grammar": [["Perfect participle clause (mệnh đề phân từ hoàn thành)", "Having established that the platforms are engineered to capture attention, Marsh proceeds to blame them for almost every social ailment of the past decade", "Having + V3 diễn tả hành động xong trước hành động ở mệnh đề chính, cùng chủ ngữ; giúp nối câu gọn trong văn viết học thuật."], ["Third conditional implied (would have + V3)", "A more cautious writer would have acknowledged that correlation does not establish causation", "Cấu trúc 'would have + V3' với chủ ngữ 'a more cautious writer' ngầm thay cho mệnh đề if, dùng để nói điều đáng lẽ nên làm trong quá khứ."], ["'Rather than' + -ing (thay vì)", "Rather than calling for a wholesale rejection of technology, an impractical demand he rightly dismisses, Marsh proposes modest regulatory measures", "Rather than + V-ing đối lập hai hành động; cụm 'an impractical demand...' là đồng vị ngữ giải thích thêm."]], "tips": ["Bài điểm sách thường đi theo trình tự: giới thiệu luận điểm, khen phần mạnh, chê phần yếu, rồi kết luận; hãy theo dõi các từ 'but', 'yet', 'still' để thấy lúc nào người viết đổi từ khen sang chê.", "Để nắm đánh giá chung, đọc câu đầu và câu cuối của đoạn cuối, nơi người điểm sách thường tóm tắt ý kiến."]}}, {"id": "rd5-c1-08", "lvl": "C1", "topic": "society", "genre": "interview", "title": "Income, Wealth and the Compounding Gap: An Economist Speaks", "text": "Host: Dr Lindqvist, inequality has become a fixture of political debate, yet people seem to mean quite different things by it. What exactly are we talking about?\nDr Lindqvist: You're quite right, and the confusion matters. There is inequality of income, which is what people earn in a year, and inequality of wealth, which is what they own. The second is far more concentrated than the first. In most rich countries, the richest tenth hold well over half of all wealth, whereas their share of income, while large, is considerably lower.\nHost: Why does that distinction matter?\nDr Lindqvist: Because wealth compounds. Someone who inherits property doesn't merely have a comfortable life; they have a base from which to take risks, start businesses, and weather setbacks. Had two equally talented people started out with different assets, we would expect their lives to diverge sharply, and the data confirm that. Education, health, even the neighbourhood you grow up in all tend to follow the same pattern, which is why the effects persist across generations.\nHost: Some argue that inequality is simply the price of a dynamic economy, that rewarding success encourages innovation. Do you accept that?\nDr Lindqvist: Partly. Incentives clearly matter, and I wouldn't defend a system in which effort goes entirely unrewarded. But the argument is often stretched beyond what the evidence supports. Countries with very similar levels of innovation display strikingly different degrees of inequality, which suggests that the relationship is far from automatic. Beyond a certain point, moreover, extreme disparities seem to erode trust and, with it, the willingness to cooperate that economies depend on.\nHost: What would you do about it, then?\nDr Lindqvist: I'd be wary of any single remedy. Taxing wealth sounds appealing, but it's notoriously hard to administer, because assets can be hidden or moved abroad. I'd put more emphasis on what economists call predistribution, that is, shaping the market so that fewer people end up in precarious positions to begin with: better early-years education, stronger bargaining rights for workers, and competition rules that prevent a handful of firms from dominating. Redistribution through taxes and benefits still has a role, but it's treating symptoms rather than causes.\nHost: Critics would say that's wishful thinking.\nDr Lindqvist: Some of it is hard, I concede. Politicians rarely win votes by promising results that arrive in twenty years. Still, I'd rather be accused of optimism than resign myself to the idea that nothing can be done. Societies have narrowed gaps before, and not by accident.\nHost: Dr Lindqvist, thank you.", "gist": "Cuộc phỏng vấn một nhà kinh tế về bất bình đẳng: phân biệt thu nhập và tài sản, bàn về đổi mới sáng tạo và các giải pháp nên kết hợp nhiều biện pháp.", "qs": [{"kind": "main", "q": "What is the main message of Dr Lindqvist's answers?", "opts": ["Inequality is harmless and should be left alone.", "Wealth taxes will solve inequality quickly.", "Inequality has several dimensions and needs several complementary responses rather than one remedy.", "Innovation always requires extreme inequality."], "a": 2, "ev": "I'd be wary of any single remedy.", "why": "Bà cảnh giác với bất kỳ giải pháp đơn lẻ nào và đưa ra nhiều biện pháp bổ trợ nhau: \"I'd be wary of any single remedy.\""}, {"kind": "detail", "q": "How does Dr Lindqvist distinguish income from wealth?", "opts": ["Income is what people earn in a year, while wealth is what they own.", "Income is what people own, while wealth is what they spend.", "Income is taxed, while wealth is not.", "Income is shared equally, while wealth is not."], "a": 0, "ev": "inequality of wealth, which is what they own", "why": "Bà định nghĩa thu nhập là số tiền kiếm được trong năm còn tài sản là thứ người ta sở hữu: \"inequality of wealth, which is what they own\"."}, {"kind": "detail", "q": "Why does Dr Lindqvist say taxing wealth is difficult?", "opts": ["Because people dislike paying taxes.", "Because it would harm innovation.", "Because wealthy people are too few.", "Because assets can be hidden or moved abroad."], "a": 3, "ev": "because assets can be hidden or moved abroad", "why": "Thuế tài sản khó quản lý vì tài sản có thể bị giấu hoặc chuyển ra nước ngoài: \"because assets can be hidden or moved abroad\"."}, {"kind": "detail", "q": "What evidence does she give against the claim that inequality drives innovation?", "opts": ["Innovative countries always have equal incomes.", "Countries with similar innovation can have very different inequality.", "Innovation has fallen in rich countries.", "Inventors rarely earn high incomes."], "a": 1, "ev": "Countries with very similar levels of innovation display strikingly different degrees of inequality", "why": "Các nước có mức đổi mới tương tự lại có bất bình đẳng rất khác nhau, nên mối liên hệ không tự động: \"strikingly different degrees of inequality\"."}, {"kind": "vocab", "q": "In the text, what does \"compounds\" mean in \"wealth compounds\"?", "opts": ["disappears quickly", "is shared among families", "builds upon itself and grows over time", "is spent on property"], "a": 2, "ev": "Because wealth compounds.", "why": "Bà giải thích người thừa kế tài sản có nền tảng để mạo hiểm, nên lợi thế tích lũy và tự nhân lên theo thời gian."}, {"kind": "vocab", "q": "In the text, what does \"weather\" mean in \"weather setbacks\"?", "opts": ["survive", "predict", "cause", "enjoy"], "a": 0, "ev": "weather setbacks", "why": "Weather ở đây là động từ, nghĩa là vượt qua khó khăn mà không bị đánh gục; người có tài sản dễ chống chọi thất bại hơn."}, {"kind": "tfng", "q": "Dr Lindqvist thinks incentives are unimportant.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Incentives clearly matter", "why": "Sai: bà nói rõ các động lực kinh tế có vai trò: \"Incentives clearly matter\"."}, {"kind": "tfng", "q": "Dr Lindqvist has advised a government on tax policy.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói gì về việc bà từng cố vấn cho chính phủ, nên là Not given."}, {"kind": "tfng", "q": "In most rich countries, the richest tenth hold more than half of all wealth.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "the richest tenth hold well over half of all wealth", "why": "Đúng: một phần mười giàu nhất nắm hơn một nửa tài sản: \"well over half of all wealth\"."}, {"kind": "inference", "q": "What does Dr Lindqvist imply about redistribution through taxes and benefits?", "opts": ["It should be abolished.", "It has never worked anywhere.", "It is useful but does not tackle the underlying causes.", "It is more effective than predistribution."], "a": 2, "ev": "it's treating symptoms rather than causes", "why": "Bà nói tái phân phối vẫn có vai trò nhưng chỉ chữa triệu chứng chứ không giải quyết nguyên nhân gốc: \"treating symptoms rather than causes\"."}], "notes": {"vocab": [["compounds", "tích lũy, tự nhân lên", "compound interest = lãi kép"], ["weather", "vượt qua (khó khăn)", "weather a storm/setback"], ["diverge", "phân kỳ, khác biệt dần", "trái nghĩa: converge"], ["erode", "bào mòn, làm xói mòn", "erode trust"], ["disparities", "sự chênh lệch", "income disparities"], ["predistribution", "tiền phân phối (điều chỉnh thị trường từ đầu)", "đối lập với redistribution"], ["bargaining", "thương lượng", "collective bargaining"], ["concede", "thừa nhận, nhượng bộ", "concede a point"]], "grammar": [["Inverted third conditional (điều kiện loại 3 đảo ngữ)", "Had two equally talented people started out with different assets, we would expect their lives to diverge sharply", "Had + chủ ngữ + V3 thay cho 'If two people had started...'; kết hợp với 'would expect' tạo câu điều kiện hỗn hợp, trang trọng."], ["Non-defining 'which' clause (mệnh đề quan hệ bổ sung)", "Countries with very similar levels of innovation display strikingly different degrees of inequality, which suggests that the relationship is far from automatic.", "'which' sau dấu phẩy thay cho cả mệnh đề trước, thêm nhận xét hay kết luận."], ["'would rather... than' (thà... còn hơn)", "I'd rather be accused of optimism than resign myself to the idea that nothing can be done.", "would rather + V nguyên mẫu (be accused) ... than + V nguyên mẫu (resign) diễn tả sự ưu tiên; 'be accused' là dạng bị động."], ["Purpose clause with 'so that'", "shaping the market so that fewer people end up in precarious positions to begin with", "so that + mệnh đề chỉ mục đích hoặc kết quả mong muốn của hành động chính."]], "tips": ["Phỏng vấn dùng 'Name: lời thoại'; câu hỏi của người dẫn thường gợi ra chủ đề của từng đoạn trả lời, nên đọc câu hỏi trước để biết ý chính.", "Chú ý các từ chỉ mức độ như 'Partly', 'Still', 'I concede': chuyên gia thường đồng ý một phần rồi mới phản biện."]}}, {"id": "rd5-c1-09", "lvl": "C1", "topic": "medical", "genre": "article", "title": "The Body's Slow Messengers: Hormones and Feedback", "text": "The endocrine system is often described as the body's slow-motion communication network. Whereas the nervous system relays electrical impulses in milliseconds, endocrine glands release chemical messengers called hormones into the bloodstream, and their effects may take minutes, hours or even weeks to unfold. Although the signals are sluggish, they are remarkably far-reaching: a single hormone can alter the behaviour of cells in organs scattered throughout the body, provided those cells carry the matching receptors.\n\nThe key players are a handful of glands. The hypothalamus, a small region at the base of the brain, monitors conditions such as temperature and blood salt concentration, and it instructs the pituitary gland lying just beneath it. The pituitary, often called the \"master gland\", in turn releases hormones that direct other glands, including the thyroid in the neck, the adrenal glands above the kidneys, and the ovaries or testes. The pancreas, meanwhile, secretes insulin and glucagon, which together keep blood glucose within a narrow range.\n\nWhat makes this arrangement stable is not the release of hormones itself but the way it is switched off. Most endocrine pathways operate through negative feedback: when the level of a hormone or of the substance it controls rises beyond a set point, the signal that stimulated its release is dampened. Consider thyroid hormone. When its concentration in the blood falls, the pituitary secretes more thyroid-stimulating hormone, which prompts the thyroid to produce more. Once levels are restored, the pituitary eases off. Much like a thermostat that cuts the heating when a room is warm enough, the system hovers around a target rather than overshooting it.\n\nPositive feedback, by contrast, amplifies a change instead of correcting it, and it is rare in physiology. Contractions during childbirth illustrate it: stretching of the cervix triggers the release of oxytocin, which strengthens contractions, which stretch the cervix further, until the baby is born and the loop is broken.\n\nWhen regulation fails, the consequences can be considerable. In type 1 diabetes, the immune system destroys the insulin-producing cells, so glucose accumulates in the blood while the tissues are starved of it. An underactive thyroid slows the metabolism, leaving people tired, cold and prone to weight gain, whereas an overactive one has the opposite effect. Importantly, these conditions are usually managed by replacing or adjusting the missing hormone, not by repairing the gland itself.\n\nClinicians therefore rarely judge a hormone level in isolation. A raised value of one hormone may reflect a fault in the gland that makes it, or a failure of the upstream signal that should be restraining it. Interpreting the pattern across the whole feedback loop is what allows the underlying problem to be located.", "gist": "Bài báo giải thích cách hệ nội tiết điều hòa cơ thể bằng hormone và cơ chế phản hồi, và vì sao rối loạn của vòng phản hồi gây bệnh.", "qs": [{"kind": "main", "q": "What is the main point of the article?", "opts": ["The nervous system is more important than the endocrine system because it works faster.", "Most hormonal diseases can be cured by repairing the damaged gland.", "Hormones regulate the body slowly but reliably, mainly because feedback loops switch them off at the right moment.", "The pituitary gland alone controls every function in the body."], "a": 2, "ev": "What makes this arrangement stable is not the release of hormones itself but the way it is switched off.", "why": "Ý chính là hệ nội tiết ổn định nhờ cơ chế phản hồi tắt tín hiệu: \"What makes this arrangement stable is not the release of hormones itself but the way it is switched off.\""}, {"kind": "detail", "q": "Which gland is called the \"master gland\" in the text?", "opts": ["The pituitary", "The hypothalamus", "The pancreas", "The thyroid"], "a": 0, "ev": "The pituitary, often called the \"master gland\", in turn releases hormones that direct other glands", "why": "Bài viết nói tuyến yên (pituitary) thường được gọi là \"master gland\" vì nó điều khiển các tuyến khác."}, {"kind": "detail", "q": "According to the text, what do insulin and glucagon do together?", "opts": ["They raise the level of thyroid hormone.", "They trigger contractions during childbirth.", "They control the salt concentration of the blood.", "They keep blood glucose within a narrow range."], "a": 3, "ev": "which together keep blood glucose within a narrow range", "why": "Văn bản viết insulin và glucagon \"together keep blood glucose within a narrow range\", tức giữ đường huyết trong khoảng hẹp."}, {"kind": "vocab", "q": "In the text, what does \"sluggish\" mean?", "opts": ["Unreliable", "Slow-moving", "Painful", "Very strong"], "a": 1, "ev": "Although the signals are sluggish", "why": "Câu nêu tương phản với hệ thần kinh nhanh (milliseconds) nên \"sluggish\" nghĩa là chậm chạp."}, {"kind": "tfng", "q": "A hormone can affect a cell only if that cell has the matching receptors.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "provided those cells carry the matching receptors", "why": "Đúng: \"provided those cells carry the matching receptors\" nghĩa là tế bào phải có thụ thể phù hợp thì mới chịu tác động."}, {"kind": "tfng", "q": "Positive feedback is the most common control mechanism in physiology.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "it is rare in physiology", "why": "Sai: bài viết nói phản hồi dương \"is rare in physiology\", còn phản hồi âm mới là cơ chế phổ biến."}, {"kind": "tfng", "q": "Thyroid disorders are more common in women than in men.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Không có thông tin: bài chỉ nói về suy giáp và cường giáp, không so sánh tần suất giữa nam và nữ."}, {"kind": "detail", "q": "In the thyroid example, what happens when the blood level of thyroid hormone falls?", "opts": ["The pituitary stops releasing any hormone.", "The pituitary secretes more thyroid-stimulating hormone.", "The pancreas releases more insulin.", "The hypothalamus destroys the thyroid cells."], "a": 1, "ev": "the pituitary secretes more thyroid-stimulating hormone", "why": "Văn bản: khi nồng độ giảm, \"the pituitary secretes more thyroid-stimulating hormone\" để kích thích tuyến giáp."}, {"kind": "inference", "q": "Why do clinicians rarely judge a hormone level in isolation?", "opts": ["Hormone levels change too quickly to be measured.", "Only the pituitary gland can produce reliable results.", "A single abnormal value does not show where in the loop the fault lies.", "Abnormal hormone levels are usually harmless."], "a": 2, "ev": "A raised value of one hormone may reflect a fault in the gland that makes it, or a failure of the upstream signal", "why": "Một giá trị cao có thể do chính tuyến đó hoặc do tín hiệu phía trên, nên phải xem cả vòng phản hồi để xác định vị trí lỗi."}, {"kind": "inference", "q": "What does the thermostat comparison suggest about negative feedback?", "opts": ["It keeps a variable close to a target instead of letting it swing too far.", "It makes the body produce as much hormone as possible.", "It works only when the room or body is cold.", "It needs the nervous system to switch it on."], "a": 0, "ev": "the system hovers around a target rather than overshooting it", "why": "Phép so sánh cho thấy hệ thống giữ mức ổn định quanh mục tiêu: \"hovers around a target rather than overshooting it\"."}], "notes": {"vocab": [["sluggish", "chậm chạp, uể oải", "tính từ; ở đây chỉ tín hiệu nội tiết chậm hơn thần kinh"], ["far-reaching", "có tác động rộng, lan xa", "far-reaching effects/consequences"], ["receptors", "thụ thể (trên tế bào)", "hormone gắn vào receptor như chìa vào ổ khóa"], ["negative feedback", "phản hồi âm (cơ chế tự điều chỉnh)", "đối lập với positive feedback"], ["dampened", "bị làm yếu đi, giảm bớt", "dampen = làm giảm cường độ"], ["overshooting", "vượt quá mục tiêu", "overshoot a target"], ["upstream", "ở phía trước trong chuỗi tín hiệu", "đối lập với downstream"], ["set point", "điểm đặt, mức mục tiêu", "thuật ngữ sinh lý và kỹ thuật"]], "grammar": [["Contrast with whereas (liên từ chỉ sự tương phản)", "Whereas the nervous system relays electrical impulses in milliseconds", "Whereas mở đầu mệnh đề phụ để đối chiếu hai điều trái ngược (thần kinh nhanh, nội tiết chậm); mệnh đề chính đi sau dấu phẩy."], ["Condition with provided (điều kiện với provided)", "provided those cells carry the matching receptors", "Provided (that) tương đương \"only if\", đặt một điều kiện bắt buộc; động từ chia ở hiện tại đơn dù nói về điều kiện chung."], ["Wh-cleft sentence (câu nhấn mạnh với What)", "What makes this arrangement stable is not the release of hormones itself but the way it is switched off.", "Cấu trúc What... is (not) A but B nhấn mạnh thông tin mới; \"is switched off\" là bị động chỉ cách hormone bị tắt."], ["Relative clause in comparison (mệnh đề quan hệ)", "Much like a thermostat that cuts the heating when a room is warm enough", "Mệnh đề quan hệ \"that cuts...\" bổ nghĩa cho thermostat, dùng để so sánh hình ảnh với cơ chế phản hồi."]], "tips": ["Bài báo khoa học phổ thông thường đặt ý chính ở đoạn đầu và đoạn giữa: tìm câu bắt đầu bằng \"What makes...\" để nắm luận điểm trung tâm.", "Chú ý các từ nối tương phản (whereas, by contrast, rather than) để phân biệt phản hồi âm và dương, thần kinh và nội tiết."]}}, {"id": "rd5-c1-10", "lvl": "C1", "topic": "medical", "genre": "case", "title": "When Every Guideline Is Followed: An Elderly Patient on Eleven Medicines", "text": "Case presentation\n\nMrs Halloran, an 81-year-old retired schoolteacher, was brought to the outpatient clinic by her daughter, who reported that her mother had become increasingly breathless, unsteady on her feet and forgetful over the preceding two months.\n\nPast medical history\n\nShe had long-standing hypertension, type 2 diabetes, osteoarthritis of both knees, and chronic kidney disease of moderate severity. Three years earlier she had developed atrial fibrillation. She was taking eleven regular medications, including a blood thinner, two blood-pressure tablets, a diuretic, a painkiller from the anti-inflammatory group, and a sleeping tablet that had been started after her husband's death. She lived alone, did not smoke and drank alcohol only occasionally.\n\nExamination\n\nShe appeared frail and mildly confused about the date. Her blood pressure fell noticeably when she moved from lying to standing, and she described feeling faint. Both ankles were swollen, and there were crackles at the base of each lung. Her pulse was irregular. Her gait was slow and wide-based.\n\nInvestigations\n\nBlood tests showed that her kidney function had deteriorated compared with a year earlier, and her blood glucose was well controlled, perhaps too tightly for her age. An echocardiogram revealed a mildly weakened heart muscle. Brain imaging showed age-related changes but no stroke or tumour.\n\nDiscussion\n\nThis case illustrates how multimorbidity, the coexistence of several chronic conditions, complicates care far beyond the sum of the individual diagnoses. Each disease had been managed sensibly according to its own guideline, yet the combined regimen was harming her. The anti-inflammatory painkiller was likely to be worsening both her kidney function and her fluid retention, while the diuretic and blood-pressure tablets contributed to her dizziness on standing. The sleeping tablet probably accounted for much of her confusion and increased her risk of falling. In other words, several of her symptoms were not new diseases but adverse effects of treatment, a phenomenon sometimes described as a prescribing cascade.\n\nManagement therefore centred on priorities rather than protocols. The team asked Mrs Halloran what mattered most to her, and she said that she wished to remain in her own home and walk to the shops. Guided by this goal, the doctors stopped the anti-inflammatory painkiller and the sleeping tablet, adjusted her blood-pressure treatment, relaxed her diabetes target, and arranged physiotherapy and a home visit by a pharmacist.\n\nOutcome\n\nAt review after eight weeks, her ankle swelling had resolved, her dizziness had largely disappeared and her thinking was clearer. Although none of her chronic diseases had been cured, she was safer, more independent and taking six medications instead of eleven.", "gist": "Ca bệnh một cụ bà 81 tuổi nhiều bệnh mạn tính cho thấy thuốc điều trị chồng chéo có thể gây hại và cần ưu tiên mục tiêu của bệnh nhân.", "qs": [{"kind": "main", "q": "What is the main lesson of this case?", "opts": ["Older patients should be given as many medications as possible to protect them.", "Following separate guidelines for each disease can harm an older patient, so care should be organised around her priorities.", "Dementia is the most likely cause of confusion in every elderly patient.", "Chronic diseases can be cured if treatment starts early enough."], "a": 1, "ev": "Each disease had been managed sensibly according to its own guideline, yet the combined regimen was harming her.", "why": "Ca bệnh cho thấy điều trị từng bệnh theo hướng dẫn riêng lại gây hại: \"the combined regimen was harming her\", nên cần ưu tiên mục tiêu của bệnh nhân."}, {"kind": "detail", "q": "For how long had the symptoms been developing before the visit?", "opts": ["About two months", "About two weeks", "About eight weeks after the visit", "About three years"], "a": 0, "ev": "over the preceding two months", "why": "Con gái bà báo rằng các triệu chứng tăng dần \"over the preceding two months\", tức khoảng hai tháng."}, {"kind": "detail", "q": "What did Mrs Halloran say mattered most to her?", "opts": ["Curing her diabetes completely", "Moving in with her daughter", "Taking fewer tablets at night", "Staying in her own home and walking to the shops"], "a": 3, "ev": "she wished to remain in her own home and walk to the shops", "why": "Bà nói muốn ở lại nhà mình và đi bộ ra cửa hàng: \"she wished to remain in her own home and walk to the shops\"."}, {"kind": "detail", "q": "What happened to her blood pressure at examination?", "opts": ["It was dangerously high while she lay down.", "It stayed the same in every position.", "It dropped when she stood up.", "It rose whenever she felt faint."], "a": 2, "ev": "Her blood pressure fell noticeably when she moved from lying to standing", "why": "Khám cho thấy huyết áp tụt rõ khi chuyển từ nằm sang đứng, gây choáng váng."}, {"kind": "vocab", "q": "In the text, what does \"multimorbidity\" mean?", "opts": ["A single disease that gets steadily worse", "Having several long-term conditions at the same time", "Side effects caused by too many medications", "A disease that affects the elderly only"], "a": 1, "ev": "the coexistence of several chronic conditions", "why": "Văn bản tự định nghĩa: multimorbidity là \"the coexistence of several chronic conditions\", tức nhiều bệnh mạn tính cùng lúc."}, {"kind": "tfng", "q": "A sleeping tablet probably contributed to Mrs Halloran's confusion.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "The sleeping tablet probably accounted for much of her confusion", "why": "Đúng: bài viết cho rằng thuốc ngủ \"probably accounted for much of her confusion\"."}, {"kind": "tfng", "q": "By the end of the case, all of her chronic diseases had been cured.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "none of her chronic diseases had been cured", "why": "Sai: kết quả ghi rõ \"none of her chronic diseases had been cured\"; bà chỉ an toàn và tự lập hơn."}, {"kind": "tfng", "q": "Mrs Halloran's husband died of heart disease.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Không có thông tin: văn bản chỉ nhắc chồng bà đã mất, không nói nguyên nhân."}, {"kind": "inference", "q": "Why did the doctors relax her diabetes target?", "opts": ["Her diabetes had been cured during the admission.", "Her kidneys no longer needed protection.", "The blood tests had been taken incorrectly.", "Very tight glucose control may not suit a frail older person."], "a": 3, "ev": "perhaps too tightly for her age", "why": "Đường huyết kiểm soát \"perhaps too tightly for her age\" cho thấy ở người già yếu, mục tiêu quá chặt có thể không phù hợp."}, {"kind": "inference", "q": "What does the term \"prescribing cascade\" imply in this case?", "opts": ["A drug's side effect may be mistaken for a new disease and treated with another drug.", "Doctors prescribe medicines in a fixed order of severity.", "Patients take medicines in a cascade of increasing doses.", "A new illness appears whenever a medicine is stopped."], "a": 0, "ev": "several of her symptoms were not new diseases but adverse effects of treatment", "why": "Nhiều triệu chứng là tác dụng phụ chứ không phải bệnh mới, nên thêm thuốc chữa chúng sẽ tạo chuỗi kê đơn nối tiếp."}], "notes": {"vocab": [["multimorbidity", "đa bệnh lý (nhiều bệnh mạn tính cùng lúc)", "multi- + morbidity"], ["frail", "yếu ớt, dễ tổn thương (người già)", "danh từ: frailty"], ["gait", "dáng đi, kiểu bước đi", "thuật ngữ khám lâm sàng"], ["deteriorated", "xấu đi, suy giảm", "deteriorate; danh từ: deterioration"], ["regimen", "phác đồ, chế độ điều trị", "a drug regimen"], ["fluid retention", "giữ nước, phù", "retention = sự giữ lại"], ["adverse effects", "tác dụng không mong muốn", "gần nghĩa side effects, trang trọng hơn"], ["prescribing cascade", "chuỗi kê đơn nối tiếp (thuốc mới chữa tác dụng phụ của thuốc cũ)", "thuật ngữ dược lâm sàng"]], "grammar": [["Reported speech with past perfect (câu tường thuật)", "her daughter, who reported that her mother had become increasingly breathless", "Động từ tường thuật ở quá khứ nên mệnh đề sau lùi thì thành past perfect (had become); who mở mệnh đề quan hệ không xác định."], ["Past perfect passive (bị động quá khứ hoàn thành)", "Each disease had been managed sensibly according to its own guideline, yet the combined regimen was harming her.", "Had been managed diễn tả việc xảy ra trước thời điểm hiện tại của câu chuyện; yet đưa ra sự tương phản bất ngờ."], ["Participle clause (mệnh đề phân từ)", "Guided by this goal, the doctors stopped the anti-inflammatory painkiller", "Phân từ quá khứ mở đầu câu có nghĩa bị động (được dẫn dắt bởi mục tiêu), chủ ngữ của nó trùng với chủ ngữ mệnh đề chính."], ["Appositive and reduced relative (cụm đồng vị)", "a phenomenon sometimes described as a prescribing cascade", "Cụm danh từ đứng sau dấu phẩy bổ sung/giải thích cho mệnh đề trước; described as là phân từ quá khứ rút gọn."]], "tips": ["Ca lâm sàng có cấu trúc cố định (Presentation, History, Examination, Investigations, Discussion, Outcome): đọc tiêu đề trước để biết thông tin nằm ở đâu.", "Phần Discussion chứa lập luận và bài học chính; câu có \"In other words\" thường tóm tắt ý quan trọng nhất."]}}, {"id": "rd5-c1-11", "lvl": "C1", "topic": "medical", "genre": "abstract", "title": "Supervised Exercise for Chronic Low Back Pain: A Randomised Trial", "text": "Background: Chronic low back pain is a leading cause of disability worldwide, yet the benefit of structured exercise remains debated, partly because earlier trials were small and adherence was seldom measured. We investigated whether a supervised exercise programme reduces pain and disability compared with usual care.\n\nMethods: This was a multicentre, parallel-group, randomised controlled trial conducted in six outpatient physiotherapy departments. Adults aged 25 to 65 with non-specific low back pain lasting more than twelve weeks were eligible; those with suspected fracture, infection, tumour or nerve compression were excluded. Participants were allocated by computer-generated sequence, concealed from recruiting staff, to either a twelve-week supervised programme of strengthening and stretching exercises (intervention group) or usual care consisting of brief advice and simple analgesia (control group). Because of the nature of the intervention, participants could not be blinded, but the assessors who measured outcomes were unaware of group allocation. The primary outcome was pain intensity on a 0-10 scale at six months. Secondary outcomes included disability scores, days of sick leave and adverse events. Pain and disability were recorded with standard questionnaires completed at baseline and again at twelve weeks, six months and twelve months. Analysis followed the intention-to-treat principle, meaning that every participant was analysed in the group to which he or she had been assigned, regardless of attendance.\n\nResults: In total, 412 participants were randomised, 206 to each group, and 371 (90%) completed the six-month assessment. Participants in the intervention group attended a median of nine of the twelve scheduled sessions. Mean pain intensity fell by 2.4 points in the intervention group and by 1.1 points in the control group, giving an adjusted difference of 1.3 points (95% confidence interval 0.8 to 1.8). Disability scores improved significantly more in the intervention group, and participants in this group took fewer days of sick leave. Minor, transient muscle soreness was reported by 18% of those exercising; no serious adverse events were attributed to the intervention. The benefit was smaller at twelve months, although it remained statistically significant for pain.\n\nConclusion: A supervised exercise programme produced clinically meaningful reductions in pain and disability in adults with chronic low back pain, at low risk. However, the attenuation of the effect at twelve months suggests that benefits may depend on continued activity. Because participants knew their allocation, subjective outcomes may have been influenced by expectation, and the findings may not generalise to people with acute pain or serious underlying disease. Larger studies with longer follow-up are also needed. Future research should examine strategies to sustain adherence beyond the end of supervised treatment.", "gist": "Tóm tắt thử nghiệm ngẫu nhiên cho thấy tập luyện có giám sát giảm đau lưng mạn và tàn tật hơn chăm sóc thông thường, nhưng lợi ích yếu dần sau một năm.", "qs": [{"kind": "main", "q": "What was the aim of the trial?", "opts": ["To compare two different types of painkillers", "To test whether supervised exercise reduces pain and disability more than usual care", "To find the cause of acute back injuries", "To measure how many people develop back pain at work"], "a": 1, "ev": "whether a supervised exercise programme reduces pain and disability compared with usual care", "why": "Mục tiêu nêu ở Background: kiểm tra liệu chương trình tập có giám sát giảm đau và giảm tàn tật so với chăm sóc thông thường hay không."}, {"kind": "detail", "q": "How many participants completed the six-month assessment?", "opts": ["412", "206", "371", "18"], "a": 2, "ev": "371 (90%) completed the six-month assessment", "why": "Phần Results ghi 412 người được phân ngẫu nhiên và \"371 (90%) completed the six-month assessment\"."}, {"kind": "detail", "q": "Who measured the outcomes?", "opts": ["Assessors who did not know which group each person was in", "The participants themselves, who knew their group", "The physiotherapists who ran the exercise sessions", "Recruiting staff who had seen the random sequence"], "a": 0, "ev": "the assessors who measured outcomes were unaware of group allocation", "why": "Người đánh giá kết quả không biết nhóm của từng người: \"unaware of group allocation\"."}, {"kind": "detail", "q": "What was the primary outcome?", "opts": ["Days of sick leave", "Disability score at twelve weeks", "Number of adverse events", "Pain intensity at six months"], "a": 3, "ev": "The primary outcome was pain intensity on a 0-10 scale at six months.", "why": "Kết cục chính là cường độ đau trên thang 0-10 sau sáu tháng; ngày nghỉ ốm và tàn tật chỉ là kết cục phụ."}, {"kind": "vocab", "q": "In the text, what does \"attenuation\" mean?", "opts": ["Confirmation", "Weakening", "Measurement", "Repetition"], "a": 1, "ev": "the attenuation of the effect at twelve months", "why": "Hiệu quả nhỏ hơn ở tháng 12 (\"The benefit was smaller at twelve months\"), nên attenuation nghĩa là sự suy yếu, giảm bớt."}, {"kind": "tfng", "q": "The participants could not be blinded to which treatment they received.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "participants could not be blinded", "why": "Đúng: do bản chất can thiệp, \"participants could not be blinded\"."}, {"kind": "tfng", "q": "No participant in the exercise group reported any side effect.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Minor, transient muscle soreness was reported by 18% of those exercising", "why": "Sai: 18% người tập báo cáo đau cơ nhẹ, thoáng qua, dù không có biến cố nghiêm trọng."}, {"kind": "tfng", "q": "The exercise programme was cheaper than usual care.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Không có thông tin: bài tóm tắt không đề cập chi phí."}, {"kind": "inference", "q": "Why do the authors worry that expectation may have affected the results?", "opts": ["The assessors were told who received exercise.", "The control group received no care at all.", "Participants knew their group, and pain scores are self-reported.", "The sample was too small to measure pain."], "a": 2, "ev": "Because participants knew their allocation, subjective outcomes may have been influenced by expectation", "why": "Vì người tham gia biết mình ở nhóm nào, các kết cục chủ quan như mức đau có thể bị ảnh hưởng bởi kỳ vọng."}, {"kind": "inference", "q": "What do the authors imply by recommending research on adherence?", "opts": ["Patients may need help to keep exercising after supervised treatment ends.", "Exercise causes serious harm after twelve months.", "Usual care works better in the long term.", "Supervised sessions should be shortened."], "a": 0, "ev": "benefits may depend on continued activity", "why": "Lợi ích giảm sau 12 tháng và \"may depend on continued activity\", nên cần chiến lược giúp bệnh nhân duy trì tập luyện."}], "notes": {"vocab": [["adherence", "sự tuân thủ (điều trị, chương trình tập)", "adhere to; thường dùng trong nghiên cứu lâm sàng"], ["allocated", "được phân bổ (vào nhóm)", "allocation = sự phân nhóm"], ["concealed", "được che giấu", "allocation concealment = giấu trình tự phân nhóm"], ["blinded", "bị làm mù (không biết nhóm điều trị)", "blinding giúp giảm sai lệch"], ["intention-to-treat", "phân tích theo ý định điều trị", "phân tích theo nhóm ban đầu được phân"], ["transient", "thoáng qua, tạm thời", "đồng nghĩa temporary"], ["attenuation", "sự suy yếu, giảm dần", "attenuate (v)"], ["confidence interval", "khoảng tin cậy", "thường viết tắt CI"]], "grammar": [["Passive voice in Methods (bị động trong phần phương pháp)", "those with suspected fracture, infection, tumour or nerve compression were excluded", "Phần Methods dùng bị động vì người thực hiện không quan trọng; tập trung vào đối tượng bị loại."], ["Participle phrase (cụm phân từ)", "Participants were allocated by computer-generated sequence, concealed from recruiting staff, to either", "Concealed from recruiting staff là phân từ quá khứ bổ nghĩa cho sequence, nói trình tự được giấu khỏi người tuyển."], ["Concession with although (nhượng bộ)", "although it remained statistically significant for pain", "Although đưa ra điều trái với kỳ vọng: lợi ích nhỏ hơn nhưng vẫn có ý nghĩa thống kê."], ["Modal perfect passive (khả năng trong quá khứ, bị động)", "subjective outcomes may have been influenced by expectation", "May have been + phân từ quá khứ diễn tả khả năng điều gì đó đã xảy ra trong quá khứ nhưng chưa chắc chắn; giọng thận trọng của học thuật."]], "tips": ["Abstract có bốn phần Background, Methods, Results, Conclusion: câu hỏi về mục tiêu nằm ở Background, con số nằm ở Results, hạn chế nằm ở Conclusion.", "Khi gặp số liệu, đọc kỹ đối tượng của con số (số người đã hoàn thành, sai khác điều chỉnh) trước khi chọn đáp án."]}}, {"id": "rd5-c1-12", "lvl": "C1", "topic": "medical", "genre": "article", "title": "More Than a Signature: The Ethics of Informed Consent", "text": "Few principles in medicine are invoked as often, or understood as imperfectly, as informed consent. In its simplest form, it holds that a competent adult may accept or refuse any treatment, and that this choice must follow, rather than precede, an honest explanation of what is proposed. Yet beneath this apparently straightforward rule lies a series of difficult questions about information, understanding and freedom.\n\nHistorically, consent was a response to abuse. Following revelations of experiments conducted on prisoners and vulnerable groups without their knowledge, codes of research ethics established that voluntary agreement was indispensable. Clinical practice took longer to follow suit. For much of the twentieth century, doctors operated within a paternalistic tradition in which the physician decided what was best and disclosed only as much as he or she judged fit. Patients were expected to trust; questioning was regarded as ungrateful.\n\nModern ethics rests on respect for autonomy, the idea that people are entitled to govern their own lives, including their bodies. Valid consent is generally held to require three conditions: that the person has capacity, that the information disclosed is adequate, and that the decision is made voluntarily, free from coercion or undue pressure. Each condition is less tidy than it sounds. Capacity is not an all-or-nothing attribute; a person with dementia may be able to choose what to eat yet unable to weigh the risks of surgery. Disclosure raises the question of how much is enough. Reciting every conceivable complication may satisfy a lawyer but overwhelm a frightened patient, whereas a selective summary may quietly steer the decision. Many courts now ask what a reasonable patient would wish to know, together with what this particular patient would consider significant, rather than what the average doctor would say.\n\nVoluntariness is subtler still. Patients are rarely in a position to bargain on equal terms: they are unwell, anxious and dependent on the very person who recommends the treatment. A signature on a form, therefore, proves little. Consent is better understood as a process, a conversation unfolding over time, than as a moment of paperwork. Techniques such as asking patients to explain the plan in their own words, offering time to reflect, and inviting questions help to ensure that agreement is genuine rather than merely formal.\n\nExceptions exist. In an emergency, when an unconscious patient needs immediate life-saving treatment, clinicians may proceed on the assumption that a reasonable person would agree. Even then, the justification is narrow and temporary, and it does not extend to procedures that could wait until the patient has recovered.\n\nUltimately, informed consent is less a legal hurdle than an expression of respect. Its purpose is not to protect the institution from complaint but to make sure that the person who bears the consequences of a decision is the one who makes it.", "gist": "Bài viết lập luận rằng đồng thuận có hiểu biết là một quá trình tôn trọng quyền tự chủ của bệnh nhân chứ không chỉ là chữ ký trên giấy.", "qs": [{"kind": "main", "q": "What is the author's central argument?", "opts": ["Doctors should decide treatment because patients rarely understand medicine.", "Consent forms should list every possible complication in detail.", "Consent is unnecessary when a patient is anxious.", "Informed consent is an ongoing, respectful process rather than a signature on a form."], "a": 3, "ev": "Consent is better understood as a process, a conversation unfolding over time, than as a moment of paperwork.", "why": "Tác giả lập luận consent là một quá trình đối thoại: \"Consent is better understood as a process\", không chỉ là thủ tục giấy tờ."}, {"kind": "detail", "q": "According to the text, what prompted the development of consent?", "opts": ["Revelations of abusive experiments", "A rise in malpractice lawsuits", "New surgical technology", "Pressure from hospital managers"], "a": 0, "ev": "Historically, consent was a response to abuse.", "why": "Bài viết nêu rõ nguồn gốc: \"consent was a response to abuse\", sau khi các thí nghiệm lạm dụng bị phanh phui."}, {"kind": "detail", "q": "Which is NOT given as a condition for valid consent?", "opts": ["That the person has capacity", "That the patient has paid for the treatment", "That adequate information is disclosed", "That the decision is voluntary"], "a": 1, "ev": "that the person has capacity, that the information disclosed is adequate, and that the decision is made voluntarily", "why": "Ba điều kiện là năng lực, thông tin đầy đủ và tự nguyện; việc trả tiền không được nhắc tới."}, {"kind": "detail", "q": "When may clinicians treat an unconscious patient without explicit consent?", "opts": ["Whenever relatives are not available", "If the procedure could be done later", "In an emergency requiring immediate life-saving treatment", "Whenever the doctor thinks it is best"], "a": 2, "ev": "clinicians may proceed on the assumption that a reasonable person would agree", "why": "Ngoại lệ chỉ áp dụng trong cấp cứu, khi bác sĩ giả định một người hợp lý sẽ đồng ý; không áp dụng cho thủ thuật có thể chờ."}, {"kind": "vocab", "q": "In the text, what does \"paternalistic\" describe?", "opts": ["A respectful partnership between equals", "A strict legal approach to contracts", "A tradition that focuses on family history", "An attitude in which the authority decides for others, supposedly for their good"], "a": 3, "ev": "paternalistic tradition in which the physician decided what was best", "why": "Câu giải thích ngay sau đó: bác sĩ tự quyết định điều tốt nhất và chỉ tiết lộ phần ông/bà thấy phù hợp, tức thái độ gia trưởng."}, {"kind": "tfng", "q": "A person with dementia may be able to make some decisions but not others.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "a person with dementia may be able to choose what to eat yet unable to weigh the risks of surgery", "why": "Đúng: năng lực không phải \"all-or-nothing\"; người sa sút trí tuệ có thể chọn bữa ăn nhưng không cân nhắc được rủi ro phẫu thuật."}, {"kind": "tfng", "q": "Clinical practice adopted informed consent faster than research did.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Clinical practice took longer to follow suit.", "why": "Sai: bài viết nói thực hành lâm sàng \"took longer to follow suit\", tức chậm hơn nghiên cứu."}, {"kind": "tfng", "q": "Written consent forms are legally required in every country.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Không có thông tin: bài không nói về yêu cầu pháp lý của văn bản đồng ý ở các quốc gia."}, {"kind": "inference", "q": "What does the author imply about listing every possible complication?", "opts": ["It is the best way to protect the patient.", "More information is not always better for a frightened patient.", "It is forbidden by most courts.", "It always makes patients refuse treatment."], "a": 1, "ev": "Reciting every conceivable complication may satisfy a lawyer but overwhelm a frightened patient", "why": "Liệt kê mọi biến chứng có thể làm lợi cho luật sư nhưng khiến bệnh nhân choáng ngợp, nên nhiều thông tin chưa chắc tốt hơn."}, {"kind": "inference", "q": "What does \"A signature on a form, therefore, proves little\" suggest?", "opts": ["Patients should never sign medical forms.", "Forms are more accurate than conversations.", "Signing does not guarantee that the patient understood and chose freely.", "Doctors are not allowed to ask for signatures."], "a": 2, "ev": "A signature on a form, therefore, proves little.", "why": "Vì bệnh nhân hiếm khi ngang quyền với bác sĩ, chữ ký không chứng minh được sự hiểu biết và tự nguyện."}], "notes": {"vocab": [["invoked", "được viện dẫn, nhắc đến", "invoke a principle/law"], ["indispensable", "không thể thiếu", "đồng nghĩa essential"], ["paternalistic", "gia trưởng, áp đặt vì \"tốt cho bạn\"", "paternalism (n)"], ["autonomy", "quyền tự chủ", "tự quyết định về bản thân"], ["capacity", "năng lực ra quyết định (pháp lý, y đạo đức)", "mental capacity"], ["coercion", "sự ép buộc, cưỡng ép", "coerce (v)"], ["steer", "lái, dẫn dắt (quyết định)", "steer someone towards"], ["voluntariness", "tính tự nguyện", "voluntary (adj)"]], "grammar": [["Participle clause with Following (mệnh đề phân từ)", "Following revelations of experiments conducted on prisoners and vulnerable groups without their knowledge", "Following + danh từ nghĩa là sau khi; conducted là phân từ quá khứ rút gọn của mệnh đề quan hệ (experiments which were conducted)."], ["Passive with reporting verb (bị động với động từ tường thuật)", "Valid consent is generally held to require three conditions", "is held to + động từ nguyên mẫu diễn đạt quan điểm chung (người ta cho rằng), văn phong học thuật khách quan."], ["Contrast with whereas and modals (tương phản, động từ khuyết thiếu)", "Reciting every conceivable complication may satisfy a lawyer but overwhelm a frightened patient, whereas a selective summary may quietly steer the decision.", "Danh động từ làm chủ ngữ, may thể hiện khả năng; whereas đối chiếu hai cách làm trái ngược."], ["Not... but... structure (cấu trúc phủ định-khẳng định)", "Its purpose is not to protect the institution from complaint but to make sure that the person who bears the consequences of a decision is the one who makes it.", "Cấu trúc not A but B nhấn mạnh mục đích thật sự (B) và bác bỏ cách hiểu thông thường (A); mệnh đề quan hệ who bears... xác định người."]], "tips": ["Bài luận lập luận thường mở bằng câu hỏi hay mâu thuẫn và kết bằng câu khẳng định thái độ của tác giả: đọc kỹ câu đầu và câu cuối để nắm ý chính.", "Chú ý từ \"yet\", \"rather than\", \"whereas\": chúng báo hiệu tác giả đang bác bỏ quan niệm phổ biến để đưa ra quan điểm của mình."]}}, {"id": "rd5-c1-13", "lvl": "C1", "topic": "medical", "genre": "interview", "title": "Ninety Seconds at the Front Desk: An Emergency Physician on Triage", "text": "Interviewer: Dr Hallam, most people picture an emergency department as chaos. How does triage bring order to it?\nDr Hallam: Triage is essentially a sorting process, and its purpose is often misunderstood. We are not deciding who deserves care; we are deciding who cannot safely wait. A patient with a sprained ankle and a patient with crushing chest pain may arrive within a minute of each other, and the nurse at the front desk has perhaps ninety seconds to tell them apart. It is a little like air traffic control: the aim is safe order, not speed for its own sake.\nInterviewer: Ninety seconds seems very short. What is the nurse actually looking for?\nDr Hallam: Primarily, signs of physiological instability: a rapid pulse, low blood pressure, laboured breathing, or a drop in consciousness. Those findings matter more than the complaint itself. Rarely does a patient say they are deteriorating, yet their breathing rate usually says it for them.\nInterviewer: Doesn't that mean some patients wait a very long time?\nDr Hallam: Inevitably, and that is the hardest part to explain. Had we treated people strictly in order of arrival, a child with an ear infection would be seen before an elderly man whose oxygen levels are quietly falling. Waiting is not neglect, but it can feel like it, which is why we reassess anyone who has been in the waiting room for more than an hour.\nInterviewer: Can triage get it wrong?\nDr Hallam: Of course. Heart attacks in women and in diabetic patients, for example, may present with fatigue or nausea rather than classic chest pain, and an inexperienced nurse could underestimate the risk. We therefore build in safety nets: protocols that automatically flag certain combinations of symptoms, and a culture in which any staff member can raise concerns without fear of criticism.\nInterviewer: What would you ask of the public?\nDr Hallam: Honesty and patience. Tell us about any medication you take, even if it seems irrelevant, and mention it if your symptoms change while you wait. Not only does that help us; it also protects you. And please do not assume that a quiet waiting room means a quiet department. Behind the doors, the resuscitation rooms may be full.\nInterviewer: Has triage changed during your career?\nDr Hallam: Considerably. When I started, decisions relied mostly on instinct. Now we use structured scoring systems, which reduce variation between nurses, although they have not replaced clinical judgement. A score can prompt us to look again; it cannot see the patient who simply looks wrong to an experienced eye. Honestly, I would rather have a nurse who doubts a score than one who trusts it blindly, because blind trust is how errors slip through unnoticed during a busy night shift.", "gist": "Một bác sĩ cấp cứu giải thích phân loại bệnh nhân (triage) nhằm xác định ai không thể chờ an toàn, những hạn chế của nó và cách giảm sai sót.", "qs": [{"kind": "main", "q": "What is the main point Dr Hallam makes about triage?", "opts": ["It rewards patients who arrive earliest.", "It decides who cannot safely wait, not who deserves care.", "It replaces the need for doctors' clinical judgement.", "It is designed to shorten waiting times for everyone."], "a": 1, "ev": "we are deciding who cannot safely wait", "why": "Bác sĩ nói rõ triage không quyết định ai xứng đáng được chăm sóc mà quyết định ai không thể chờ an toàn: \"we are deciding who cannot safely wait\"."}, {"kind": "detail", "q": "How much time does the front-desk nurse may have to assess a patient?", "opts": ["About ten seconds", "About thirty seconds", "About nine minutes", "About ninety seconds"], "a": 3, "ev": "perhaps ninety seconds", "why": "Bác sĩ nói y tá có \"perhaps ninety seconds\" để phân biệt các bệnh nhân."}, {"kind": "detail", "q": "According to Dr Hallam, what matters more than the patient's complaint?", "opts": ["Signs of physiological instability", "The patient's age", "The time of arrival", "The patient's medical history"], "a": 0, "ev": "Those findings matter more than the complaint itself.", "why": "Các dấu hiệu mất ổn định sinh lý (mạch nhanh, huyết áp thấp...) quan trọng hơn lời than phiền: \"Those findings matter more than the complaint itself.\""}, {"kind": "vocab", "q": "In the text, what does \"deteriorating\" mean?", "opts": ["Recovering slowly", "Becoming calmer", "Getting worse", "Staying the same"], "a": 2, "ev": "say they are deteriorating", "why": "\"Deteriorating\" nghĩa là xấu đi; hơi thở nhanh cho thấy bệnh nhân đang xấu đi dù họ không nói ra."}, {"kind": "tfng", "q": "Patients who have waited for over an hour are checked again.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "we reassess anyone who has been in the waiting room for more than an hour", "why": "Đúng: \"we reassess anyone who has been in the waiting room for more than an hour\"."}, {"kind": "tfng", "q": "Scoring systems have taken the place of clinical judgement.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "they have not replaced clinical judgement", "why": "Sai: các hệ thống điểm \"have not replaced clinical judgement\"."}, {"kind": "tfng", "q": "Most patients in the waiting room are children.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài chỉ nhắc một đứa trẻ viêm tai làm ví dụ, không nói phần lớn bệnh nhân là trẻ em nên là Not given."}, {"kind": "detail", "q": "Why might triage underestimate a heart attack in some patients?", "opts": ["They refuse to describe symptoms.", "They may show fatigue or nausea instead of chest pain.", "They usually arrive by ambulance.", "They are often too young to be at risk."], "a": 1, "ev": "may present with fatigue or nausea rather than classic chest pain", "why": "Phụ nữ và bệnh nhân tiểu đường có thể chỉ mệt hoặc buồn nôn: \"may present with fatigue or nausea rather than classic chest pain\"."}, {"kind": "inference", "q": "What does Dr Hallam imply about a quiet waiting room?", "opts": ["It means the department has few seriously ill patients.", "It shows that triage is working perfectly.", "It suggests that nurses have too little to do.", "It may hide the fact that the most urgent cases are inside."], "a": 3, "ev": "Behind the doors, the resuscitation rooms may be full.", "why": "Phòng chờ yên tĩnh không có nghĩa khoa yên tĩnh vì \"the resuscitation rooms may be full\" - các ca nặng đang được xử trí bên trong."}, {"kind": "inference", "q": "What can be inferred from the final remark about a patient who \"simply looks wrong\"?", "opts": ["Scores can never be useful.", "Nurses should ignore their instincts.", "Experienced clinicians may notice danger that a score misses.", "Patients often exaggerate their symptoms."], "a": 2, "ev": "it cannot see the patient who simply looks wrong to an experienced eye", "why": "Điểm số \"cannot see\" bệnh nhân trông bất ổn, ngụ ý kinh nghiệm lâm sàng vẫn phát hiện được điều mà điểm số bỏ sót."}], "notes": {"vocab": [["triage", "phân loại bệnh nhân theo mức độ khẩn cấp", "thuật ngữ cấp cứu"], ["physiological", "(thuộc) sinh lý", "danh từ: physiology"], ["laboured", "(thở) nặng nhọc, khó khăn", "laboured breathing"], ["deteriorating", "đang xấu đi", "deteriorate -> deterioration"], ["neglect", "sự bỏ mặc, thiếu chăm sóc", "đối lập với care"], ["reassess", "đánh giá lại", "re- + assess"], ["protocols", "quy trình chuẩn", "clinical protocol"], ["resuscitation", "hồi sức", "resuscitation room"]], "grammar": [["Negative inversion (đảo ngữ với trạng từ phủ định)", "Rarely does a patient say they are deteriorating", "Trạng từ phủ định Rarely đứng đầu thì trợ động từ does đảo trước chủ ngữ, để nhấn mạnh rằng điều này hiếm khi xảy ra."], ["Inverted conditional (câu điều kiện đảo ngữ)", "Had we treated people strictly in order of arrival", "Had + chủ ngữ + V3 thay cho If we had treated; dùng để nói về một giả định không có thật, trang trọng hơn."], ["Not only ... (đảo ngữ nhấn mạnh)", "Not only does that help us; it also protects you.", "Not only đứng đầu câu kéo theo đảo does that, nhấn mạnh lợi ích kép."]], "tips": ["Trong bài phỏng vấn, hãy đọc câu hỏi của người phỏng vấn trước: nó cho biết chủ đề của từng đoạn trả lời, giúp tìm ý chính nhanh.", "Chú ý các cụm đối lập như \"not ... but\" hay \"although\": ý chính của chuyên gia thường nằm ở vế sau."]}}, {"id": "rd5-c1-14", "lvl": "C1", "topic": "medical", "genre": "report", "title": "Quality-Improvement Report: Medication Administration Errors on Ward 7", "text": "Quality-Improvement Report: Reducing Medication Administration Errors on Ward 7\n\nBackground\nMedication errors remain one of the most common preventable causes of harm in hospitals. On Ward 7, a 28-bed general medical unit, an internal audit in January found that 6.4 per cent of scheduled doses were given late, omitted, or given to the wrong patient. Staff attributed many of these incidents to interruptions, since nurses preparing drugs were approached by colleagues, relatives, and telephones an average of eleven times per round. Several serious incidents had also been reported to the hospital's patient safety committee during the previous year, which prompted senior management to support a structured response.\n\nMethods\nOver four months, the project team introduced three changes. First, nurses wore bright vests marked \"Do not disturb\" while preparing medication. Second, a pharmacist joined the morning round to review each prescription before administration. Third, barcode scanners were introduced so that each wristband could be matched with its prescription at the bedside. Errors were recorded by trained observers, who were not told which change was being evaluated, in order to limit bias. Incident reports and staff surveys supplemented the observations.\n\nFindings\nBy the end of the project, the error rate had fallen to 2.9 per cent, a reduction of more than half. The vests alone cut interruptions by roughly a third, although some staff reported that visitors tended to ignore them. Pharmacist review identified several prescribing problems, such as duplicated drugs, that would otherwise have reached the patient. Staff surveys also showed that morale on the ward improved, although the reasons were not explored in detail. The scanners proved more controversial. Whereas the majority of nurses valued the extra check, a minority complained that the devices were slow and frequently failed to read worn wristbands, which sometimes encouraged workarounds such as scanning a label before reaching the bedside. Such workarounds undermine the very protection the technology is intended to provide.\n\nLimitations\nBecause the three changes were introduced almost simultaneously, it is impossible to say which contributed most. The project also ran on a single ward, and results might not be generalisable to units with different staffing. Furthermore, heightened staff awareness may have produced a temporary improvement that will fade. Finally, the observers were visible to nurses, which may have changed how carefully some of them worked.\n\nRecommendations\nThe team recommends that the vests be retained and that wristbands be replaced more regularly. Scanner software should be upgraded before the system is extended to other wards, and a follow-up audit should be conducted after twelve months to establish whether the gains are sustained. Staff should also be encouraged to report near misses without fear of blame, since these provide early warning of weaknesses in the system.", "gist": "Báo cáo cải tiến chất lượng cho thấy áo chống làm phiền, dược sĩ rà soát và máy quét mã vạch làm giảm hơn một nửa sai sót dùng thuốc trên một khoa.", "qs": [{"kind": "main", "q": "What is the report mainly about?", "opts": ["Why nurses dislike working on a medical ward", "How a hospital ward tried to cut errors in giving drugs", "The cost of buying barcode scanners", "A comparison of two hospitals' pharmacies"], "a": 1, "ev": "Reducing Medication Administration Errors on Ward 7", "why": "Tiêu đề và toàn bộ báo cáo nói về việc giảm sai sót khi dùng thuốc: \"Reducing Medication Administration Errors on Ward 7\"."}, {"kind": "detail", "q": "What proportion of doses were wrongly handled in the January audit?", "opts": ["2.9 per cent", "11 per cent", "28 per cent", "6.4 per cent"], "a": 3, "ev": "6.4 per cent of scheduled doses", "why": "Audit tháng Một cho thấy \"6.4 per cent of scheduled doses\" bị trễ, bỏ sót hoặc nhầm bệnh nhân."}, {"kind": "detail", "q": "What was the pharmacist's role in the project?", "opts": ["Checking each prescription before drugs were given", "Training nurses to use scanners", "Recording incident reports", "Replacing worn wristbands"], "a": 0, "ev": "a pharmacist joined the morning round to review each prescription before administration", "why": "Dược sĩ tham gia vòng buổi sáng để rà soát từng đơn thuốc trước khi cho thuốc."}, {"kind": "vocab", "q": "In the text, what does \"attributed ... to\" mean?", "opts": ["Gave a reward for", "Took responsibility away from", "Explained as being caused by", "Compared with"], "a": 2, "ev": "Staff attributed many of these incidents to interruptions", "why": "\"Attribute A to B\" là cho rằng A do B gây ra; nhân viên cho rằng sự cố do bị làm gián đoạn."}, {"kind": "vocab", "q": "In the text, what does \"workarounds\" mean?", "opts": ["Official safety rules", "Informal shortcuts that avoid the intended procedure", "Extra training sessions", "Faulty devices"], "a": 1, "ev": "workarounds such as scanning a label before reaching the bedside", "why": "Quét nhãn trước khi đến giường bệnh là cách lách quy trình, tức \"workarounds\"."}, {"kind": "tfng", "q": "The error rate fell by more than half during the project.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "a reduction of more than half", "why": "Đúng: tỷ lệ giảm xuống 2.9% - \"a reduction of more than half\"."}, {"kind": "tfng", "q": "All nurses valued the extra check provided by the scanners.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "Whereas the majority of nurses valued the extra check, a minority complained", "why": "Sai: chỉ \"the majority\" đánh giá cao, còn một thiểu số phàn nàn."}, {"kind": "tfng", "q": "The project was funded by the hospital's pharmacy department.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không đề cập nguồn kinh phí nên là Not given."}, {"kind": "inference", "q": "Why does the report say workarounds \"undermine the very protection\" of the technology?", "opts": ["They make scanners more expensive.", "They slow down the pharmacist's review.", "They prevent staff from reporting errors.", "Scanning away from the bedside defeats the matching of wristband to patient."], "a": 3, "ev": "Such workarounds undermine the very protection the technology is intended to provide.", "why": "Máy quét nhằm đối chiếu vòng tay với đơn thuốc tại giường; quét nhãn từ xa làm mất mục đích đó."}, {"kind": "inference", "q": "Why does the team recommend a follow-up audit after twelve months?", "opts": ["To test a new type of scanner", "To punish staff who make mistakes", "To confirm the improvement lasts rather than fading", "To reduce the number of beds"], "a": 2, "ev": "whether the gains are sustained", "why": "Phần hạn chế lo rằng cải thiện có thể chỉ là tạm thời, nên cần kiểm tra lại để xem \"whether the gains are sustained\"."}], "notes": {"vocab": [["omitted", "bị bỏ sót", "omit -> omission"], ["attributed", "cho là do", "attribute A to B"], ["interruptions", "sự gián đoạn", "interrupt (v)"], ["evaluated", "được đánh giá", "evaluate -> evaluation"], ["bias", "thiên lệch", "limit bias"], ["workarounds", "cách lách quy trình", "danh từ ghép"], ["generalisable", "có thể áp dụng rộng", "generalise (v)"], ["sustained", "được duy trì bền vững", "sustain (v)"]], "grammar": [["Purpose clause with passive (mệnh đề mục đích, bị động)", "barcode scanners were introduced so that each wristband could be matched with its prescription at the bedside", "So that + could + V3 bị động chỉ mục đích; chủ ngữ của vế sau (wristband) khác chủ ngữ vế trước."], ["Past perfect (quá khứ hoàn thành)", "By the end of the project, the error rate had fallen to 2.9 per cent", "Had fallen diễn tả việc xảy ra xong trước mốc thời gian trong quá khứ (cuối dự án)."], ["Contrast with Whereas (liên từ đối lập)", "Whereas the majority of nurses valued the extra check, a minority complained", "Whereas nối hai vế tương phản, thường dùng trong văn bản học thuật."], ["Subjunctive after recommend (giả định)", "The team recommends that the vests be retained", "Sau recommend that dùng be + V3 (không chia), kiểu trang trọng trong báo cáo."]], "tips": ["Báo cáo có tiêu đề từng phần (Background, Methods, Findings...): đọc tiêu đề trước để biết thông tin nằm ở đâu, rồi chỉ đọc kỹ phần câu hỏi cần.", "Phần Limitations và Recommendations thường chứa câu hỏi suy luận: tìm các từ chỉ nguyên nhân như \"Because\", \"since\"."]}}, {"id": "rd5-c1-15", "lvl": "C1", "topic": "medical", "genre": "article", "title": "Why the Body Does Not Attack Itself: Tolerance and Autoimmunity", "text": "Why the Body Does Not Attack Itself\n\nThe immune system performs a remarkable balancing act. It must recognise an almost limitless range of foreign invaders, yet it must also refrain from attacking the body's own tissues. The state of not responding to one's own components is known as immune tolerance, and its failure produces autoimmune disease.\n\nTolerance is established in two main stages. During development, immature T cells, a type of white blood cell, mature in the thymus, a small organ behind the breastbone. There they are exposed to a wide sample of the body's own proteins. The balance is delicate, because too strict a screen would leave gaps in the body's defences. Cells that bind too strongly to these proteins are destroyed or disabled, a process called central tolerance. Yet the screening is imperfect: some self-reactive cells escape into the bloodstream. A second safeguard, peripheral tolerance, then keeps them in check. Specialised regulatory T cells, for instance, release signals that suppress their more aggressive neighbours, and many self-reactive cells simply become inactive when they lack the additional signals normally required for activation.\n\nWhen these safeguards fail, the consequences vary. In type 1 diabetes, the immune system destroys the insulin-producing cells of the pancreas. In rheumatoid arthritis, inflammation damages the lining of the joints, while in multiple sclerosis the protective coating around nerve fibres is attacked. Although the target tissue differs, the underlying principle is the same: a response intended to protect has been redirected against the host. Symptoms may appear gradually and come and go, which often delays diagnosis.\n\nWhy tolerance breaks down is not fully understood, and most researchers believe that no single cause is responsible. Genetic susceptibility plays a part, as these conditions often cluster in families. Nevertheless, genes alone do not determine outcome; identical twins, who share the same DNA, are frequently discordant, meaning that one develops the disease and the other does not. Environmental triggers, including certain infections, are therefore suspected. One hypothesis proposes that some microbes carry molecules resembling human proteins, so that an immune response against the microbe inadvertently targets the body as well. This is known as molecular mimicry, although evidence for it remains largely circumstantial in most diseases.\n\nTreatment has traditionally relied on drugs that dampen the whole immune system. Such an approach controls symptoms but leaves patients more vulnerable to infection. Researchers are consequently exploring therapies that would restore tolerance selectively, retraining the immune system to ignore one specific target while leaving its defences against infection intact. Such strategies remain experimental, and it will probably be years before their benefits, if any, can be judged.", "gist": "Bài báo giải thích cách hệ miễn dịch duy trì dung nạp với chính cơ thể, điều gì xảy ra khi cơ chế này hỏng và các hướng điều trị.", "qs": [{"kind": "main", "q": "What is the article mainly about?", "opts": ["How vaccines prepare the body for infection", "How the immune system normally spares the body and what happens when it fails", "Why identical twins have different DNA", "The history of drugs for arthritis"], "a": 1, "ev": "its failure produces autoimmune disease", "why": "Bài giải thích dung nạp miễn dịch và hậu quả khi nó hỏng: \"its failure produces autoimmune disease\"."}, {"kind": "detail", "q": "Where do immature T cells mature?", "opts": ["In the pancreas", "In the bloodstream", "In the joints", "In the thymus"], "a": 3, "ev": "mature in the thymus", "why": "T cell non trưởng thành ở tuyến ức: \"mature in the thymus\"."}, {"kind": "detail", "q": "How do regulatory T cells help maintain tolerance?", "opts": ["They release signals that suppress aggressive cells.", "They destroy all self-reactive cells.", "They make insulin.", "They carry DNA between twins."], "a": 0, "ev": "release signals that suppress their more aggressive neighbours", "why": "Tế bào T điều hòa tiết tín hiệu ức chế các tế bào hung hăng hơn."}, {"kind": "vocab", "q": "In the text, what does \"discordant\" mean?", "opts": ["Identical in outcome", "Unable to inherit DNA", "Differing in whether the disease appears", "Resistant to infection"], "a": 2, "ev": "frequently discordant, meaning that one develops the disease and the other does not", "why": "Bài tự giải thích: \"discordant\" là một người mắc bệnh, người kia không, tức khác nhau về kết quả."}, {"kind": "vocab", "q": "In the text, what does \"circumstantial\" suggest about the evidence?", "opts": ["It is based on large trials.", "It is indirect and not conclusive.", "It is completely false.", "It is recent and complete."], "a": 1, "ev": "remains largely circumstantial in most diseases", "why": "\"Circumstantial\" là bằng chứng gián tiếp, chưa đủ kết luận; câu có \"although\" cho thấy sự dè dặt."}, {"kind": "tfng", "q": "Some self-reactive cells get past central tolerance.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "some self-reactive cells escape into the bloodstream", "why": "Đúng: một số tế bào tự phản ứng \"escape into the bloodstream\"."}, {"kind": "tfng", "q": "Identical twins always both develop the same autoimmune disease.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "identical twins, who share the same DNA, are frequently discordant", "why": "Sai: cặp song sinh giống hệt thường \"discordant\", tức chỉ một người mắc."}, {"kind": "tfng", "q": "Autoimmune diseases are more common in women than in men.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không đề cập giới tính nên là Not given."}, {"kind": "inference", "q": "Why are researchers interested in selective therapies?", "opts": ["Selective therapies are already widely used.", "Current drugs cannot control symptoms.", "They cost less than all other treatments.", "Current drugs suppress the whole immune system and raise infection risk."], "a": 3, "ev": "leaves patients more vulnerable to infection", "why": "Thuốc hiện nay làm yếu cả hệ miễn dịch nên bệnh nhân dễ nhiễm trùng; liệu pháp chọn lọc nhằm khắc phục điều này."}, {"kind": "inference", "q": "What is the author's attitude toward molecular mimicry?", "opts": ["Fully convinced it explains all autoimmune disease", "Dismissive, calling it nonsense", "Cautious, because proof is limited", "Unaware of the evidence"], "a": 2, "ev": "although evidence for it remains largely circumstantial in most diseases", "why": "Tác giả nêu giả thuyết nhưng nhấn mạnh bằng chứng còn gián tiếp, nên thái độ thận trọng."}], "notes": {"vocab": [["tolerance", "sự dung nạp (miễn dịch)", "immune tolerance"], ["refrain from", "kiềm chế không", "refrain from + V-ing"], ["safeguard", "cơ chế bảo vệ", "danh từ và động từ"], ["suppress", "ức chế", "suppress -> suppression"], ["susceptibility", "tính dễ mắc bệnh", "susceptible to"], ["discordant", "không đồng nhất (về kết quả)", "trái nghĩa: concordant"], ["inadvertently", "vô tình", "trạng từ"], ["circumstantial", "gián tiếp (bằng chứng)", "circumstantial evidence"]], "grammar": [["Appositive (đồng vị ngữ)", "Cells that bind too strongly to these proteins are destroyed or disabled, a process called central tolerance.", "Cụm danh từ sau dấu phẩy bổ sung thông tin cho cả mệnh đề trước; a process called... là mệnh đề rút gọn."], ["Reduced relative + present perfect passive", "a response intended to protect has been redirected against the host", "intended to protect là mệnh đề quan hệ rút gọn (= that is intended); has been redirected là hiện tại hoàn thành bị động."], ["Concession with Although/Nevertheless (nhượng bộ)", "Although the target tissue differs, the underlying principle is the same", "Although nêu điều đối lập ở vế đầu; ý chính nằm ở vế sau."]], "tips": ["Bài báo khoa học phổ thông thường có đoạn đầu nêu chủ đề; mỗi đoạn sau phát triển một ý (cơ chế, ví dụ bệnh, nguyên nhân, điều trị).", "Từ nối như \"Nevertheless\", \"therefore\", \"consequently\" cho biết quan hệ đối lập hay kết quả giữa các câu, rất hữu ích cho câu suy luận."]}}, {"id": "rd5-c1-16", "lvl": "C1", "topic": "medical", "genre": "speech", "title": "The Person Who Lives in the Body: A Welcome Address on Empathy", "text": "Good morning, everyone, and congratulations. Look around you for a moment. In six years, the person sitting beside you may be the colleague who saves your life, or the one who tells you, gently, that you have made a mistake. Please treat them accordingly. You will spend more hours with one another than with your own families, so be generous.\n\nI have been asked to speak about empathy, and I confess I was tempted to decline. Empathy is one of those words that everyone admires and few can define. So let me begin with what it is not. It is not sympathy, which keeps us at a comfortable distance and says, \"I am sorry for you.\" Nor is it the dramatic sharing of every patient's pain, which would leave you exhausted within a year. Empathy, as I have come to understand it, is the disciplined effort to see a situation through another person's eyes, followed by the decision to act on what you see.\n\nYou will be told, and you will be tempted to believe, that empathy is a luxury, a pleasant extra once the real medicine has been done. I disagree. Studies have repeatedly suggested that patients who feel understood describe their symptoms more fully, follow advice more reliably, and complain less often. Were empathy a drug, it would be prescribed everywhere, and no one would dream of calling it optional.\n\nBut I must warn you about something that textbooks rarely mention. Empathy tends to erode, not because students stop caring, but because the pressure of exams, long shifts, and ever-growing lists of tasks quietly teaches us to treat people as problems to be solved. I have watched brilliant young doctors drift into this habit without noticing. The remedy is surprisingly small. Sit down when you speak to a patient, since standing makes you look hurried. Learn names and use them. Ask, \"What worries you most?\" and then, crucially, wait for the answer.\n\nAnd do not confuse empathy with agreeing. Sometimes the kindest thing you can do is deliver an unwelcome truth, clearly and without hiding behind jargon. Patients forgive honesty far more readily than evasion.\n\nFinally, look after yourselves. You cannot pour from an empty cup, as the saying goes. Rest, friendship, and the occasional afternoon doing nothing useful are not indulgences; they are the maintenance of the instrument you will use every day, which is you.\n\nSo, as you begin, I ask only this: whatever you learn about the body, never forget the person who lives in it. Thank you, and welcome.", "gist": "Diễn giả chào đón tân sinh viên y khoa và nói rằng đồng cảm là nỗ lực có kỷ luật, dễ bị mai một, cần được giữ gìn cùng với việc chăm sóc bản thân.", "qs": [{"kind": "main", "q": "What is the speaker's central message?", "opts": ["Sympathy is more useful than empathy.", "Empathy is a disciplined practice that doctors must protect.", "Students should avoid sharing patients' emotions entirely.", "Exams matter more than patient relationships."], "a": 1, "ev": "Empathy, as I have come to understand it, is the disciplined effort to see a situation through another person's eyes", "why": "Diễn giả định nghĩa đồng cảm là nỗ lực có kỷ luật nhìn qua mắt người khác, rồi cảnh báo nó dễ mai một."}, {"kind": "detail", "q": "How does the speaker say sympathy differs from empathy?", "opts": ["It requires sharing every patient's pain.", "It is taught in textbooks.", "It improves test results.", "It keeps us at a comfortable distance."], "a": 3, "ev": "keeps us at a comfortable distance", "why": "Sympathy \"keeps us at a comfortable distance\", còn empathy đòi hỏi nhìn từ góc nhìn người bệnh."}, {"kind": "detail", "q": "What do studies suggest about patients who feel understood?", "opts": ["They describe their symptoms more fully.", "They need fewer tests.", "They leave hospital sooner.", "They choose younger doctors."], "a": 0, "ev": "patients who feel understood describe their symptoms more fully", "why": "Bệnh nhân cảm thấy được hiểu mô tả triệu chứng đầy đủ hơn."}, {"kind": "detail", "q": "According to the speaker, why does empathy tend to erode?", "opts": ["Students stop caring about patients.", "Patients become less honest.", "Pressure and heavy workloads teach people to see patients as problems.", "Textbooks discourage it."], "a": 2, "ev": "the pressure of exams, long shifts, and ever-growing lists of tasks", "why": "Áp lực thi cử, ca trực dài và danh sách việc làm bệnh nhân thành \"problems to be solved\"; không phải vì hết quan tâm."}, {"kind": "vocab", "q": "In the text, what does \"erode\" mean?", "opts": ["Disappear suddenly", "Weaken gradually", "Grow stronger", "Become popular"], "a": 1, "ev": "Empathy tends to erode", "why": "\"Erode\" là mòn dần; diễn giả nói đồng cảm bị mai một từ từ mà không ai nhận ra."}, {"kind": "vocab", "q": "In the text, what does \"evasion\" mean?", "opts": ["Speaking too loudly", "Giving detailed advice", "Showing sympathy", "Avoiding a direct answer"], "a": 3, "ev": "Patients forgive honesty far more readily than evasion.", "why": "\"Evasion\" đối lập với honesty: né tránh không nói thẳng."}, {"kind": "tfng", "q": "The speaker advises sitting down when speaking to a patient.", "opts": ["True", "False", "Not given"], "a": 0, "ev": "Sit down when you speak to a patient", "why": "Đúng: \"Sit down when you speak to a patient\"."}, {"kind": "tfng", "q": "The speaker believes empathy means agreeing with patients.", "opts": ["True", "False", "Not given"], "a": 1, "ev": "do not confuse empathy with agreeing", "why": "Sai: diễn giả bảo đừng nhầm đồng cảm với việc đồng ý."}, {"kind": "tfng", "q": "The speaker worked as a nurse before becoming a doctor.", "opts": ["True", "False", "Not given"], "a": 2, "ev": "", "why": "Bài không nói gì về nghề trước đây của diễn giả nên là Not given."}, {"kind": "inference", "q": "What is the speaker implying with \"Were empathy a drug\"?", "opts": ["Empathy should be prescribed in tablet form.", "Doctors rarely use drugs.", "Its benefits are strong enough that treating it as optional makes no sense.", "Patients prefer drugs to empathy."], "a": 2, "ev": "no one would dream of calling it optional", "why": "Câu điều kiện đảo ngữ ngụ ý nếu đồng cảm là thuốc thì ai cũng dùng; vậy không thể xem nó là tùy chọn."}], "notes": {"vocab": [["confess", "thú nhận", "confess to V-ing"], ["sympathy", "sự thông cảm", "khác empathy"], ["disciplined", "có kỷ luật", "discipline (n)"], ["luxury", "thứ xa xỉ, không thiết yếu", "a luxury item"], ["erode", "bị mai một dần", "erosion (n)"], ["remedy", "biện pháp khắc phục", "a remedy for"], ["jargon", "thuật ngữ chuyên môn khó hiểu", "medical jargon"], ["evasion", "sự né tránh", "evade (v)"]], "grammar": [["Inverted conditional (đảo ngữ điều kiện)", "Were empathy a drug, it would be prescribed everywhere", "Were + chủ ngữ thay cho If empathy were a drug; giả định trái với thực tế, giọng trang trọng."], ["Negative inversion with Nor", "Nor is it the dramatic sharing of every patient's pain", "Nor đứng đầu đảo is it; dùng để thêm một phủ định nữa."], ["Contrast: not because ..., but because ...", "not because students stop caring, but because the pressure of exams", "Cấu trúc loại trừ lý do sai rồi nêu lý do đúng."], ["Imperatives (câu mệnh lệnh)", "Sit down when you speak to a patient", "Lời khuyên trực tiếp là đặc trưng của bài diễn văn."]], "tips": ["Bài diễn văn có mở đầu chào hỏi, phần giữa tăng dần lập luận và phần kết nhắc lại thông điệp chính: câu cuối thường tóm tắt ý chính.", "Chú ý các hình ảnh và thành ngữ (ví dụ \"pour from an empty cup\"): chúng thường được dùng để minh họa một lời khuyên, nên hãy suy ra nghĩa bóng."]}}]);
